/* ============ 在线存储模式判定 ============
 * 四种模式优先级：db（资料库智能页）> localfile（File System Access 直接写本机文件）> gh（GitHub 仓库当数据库）> local（浏览器 localStorage）
 * - db      ：在 WorkBuddy 资料库里打开，数据存私有资料库云端表
 * - localfile：浏览器支持 showDirectoryPicker 时启用，用户挑一次文件夹，数据作为真实文件写进本机（推荐，免服务器）
 * - gh      ：部署到 GitHub Pages 后，用户填好仓库配置，数据读写仓库里的 data/lifedesk.json
 * - local   ：不支持 FSA 且无网络后端时兜底，数据存当前浏览器 localStorage
 * 注意：db 模式永远优先于 gh（资料库自带云端，不需要 GitHub）。 */
/* 部署版：仓库信息已内置（owner/repo/分支/路径），用户只需在「同步设置」粘贴 Token 即可连接。
 * 读取公开仓库无需 Token；写入需要带 repo 权限的 Token。 */
var GH_DEFAULT = { owner:'Ciaorz', repo:'life-desk', branch:'main', path:'data/lifedesk.json', token:'', apiBase:'' };
var GH = null, MODE = 'local';
try { GH = JSON.parse(localStorage.getItem('lifedesk_gh') || 'null'); } catch(e){ GH = null; }
if (!GH || typeof GH !== 'object') GH = {};
GH = Object.assign({}, GH_DEFAULT, GH);            // 已存的本地配置（含 Token）覆盖默认值
GH.branch = GH.branch || 'main';
GH.path   = GH.path   || 'data/lifedesk.json';
/* 只要有 owner+repo（默认就有）就走 gh 模式：读公开仓库无需 Token，写需要 Token */
if (GH && GH.owner && GH.repo){ MODE = 'gh'; } else { MODE = 'local'; }
if (ONLINE) MODE = 'db';

/* ============ 离线本地存储后端 ============
 * 当不在资料库智能页环境（ONLINE=false，例如部署到 GitHub Pages 或直接双击打开）时，
 * 所有录入的书籍/手办/电影/学习计划等数据不再依赖任何服务器，改存浏览器 localStorage。
 * 每张表一个 key：lifedesk_<table>，值为扁平行数组（与内存 store[key].rows 同构）。
 * 这样部署后的页面是一个真正能独立录入、保存、读取的个人工具。 */
function lsKey(k){ return 'lifedesk_' + k; }
function lsGet(k){ try { return JSON.parse(localStorage.getItem(lsKey(k)) || '[]'); } catch(e){ return []; } }
function lsSet(k, arr){ try { localStorage.setItem(lsKey(k), JSON.stringify(arr)); } catch(e){} }

/* ============ GitHub 仓库当数据库（在线模式） ============
 * 数据统一存成仓库里的单个 JSON 文件（默认 data/lifedesk.json），结构 { 表名: [行...] }。
 * 读取：GET contents API；写入：PUT 整文件（带 sha 覆盖，无 sha 则创建）。
 * Token 仅存浏览器 localStorage（key lifedesk_gh），绝不进仓库；公开仓库则数据公开可读写。 */
function ghConfig(){ return GH; }
/* GitHub API 基地址：默认官方 api.github.com；国内手机访问被墙时，可填一个转发代理
   （如 Cloudflare Worker / 自建 relay），所有 Contents API 请求都会走这个地址。 */
function ghApiBase(){
  var b = (GH && GH.apiBase) ? String(GH.apiBase).trim().replace(/\/+$/,'') : '';
  return b || 'https://api.github.com';
}
function ghHeaders(extra){
  var h = extra || {};
  if (GH && GH.token) h['Authorization'] = 'token ' + GH.token;
  h['Accept'] = 'application/vnd.github+json';
  return h;
}
function b64decodeUtf8(b64){
  var bin = atob(b64.replace(/\s/g, ''));
  var bytes = new Uint8Array(bin.length);
  for (var i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}
function utf8ToB64(str){
  var bytes = new TextEncoder().encode(str);
  var bin = '';
  for (var i=0;i<bytes.length;i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}
function ghFileUrl(){ return ghApiBase() + '/repos/' + GH.owner + '/' + GH.repo + '/contents/' + GH.path + '?ref=' + (GH.branch || 'main'); }
var _ghSha = null, _ghCache = null, _ghLoading = null, _ghIncrSkip = 0;
/* v60：一键「获取最新数据」时生成的临时戳；非空时给所有数据请求加 ?_=<戳> 缓存击穿参数，
   绕过 SW / 浏览器 HTTP 缓存，确保拉到服务器上的最新文件。 */
var _forceFresh = 0;
function _bustUrl(url){
  if (!_forceFresh) return url;
  var sep = url.indexOf('?') >= 0 ? '&' : '?';
  return url + sep + '_=' + _forceFresh;
}
function ghGetAll(cb){
  fetch(_bustUrl(ghFileUrl()), { headers: ghHeaders(), cache: 'no-store' })
    .then(function(r){
      if (r.status === 404){ _ghSha = null; return cb({}, null); }
      if (!r.ok) throw new Error('gh-status-' + r.status);
      return r.json();
    })
    .then(function(j){
      if (j === undefined) return;
      _ghSha = j.sha;
      var obj = {};
      try {
        var raw = (j.content ? b64decodeUtf8(j.content) : '').trim();
        if (raw) obj = JSON.parse(raw);
      } catch(e){ obj = {}; } /* 文件不是合法 JSON（如空文件/只剩换行）时，当作空数据，避免整条连接崩掉 */
      cb(obj, j.sha);
    })
    .catch(function(e){ cb(null, null, (e && e.message) ? e.message : 'network'); });
}
function ghSaveAll(obj, cb){
  if (!GH || !GH.token){ if (cb) cb(false); return; }
  _ghCache = obj; /* 写完后内存视图立刻与仓库一致 */
  var body = { message: 'life-desk data sync ' + new Date().toISOString().slice(0,19), content: utf8ToB64(JSON.stringify(obj, null, 2)) };
  if (_ghSha) body.sha = _ghSha;
  fetch(ghFileUrl(), { method:'PUT', headers: ghHeaders({'Content-Type':'application/json'}), body: JSON.stringify(body) })
    .then(function(r){
      if (r.ok){ return r.json().then(function(j){ _ghSha = (j && j.content && j.content.sha) ? j.content.sha : _ghSha; cb(true); }); }
      if (r.status === 409){ return ghGetAll(function(){ ghSaveAll(obj, cb); }); } /* sha 过期，重拉后重试一次 */
      cb(false);
    })
    .catch(function(){ cb(false); });
}
var _ghTimer = null;
function queueGhSave(){
  if (!GH || !GH.token){
    setGhStatus('noconn');
    toast('要保存改动，请先点右下角 ⚙ 同步设置 粘贴 GitHub Token', '去填', function(){ toggleGhPanel(); });
    return;
  }
  setGhStatus('saving');
  if (_ghTimer) clearTimeout(_ghTimer);
  _ghTimer = setTimeout(function(){ _ghTimer = null; ghSaveNow(function(ok){ if (ok) setGhStatus('synced'); else setGhStatus('failed'); if (!ok) toast('同步到 GitHub 失败，稍后重试'); }); }, 700);
}
/* 分片感知的 GitHub 保存：分片仓库走 sharded 路径，单文件仓库退化为 ghSaveAll */
function ghSaveNow(cb){
  if (_shardMode) ghSaveShardedFromStore(cb);
  else ghSaveAll(snapshotAll(), cb);
}
/* v60：清空 Service Worker 缓存 + 同源 caches，确保下一次请求拉到服务器最新文件。
   双管齐下：① 给激活中的 SW 发 PURGE_CACHES 消息；② 页面侧直接删 caches.keys()。 */
function clearSwCaches(){
  try {
    if (navigator.serviceWorker && navigator.serviceWorker.controller){
      var ch = new MessageChannel();
      ch.port1.onmessage = function(){};
      navigator.serviceWorker.controller.postMessage({ type:'PURGE_CACHES' }, [ch.port2]);
    }
  } catch(e){}
  try {
    if ('caches' in window){
      caches.keys().then(function(ks){
        ks.forEach(function(k){ try { caches.delete(k); } catch(e){} });
      }).catch(function(){});
    }
  } catch(e){}
}
/* v60：一键「获取网站最新数据」。
   流程：清空 SW 缓存 → 清空内存与 localStorage 兜底缓存 → 给数据请求加缓存击穿参数 →
   重新加载全部数据。适用于手机/电脑在线版手动刷新仍拿不到最新数据的场景。 */
function refreshFromServer(){
  _forceFresh = Date.now();
  _ghCache = null; _ghLoading = null; _idxCache = null;
  try { localStorage.removeItem(_LOCAL_CACHE_KEY); } catch(e){}
  clearSwCaches();
  if (MODE === 'gh' || MODE === 'db' || MODE === 'localfile'){
    toast('正在从网站获取最新数据…', '刷新', function(){ window.location.reload(); });
  } else {
    toast('正在重新加载数据…');
  }
  loadAll();
  /* 数据请求在 ~600ms 后清掉击穿戳，避免后续正常刷新也带参数；再延迟提示完成 */
  setTimeout(function(){ _forceFresh = 0; }, 800);
  setTimeout(function(){
    var msg = (MODE === 'gh' || MODE === 'db') ? '已从网站获取最新数据' : '已重新加载数据';
    try { toast(msg); } catch(e){}
  }, 1600);
}
function snapshotAll(){
  var obj = {};
  ORDER.filter(function(k){ return k!=='overview'; }).concat(EXTRA).forEach(function(k){
    obj[k] = (store[k] && store[k].rows) ? store[k].rows : [];
  });
  return obj;
}
/* 本地兜底缓存：gh 模式下 GitHub 写入是异步且国内访问 api.github.com 可能慢/失败，
   每次本地改动后同步写一份全量到 localStorage；启动读取 GitHub 失败时回退到此缓存，避免强刷丢数据。 */
var _LOCAL_CACHE_KEY = 'lifedesk_local_cache';
function localCacheSetFrom(obj){ try { localStorage.setItem(_LOCAL_CACHE_KEY, JSON.stringify(obj)); } catch(e){} }
function localCacheSet(){ localCacheSetFrom(snapshotAll()); }
function localCacheGet(){ try { return JSON.parse(localStorage.getItem(_LOCAL_CACHE_KEY) || 'null'); } catch(e){ return null; } }
function persistAll(cb){
  if (MODE === 'localfile'){ saveLocalAll(snapshotAll(), function(ok){ if (cb) cb(ok); }); return; }
  if (MODE === 'gh'){ ghSaveNow(function(ok){ if (cb) cb(ok); }); return; }
  if (MODE === 'local'){ var o = snapshotAll(); Object.keys(o).forEach(function(k){ lsSet(k, o[k]); }); if (cb) cb(true); return; }
  if (cb) cb(false);
}

/* === 本地文件模式（File System Access API：浏览器原生直接写本机真实文件，无需任何服务器）===
 * 与「serve.js + fetch」方案相比：不用起 Node 服务，数据作为真实文件落盘（lifedesk.json），
 * 用户只需在首次使用时用系统对话框挑一个文件夹（建议选本项目 data 文件夹）即可，之后自动读写。
 * 目录句柄存 IndexedDB 跨刷新保留；不支持 FSA 的浏览器（Firefox / Safari / 多数手机浏览器）
 * 自动回退到 gh / local 模式，不报错。
 * 上传 GitHub 按钮保留：把内存数据覆盖 PUT 到仓库（图片内联在 JSON 里，单文件自包含）。 */
var _FSA_SUPPORT = (typeof window !== 'undefined') && ('showDirectoryPicker' in window);
var _fsaHandle = null;
var _LOCALFS_FILE = 'lifedesk.json';
var _fsaTimer = null;

/* ---- IndexedDB 持久化目录句柄（跨刷新保留；失败则每次需重选，不阻断）---- */
function _fsaOpenDB(){
  return new Promise(function(res, rej){
    if (!('indexedDB' in window)){ rej(new Error('no idb')); return; }
    var req = indexedDB.open('lifedesk-fsa', 1);
    req.onupgradeneeded = function(e){ var db=e.target.result; if(!db.objectStoreNames.contains('handles')) db.createObjectStore('handles'); };
    req.onsuccess = function(e){ res(e.target.result); };
    req.onerror = function(e){ rej(e.target.error); };
  });
}
async function _fsaSaveHandle(h){
  try { var db=await _fsaOpenDB(); var tx=db.transaction('handles','readwrite'); tx.objectStore('handles').put(h,'handle'); await new Promise(function(r){tx.oncomplete=r;tx.onerror=function(){r();};}); return true; } catch(e){ return false; }
}
async function _fsaLoadHandle(){
  try { var db=await _fsaOpenDB(); return await new Promise(function(res){ var tx=db.transaction('handles','readonly'); var rq=tx.objectStore('handles').get('handle'); rq.onsuccess=function(){res(rq.result||null);}; rq.onerror=function(){res(null);}; }); } catch(e){ return null; }
}
async function _fsaClearHandle(){ try { var db=await _fsaOpenDB(); var tx=db.transaction('handles','readwrite'); tx.objectStore('handles').delete('handle'); } catch(e){} }

/* 让用户挑一次数据目录；成功则写入 IndexedDB 并设 _fsaHandle */
async function pickFsaDir(){
  var handle = await window.showDirectoryPicker({ mode:'readwrite' });
  _fsaHandle = handle;
  await _fsaSaveHandle(handle);
  return handle;
}

/* 启动时恢复目录句柄：有则请求权限，授权成功返回 handle，否则 null */
async function restoreFsaHandle(){
  var h = await _fsaLoadHandle();
  if (!h) return null;
  try {
    var p = await h.queryPermission({ mode:'readwrite' });
    if (p === 'granted') return h;
    if (p === 'prompt'){ p = await h.requestPermission({ mode:'readwrite' }); if (p === 'granted') return h; }
    return null;
  } catch(e){ return null; }
}

/* 读 lifedesk.json：兼容「导出备份」格式 {tables:{...}} 与扁平行格式；默认 {} */
async function localfsRead(cb){
  if (!_fsaHandle){ cb({}); return; }
  try {
    var fh = await _fsaHandle.getFileHandle(_LOCALFS_FILE);
    var f = await fh.getFile();
    var txt = await f.text();
    var obj = (txt && txt.trim()) ? JSON.parse(txt) : {};
    if (obj && obj.tables && typeof obj.tables === 'object') obj = obj.tables;
    cb(obj && typeof obj === 'object' ? obj : {});
  } catch(e){ cb({}); }
}

/* 写 lifedesk.json（覆盖） */
async function localfsWrite(obj, cb){
  if (!_fsaHandle){ if (cb) cb(false); return; }
  try {
    var fh = await _fsaHandle.getFileHandle(_LOCALFS_FILE, { create:true });
    var w = await fh.createWritable();
    await w.write(JSON.stringify(obj, null, 2));
    await w.close();
    if (cb) cb(true);
  } catch(e){ if (cb) cb(false); }
}

/* ============================================================
   分片存储 v2（schema 2）—— 每个小类一个独立数据文件
   ------------------------------------------------------------
   主索引  lifedesk.json
     { schema:2, shards:{ "唱片":{file:"唱片-data.json", module:"collection"}, ... },
       __main:{ travel:[...], collection:[...] } }   // __main 存尚未分片的记录
   分片    {类目}-data.json
     { schema:2, cat:"唱片", module:"collection", rows:[...] }
   封面    images/{类目}/{记录id}_{序号}.jpg  —— JSON 里只记相对路径
   ------------------------------------------------------------
   兼容：schema 缺失或为 1 时，完全走旧的「单文件扁平」逻辑，不做任何迁移。
   ============================================================ */
var SCHEMA_V2 = 2;
var IMG_DIR = 'images';
/* 数据目录在站点下的路径前缀。
   注意区分两种路径：
   - 写文件时用的路径：相对于 FSA 数据目录，形如 images/{类目}-封面/0001.jpg
   - 存进 JSON / 显示时用的路径：相对于站点根，必须带 data/ 前缀，
     形如 data/images/{类目}-封面/0001.jpg
     否则会打到站点根的 images/（那是应用自带图标目录），图片 404。 */
var DATA_PREFIX = 'data';

/* 每个模块用哪个字段当分片键 */
var SHARD_FIELD = { travel:'状态', collection:'小类', av:'大类', study:'领域', food:'类型', recipe:'', idea:'分类' };
/* 旅行：状态值 → 类目名（用户口径是「去过的地方」「想去的地方」） */
var TRAVEL_CAT = { '去过':'去过的地方', '想去':'想去的地方' };
/* v67：书籍的五个预设标签分类（书架顶部那 7 张标签卡就是「全部 + 这 5 个 + 未分类」） */
var BOOK_TAGS = ['自然科技','工具语言','艺术视觉','人文历史','兴趣收藏'];
/* v67：要收进独立文件夹管理的数据分组。
   规则：一个 data.json 永远配一个同名封面文件夹 images/{名字}-封面/；
        IP / 系列 / 书籍 各自的 data 放进同名文件夹，以后新建的
        「{IP名}-data.json」「{系列名}-data.json」「{小分类}-data.json」也都落在这里。 */
var GROUP_DIR = { ip:'ip', series:'series', 书籍:'书籍' };
var LAYOUT_V3 = 3;

function shardCatOf(mk, row){
  if (mk === 'ip') return 'ip';
  if (mk === 'series') return 'series';
  /* v54：美食 / 菜谱 各自一个独立分片文件（不再按 类型 细分，也不再留在主文件），
     这样 data/ 下是 美食-data.json + images/美食-封面/ 与 菜谱-data.json + images/菜谱-封面/ */
  if (mk === 'food') return '美食';
  if (mk === 'recipe') return '菜谱';
  /* v54：书籍 / 杂志 在 collection 里按「大类」分片，其它藏品按「小类」分片 */
  if (mk === 'collection'){
    var big = String(row && row['大类'] || '').trim();
    if (big === '杂志') return big;
    /* v67：书籍再往下细分——有「小分类」就用小分类（如 德语），
       否则用「标签分类」（如 工具语言），都没有就是「未分类」，统一落在 书籍-data.json。
       这样每个分类一个 data.json：自然科技-data.json / 德语-data.json / 书籍-data.json */
    if (big === '书籍'){
      var bsub = String(row && row['小分类'] || '').trim();
      var btag = String(row && row['标签分类'] || '').trim();
      return bsub || btag || '书籍';
    }
    var f = SHARD_FIELD[mk]; if (!f || !row) return '';
    var v = String(row[f] || '').trim(); if (!v) return '';
    return v;
  }
  /* v58：学习计划固定一个专属分片（原来按「领域」分散且不建文件，用户找不到 data.json） */
  if (mk === 'study') return '学习计划';
  var f = SHARD_FIELD[mk]; if (!f || !row) return '';
  var v = String(row[f] || '').trim(); if (!v) return '';
  if (mk === 'travel') return TRAVEL_CAT[v] || v;
  return v;
}
/* 文件名安全化：去掉 Windows/URL 非法字符，限长 */
function safeFileName(s){
  return String(s || '').replace(/[\\/:*?"<>|\r\n\t]/g, '_').trim().slice(0, 60) || '未命名';
}
function shardFileName(cat){ return safeFileName(cat) + '-data.json'; }
/* 每个类目的封面图片文件夹：images/{类目}-封面/ */
function coverDirName(cat){ return safeFileName(cat) + '-封面'; }
function coverDirPath(cat){ return DATA_PREFIX + '/' + IMG_DIR + '/' + coverDirName(cat) + '/'; }
function pad2(n){ n = String(n); return n.length < 2 ? '0' + n : n; }
/* v78：封面分文件夹存储规则（解决 GitHub 单目录超 1000 文件被截断的问题）
   - 有「系列」：归入 series/{小类}-封面-NN（每 100 张一个文件夹，NN 从 01 起）
   - 无「系列」：前 100 张在 {小类}-封面/，超出部分进 {小类}-封面/{小类}-NN/
   返回的是相对 data/images/ 的「路径分段」数组。 */
function coverIsSeries(row){ return !!(row && String(row['系列'] || '').trim()); }
function coverBaseParts(cat, row){
  var np = coverDirName(cat);                       /* 冰箱贴-封面 */
  if (coverIsSeries(row)) return { base: ['series'], prefix: np, cat: cat, isSeries: true, entity: false };
  return { base: [np], prefix: np, cat: cat, isSeries: false, entity: false };
}
/* 给定基础信息，返回一个「当前还能放封面」的子文件夹分段（不足 100 张的优先，满了就开下一个） */
async function pickCoverFolder(info){
  if (info.entity) return info.base;
  var base = info.base, prefix = info.prefix, cat = info.cat, isSeries = info.isSeries;
  if (isSeries){
    var dirs = await fsListDirs(base);
    var re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '-(\\d+)$');
    var maxNN = 0;
    dirs.forEach(function(d){ var m = re.exec(d); if (m){ var v = parseInt(m[1], 10); if (v > maxNN) maxNN = v; } });
    var target = base.concat([prefix + '-' + pad2(maxNN || 1)]);
    if (maxNN){
      var cnt = (await fsListFiles(target)).length;
      if (cnt >= 100) target = base.concat([prefix + '-' + pad2(maxNN + 1)]);
    }
    return target;
  } else {
    var cnt0 = (await fsListFiles(base)).length;
    if (cnt0 < 100) return base;
    var sub = await fsListDirs(base);
    var re2 = new RegExp('^' + cat.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '-(\\d+)$');
    var maxN2 = 0;
    sub.forEach(function(d){ var m = re2.exec(d); if (m){ var v = parseInt(m[1], 10); if (v > maxN2) maxN2 = v; } });
    var tgt2 = maxN2 ? base.concat([cat + '-' + pad2(maxN2)]) : base.concat([cat + '-01']);
    if (maxN2){
      var c2 = (await fsListFiles(tgt2)).length;
      if (c2 >= 100) tgt2 = base.concat([cat + '-' + pad2(maxN2 + 1)]);
    }
    return tgt2;
  }
}

/* ============================================================
   v68：每实体 IP / 系列 存储（一个实体一个 data.json + 同名图片文件夹）
   ------------------------------------------------------------
   - IP：    data/ip/{IP名}-data.json            图片 data/images/ip/{IP名}-封面/
   - 系列：  data/series/{系列名}-data.json      图片 data/images/series/{系列名}-封面/
   （系列不再嵌套进 IP 文件夹；「所属IP」字段仅作归类 / 展示用，不影响文件位置。
     每个系列都是 data/series/ 下的独立文件，便于单独操作、改名、迁移。） */
function ipCoverDir(ipName){ return 'ip/' + safeFileName(ipName) + '-封面'; }
function seriesCoverDir(seriesName, ipName){
  return 'series/' + safeFileName(seriesName) + '-封面';   /* v68fix：系列封面固定落在 data/images/series/，不再随所属IP 嵌套 */
}
function ipDataRel(ipName){ return 'ip/' + safeFileName(ipName) + '-data.json'; }
function seriesDataRel(seriesName, ipName){
  return 'series/' + safeFileName(seriesName) + '-data.json';   /* v68fix：系列 data.json 固定落在 data/series/，不再随所属IP 嵌套 */
}
/* 由 data 文件路径反推它的图片封面文件夹名（'ip/宝可梦-data.json' → 'ip/宝可梦-封面'） */
function coverDirFromDataRel(rel){ return String(rel || '').replace(/-data\.json$/, '-封面'); }
function entityCoverDir(mk, row){
  if (mk === 'ip') return ipCoverDir(String(row && row['IP名称'] || '').trim());
  if (mk === 'series') return seriesCoverDir(String(row && row['系列名称'] || '').trim(), String(row && row['所属IP'] || '').trim());
  return coverDirName(mk);
}
/* 删除一个（可能含文件的）目录 */
async function fsRemoveDirAt(rel){
  if (!_fsaHandle) return false;
  try {
    var parts = splitRelPath(rel);
    if (!parts.length) return false;
    var name = parts.pop();
    var d = _fsaHandle;
    for (var i = 0; i < parts.length; i++){ d = await d.getDirectoryHandle(parts[i], { create:false }); }
    if (typeof d.removeEntry === 'function'){ await d.removeEntry(name, { recursive:true }); return true; }
  } catch(e){}
  return false;
}
/* 把一条记录里的图片从旧封面目录整批搬进新封面目录（同名落盘），并改写引用。
   用于 IP / 系列 改名、或系列更换所属 IP 时，图片文件夹跟着挪、data.json 里的路径不断链。 */
async function moveImageFolder(oldCoverDir, newCoverDir, row){
  oldCoverDir = String(oldCoverDir || ''); newCoverDir = String(newCoverDir || '');
  if (!oldCoverDir || oldCoverDir === newCoverDir || !row) return false;
  var oldParts = oldCoverDir.split('/').filter(Boolean);
  var newParts = newCoverDir.split('/').filter(Boolean);
  var oldDir = await _fsaGetDir([IMG_DIR].concat(oldParts), false);
  if (!oldDir) return false;
  await _fsaGetDir([IMG_DIR].concat(newParts), true);
  var names = await fsListFiles([IMG_DIR].concat(oldParts));
  var moved = 0;
  for (var i = 0; i < names.length; i++){
    try {
      var src = await oldDir.getFileHandle(names[i]);
      var buf = await (await src.getFile()).arrayBuffer();
      var ok = await _fsaWriteBinary([IMG_DIR].concat(newParts), names[i], new Uint8Array(buf));
      if (ok) moved++;
    } catch(e){}
  }
  var oldPrefix = DATA_PREFIX + '/' + IMG_DIR + '/' + oldCoverDir + '/';
  var newPrefix = DATA_PREFIX + '/' + IMG_DIR + '/' + newCoverDir + '/';
  for (var j = 0; j < IMG_FIELDS.length; j++){
    var arr = row[IMG_FIELDS[j]];
    if (!arr || !arr.length) continue;
    for (var k = 0; k < arr.length; k++){
      if (arr[k] && arr[k].imageUrl && String(arr[k].imageUrl).indexOf(oldPrefix) === 0){
        arr[k].imageUrl = newPrefix + String(arr[k].imageUrl).slice(oldPrefix.length);
      }
    }
  }
  if (moved){ try { await fsRemoveDirAt([IMG_DIR].concat(oldParts).join('/')); } catch(e){} }
  return moved > 0;
}

/* ============================================================
   v67：分片文件支持「子目录」
   ------------------------------------------------------------
   以前所有 {类目}-data.json 都平铺在 data/ 根目录。
   现在 IP / 系列 / 书籍 各自的 data 收进同名文件夹，便于管理：
       data/ip/ip-data.json、data/ip/宝可梦-data.json
       data/series/series-data.json
       data/书籍/书籍-data.json、data/书籍/自然科技-data.json、data/书籍/德语-data.json
   所以 shards[x].file 可能是 "书籍/自然科技-data.json" 这种带斜杠的路径，
   下面几个函数负责把它拆开逐级取句柄。
   ============================================================ */
function splitRelPath(rel){ return String(rel || '').split('/').filter(Boolean); }
async function fsGetFileHandleAt(rel, create){
  if (!_fsaHandle) return null;
  var parts = splitRelPath(rel);
  if (!parts.length) return null;
  var name = parts.pop();
  var d = _fsaHandle;
  for (var i = 0; i < parts.length; i++){
    try { d = await d.getDirectoryHandle(parts[i], { create: !!create }); }
    catch(e){ return null; }
  }
  try { return await d.getFileHandle(name, { create: !!create }); }
  catch(e){ return null; }
}
async function fsReadJSONAt(rel){
  try {
    var fh = await fsGetFileHandleAt(rel, false);
    if (!fh) return null;
    var txt = await (await fh.getFile()).text();
    if (!txt || !txt.trim()) return null;
    return JSON.parse(txt);
  } catch(e){ return null; }
}
async function fsWriteJSONAt(rel, obj){
  try {
    var fh = await fsGetFileHandleAt(rel, true);
    if (!fh) return false;
    var w = await fh.createWritable();
    await w.write(JSON.stringify(obj, null, 2));
    await w.close();
    return true;
  } catch(e){ console.warn('写文件失败', rel, e); return false; }
}
async function fsRemoveFileAt(rel){
  if (!_fsaHandle) return false;
  try {
    var parts = splitRelPath(rel);
    if (!parts.length) return false;
    var name = parts.pop();
    var d = _fsaHandle;
    for (var i = 0; i < parts.length; i++){ d = await d.getDirectoryHandle(parts[i], {}); }
    if (d && typeof d.removeEntry === 'function'){ await d.removeEntry(name); return true; }
  } catch(e){}
  return false;
}
/* 在同一目录内重命名（先复制内容到新名，再删旧名；任一步失败都尽量回滚） */
async function fsRenameFileAt(rel, newName){
  var ok = false;
  try {
    var parts = splitRelPath(rel);
    if (!parts.length) return false;
    var name = parts.pop();
    var d = _fsaHandle;
    for (var i = 0; i < parts.length; i++){ d = await d.getDirectoryHandle(parts[i], { create:false }); }
    var oldFh = await d.getFileHandle(name);
    var buf = await (await oldFh.getFile()).arrayBuffer();
    var newFh = await d.getFileHandle(newName, { create:true });
    var w = await newFh.createWritable();
    await w.write(buf); await w.close();
    /* 校验：新文件确实写出来了才删旧的，避免改名丢图 */
    var chk = await d.getFileHandle(newName);
    var sz = (await chk.getFile()).size;
    if (sz > 0 && sz === buf.byteLength){
      if (typeof d.removeEntry === 'function') await d.removeEntry(name);
      ok = true;
    }
  } catch(e){ ok = false; }
  return ok;
}
/* 列出某个目录下的直属文件名（只列文件） */
async function fsListFiles(dirParts){
  var out = [];
  try {
    var d = await _fsaGetDir(dirParts, false);
    if (!d) return out;
    if (typeof d.entries === 'function'){
      var it = d.entries(), e = await it.next();
      while (!e.done){ if (e.value[1].kind === 'file') out.push(e.value[0]); e = await it.next(); }
    } else if (typeof d.values === 'function'){
      for await (var h of d.values()){ if (h.kind === 'file') out.push(h.name); }
    }
  } catch(e){}
  return out;
}
/* 列出某个目录下的直属子目录名 */
async function fsListDirs(dirParts){
  var out = [];
  try {
    var d = await _fsaGetDir(dirParts, false);
    if (!d) return out;
    if (typeof d.entries === 'function'){
      var it = d.entries(), e = await it.next();
      while (!e.done){ if (e.value[1].kind === 'directory') out.push(e.value[0]); e = await it.next(); }
    } else if (typeof d.values === 'function'){
      for await (var h of d.values()){ if (h.kind === 'directory') out.push(h.name); }
    }
  } catch(e){}
  return out;
}

/* ---------- 底层文件读写（FSA）---------- */
/* v67：改为走 fsReadJSONAt / fsWriteJSONAt，从而支持 "书籍/自然科技-data.json" 这类带子目录的路径 */
async function fsReadJSON(name){
  if (!_fsaHandle) return null;
  if (String(name).indexOf('/') >= 0) return await fsReadJSONAt(name);
  try {
    var fh = await _fsaHandle.getFileHandle(name);
    var f = await fh.getFile();
    var txt = await f.text();
    if (!txt || !txt.trim()) return null;
    return JSON.parse(txt);
  } catch(e){ return null; }
}
async function fsWriteJSON(name, obj){
  if (!_fsaHandle) return false;
  if (String(name).indexOf('/') >= 0) return await fsWriteJSONAt(name, obj);
  try {
    var fh = await _fsaHandle.getFileHandle(name, { create:true });
    var w = await fh.createWritable();
    await w.write(JSON.stringify(obj, null, 2));
    await w.close();
    return true;
  } catch(e){ console.warn('写文件失败', name, e); return false; }
}
async function fsFileExists(name){
  if (!_fsaHandle) return false;
  try { await _fsaHandle.getFileHandle(name); return true; } catch(e){ return false; }
}
/* 主索引：保证结构完整 */
function normalizeIndex(idx){
  if (!idx || typeof idx !== 'object') idx = {};
  if (idx.schema !== SCHEMA_V2) idx.schema = SCHEMA_V2;
  if (!idx.shards || typeof idx.shards !== 'object') idx.shards = {};
  if (!idx.__main || typeof idx.__main !== 'object') idx.__main = {};
  /* v68：IP / 系列 是「每实体一个文件」的目录分片（dirShard），不再有单一 ip-data.json / series-data.json。
     真正的文件在 data/ip/、data/ip/{IP}/、data/series/ 下，由 loadEntityModule / saveEntityModule 扫描读写。 */
  if (!idx.shards.ip) idx.shards.ip = { module:'ip', dirShard:true, dir:'ip', coverDir:'ip' };
  if (!idx.shards.series) idx.shards.series = { module:'series', dirShard:true, dir:'series', coverDir:'系列' };
  /* v54：把电影 / 留声机 / 书籍 / 杂志 / 美食 / 菜谱 预注册为独立分片，各自有自己的 data/{cat}-data.json 和 images/{cat}-封面 */
  [
    { cat:'赏戏',    module:'av',        file:'赏戏-data.json',    coverDir:'赏戏-封面' },
    { cat:'留音',    module:'av',        file:'留音-data.json',    coverDir:'留音-封面' },
    { cat:'书籍',    module:'collection', file:'书籍/书籍-data.json', coverDir:'书籍-封面' },
    { cat:'杂志',    module:'collection', file:'杂志-data.json',    coverDir:'杂志-封面' },
    { cat:'美食',    module:'food',       file:'美食-data.json',    coverDir:'美食-封面' },
    { cat:'菜谱',    module:'recipe',     file:'菜谱-data.json',    coverDir:'菜谱-封面' },
    { cat:'学习计划', module:'study',      file:'学习计划-data.json', coverDir:'学习计划-封面' }
  ].forEach(function(sh){
    if (!idx.shards[sh.cat]) idx.shards[sh.cat] = { file:sh.file, module:sh.module, coverDir:sh.coverDir };
  });
  /* v67：书籍的五个标签分类各自一个 data.json，统一放在 data/书籍/ 文件夹里
     （自然科技-data.json / 工具语言-data.json / …），并各自配 images/{分类}-封面/ */
  BOOK_TAGS.forEach(function(t){
    var s = idx.shards[t];
    if (!s) s = idx.shards[t] = { file:'书籍/' + shardFileName(t), module:'collection', coverDir:coverDirName(t) };
    if (!s.group) s.group = '书籍';
    if (!s.kind) s.kind = 'booktag';
    if (!s.coverDir) s.coverDir = coverDirName(t);
    if (String(s.file).indexOf('书籍/') !== 0) s.file = '书籍/' + shardFileName(t);
  });
  /* 书籍 / 系列 / ip 的分组标记（迁移前也先打上，迁移负责把文件真正挪进文件夹） */
  /* 书籍主分片：v67 迁移后文件实际在 data/书籍/书籍-data.json，修正索引指向，避免读不到（本地/gh 自愈） */
  if (idx.shards['书籍']){
    var _bs = idx.shards['书籍'];
    if (!_bs.group) _bs.group = '书籍';
    if (!_bs.module) _bs.module = 'collection';
    if (String(_bs.file).indexOf('书籍/') !== 0) _bs.file = '书籍/' + shardFileName('书籍');
  }
  if (idx.shards['ip'] && !idx.shards['ip'].group) idx.shards['ip'].group = 'ip';
  if (idx.shards['series'] && !idx.shards['series'].group) idx.shards['series'].group = 'series';
  /* v75：把持久化的用户自定义大类 / 小类合并进运行时 CATS / SUBS，让它们出现在全站筛选、表单与页面管理里 */
  USER_CATS = (idx.userCats && idx.userCats.slice) ? idx.userCats.slice() : [];
  USER_SUBS = (idx.userSubs && typeof idx.userSubs==='object') ? JSON.parse(JSON.stringify(idx.userSubs)) : {};
  USER_CATS.forEach(function(c){ if (CATS.indexOf(c)<0) CATS.push(c); });
  Object.keys(USER_SUBS).forEach(function(cat){
    if (!SUBS[cat]) SUBS[cat] = [];
    (USER_SUBS[cat]||[]).forEach(function(s){ if (SUBS[cat].indexOf(s)<0) SUBS[cat].push(s); });
  });
  /* v75fix：存储地点三段（房间 / 柜体墙面 / 所在层）的可管理选项 */
  LOC_OPTS = { '房间':[], '柜体墙面':[], '所在层':[] };
  if (idx.locOptions && typeof idx.locOptions==='object'){
    LOC_DIMS.forEach(function(d){
      var arr = idx.locOptions[d];
      if (arr && arr.slice) LOC_OPTS[d] = arr.slice();
    });
  }
  return idx;
}
var _idxCache = null;   /* v67：最近一次读到的主索引（同步访问用，避免每次 await） */
async function fsReadIndex(){ var i = normalizeIndex(await fsReadJSON(_LOCALFS_FILE)); _idxCache = i; refreshBookSubs(); return i; }
async function fsWriteIndex(idx){ var i = normalizeIndex(idx); _idxCache = i; refreshBookSubs(); return await fsWriteJSON(_LOCALFS_FILE, i); }
/* v67：书籍小分类的运行时清单：{ 父分类: [小分类...] }，从主索引里 shards[x].kind==='booksub' 推导 */
var BOOK_SUBS = {};
function refreshBookSubs(){
  BOOK_SUBS = {};
  var idx = _idxCache || {};
  Object.keys(idx.shards || {}).forEach(function(cat){
    var sh = idx.shards[cat] || {};
    if (sh.kind === 'booksub'){
      var p = String(sh.parent || '');
      (BOOK_SUBS[p] = BOOK_SUBS[p] || []).push(cat);
    }
  });
}
function bookSubCatsOf(parentTag){ return (BOOK_SUBS[String(parentTag || '')] || []).slice(); }
/* v67：一本书「归属哪个大分类」——优先看标签分类；只填了小分类时，反查它挂在哪个大分类下。
   这样小分类的书也会计入大分类的标数，点大分类卡也能把它带出来。 */
function bookEffectiveTag(r){
  var t = String(r && r['标签分类'] || '').trim();
  if (t) return t;
  var s = String(r && r['小分类'] || '').trim();
  if (s){
    for (var i = 0; i < BOOK_TAGS.length; i++){
      if ((BOOK_SUBS[BOOK_TAGS[i]] || []).indexOf(s) >= 0) return BOOK_TAGS[i];
    }
  }
  return '';
}
/* 小分类下拉的选项 HTML：已有小分类 + 「＋ 新建小分类…」 */
function bookSubOptionsHTML(parentTag, cur){
  var subs = bookSubCatsOf(parentTag);
  var h = '<option value=""' + (!cur ? ' selected' : '') + '>（无）</option>';
  subs.forEach(function(s){ h += '<option value="' + esc(s) + '"' + (s === cur ? ' selected' : '') + '>' + esc(s) + '</option>'; });
  if (cur && subs.indexOf(cur) < 0) h += '<option value="' + esc(cur) + '" selected>' + esc(cur) + '</option>';
  h += '<option value="__new__">＋ 新建小分类…</option>';
  return h;
}
function bookAllSubCats(){
  var out = [];
  Object.keys(BOOK_SUBS).forEach(function(p){ BOOK_SUBS[p].forEach(function(s){ if (out.indexOf(s) < 0) out.push(s); }); });
  return out;
}

/* ---------- 组装 / 拆分 ---------- */
/* 把「扁平快照」{模块:[记录]} 拆成 主索引 + 各分片，并写盘。
   只写有变动的分片（对比旧内容），避免每次全量重写几十个文件。 */
async function storageSaveV2(snapshot){
  var idx = await fsReadIndex();
  var buckets = {};        /* cat -> {module, rows} */
  var main = {};           /* 未分片记录 */
  Object.keys(snapshot || {}).forEach(function(mk){
    var rows = snapshot[mk] || [];
    main[mk] = [];
    rows.forEach(function(r){
      if (!r) return;
      var cat = shardCatOf(mk, r);
      var sh = cat ? idx.shards[cat] : null;
      if (sh && sh.dirShard) return;            /* v68：ip / series 逐实体写，下面单独处理 */
      if (cat && sh){
        if (!buckets[cat]) buckets[cat] = { module: mk, rows: [] };
        buckets[cat].rows.push(r);
      } else {
        main[mk].push(r);     /* 尚未建专属文件的类目，先留在主文件 */
      }
    });
  });
  idx.__main = main;

  /* 写分片：内容无变化则跳过 */
  var okAll = true;
  for (var cat in buckets){
    if (!Object.prototype.hasOwnProperty.call(buckets, cat)) continue;
    var sh = idx.shards[cat] || {};
    var file = sh.file || shardFileName(cat);
    sh.file = file; sh.module = buckets[cat].module;
    if (!sh.coverDir) sh.coverDir = coverDirName(cat);
    idx.shards[cat] = sh;
    /* 先把 base64 / 外链封面落盘成独立文件，row 内换成相对路径，再比较/写入。
       图片编号在每个类目封面文件夹内独立递增。 */
    await externalizeImages(cat, buckets[cat].rows);
    var oldObj = await fsReadJSON(file);
    var oldStr = oldObj ? JSON.stringify(oldObj.rows || []) : '';
    var newStr = JSON.stringify(buckets[cat].rows);
    if (oldStr !== newStr){
      var okw = await fsWriteJSON(file, {
        schema: SCHEMA_V2, cat: cat, module: buckets[cat].module, rows: buckets[cat].rows
      });
      if (!okw) okAll = false;
    }
  }
  /* v68：逐实体写 IP / 系列（每个实体一个文件；改名 / 删除会自动挪文件与图片文件夹、更新引用） */
  await saveEntityModule('ip', snapshot.ip || []);
  await saveEntityModule('series', snapshot.series || []);
  /* v??：把 dirShard 实体文件清单写进主索引，供 GitHub Pages 静态直读（无法列目录）时按清单逐个拉取。
     直接扫描磁盘真实目录，避免依赖内存快照里的 _file 字段（存储快照已扁平成 {模块:[记录]}，本身没有 .rows）。 */
  if (idx && idx.shards && idx.shards.ip && idx.shards.ip.dirShard){
    var _efMap = {};
    (await entityExistingFiles('ip')).forEach(function(p){ _efMap[p] = 1; });
    (await entityExistingFiles('series')).forEach(function(p){ _efMap[p] = 1; });
    idx.entityFiles = Object.keys(_efMap).sort();
  }
  var oki = await fsWriteIndex(idx);
  await writeReadme();          /* 顺带刷新说明文件里的类目清单与封面编号 */
  return okAll && oki;
}
/* 读主索引 + 全部分片，合并成扁平快照 {模块:[记录]} */
async function storageLoadV2(){
  var idx = await fsReadIndex();
  var out = {};
  /* 先放主文件里的未分片记录 */
  Object.keys(idx.__main || {}).forEach(function(mk){ out[mk] = (idx.__main[mk] || []).slice(); });
  /* 再叠加各分片 */
  for (var cat in idx.shards){
    if (!Object.prototype.hasOwnProperty.call(idx.shards, cat)) continue;
    var sh = idx.shards[cat] || {};
    if (sh.dirShard) continue;          /* v68：ip / series 逐实体加载，下面单独处理 */
    var obj = await fsReadJSON(sh.file || shardFileName(cat));
    if (!obj) continue;
    var mk = sh.module || obj.module;
    if (!mk) continue;
    if (!out[mk]) out[mk] = [];
    out[mk] = out[mk].concat(obj.rows || []);
  }
  /* v68：逐实体加载 IP / 系列（data/ip/、data/ip/{IP}/、data/series/ 下各一个 data.json） */
  await loadEntityModule('ip', out);
  await loadEntityModule('series', out);
  /* 相对路径的图片 → blob URL，供封面显示 */
  for (var m in out){ if (Object.prototype.hasOwnProperty.call(out, m)) await resolveImagesFor(out[m]); }
  /* v77：宝可梦属性图标（18 张）同样要解析成可显示 URL */
  await resolveImagesFor(pkIconProbeRows());
  return out;
}

/* ============================================================
   v68：IP / 系列「每实体一个文件」的读写
   ============================================================ */
/* 列出某实体模块当前磁盘上所有的 data.json 相对路径（用于删除不再存在的记录） */
async function entityExistingFiles(mk){
  var out = [];
  if (mk === 'ip'){
    var f = await fsListFiles(['ip']);
    f.forEach(function(n){ if (/-data\.json$/.test(n)) out.push('ip/' + n); });
  } else if (mk === 'series'){
    var sf = await fsListFiles(['series']);
    sf.forEach(function(n){ if (/-data\.json$/.test(n)) out.push('series/' + n); });
    var dirs = await fsListDirs(['ip']);
    for (var d = 0; d < dirs.length; d++){
      var s2 = await fsListFiles(['ip', dirs[d]]);
      s2.forEach(function(n){ if (/-data\.json$/.test(n)) out.push('ip/' + dirs[d] + '/' + n); });
    }
  }
  return out;
}
/* 逐实体加载：扫描 data/ip/、data/ip/{IP}/、data/series/ 下所有 *-data.json，
   每个文件即一个 IP / 系列 记录；给每条记录挂上 _file（它的相对路径），后续改名/删除要用。 */
async function loadEntityModule(mk, out){
  out[mk] = out[mk] || [];
  if (mk === 'ip'){
    var files = await fsListFiles(['ip']);
    for (var i = 0; i < files.length; i++){
      if (!/-data\.json$/.test(files[i])) continue;
      var obj = await fsReadJSONAt('ip/' + files[i]);
      if (obj && obj.rows) obj.rows.forEach(function(r){ if (r){ r._file = 'ip/' + files[i]; out.ip.push(r); } });
    }
  } else if (mk === 'series'){
    var sf = await fsListFiles(['series']);
    for (var i = 0; i < sf.length; i++){
      if (!/-data\.json$/.test(sf[i])) continue;
      var o = await fsReadJSONAt('series/' + sf[i]);
      if (o && o.rows) o.rows.forEach(function(r){ if (r){ r._file = 'series/' + sf[i]; out.series.push(r); } });
    }
    var ipdirs = await fsListDirs(['ip']);
    for (var d = 0; d < ipdirs.length; d++){
      var s2 = await fsListFiles(['ip', ipdirs[d]]);
      for (var j = 0; j < s2.length; j++){
        if (!/-data\.json$/.test(s2[j])) continue;
        var o2 = await fsReadJSONAt('ip/' + ipdirs[d] + '/' + s2[j]);
        if (o2 && o2.rows) o2.rows.forEach(function(r){ if (r){ r._file = 'ip/' + ipdirs[d] + '/' + s2[j]; out.series.push(r); } });
      }
    }
  }
}
/* 逐实体写：每个 IP / 系列 一个文件；改名（含换所属 IP）自动挪文件 + 图片文件夹并改引用；
   被删掉的记录，它对应的旧文件与图片文件夹一并清理，不留残留。 */
async function saveEntityModule(mk, rows){
  if (!_fsaHandle) return;
  var prev = {};
  (store[mk] && store[mk].rows || []).forEach(function(r){ if (r && r._id) prev[String(r._id)] = r._file || null; });
  var keep = {};
  for (var i = 0; i < (rows || []).length; i++){
    var row = rows[i]; if (!row) continue;
    var name = (mk === 'ip' ? String(row['IP名称'] || '') : String(row['系列名称'] || '')).trim();
    var ipName = mk === 'series' ? String(row['所属IP'] || '').trim() : '';
    var newFile = mk === 'ip' ? ipDataRel(name) : seriesDataRel(name, ipName);
    var newCoverDir = mk === 'ip' ? ipCoverDir(name) : seriesCoverDir(name, ipName);
    var oldFile = prev[String(row._id)] || null;
    var oldCoverDir = oldFile ? coverDirFromDataRel(oldFile) : null;
    /* 改名 / 换 IP：先把旧图片文件夹里的图搬进新文件夹、改写引用（externalize 之前做，避免重复写） */
    if (oldCoverDir && oldCoverDir !== newCoverDir) await moveImageFolder(oldCoverDir, newCoverDir, row);
    /* IP 改名：级联把旗下系列的 所属IP 也改成新名字，系列才会跟着挪进新 IP 文件夹 */
    if (mk === 'ip' && oldFile){
      try {
        var oldObj = await fsReadJSONAt(oldFile);
        var oldName = oldObj && oldObj.rows && oldObj.rows[0] ? String(oldObj.rows[0]['IP名称'] || '').trim() : '';
        if (oldName && oldName !== name){
          (store.series && store.series.rows || []).forEach(function(sr){
            if (sr && String(sr['所属IP'] || '').trim() === oldName) sr['所属IP'] = name;
          });
        }
      } catch(e){}
    }
    /* 外链 / base64 落盘到新封面目录 */
    await externalizeImages(mk, [row], null, { coverDir: newCoverDir, namePrefix: name });
    /* 写新文件（清掉运行期字段 _file，保持文件干净） */
    var clean = JSON.parse(JSON.stringify(row)); if ('_file' in clean) delete clean._file;
    await fsWriteJSONAt(newFile, { schema: SCHEMA_V2, cat: mk, module: mk, rows: [clean] });
    row._file = newFile;
    keep[newFile] = true;
  }
  /* 删除不再存在的文件（被删记录，或改名后留下的旧文件）+ 它们的图片文件夹 */
  var existing = await entityExistingFiles(mk);
  for (var e = 0; e < existing.length; e++){
    if (keep[existing[e]]) continue;
    await fsRemoveFileAt(existing[e]);
    await fsRemoveDirAt(coverDirFromDataRel(existing[e]));
  }
  /* IP 文件夹里若已空（系列都搬走 / 删光），顺手清掉，不留空目录 */
  if (mk === 'ip'){
    var ipdirs = await fsListDirs(['ip']);
    for (var x = 0; x < ipdirs.length; x++){
      var f2 = await fsListFiles(['ip', ipdirs[x]]);
      var d2 = await fsListDirs(['ip', ipdirs[x]]);
      if (!f2.length && !d2.length) await fsRemoveDirAt('ip/' + ipdirs[x]);
    }
  }
}

/* ---------- v67：目录重组 / 小分类创建 ----------
   规则（一个 data.json 永远配一个同名封面文件夹）：
     data/ip/·        ip-data.json、{IP名}-data.json      → images/ip-封面/、images/{IP名}-封面/
     data/series/·    series-data.json、{系列名}-data.json  → 同名封面文件夹
     data/书籍/·      书籍-data.json（未分类）、{标签分类}-data.json、{小分类}-data.json
   下面两个函数负责「保证文件存在」，新建 IP / 系列 / 书籍小分类时都走它们。 */
async function ensureShardFile(cat, module, opt){
  opt = opt || {};
  if (!_fsaHandle) return null;
  var idx = await fsReadIndex();
  var dirPrefix = opt.dir || GROUP_DIR[cat] || '';
  var sh = idx.shards[cat];
  if (!sh){
    sh = idx.shards[cat] = {
      file: (dirPrefix ? dirPrefix + '/' : '') + shardFileName(cat),
      module: module || 'collection',
      coverDir: coverDirName(cat)
    };
  }
  if (!sh.coverDir) sh.coverDir = coverDirName(cat);
  if (!sh.file) sh.file = shardFileName(cat);
  if (dirPrefix && String(sh.file).indexOf(dirPrefix + '/') !== 0){
    sh.file = dirPrefix + '/' + String(sh.file).split('/').pop();
  }
  if (opt.group) sh.group = opt.group;
  if (opt.kind) sh.kind = opt.kind;
  if (opt.parent != null) sh.parent = opt.parent;
  var cur = await fsReadJSON(sh.file);
  if (!cur){
    var okw = await fsWriteJSONAt(sh.file, { schema:SCHEMA_V2, cat:cat, module:(sh.module || module || 'collection'), rows:[] });
    if (!okw) return null;
  }
  await _fsaGetDir([IMG_DIR, sh.coverDir], true);        /* 同名图片文件夹一定一起建出来 */
  await fsWriteIndex(idx);
  return sh;
}
/* v67：在五个大分类之下新建一个小分类（如 工具语言 → 德语）。
   自动创建 书籍/{小分类}-data.json + images/{小分类}-封面/ 并登记到主索引。 */
async function ensureBookSubCat(parentTag, subName){
  subName = String(subName || '').trim();
  if (!subName) return { ok:false, msg:'小分类名不能为空' };
  if (BOOK_TAGS.indexOf(subName) >= 0) return { ok:false, msg:'不能和五个大分类重名' };
  if (subName === '书籍') return { ok:false, msg:'「书籍」是未分类专用的名字，换一个' };
  if (!_fsaHandle) return { ok:false, msg:'还没连接本地数据目录' };
  var idx = await fsReadIndex();
  if (idx.shards[subName]) return { ok:true, cat:subName, existed:true, msg:'「' + subName + '」已经存在，已直接选中' };
  var sh = await ensureShardFile(subName, 'collection', { dir:'书籍', group:'书籍', kind:'booksub', parent:parentTag || '' });
  if (!sh) return { ok:false, msg:'创建数据文件失败' };
  return { ok:true, cat:subName, existed:false,
           msg:'已创建 书籍/' + safeFileName(subName) + '-data.json 和 images/' + coverDirName(subName) + '/' };
}
/* v67：目录重组迁移——只跑一次（主索引里记 layoutVersion），跑之前先备份主索引。 */
var _groupLayoutDone = false;
async function migrateGroupLayout(){
  if (_groupLayoutDone || !_fsaHandle || MODE !== 'localfile') return false;
  _groupLayoutDone = true;
  var idx = await fsReadIndex();
  if ((idx.layoutVersion || 0) >= LAYOUT_V3) return false;
  var moved = false;
  try {
    var rawIdx = await fsReadJSON(_LOCALFS_FILE);
    if (rawIdx) await fsWriteJSON('lifedesk.bak-v66.json', rawIdx);   /* 先留一份，出问题能还原 */

    /* ① ip / 系列 / 书籍 的 data.json 收进同名文件夹 */
    var plans = [
      { cat:'ip',     group:'ip',     base:'ip-data.json' },
      { cat:'series', group:'series', base:'series-data.json' },
      { cat:'书籍',    group:'书籍',    base:'书籍-data.json' }
    ];
    for (var i = 0; i < plans.length; i++){
      var p = plans[i];
      var sh = idx.shards[p.cat];
      if (!sh || sh.dirShard) continue;     /* v68：ip / series 已是 dirShard，跳过 */
      var oldFile = String(sh.file || p.base);
      var fname = String(oldFile).split('/').pop();
      var newFile = p.group + '/' + fname;
      if (oldFile !== newFile){
        var obj = await fsReadJSON(oldFile);
        if (obj){
          var okw = await fsWriteJSONAt(newFile, obj);
          if (okw){ await fsRemoveFileAt(oldFile); sh.file = newFile; moved = true; }
        } else {
          sh.file = newFile;                       /* 文件还没建出来，只改登记 */
        }
      }
      sh.group = p.group;
    }
    /* ② 五个标签分类：各自建 data.json + 图片文件夹 */
    for (var t = 0; t < BOOK_TAGS.length; t++){
      await ensureShardFile(BOOK_TAGS[t], 'collection', { dir:'书籍', group:'书籍', kind:'booktag' });
    }
    /* ③ 把现有书籍按「标签分类 / 小分类」分流到对应的 data.json */
    var bookSh = idx.shards['书籍'] || {};
    var bookFile = bookSh.file || '书籍/书籍-data.json';
    var bookObj = await fsReadJSON(bookFile);
    var rows = (bookObj && bookObj.rows) || [];
    if (rows.length){
      var buckets = {}, stay = [];
      rows.forEach(function(r){
        var c = shardCatOf('collection', r);
        if (c && c !== '书籍' && idx.shards[c]) (buckets[c] = buckets[c] || []).push(r);
        else stay.push(r);
      });
      var ckeys = Object.keys(buckets);
      for (var b = 0; b < ckeys.length; b++){
        var bc = ckeys[b];
        await ensureShardFile(bc, 'collection', { dir:'书籍', group:'书籍', kind:'booktag' });
        var bf = (idx.shards[bc] || {}).file || ('书籍/' + shardFileName(bc));
        var bo = (await fsReadJSON(bf)) || { schema:SCHEMA_V2, cat:bc, module:'collection', rows:[] };
        var have = {}; (bo.rows || []).forEach(function(r){ if (r && r._id) have[String(r._id)] = true; });
        buckets[bc].forEach(function(r){ if (!have[String(r._id)]) bo.rows.push(r); });
        await fsWriteJSONAt(bf, bo);
        moved = true;
      }
      if (stay.length !== rows.length){
        bookObj.rows = stay;
        await fsWriteJSONAt(bookFile, bookObj);
      }
    }
    /* ④ 记档，以后不再重跑 */
    idx = await fsReadIndex();
    idx.layoutVersion = LAYOUT_V3;
    await fsWriteIndex(idx);
    await writeReadme();
  } catch(e){
    console.warn('目录重组迁移失败（不影响使用）', e);
    return false;
  }
  return moved;
}

/* ---------- 封面图片外置 ----------
   JSON 里只存相对路径（images/{类目}/{id}_{f}_{i}.jpg），真正图片落盘为独立文件。
   显示时通过 _imgUrlCache 把相对路径换成 blob: URL（FSA）或直接用静态 URL（GitHub Pages）。
   这样 JSON 体积不再随图片数量线性膨胀。 */
var IMG_FIELDS = ['封面', '照片', 'IP图像', '系列封面', '图片'];
var _imgUrlCache = {};                 /* 相对路径 -> 可直接用于 <img>/CSS 的 URL */
var _imgFetchFailed = 0;               /* 本次保存中「外链图片下载失败」的数量 */

/* 兼容旧数据：早期存的路径缺 data/ 前缀（形如 images/...），这里补上 */
function normalizeImgPath(u){
  u = String(u || '');
  if (!u) return '';
  if (/^(data|blob):/.test(u) || /^https?:/i.test(u) || u.indexOf('//') === 0) return u;
  if (u.indexOf(DATA_PREFIX + '/') === 0) return u;              /* 已带前缀 */
  if (u.indexOf(IMG_DIR + '/') === 0) return DATA_PREFIX + '/' + u;  /* 旧路径补前缀 */
  return u;
}
function resolveImgUrl(u){
  u = normalizeImgPath(u);
  if (!u) return '';
  if (/^(data|blob):/.test(u) || /^https?:/i.test(u) || u.indexOf('//') === 0) return u;
  return _imgUrlCache[u] || u;         /* 未解析完时先返回原值，不至于整块空白 */
}
/* v67：是不是「还没落盘」的图（外链网址 / base64）。是的话才需要「存进本地图库」。 */
function imgIsRemote(u){
  u = String(u || '');
  if (!u) return false;
  if (u.indexOf('data:image/') === 0) return true;
  if (/^blob:/i.test(u)) return false;
  if (/^https?:/i.test(u) || u.indexOf('//') === 0) return true;
  return false;
}
async function _fsaGetDir(parts, create){
  if (!_fsaHandle) return null;
  var d = _fsaHandle;
  for (var i = 0; i < parts.length; i++){
    try { d = await d.getDirectoryHandle(parts[i], { create: !!create }); }
    catch(e){ return null; }
  }
  return d;
}
async function _fsaWriteBinary(dirParts, name, uint8){
  var d = await _fsaGetDir(dirParts, true); if (!d) return false;
  try {
    var fh = await d.getFileHandle(name, { create: true });
    var w = await fh.createWritable();
    await w.write(uint8); await w.close(); return true;
  } catch(e){ return false; }
}
function dataUrlToBytes(dataUrl){
  try {
    var b64 = String(dataUrl).split(',')[1] || '';
    var bin = atob(b64);
    var arr = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return arr;
  } catch(e){ return null; }
}
/* 下载外链图片为字节（失败返回 null，保留原链接不阻断） */
async function fetchImageBytes(url){
  try {
    var r = await fetch(url, { mode: 'cors' });
    if (!r || !r.ok) return null;
    var blob = await r.blob();
    var buf = await blob.arrayBuffer();
    var bytes = new Uint8Array(buf);
    var ext = 'jpg';
    var ct = String(blob.type || '').toLowerCase();
    if (ct.indexOf('png') >= 0) ext = 'png';
    else if (ct.indexOf('webp') >= 0) ext = 'webp';
    else if (ct.indexOf('gif') >= 0) ext = 'gif';
    else {
      var mm = /\.(png|jpe?g|webp|gif)(?:[?#]|$)/i.exec(url);
      if (mm) ext = mm[1].replace('jpeg', 'jpg');
    }
    return { bytes: bytes, ext: ext };
  } catch(e){ return null; }
}
function pad4(n){ n = String(n); while (n.length < 4) n = '0' + n; return n; }

/* ============================================================
   v67：图库索引 data/images/_index.json
   ------------------------------------------------------------
   解决的问题：
   ① 同一张图在不同分类下只落盘一次 —— 先在 bySrc（原始外链）里查，
      再在 byHash（内容哈希）里查，命中就把已有相对路径直接引用过去；
   ② 图库管理页要能列图、查引用、清残留 —— files 里记着每张图的
      哈希 / 来源 / 大小，能据此判定「孤儿图」（没有任何 data.json 引用）。
   结构：
     { schema:1,
       bySrc : { 原始外链   -> 已存的相对路径 }
       byHash: { 内容哈希   -> 已存的相对路径 }
       files : { 相对路径   -> {hash, src, size, ext, added, refs} } }
   ============================================================ */
var IMG_INDEX_FILE = IMG_DIR + '/_index.json';
var _imgIndex = null;
function emptyImgIndex(){ return { schema:1, bySrc:{}, byHash:{}, files:{} }; }
async function loadImgIndex(){
  if (_imgIndex) return _imgIndex;
  var ix = await fsReadJSONAt(IMG_INDEX_FILE);
  _imgIndex = (ix && typeof ix === 'object') ? ix : emptyImgIndex();
  if (!_imgIndex.files) _imgIndex.files = {};
  if (!_imgIndex.bySrc) _imgIndex.bySrc = {};
  if (!_imgIndex.byHash) _imgIndex.byHash = {};
  return _imgIndex;
}
async function saveImgIndex(){
  if (!_imgIndex) return false;
  return await fsWriteJSONAt(IMG_INDEX_FILE, _imgIndex);
}
function resetImgIndex(){ _imgIndex = null; }
/* FNV-1a 32 位：够快，用于同图识别 */
function hashBytes(u8){
  var h = 0x811c9dc5;
  for (var i = 0; i < u8.length; i++){
    h ^= u8[i];
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}
/* 入库前查重：先看外链存过没，再看内容哈希存在没。命中返回已有相对路径。 */
function imgIndexHit(src, hash){
  var ix = _imgIndex; if (!ix) return null;
  if (src && ix.bySrc[src] && ix.files[ix.bySrc[src]]) return ix.bySrc[src];
  if (hash && ix.byHash[hash] && ix.files[ix.byHash[hash]]) return ix.byHash[hash];
  return null;
}
function imgIndexPut(rel, hash, src, size, ext){
  var ix = _imgIndex; if (!ix) return;
  ix.files[rel] = { hash: hash || '', src: src || '', size: size || 0, ext: ext || 'jpg',
                    added: new Date().toISOString().slice(0,10) };
  if (src) ix.bySrc[src] = rel;
  if (hash) ix.byHash[hash] = rel;
}
function imgIndexDrop(rel){
  var ix = _imgIndex; if (!ix || !ix.files[rel]) return;
  var rec = ix.files[rel] || {};
  if (rec.src && ix.bySrc[rec.src] === rel) delete ix.bySrc[rec.src];
  if (rec.hash && ix.byHash[rec.hash] === rel) delete ix.byHash[rec.hash];
  delete ix.files[rel];
}
/* 当前正在编辑的这条记录，落盘时该进哪个 data.json（决定图片放哪个文件夹） */
function currentShardCat(){
  if (!editing) return '未命名';
  var c = shardCatOf(editing.key, editing.vals);
  return c || editing.key || '未命名';
}
/* v67：表单里「⬇ 存进本地图库」按钮 —— 把外链 / base64 封面真正落盘到 data/images，
   同一张图只会存一次（图库索引按外链 + 内容哈希查重）。 */
/* v78：线上（GitHub Pages）模式拿不到本地目录句柄，但只要仓库 Token 在，
   就能把封面图片经 GitHub Contents API 直接传进仓库，再把相对路径回填给字段。 */
async function ghUploadCover(fk, url, done){
  var safe = String(rowDisplayName(editing.vals) || 'cover')
    .replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, '-').slice(0, 40) || 'cover';
  var ext = 'jpg', blob = null;
  toast('正在把封面上传到仓库…');
  try{
    if (url.indexOf('data:image/') === 0){
      var by = dataUrlToBytes(url);
      if (!by) throw new Error('bad data url');
      ext = (url.indexOf('image/png') >= 0 ? 'png' : (url.indexOf('image/webp') >= 0 ? 'webp' : 'jpg'));
      blob = new Blob([by], { type: 'image/' + ext });
    } else {
      var r = await fetch(url, { mode: 'cors' });
      if (!r || !r.ok) throw new Error('http ' + (r && r.status));
      blob = await r.blob();
      var mt = String(blob.type || '').toLowerCase();
      if (mt.indexOf('png') >= 0) ext = 'png';
      else if (mt.indexOf('webp') >= 0) ext = 'webp';
      else if (mt.indexOf('gif') >= 0) ext = 'gif';
      else ext = 'jpg';
    }
  }catch(e){
    toast('这张图下不下来（多半是对方防盗链），请点「上传」选本地图片');
    return;
  }
  if (blob.size > 4 * 1024 * 1024){
    toast('这张图有 ' + Math.round(blob.size / 1048576) + 'MB，太大了，仓库上传容易失败');
    return;
  }
  var cat = currentShardCat() || '其他';
  var rel = 'data/images/' + cat + '-封面/' + safe + '-' + Date.now().toString(36) + '.' + ext;
  var ok = false;
  try{ ok = await ghPutFile(rel, blob); }catch(e){ ok = false; }
  if (!ok){ toast('上传仓库失败，请检查 Token 是否有 repo 权限'); return; }
  editing.vals[fk] = rel;
  var inp = document.querySelector('[data-f="' + fk + '"]');
  if (inp) inp.value = rel;
  var prev = document.querySelector('[data-img-prev="' + fk + '"]');
  if (prev){
    var u = resolveImgUrl(rel);
    if (u) prev.style.backgroundImage = "url('" + u.replace(/["'()\\]/g, '') + "')";
  }
  var tip = document.querySelector('[data-img-dltip="' + fk + '"]');
  if (tip) tip.textContent = '已上传到仓库：' + rel.replace('data/images/', '') + '（Pages 生效约需 1 分钟）';
  toast('封面已传进仓库，点保存后生效');
  if (done) done();
}
async function downloadCoverToLib(fk, done){
  if (!editing){ return; }
  var v = String(editing.vals[fk] || '').trim();
  if (!v){ toast('先粘贴一个图片链接，或点「上传」选本地图片'); return; }
  if (!imgIsRemote(v)){ toast('这张已经是本地图片了'); return; }
  if (!_fsaHandle){
    /* v78：线上模式（GitHub Pages）没有本地目录句柄，但有仓库 Token —— 直接传进仓库。
       本地 file:// 模式既没句柄也没 Token，才提示去连目录。 */
    if (MODE === 'gh' && GH && GH.token){ await ghUploadCover(fk, v, done); return; }
    toast('还没连接本地数据目录，存不进去', '选择目录', function(){ pickFsaDirAndConnect(); });
    return;
  }
  var cat = currentShardCat();
  var bn = rowDisplayName(editing.vals);
  var entCover = null, entPrefix = null;
  if (editing.key === 'ip' || editing.key === 'series'){
    entCover = entityCoverDir(editing.key, editing.vals);
    entPrefix = editing.key === 'ip' ? String(editing.vals['IP名称'] || '') : String(editing.vals['系列名称'] || '');
  }
  toast('正在把封面存进本地图库…');
  var res = null;
  if (v.indexOf('data:image/') === 0){
    var by = dataUrlToBytes(v);
    res = by ? await ingestImageToLib(cat, { bytes: by, ext: (v.indexOf('image/png') >= 0 ? 'png' : 'jpg'), baseName: bn, coverDir: entCover, namePrefix: entPrefix, row: editing.vals }) : null;
  } else {
    res = await ingestImageToLib(cat, { src: v, baseName: bn, coverDir: entCover, namePrefix: entPrefix, row: editing.vals });
  }
  if (!res){ toast('这张图下不下来（多半是对方防盗链），请点「上传」选本地图片'); return; }
  editing.vals[fk] = res.rel;
  var inp = document.querySelector('[data-f="' + fk + '"]');
  if (inp) inp.value = res.rel;
  var prev = document.querySelector('[data-img-prev="' + fk + '"]');
  if (prev){
    var u = resolveImgUrl(res.rel);
    if (u) prev.style.backgroundImage = "url('" + u.replace(/["'()\\]/g, '') + "')";
  }
  var tip = document.querySelector('[data-img-dltip="' + fk + '"]');
  if (tip) tip.textContent = '已存到本地：' + res.rel.replace('data/images/', '') + '（不会再重复存第二份）';
  toast(res.reused ? '图库里已经有这张了，已直接引用，没有重复占空间'
                   : '封面已存进 ' + res.rel.replace('data/images/', '').replace(/\/[^\/]+$/, ''));
  if (done) done();
}
/* v67：批量——把某个模块里所有「还是外链」的封面一次性存进本地图库 */
async function downloadAllRemoteCovers(key, rows, onProgress, onDone){
  if (!_fsaHandle){ toast('还没连接本地数据目录'); if (onDone) onDone(0, 0); return; }
  var targets = [];
  (rows || []).forEach(function(r){
    if (!r) return;
    for (var j = 0; j < IMG_FIELDS.length; j++){
      var arr = r[IMG_FIELDS[j]];
      if (!arr || !arr.length) continue;
      for (var k = 0; k < arr.length; k++){
        var it = arr[k];
        if (it && it.imageUrl && imgIsRemote(it.imageUrl)){
          targets.push({ row: r, field: IMG_FIELDS[j], item: it, url: String(it.imageUrl) });
        }
      }
    }
  });
  if (!targets.length){ toast('没有需要下载的封面（都已经存在本地了）'); if (onDone) onDone(0, 0); return; }
  var okN = 0, reuseN = 0, failN = 0;
  for (var i = 0; i < targets.length; i++){
    var t = targets[i];
    if (onProgress) onProgress(i + 1, targets.length);
    var cat = shardCatOf(key, t.row) || (t.row['大类'] || key);
    var dopt = { src: t.url, baseName: rowDisplayName(t.row), row: t.row };
    if (key === 'ip' || key === 'series'){
      dopt.coverDir = entityCoverDir(key, t.row);
      dopt.namePrefix = key === 'ip' ? String(t.row['IP名称'] || '') : String(t.row['系列名称'] || '');
    }
    var res = await ingestImageToLib(cat, dopt);
    if (res){ t.item.imageUrl = res.rel; _imgUrlCache[res.rel] = t.url; if (res.reused) reuseN++; else okN++; }
    else failN++;
  }
  if (okN || reuseN){
    if (MODE === 'localfile') await saveLocalAll(snapshotAll());
    else if (MODE === 'gh') queueGhSave();
    else { lsSet(key, store[key].rows); localCacheSet(); }
  }
  toast('已存 ' + okN + ' 张' + (reuseN ? '，' + reuseN + ' 张图库里已有直接引用' : '') + (failN ? '，' + failN + ' 张下载失败（防盗链，请手动上传）' : ''));
  if (onDone) onDone(okN + reuseN, failN);
}
/* 相对路径（存进 JSON 的形态 data/images/xx-封面/a.jpg）→ 站点可访问路径 / FSA 内部路径 */
function relToFsParts(rel){
  var parts = String(normalizeImgPath(rel)).split('/').filter(Boolean);
  if (parts.length && parts[0] === DATA_PREFIX) parts.shift();
  return parts;   /* ['images','xx-封面','a.jpg'] */
}
/* 把一个 File / Blob 读成字节 */
async function blobToBytes(b){
  var buf = await b.arrayBuffer();
  return new Uint8Array(buf);
}

/* v67：核心入库函数——把一张图存进图库（带查重），返回 {rel, reused} 或 null。
   cat 决定落在 images/{cat}-封面/ 哪个文件夹；opt.src 记来源外链便于再次查重；
   opt.bytes 可直接传字节（上传本地文件时用）；opt.baseName 决定文件名里的条目名。 */
async function ingestImageToLib(cat, opt){
  opt = opt || {};
  if (!_fsaHandle){ toast('还没连接本地数据目录，图片存不下来'); return null; }
  await loadImgIndex();
  var src = opt.src || '';
  var bytes = opt.bytes || null, ext = (opt.ext || 'jpg').toLowerCase();
  if (!bytes && src){
    var got = await fetchImageBytes(src);
    if (!got) return null;
    bytes = got.bytes; ext = got.ext;
  }
  if (!bytes || !bytes.length) return null;
  var hash = hashBytes(bytes);
  /* —— 查重：同一张图只存第一次，后面全部引用第一次那份 —— */
  var hit = imgIndexHit(src, hash);
  if (hit){ return { rel: hit, reused: true }; }
  var parts;
  if (opt.coverDir){
    parts = splitRelPath(opt.coverDir);            /* 实体(IP/系列)封面：维持原单文件夹行为 */
  } else {
    var _cinfo = coverBaseParts(cat, opt.row);
    parts = await pickCoverFolder(_cinfo);
  }
  var okDir = await _fsaGetDir([IMG_DIR].concat(parts), true);
  if (!okDir){ toast('创建图片文件夹失败：' + parts.join('/')); return null; }
  var seq = await scanMaxImageSeqFor(parts);
  var bn = safeFileName(opt.baseName || cat);
  var rel = '', ok = false;
  var pn = safeFileName(opt.namePrefix || cat);
  for (var t = 0; t < 60; t++){
    seq++;
    var name = pn + '-' + (bn ? bn + '-' : '') + pad4(seq) + '.' + ext;
    var relTry = DATA_PREFIX + '/' + IMG_DIR + '/' + parts.join('/') + '/' + name;
    var dup = await fsGetFileHandleAt(relToFsParts(relTry).join('/'), false);
    if (dup) continue;                 /* 极端情况：同名已存在，跳号 */
    ok = await _fsaWriteBinary([IMG_DIR].concat(parts), name, bytes);
    if (ok){ rel = relTry; break; }
    seq--; break;
  }
  if (!ok || !rel) return null;
  imgIndexPut(rel, hash, src, bytes.length, ext);
  _imgUrlCache[rel] = src || URL.createObjectURL(new Blob([bytes]));
  await saveImgIndex();
  return { rel: rel, reused: false };
}
/* 扫描某个类目封面文件夹内已有的最大编号（按项目独立编号） */
async function scanMaxImageSeqFor(dirName){
  var parts = Array.isArray(dirName) ? dirName : String(dirName || '').split('/').filter(Boolean);
  var max = 0;
  try {
    var dir = await _fsaGetDir([IMG_DIR].concat(parts), false);
    if (dir){
      /* File System Access API 的迭代器。
         文件名形如「去过的地方-0001.jpg」，数字在中间（前缀是中文+连字符），
         必须用 /-(\d+)\.[^.]+$/ 提取末尾编号，而不是 ^(\d+)\. （要求以数字开头，永远匹配不到）。 */
      if (typeof dir.entries === 'function'){
        for await (var [name] of dir.entries()){
          var mm = /-(\d{1,})\.[^.]+$/i.exec(name);
          if (mm){ var v = parseInt(mm[1], 10); if (isFinite(v) && v > max) max = v; }
        }
      } else if (typeof dir.values === 'function'){
        for await (var fh of dir.values()){
          var name = fh.name || '';
          var mm = /-(\d{1,})\.[^.]+$/i.exec(name);
          if (mm){ var v = parseInt(mm[1], 10); if (isFinite(v) && v > max) max = v; }
        }
      }
    }
  } catch(e){}
  return max;
}
/* 取一条记录最像「名字」的字段，用于封面文件命名（如 电影-千与千寻-0001.jpg） */
function rowDisplayName(r){
  if (!r) return '';
  var keys = ['名称','计划','地点','店名','菜名','菜谱名','IP名称','系列名称','地点名称','内容'];
  for (var i=0;i<keys.length;i++){
    var v = String(r[keys[i]] || '').trim();
    if (v) return safeFileName(v);
  }
  return '';
}
/* 保存前：把 base64 或外链图片都落到本地磁盘，row 内改为相对路径。
   文件名 {类目}-{条目名}-0001.jpg / {类目}-{条目名}-0002.jpg …
   （条目名可缺省，例如批量导入时），在每个类目文件夹内独立递增，
   避免 ip-封面 第一张变成 ip-0005 这种跨目录跳号。 */
async function externalizeImages(cat, rows, startSeq, opts){
  if (!_fsaHandle || !rows || !rows.length) return startSeq;
  var cinfo;
  if (opts && opts.coverDir){ cinfo = { base: splitRelPath(opts.coverDir), prefix: '', cat: cat, isSeries: false, entity: true }; }
  else { cinfo = coverBaseParts(cat, (rows && rows[0]) || null); }
  var prefix = (opts && opts.namePrefix) ? safeFileName(opts.namePrefix) : safeFileName(cat);
  var lastSeq = 0;
  await loadImgIndex();
  var _idxDirty = false;
  for (var i = 0; i < rows.length; i++){
    var r = rows[i]; if (!r) continue;
    for (var j = 0; j < IMG_FIELDS.length; j++){
      var arr = r[IMG_FIELDS[j]];
      if (!arr || !arr.length) continue;
      for (var k = 0; k < arr.length; k++){
        var it = arr[k]; if (!it || !it.imageUrl) continue;
        var u = String(it.imageUrl);
        var isData = (u.indexOf('data:image/') === 0);
        var isRemote = /^https?:/i.test(u);
        if (!isData && !isRemote) continue;          /* 已经是本地相对路径 */
        var bytes = null, ext = 'jpg';
        if (isData){
          ext = (u.indexOf('image/png') >= 0) ? 'png' : 'jpg';
          bytes = dataUrlToBytes(u);
        } else {
          var got = await fetchImageBytes(u);
          if (!got){
            /* 外链取不到（防盗链 / 国内访问不了，如 gstatic.com）：保留原链接，不阻断保存 */
            _imgFetchFailed++;
            console.warn('外链图片下载失败，保留原链接：', u.slice(0, 80));
            continue;
          }
          bytes = got.bytes; ext = got.ext;
        }
        if (!bytes || !bytes.length) continue;
        /* —— v67 去重：这张图（同一个外链 / 同一份内容）已经在图库里了，
              就不再存第二份，直接引用第一次存的那份 —— */
        var hsh = hashBytes(bytes);
        var hit = imgIndexHit(u, hsh);
        if (hit){
          _imgUrlCache[hit] = u;
          it.imageUrl = hit;
          continue;
        }
        /* 每张图独立选择「当前还能放封面」的子文件夹（series / 非 series 规则） */
        var parts = cinfo.entity ? cinfo.base : await pickCoverFolder(cinfo);
        var seq = await scanMaxImageSeqFor(parts);
        seq++;
        var dn = rowDisplayName(r);
        /* 例：留声机-测试音乐-0001.jpg（条目名为空时退化为 留声机-0001.jpg） */
        var name = prefix + "-" + (dn ? dn + "-" : "") + pad4(seq) + "." + ext;
        var rel = DATA_PREFIX + '/' + IMG_DIR + '/' + parts.join('/') + '/' + name;
        /* 极端情况：同名文件已在（比如手工改过名），跳号再来 */
        var dupH = await fsGetFileHandleAt(relToFsParts(rel).join('/'), false);
        if (dupH){ seq++; name = prefix + "-" + (dn ? dn + "-" : "") + pad4(seq) + "." + ext; rel = DATA_PREFIX + '/' + IMG_DIR + '/' + parts.join('/') + '/' + name; }
        var ok = await _fsaWriteBinary([IMG_DIR].concat(parts), name, bytes);
        if (ok){
          _imgUrlCache[rel] = u;      /* 立刻可用：先用原图顶上，避免闪空白 */
          it.imageUrl = rel;          /* JSON 里只留相对路径 */
          imgIndexPut(rel, hsh, u, bytes.length, ext);
          _idxDirty = true;
          lastSeq = seq;
        }
      }
    }
  }
  if (_idxDirty) await saveImgIndex();
  return lastSeq;
}
/* 加载后：把相对路径解析成 blob URL 以便显示 */
async function readRelPathAsBlobUrl(rel){
  if (!_fsaHandle) return null;
  var parts = String(normalizeImgPath(rel)).split('/').filter(Boolean);
  if (parts.length < 2) return null;
  /* 去掉站点前缀 data/，剩下的才是相对于 FSA 数据目录的路径 */
  if (parts[0] === DATA_PREFIX) parts.shift();
  if (parts.length < 2) return null;
  var name = parts.pop();
  var dir = await _fsaGetDir(parts, false); if (!dir) return null;
  try {
    var fh = await dir.getFileHandle(name);
    var f = await fh.getFile();
    return URL.createObjectURL(f);
  } catch(e){ return null; }
}
/* 把 File 对象转成 data: URL（失败时兜底，避免封面整块空白） */
async function fileToDataUrl(f){
  try {
    var buf = await f.arrayBuffer();
    var bytes = new Uint8Array(buf);
    var bin = '';
    var CH = 0x8000;
    for (var i = 0; i < bytes.length; i += CH) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));
    var ext = String((f && f.name || '').split('.').pop() || 'jpg').toLowerCase();
    var mime = ext === 'png' ? 'image/png' : (ext === 'webp' ? 'image/webp' : (ext === 'gif' ? 'image/gif' : 'image/jpeg'));
    return 'data:' + mime + ';base64,' + btoa(bin);
  } catch(e){ return null; }
}
/* 兜底：blob 在某些情况下拿不到（如中文目录名 / 沙箱限制），改用 data: URL */
async function readRelPathAsDataUrl(rel){
  if (!_fsaHandle) return null;
  var parts = String(normalizeImgPath(rel)).split('/').filter(Boolean);
  if (parts.length < 2) return null;
  if (parts[0] === DATA_PREFIX) parts.shift();
  if (parts.length < 2) return null;
  var name = parts.pop();
  var dir = await _fsaGetDir(parts, false); if (!dir) return null;
  try {
    var fh = await dir.getFileHandle(name);
    return fileToDataUrl(await fh.getFile());
  } catch(e){ return null; }
}
/* 图片文件名 → 文件句柄 的索引（遍历 data/images 建立一次，供「按文件名模糊兜底」用，
   这样即使目录名/前缀因历史遗留对不上，也能凭文件名把封面显示出来） */
var _imgNameIndex = null;
async function ensureImageIndex(){
  if (_imgNameIndex || !_fsaHandle) return;
  _imgNameIndex = {};
  try {
    var root = await _fsaGetDir([IMG_DIR], false);
    if (!root) return;
    var list = await walkDirFiles(root, '', []);
    for (var i = 0; i < list.length; i++){
      var nm = String(list[i].rel || '').split('/').pop();
      if (nm) _imgNameIndex[nm] = list[i].handle;
    }
  } catch(e){ _imgNameIndex = _imgNameIndex || {}; }
}
/* 三层兜底解析一张封面：精确 blob → 精确 data → 按文件名模糊（用索引里的句柄直读） */
async function resolveOneImage(u){
  if (!u) return null;
  var name = String(u).split('/').pop();
  var bu = await readRelPathAsBlobUrl(u);
  if (bu) return bu;
  bu = await readRelPathAsDataUrl(u);
  if (bu) return bu;
  await ensureImageIndex();
  var h = _imgNameIndex && _imgNameIndex[name];
  if (h){
    try { var f = await h.getFile(); if (f) return URL.createObjectURL(f); } catch(_){}
    try { var f2 = await h.getFile(); if (f2) return await fileToDataUrl(f2); } catch(_){}
  }
  return null;
}
async function resolveImagesFor(rows){
  if (!rows || !rows.length) return;
  /* 1) 先把所有待解析的相对路径收集起来并去重（同一张图被多条记录引用时只解析一次） */
  var all = [];
  function push(u){
    if (!u) return;
    if (/^(data|blob):/.test(u) || /^https?:/i.test(u)) return;
    if (_imgUrlCache[u]) return;
    if (all.indexOf(u) < 0) all.push(u);
  }
  for (var i = 0; i < rows.length; i++){
    var r = rows[i]; if (!r) continue;
    for (var j = 0; j < IMG_FIELDS.length; j++){
      var arr = r[IMG_FIELDS[j]];
      if (!arr || !arr.length) continue;
      for (var k = 0; k < arr.length; k++){
        var it = arr[k]; if (!it || !it.imageUrl) continue;
        push(normalizeImgPath(it.imageUrl));
      }
    }
    /* 打卡点的封面是字符串字段「封面图片」（非数组），同样需要解析成可显示 URL */
    push(normalizeImgPath(r['封面图片'] || ''));
  }
  if (!all.length) return;
  /* 2) v75fix perf：分块并发解析。
        原来是「一条记录 → 逐张 await」的串行，图片一多就把主线程拖死（表现就是整页卡在读取中）。
        改成每批 8 张并发，并把去重后的总数最小化。 */
  var CONC = 8;
  for (var s = 0; s < all.length; s += CONC){
    var batch = all.slice(s, s + CONC);
    await Promise.all(batch.map(async function(u){
      if (_imgUrlCache[u]) return;
      if (_fsaHandle){
        /* FSA 模式：用文件句柄解析（含文件名模糊兜底） */
        var bu = await resolveOneImage(u);
        if (bu) _imgUrlCache[u] = bu;
      } else {
        /* 非 FSA（local / gh / 静态托管）：用 fetch 把相对路径转成 blob，保证能显示 */
        try {
          var resp = await fetch(u);
          if (resp && resp.ok){ var bl = await resp.blob(); _imgUrlCache[u] = URL.createObjectURL(bl); }
        } catch(_){ /* 取不到就保留原相对路径，浏览器自行尝试 */ }
      }
    }));
  }
}

/* ---------- GitHub Pages 静态直读（手机端）----------
   站点本身就是静态托管，data/ 下的 json 可以直接 fetch，不需要 Token、
   也不经过 api.github.com（国内常超时）。分片模式下会按主索引逐个拉类目文件。 */
async function fetchJSONRel(url){
  try {
    var r = await fetch(_bustUrl(url), { cache: 'no-store' });
    if (!r || !r.ok) return null;
    var t = await r.text();
    if (!t || !t.trim()) return null;
    return JSON.parse(t);
  } catch(e){ return null; }
}
async function ghStaticLoadV2(){
  try {
    /* 用绝对地址拼目录，避免页面无尾斜杠 / 基址异常时相对路径解析错位（会 404 → 回退到 api.github.com 触发 422） */
    var _base = String(location.href.split('#')[0]);
    if (_base.charAt(_base.length - 1) !== '/') _base += '/';
    var _rel = String(GH.path || 'data/lifedesk.json').replace(/[\\/][^\\/]*$/, '') || 'data';
    var dir = new URL(_rel + '/', _base).href;   /* 例：https://ciaorz.github.io/life-desk/data/ */
    var idx = await fetchJSONRel(dir + 'lifedesk.json');
    if (!idx || idx.schema !== SCHEMA_V2) return null;             /* 不是分片格式 → 走原 API 逻辑 */
    idx = normalizeIndex(idx);   /* gh 静态直读也做一次结构自愈（修正书籍等分片路径、补齐分组标记），只读、不写盘 */
    var out = {};
    Object.keys(idx.__main || {}).forEach(function(mk){ out[mk] = (idx.__main[mk] || []).slice(); });

    /* v83 优化：分片与实体文件改为【并发】抓取（Promise.all）。
       原实现用 for + await 串行，~38 个文件要排队等 38 个往返；改为并发后，
       首屏等待时间 ≈ 最慢单个文件，而非全部之和。先发全部请求，再统一合并，
       合并逻辑与串行版本完全一致，行为不变。 */
    var tasks = [];
    var cats = Object.keys(idx.shards || {});
    for (var i = 0; i < cats.length; i++){
      (function(c){
        var sh = idx.shards[c] || {};
        if (sh.dirShard) return;          /* ip/series 是目录分片，没有单一 file，改走下方 entityFiles 清单 */
        tasks.push(
          fetchJSONRel(dir + (sh.file || shardFileName(c))).then(function(obj){
            return { mk: sh.module || (obj && obj.module), rows: obj && obj.rows };
          })
        );
      })(cats[i]);
    }
    /* 目录分片（ip / series）：每个实体一个文件，静态托管又不能列目录，
       因此按主索引里的 entityFiles 清单逐个拉取这些文件并合并进对应模块。 */
    var ef = idx.entityFiles || [];
    for (var ei = 0; ei < ef.length; ei++){
      (function(efp){
        tasks.push(
          fetchJSONRel(dir + efp).then(function(eo){
            return { mk: eo && eo.module, rows: eo && eo.rows };
          })
        );
      })(ef[ei]);
    }
    var results = await Promise.all(tasks);
    for (var ri = 0; ri < results.length; ri++){
      var r = results[ri];
      if (!r || !r.mk || !r.rows) continue;
      if (!out[r.mk]) out[r.mk] = [];
      out[r.mk] = out[r.mk].concat(r.rows);
    }
    /* 图片相对路径在静态站点上可直接用，记录一下来源目录便于解析 */
    _staticImgBase = dir;
    return out;
  } catch(e){ return null; }
}
var _staticImgBase = '';

/* ---------- GitHub 批量上传（分片 + 图片）----------
   分片模式下要推的文件变多：主索引 + 每个类目 json + images/ 下的图片。
   逐个走 Contents API（PUT），带进度回调。文件特别多时建议直接用 git push 更快。 */
function ghContentsUrl(path){
  return ghApiBase() + '/repos/' + GH.owner + '/' + GH.repo + '/contents/' + path + '?ref=' + (GH.branch || 'main');
}
function utf8ToBase64(str){
  return btoa(unescape(encodeURIComponent(String(str))));
}
async function blobToBase64(blob){
  var buf = await blob.arrayBuffer();
  var bytes = new Uint8Array(buf), bin = '';
  var CH = 0x8000;
  for (var i = 0; i < bytes.length; i += CH){
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));
  }
  return btoa(bin);
}
/* 上传单个文件（自动带 sha 覆盖） */
async function ghPutFile(path, textOrBlob){
  var url = ghContentsUrl(path);
  var sha = null;
  try {
    var rg = await fetch(url, { headers: ghHeaders() });
    if (rg && rg.ok){ var jg = await rg.json(); sha = (jg && jg.sha) || null; }
  } catch(e){}
  var b64 = (typeof textOrBlob === 'string') ? utf8ToBase64(textOrBlob) : await blobToBase64(textOrBlob);
  var body = { message: 'update ' + path, content: b64, branch: (GH.branch || 'main') };
  if (sha) body.sha = sha;
  var r = await fetch(url, { method: 'PUT', headers: ghHeaders({ 'Content-Type': 'application/json' }), body: JSON.stringify(body) });
  return !!(r && r.ok);
}
/* 遍历 images/ 目录，收集图片文件 */
async function walkDirFiles(dirHandle, prefix, out){
  var entries = [];
  try {
    var it = dirHandle.entries();
    var e = await it.next();
    while (!e.done){ entries.push(e.value); e = await it.next(); }
  } catch(err){ return out; }
  for (var i = 0; i < entries.length; i++){
    var name = entries[i][0], h = entries[i][1];
    if (h.kind === 'directory'){ await walkDirFiles(h, prefix + name + '/', out); }
    else out.push({ rel: prefix + name, handle: h });
  }
  return out;
}
/* 增量上传辅助：拉取 GitHub 上 data/images/ 的远端文件大小清单（path -> size）。
   用 Git Trees API（recursive=1）一次性取整棵树，按前缀过滤成图片清单。
   失败或返回被截断时返回空对象 → 调用方降级为全量上传，绝不丢文件。 */
async function ghRemoteImageSizes(){
  var m = {};
  try {
    var br = encodeURIComponent(GH.branch || 'main');
    var url = ghApiBase() + '/repos/' + GH.owner + '/' + GH.repo + '/git/trees/' + br + '?recursive=1';
    var r = await fetch(url, { headers: ghHeaders() });
    if (!r.ok) return m;
    var j = await r.json();
    if (!j || !j.tree || j.truncated) return m;     /* 截断则放弃 diff，全量上传最安全 */
    var prefix = (String(GH.path || '').replace(/[\\/][^\\/]*$/, '') || 'data') + '/' + IMG_DIR + '/';
    for (var i = 0; i < j.tree.length; i++){
      var e = j.tree[i];
      if (e && e.type === 'blob' && typeof e.path === 'string' && e.path.indexOf(prefix) === 0){
        m[e.path] = (typeof e.size === 'number') ? e.size : -1;
      }
    }
  } catch(e){}
  return m;
}
/* 收集本次需要上传的全部文件 */
async function collectPushFiles(){
  var idx = await fsReadIndex();
  var dir = String(GH.path || '').replace(/[\\/][^\\/]*$/, '') || 'data';
  var files = [];
  files.push({ path: GH.path, text: JSON.stringify(idx, null, 2) });
  var cats = Object.keys(idx.shards || {});
  for (var i = 0; i < cats.length; i++){
    var sh = idx.shards[cats[i]] || {};
    if (sh.dirShard) continue;            /* ip/series 目录分片走下方 entityFiles 清单 */
    var obj = await fsReadJSON(sh.file || shardFileName(cats[i]));
    if (!obj) continue;
    files.push({ path: dir + '/' + (sh.file || shardFileName(cats[i])), text: JSON.stringify(obj, null, 2) });
  }
  /* 目录分片（ip/series）实体文件：直接扫描真实目录纳入上传，不再依赖可能过期的 entityFiles 清单 */
  var efList = (idx.entityFiles || []).slice();
  try { efList = efList.concat(await entityExistingFiles('ip')); } catch(e){}
  try { efList = efList.concat(await entityExistingFiles('series')); } catch(e){}
  var _efSeen = {};
  for (var ei = 0; ei < efList.length; ei++){
    var _efp = efList[ei];
    if (!_efp || _efSeen[_efp]) continue;
    _efSeen[_efp] = 1;
    try {
      var efObj = await fsReadJSON(_efp);
      if (efObj) files.push({ path: dir + '/' + _efp, text: JSON.stringify(efObj, null, 2) });
    } catch(e){}
  }
  /* 图片（增量上传：先拉远端 images 清单，仅上传「本地有而远端没有」或「大小变化」的图片，
     未变更的封面直接跳过，避免每次全量重传几百 MB / 触发限流） */
  _ghIncrSkip = 0;
  try {
    var imgDir = await _fsaGetDir([IMG_DIR], false);
    if (imgDir){
      var remoteSizes = await ghRemoteImageSizes();
      var list = await walkDirFiles(imgDir, '', []);
      for (var j = 0; j < list.length; j++){
        var rel = list[j].rel;
        var rpath = dir + '/' + IMG_DIR + '/' + rel;
        var f = await list[j].handle.getFile();
        var rsz = remoteSizes[rpath];
        if (rsz != null && rsz === f.size){ _ghIncrSkip++; continue; }   /* 远端已有且大小一致 → 跳过 */
        files.push({ path: rpath, blob: f });
      }
      if (_ghIncrSkip) console.log('[增量上传] 跳过未变更封面 ' + _ghIncrSkip + ' 张，仅上传新增/改动');
    }
  } catch(e){}
  return files;
}
/* 批量上传，带进度回调 onProgress(done, total)。
   若传入 files（已收集好的清单）则直接上传；否则先 collectPushFiles() 收集。 */
async function ghPushAll(onProgress, files){
  if (!files) files = await collectPushFiles();
  if (!files.length) return { ok:true, n:0 };
  var okCount = 0;
  for (var i = 0; i < files.length; i++){
    var f = files[i];
    var ok = await ghPutFile(f.path, (f.blob != null) ? f.blob : f.text);
    if (ok) okCount++;
    if (onProgress) onProgress(i + 1, files.length, ok, f.path);
  }
  return { ok: okCount === files.length, n: files.length, okCount: okCount };
}

/* v84：上传前人工审核弹窗——列出本次要上传的文件清单，只有勾选的项才真正上传 */
function showUploadReview(files, onConfirm){
  if (!files || !files.length){ toast('没有需要上传的文件'); if (onConfirm) onConfirm(null); return; }
  var ov = document.createElement('div');
  ov.className = 'backdrop'; ov.style.zIndex = 300;
  function rowHTML(f, i){
    var sz = (f.blob && f.blob.size != null) ? f.blob.size : (f.text != null ? new Blob([f.text]).size : 0);
    return '<label class="ur-row" style="display:flex;align-items:center;gap:10px;padding:7px 9px;border-radius:10px;cursor:pointer">'+
      '<input type="checkbox" class="ur-cb" data-i="'+i+'" checked style="flex:0 0 auto;width:17px;height:17px;accent-color:var(--accent)">'+
      '<span style="flex:1;min-width:0;font-size:12.5px;line-height:1.45;word-break:break-all;color:var(--ink)">'+esc(f.path)+'</span>'+
      '<span style="flex:0 0 auto;color:var(--muted);font-size:11px;white-space:nowrap">'+fmtSize(sz)+'</span>'+
    '</label>';
  }
  ov.innerHTML =
    '<div class="sheet" style="max-width:520px">'+
      '<div class="sheet-head"><div><p>上传前审核</p><h2>请勾选要上传的文件</h2></div></div>'+
      '<div style="font-size:12.5px;color:var(--ink-soft);line-height:1.7;margin-bottom:10px">下面列出本次将上传到 GitHub 的文件（已按增量规则排除未变更的封面）。<b>只有勾选的项才会真正上传</b>，取消勾选即可跳过你不想传的文件。</div>'+
      '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px">'+
        '<button type="button" class="btn ghost sm" id="urAll">全选</button>'+
        '<button type="button" class="btn ghost sm" id="urNone">全不选</button>'+
        '<span id="urCount" style="margin-left:auto;font-size:12px;color:var(--muted)"></span>'+
      '</div>'+
      '<div id="urList" style="max-height:48vh;overflow-y:auto;border:1px solid var(--line);border-radius:12px;padding:6px;background:var(--card)"></div>'+
      '<div class="sheet-actions">'+
        '<button type="button" class="btn ghost" id="urCancel">取消</button>'+
        '<button type="button" class="btn primary" id="urOk">确认上传</button>'+
      '</div>'+
    '</div>';
  document.body.appendChild(ov);
  var list = ov.querySelector('#urList');
  list.innerHTML = files.map(rowHTML).join('');
  function updateCount(){
    var n = list.querySelectorAll('.ur-cb:checked').length;
    var c = ov.querySelector('#urCount');
    if (c) c.textContent = '已选 ' + n + ' / ' + files.length + ' 个';
    var ok = ov.querySelector('#urOk');
    if (ok) ok.textContent = '确认上传' + (n ? ' (' + n + ')' : '');
  }
  ov.querySelectorAll('.ur-cb').forEach(function(cb){ cb.addEventListener('change', updateCount); });
  ov.querySelector('#urAll').onclick = function(){ list.querySelectorAll('.ur-cb').forEach(function(cb){ cb.checked = true; }); updateCount(); };
  ov.querySelector('#urNone').onclick = function(){ list.querySelectorAll('.ur-cb').forEach(function(cb){ cb.checked = false; }); updateCount(); };
  function close(){ try{ ov.remove(); }catch(e){} }
  ov.onclick = function(e){ if (e.target === ov) close(); };
  ov.querySelector('#urCancel').onclick = close;
  ov.querySelector('#urOk').onclick = function(){
    var sel = [];
    list.querySelectorAll('.ur-cb').forEach(function(cb){ if (cb.checked) sel.push(files[Number(cb.getAttribute('data-i'))]); });
    close();
    if (!sel.length){ toast('未勾选任何文件，已取消上传'); if (onConfirm) onConfirm(null); return; }
    if (onConfirm) onConfirm(sel);
  };
  updateCount();
}

/* 分片感知的 GitHub 保存（gh 模式、无本地文件时，如 iPhone 网页端）：
   把内存 store 里每个「常规模块」序列化回对应分片文件 PUT 上去；
   主索引 lifedesk.json 仅同步一次确保仍是分片格式（不被覆盖成 consolidated）；
   ip / series 是目录分片（dirShard），手机端不写，避免损坏。 */
async function ghSaveShardedFromStore(cb){
  var dir = String(GH.path||'').replace(/[\\/][^\\/]*$/, '') || 'data';
  if (dir.charAt(0) !== '/' && dir.indexOf('://') < 0) dir = './' + dir;
  if (dir.charAt(dir.length - 1) !== '/') dir += '/';
  try {
    var r = await fetch(ghFileUrl(), { headers: ghHeaders() });
    if (!r.ok) throw new Error('idx-status-' + r.status);
    var j = await r.json();
    var idx = j.content ? JSON.parse(b64decodeUtf8(j.content)) : null;
    if (!idx || idx.schema !== SCHEMA_V2 || !idx.shards){ return ghSaveAll(snapshotAll(), cb); }
    /* 同步主索引（保持 schema/shards 不变，防止被覆盖成 consolidated） */
    await ghPutFile(GH.path, JSON.stringify(idx, null, 2));
    /* 逐分片写入：每个分片对应一个类目，rows 必须按 shardCatOf 拆分，
       不能把整个 module 的 rows 直接写进一个文件（collection 是按大类/小类拆分的）。 */
    var total = 0, ok = 0;
    var cats = Object.keys(idx.shards);
    for (var ci = 0; ci < cats.length; ci++){
      var cat = cats[ci];
      var sh = idx.shards[cat] || {};
      if (sh.dirShard) continue;            /* ip / series 目录分片：手机端不写，避免损坏 */
      var file = sh.file || shardFileName(cat);
      var obj = null;
      try {
        var rr = await fetch(ghContentsUrl(dir + file), { headers: ghHeaders() });
        if (rr.ok){ var jj = await rr.json(); if (jj.content) obj = JSON.parse(b64decodeUtf8(jj.content)); }
      } catch(e){}
      if (!obj) obj = {};
      var mk = sh.module || obj.module || cat;
      var allRows = (store[mk] && store[mk].rows) || [];
      obj.rows = allRows.filter(function(r){ return shardCatOf(mk, r) === cat; });
      obj.module = mk;
      if (obj.schema !== SCHEMA_V2) obj.schema = SCHEMA_V2;
      var okf = await ghPutFile(dir + file, JSON.stringify(obj, null, 2));
      total++; if (okf) ok++;
    }
    if (cb) cb(ok === total);
    return { ok: ok === total, n: total, okCount: ok };
  } catch(e){
    if (cb) cb(false);
    return { ok:false, n:0 };
  }
}
/* ---------- 数据目录 README ----------
   原来页面顶部那条「已连接 GitHub 仓库…」长说明，改为写进数据目录的 README.md：
   既能在 GitHub 上直接看到说明，也列出当前有哪些数据文件、封面编号用到几号，
   方便判断往仓库里还要补传哪些文件。 */
async function fsWriteText(name, text){
  if (!_fsaHandle) return false;
  try {
    var fh = await _fsaHandle.getFileHandle(name, { create: true });
    var w = await fh.createWritable();
    await w.write(text);
    await w.close();
    return true;
  } catch(e){ return false; }
}
async function writeReadme(){
  if (!_fsaHandle) return false;
  var idx = await fsReadIndex();
  var L = [];
  L.push('# 日常集 · 数据目录');
  L.push('');
  L.push('> 这个 README 所在的位置，就是你在应用里选择的数据目录。所有数据文件都在这个文件夹里。');
  L.push('');
  L.push('## 文件结构');
  L.push('');
  L.push('```');
  L.push('（数据目录）/');
  L.push('├── README.md              ← 本文件');
  L.push('├── lifedesk.json          ← 主索引（类目清单 + 下一个封面编号）');
  L.push('├── 唱片-data.json          ← 每个类目一个数据文件');
  L.push('├── 去过的地方-data.json');
  L.push('├── lifedesk.backup.json   ← 拆分前的原始备份（确认无误后可删）');
  L.push('└── images/');
  L.push('    └── 唱片-封面/          ← 每个类目一个封面文件夹');
  L.push('        ├── 唱片-0001.jpg   ← 命名：类目-编号');
  L.push('        └── 唱片-0002.jpg');
  L.push('```');
  L.push('');
  L.push('## 当前类目文件');
  L.push('');
  var cats = Object.keys(idx.shards || {});
  if (cats.length){
    L.push('| 类目 | 数据文件 | 封面目录 | 条目数 |');
    L.push('| --- | --- | --- | --- |');
    for (var i = 0; i < cats.length; i++){
      var sh = idx.shards[cats[i]] || {};
      var obj = await fsReadJSON(sh.file || shardFileName(cats[i]));
      var n = (obj && obj.rows) ? obj.rows.length : 0;
      L.push('| ' + cats[i] + ' | `' + (sh.file || '') + '` | `images/' + (sh.coverDir || coverDirName(cats[i])) + '/` | ' + n + ' |');
    }
  } else {
    L.push('（还没有拆分类目文件，全部数据都在 `lifedesk.json` 里）');
  }
  L.push('');
  L.push('## 封面图片编号');
  L.push('');
  L.push('当前已用到 **' + pad4(idx.imgSeq || 0) + '**。');
  L.push('');
  L.push('命名规则：`{类目}-0001.jpg`，编号在每个 `images/{类目}-封面/` 文件夹内独立递增。');
  L.push('');
  L.push('所以往 GitHub 补传时，只要看仓库里已经存在到几号，从下一个号开始传就行，');
  L.push('已经传过的不用重复传。');
  L.push('');
  L.push('## 手动上传到 GitHub（不用 Token）');
  L.push('');
  L.push('1. 打开你的仓库，进入要存放数据的目录（例如 `data/`）');
  L.push('2. 点右上角的 **Add file → Upload files**');
  L.push('3. 从**本文件夹**里把文件拖进去：');
  L.push('   - `lifedesk.json`（主索引，有变动就要传）');
  L.push('   - 各个 `{类目}-data.json`');
  L.push('   - `images/` 下的封面文件夹（只传新增编号的那些）');
  L.push('4. 点 **Commit changes**');
  L.push('');
  L.push('> 也可以在本地把这个数据目录当成 git 仓库，用 `git add . && git commit && git push` 一次推完。');
  L.push('');
  L.push('## 手机端查看');
  L.push('');
  L.push('手机端打开站点后，会直接读取仓库里的静态文件（不需要 Token）。');
  L.push('如果看不到最新内容，确认一下 `lifedesk.json` 和对应类目文件都已经传上去了，然后刷新页面。');
  L.push('');
  return await fsWriteText('README.md', L.join('\n'));
}

/* ---------- 通用确认弹窗（居中卡片，两个按钮）---------- */
function confirmDialog(title, msgHTML, okLabel, onOk, cancelLabel){
  var ov = document.createElement('div');
  ov.className = 'backdrop'; ov.style.zIndex = 200;
  ov.innerHTML =
    '<div class="sheet" style="max-width:360px">'+
      '<div class="sheet-head"><div><p>数据文件</p><h2>'+esc(title)+'</h2></div></div>'+
      '<div style="padding:0 18px 16px;font-size:13px;line-height:1.75;color:var(--ink-soft)">'+msgHTML+'</div>'+
      '<div style="display:flex;gap:8px;padding:0 18px 18px">'+
        '<button type="button" class="btn primary" id="cfOk" style="flex:1">'+esc(okLabel)+'</button>'+
        '<button type="button" class="btn ghost" id="cfNo" style="flex:1">'+esc(cancelLabel||'暂不')+'</button>'+
      '</div>'+
    '</div>';
  document.body.appendChild(ov);
  function close(){ try { ov.remove(); } catch(e){} }
  ov.onclick = function(e){ if (e.target === ov) close(); };
  var ok = $('cfOk'), no = $('cfNo');
  if (ok) ok.onclick = function(){ close(); if (onOk) onOk(); };
  if (no) no.onclick = close;
}

/* ---------- v1 单文件 → v2 分片 迁移 ---------- */
async function migrateToShards(){
  var old = await new Promise(function(res){ localfsRead(function(o){ res(o || {}); }); });
  if (!old || !Object.keys(old).length) return { ok:false, reason:'empty' };
  /* 先备份原文件 */
  var backupName = 'lifedesk.backup.json';
  var okBak = await fsWriteJSON(backupName, old);
  if (!okBak) return { ok:false, reason:'backup-failed' };

  var idx = normalizeIndex(null);
  var buckets = {};
  Object.keys(old).forEach(function(mk){
    (old[mk] || []).forEach(function(r){
      var cat = shardCatOf(mk, r);
      if (!cat) return;                       /* 无类目的留在主文件 */
      if (!buckets[cat]) buckets[cat] = { module: mk, rows: [] };
      buckets[cat].rows.push(r);
    });
  });
  var n = 0;
  for (var cat in buckets){
    if (!Object.prototype.hasOwnProperty.call(buckets, cat)) continue;
    var file = shardFileName(cat);
    idx.shards[cat] = { file: file, module: buckets[cat].module, coverDir: coverDirName(cat) };
    try { await _fsaGetDir([IMG_DIR, coverDirName(cat)], true); } catch(e){}
    await externalizeImages(cat, buckets[cat].rows);
    await fsWriteJSON(file, {
      schema: SCHEMA_V2, cat: cat, module: buckets[cat].module, rows: buckets[cat].rows
    });
    n++;
  }
  /* 主文件保留没有类目的记录 */
  Object.keys(old).forEach(function(mk){
    idx.__main[mk] = (old[mk] || []).filter(function(r){ return !shardCatOf(mk, r); });
  });
  var okIdx = await fsWriteIndex(idx);
  if (!okIdx) return { ok:false, reason:'index-failed' };
  _shardMode = true;
  await writeReadme();   /* 拆分完立刻写一份说明文件，方便知道文件都在哪、封面用到几号 */
  return { ok:true, shards:n, backup:backupName };
}

/* ---------- 为某个类目新建专属数据文件 ---------- */
async function createShard(cat, mk){
  var idx = await fsReadIndex();
  idx.shards[cat] = { file: shardFileName(cat), module: mk, coverDir: coverDirName(cat) };
  await fsWriteIndex(idx);
  /* 同时把该类的封面文件夹建出来，后面新加的封面就落在里面 */
  try { await _fsaGetDir([IMG_DIR, coverDirName(cat)], true); } catch(e){}
  _shardMode = true;
  var ok = await saveLocalAll(snapshotAll());
  return { ok: ok, file: idx.shards[cat].file, coverDir: coverDirName(cat) };
}

/* 保存后检查：出现了还没有专属文件的新类目 → 询问是否新建 */
var _shardAskBusy = false;
async function maybeOfferNewShard(){
  if (_shardAskBusy || !_shardMode || MODE !== 'localfile') return;
  var idx = await fsReadIndex();
  var snap = snapshotAll();
  var missing = {};
  Object.keys(snap).forEach(function(mk){
    (snap[mk] || []).forEach(function(r){
      var cat = shardCatOf(mk, r);
      if (cat && !idx.shards[cat]) missing[cat] = mk;
    });
  });
  var cats = Object.keys(missing);
  if (!cats.length) return;
  _shardAskBusy = true;
  var cat = cats[0], mk = missing[cat];
  confirmDialog(
    '为「' + cat + '」新建数据文件',
    '这个类目还没有独立数据文件，条目目前存在主文件里。<br>'+
    '建一个专属文件（<b>' + esc(shardFileName(cat)) + '</b>）后，'+
    '它的封面图片会单独存在 <b>images/' + esc(coverDirName(cat)) + '/</b>（按 0001、0002 编号），可以存更多张，也不再挤占主文件。',
    '新建数据文件',
    async function(){
      var r = await createShard(cat, mk);
      _shardAskBusy = false;
      if (r.ok){ toast('已创建 ' + r.file + '（在目录 ' + (_fsaHandle ? _fsaHandle.name : '数据目录') + ' 里）'); loadAll(); }
      else toast('创建失败，请检查数据目录权限');
    },
    '先不用'
  );
  /* 用户直接关闭弹窗（点遮罩）时也要解锁 */
  setTimeout(function(){ _shardAskBusy = false; }, 30000);
}

/* 首次连上目录、且是旧的单文件格式时，询问是否拆分（只问一次） */
async function maybeOfferMigration(){
  if (_shardMode || MODE !== 'localfile') return;
  try { if (localStorage.getItem('lifedesk_shard_mig_dismissed')) return; } catch(e){}
  var old = await new Promise(function(res){ localfsRead(function(o){ res(o || {}); }); });
  if (!old || !Object.keys(old).length) return;
  var total = 0;
  Object.keys(old).forEach(function(k){ total += (old[k] || []).length; });
  if (total < 1) return;
  confirmDialog(
    '拆分数据文件',
    '当前所有数据都在一个 <b>lifedesk.json</b> 里（共 ' + total + ' 条）。<br>'+
    '拆成「每个类目一个文件」后，各类目可以单独存更多封面图片，手机端加载也更快。<br>'+
    '原文件会自动备份为 <b>lifedesk.backup.json</b>。',
    '立即拆分',
    async function(){
      var r = await migrateToShards();
      if (r && r.ok){ toast('已拆分出 ' + r.shards + ' 个类目文件，都在目录 ' + (_fsaHandle ? _fsaHandle.name : '数据目录') + ' 里'); loadAll(); }
      else toast('拆分失败：' + ((r && r.reason) || '未知原因'));
    },
    '以后再说'
  );
  try { localStorage.setItem('lifedesk_shard_mig_dismissed', '1'); } catch(e){}
}

/* ---------- 分片模式开关与统一读写入口 ---------- */
var _shardMode = false;   /* 主索引确认为 schema 2 时为 true */

/* 统一读取：自动识别单文件（v1）还是分片（v2），返回扁平快照 */
async function loadLocalAll(cb){
  var idx = await fsReadJSON(_LOCALFS_FILE);
  _shardMode = !!(idx && idx.schema === SCHEMA_V2);
  if (_shardMode){
    /* v67：先把 ip / 系列 / 书籍 的 data 收进各自文件夹、书籍按标签分类拆分，
       再统一加载 —— 顺序反了会读到迁移前的旧路径。 */
    await migrateGroupLayout();
    var merged = await storageLoadV2();
    cb(merged || {});
    maybeOfferNewShard();     /* 分片模式下：出现了新类目就问一句要不要建专属文件 */
    return;
  }
  localfsRead(function(obj){
    cb(obj || {});
    maybeOfferMigration();    /* 旧的单文件格式：询问是否拆分（只问一次） */
  });
}
/* 统一写入：按当前模式分派 */
async function saveLocalAll(snap, cb){
  var ok = _shardMode ? await storageSaveV2(snap)
                      : await new Promise(function(res){ localfsWrite(snap, res); });
  if (cb) cb(ok);
  return ok;
}

/* 本地保存（防抖），与 gh 的 queueGhSave 同语义 */
function queueLocalSave(){
  setGhStatus('saving');
  if (_fsaTimer) clearTimeout(_fsaTimer);
  _fsaTimer = setTimeout(async function(){
    _fsaTimer = null;
    var snap = snapshotAll();
    _imgFetchFailed = 0;
    var ok = await saveLocalAll(snap);
    _ghCache = snapshotAll();           /* 写完后内存视图与文件一致 */
    if (ok){ setGhStatus('localfile'); }
    else { setGhStatus('failed'); toast('写入本地数据目录失败'); }
    /* 外链图片没存成本地文件的，明确提示：这类链接手机端多半加载不出来 */
    if (_imgFetchFailed > 0){
      toast('有 ' + _imgFetchFailed + ' 张外链图片没能存到本地（多为国内访问不到），建议改用「上传」选本地图片');
      _imgFetchFailed = 0;
    }
  }, 400);
}

/* 选择/更换数据目录并连接：连接后若目录为空则把当前内存数据写入，避免切换丢数据 */
var _pickingDir = false;   /* v75fix perf：防连点——重复调用会让目录选择框唤不出来 */
async function pickFsaDirAndConnect(){
  if (_pickingDir) return;
  if (!('showDirectoryPicker' in window)){
    toast('当前浏览器不支持选择本地目录，请用 Chrome / Edge / Opera 桌面版打开');
    return;
  }
  _pickingDir = true;
  var h = null;
  try {
    /* 直接在事件处理链里调用 showDirectoryPicker，减少 await 层级，避免用户手势丢失 */
    h = await window.showDirectoryPicker({ mode:'readwrite' });
    _fsaHandle = h;
    await _fsaSaveHandle(h);
  } catch(e){
    _pickingDir = false;
    if (e && e.name === 'AbortError'){ toast('已取消选择目录'); return; }
    console.warn('选择目录失败', e);
    toast('选择目录失败：' + ((e && (e.message || e.name)) || '未知错误') + '。请用 Chrome / Edge 桌面版打开，并避免在 iframe 内使用。');
    return;
  }
  if (!h){ _pickingDir = false; return; }
  MODE = 'localfile';
  var existing = await new Promise(function(res){ localfsRead(function(o){ res(o); }); });
  var isEmpty = !existing || Object.keys(existing).length === 0;
  if (isEmpty){ await new Promise(function(res){ localfsWrite(snapshotAll(), function(){ res(); }); }); }
  await writeReadme();   /* 连上目录就写一份说明文件，方便知道数据都放在哪 */
  setGhStatus('localfile');
  refreshFsaButtons();
  _pickingDir = false;    /* 释放防连点锁 */
  loadAll();
  toast('已连接本地数据目录：' + h.name + (isEmpty ? '（已把当前数据写入）' : '（已读取目录内数据）'));
}

/* 刷新「选择数据目录」按钮的文案/可见性，以及「下载云端到本地」按钮的显示 */
function refreshFsaButtons(){
  var b = $('fsaPick'); if (!b) return;
  var txt=b.querySelector('.dt-txt');
  if (!_FSA_SUPPORT){ b.style.display='none'; }
  else if (MODE === 'localfile' && _fsaHandle){
    b.style.display='inline-flex'; if(txt) txt.textContent='数据目录：' + _fsaHandle.name;
  } else {
    b.style.display='inline-flex'; if(txt) txt.textContent='选择数据目录';
  }
  var pull = $('ghPull');
  if (pull) pull.style.display = (MODE === 'localfile') ? 'inline-block' : 'none';
}

/* 用已保存的目录句柄重新连接（需用户手势授权），失败再回退到重新挑目录 */
async function reconnectFsaDir(){
  var h = await _fsaLoadHandle();
  if (!h){ toast('没有找到已保存的数据目录，请重新选择'); pickFsaDirAndConnect(); return; }
  try {
    var p = await h.queryPermission({ mode:'readwrite' });
    if (p !== 'granted'){ p = await h.requestPermission({ mode:'readwrite' }); }
    if (p === 'granted'){
      _fsaHandle = h;
      MODE = 'localfile';
      await writeReadme();
      setGhStatus('localfile');
      refreshFsaButtons();
      loadAll();
      toast('已重新连接数据目录：' + h.name);
      return;
    }
  } catch(e){ console.warn('重连数据目录失败', e); }
  toast('无法恢复权限，请重新选择数据目录');
  pickFsaDirAndConnect();
}

/* 首次（本会话）提示用户连接数据目录：有历史句柄则提示一键重连，否则提示挑目录 */
async function promptPickFsaDir(){
  if (!_FSA_SUPPORT) return;
  try { if (sessionStorage.getItem('fsaPrompted')) return; sessionStorage.setItem('fsaPrompted','1'); } catch(e){}
  var savedName = '';
  try { var h = await _fsaLoadHandle(); if (h) savedName = h.name || ''; } catch(e){}
  setTimeout(function(){
    if (savedName){
      toast('检测到上次连接的数据目录「'+savedName+'」，点这里一键重连', '重新连接', reconnectFsaDir);
    } else {
      toast('可把数据直接存到本机文件夹（无需服务器），点右下角「选择数据目录」', '选择目录', pickFsaDirAndConnect);
    }
  }, 1200);
}

/* 导出全部本地数据为 JSON 文件（备份 / 迁移用） */
function exportData(){
  var tables = ORDER.filter(function(k){ return k!=='overview'; }).concat(EXTRA);
  var data = { app:'life-desk', version:1, mode:MODE, exportedAt:new Date().toISOString(), tables:{} };
  tables.forEach(function(k){
    var rows = (store[k] && store[k].rows) ? store[k].rows : lsGet(k);
    data.tables[k] = rows;
  });
  var blob = new Blob([JSON.stringify(data, null, 2)], { type:'application/json' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'life-desk-data-' + new Date().toISOString().slice(0,10) + '.json';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(function(){ try{ URL.revokeObjectURL(a.href); }catch(e){} }, 2000);
  var n = 0; tables.forEach(function(k){ n += (data.tables[k]||[]).length; });
  toast('已导出 ' + tables.length + ' 张表（共 ' + n + ' 条）到 JSON 文件');
}
/* 从 JSON 文件导入数据，覆盖本地存储并刷新 */
function importData(){
  var inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'application/json,.json';
  inp.onchange = function(){
    var f = inp.files && inp.files[0]; if (!f) return;
    var rd = new FileReader();
    rd.onload = function(){
      try {
        var data = JSON.parse(rd.result);
        if (!data || !data.tables) throw new Error('bad');
        Object.keys(data.tables).forEach(function(k){ if (MODE!=='gh') lsSet(k, data.tables[k] || []); });
        if (MODE === 'gh' && GH && GH.token){
          ORDER.filter(function(k){ return k!=='overview'; }).concat(EXTRA).forEach(function(k){
            if (data.tables[k]){ if(!store[k]) store[k]={rows:[],status:'ok'}; store[k].rows = data.tables[k]; }
          });
          persistAll(function(){ loadAll(); });
          toast('数据已导入并同步到 GitHub');
        } else {
          loadAll();
          toast('数据已导入，页面已刷新');
        }
      } catch(e){ toast('导入失败：文件不是有效的 life-desk 数据'); }
    };
    rd.readAsText(f);
  };
  inp.click();
}
