/* 按当前 大类 返回 collection/av 实际要用的字段集；其它模块原样返回。
   注意：db 模式（Notion 线上表）字段固定，不能动态扩展，故仍用 MODS 里的通用 schema。 */
/* v69：自定义字段系统 —— 从 lifedesk.json.customFields 读取模块的扩展字段定义 */
function getCustomFields(module){
  try {
    var idx = _idxCache || {};
    return (idx.customFields && idx.customFields[module]) || [];
  } catch(e){ return []; }
}
async function saveCustomFieldsToIndex(module, fields){
  var idx = await fsReadIndex();
  if (!idx.customFields) idx.customFields = {};
  idx.customFields[module] = fields;
  await fsWriteIndex(idx);
}
/* 六大模块的可读名称（用于页面管理标题） */
var MODULE_LABELS = { collection:'藏品馆', av:'影音厅', travel:'遐方坞', food:'馐馔坊', study:'文渊斋', idea:'灵思阁' };
/* 各模块内置字段名列表（页面管理里只读展示，不可删） */
var BUILTIN_FIELDS = {
  collection:['名称','大类','小类','IP','系列','编号','购入日期','购入价格','购入渠道','存储地点','状态','短评','封面','照片'],
  av:['名称','大类','导演','主演','上映日期','观看日期','状态','评分','短评','封面'],
  travel:['名称','国家','地区','状态','心愿等级','日期','备注','封面','封面图片'],
  food:['名称','类型','城市','星级','打卡日期','短评','想再去','照片'],
  study:['名称','领域','状态','进度','目标日期','每日分钟','备注','封面'],
  idea:['内容','分类','来源','星标','记录日期','封面']
};
/* v75fix：内置字段改成「从模块实际使用的字段模板动态取」，别再写死。
   之前影音厅/文渊斋的页面管理显示的是一份跟实际录入界面不符的旧名单（看着像藏品馆的模板），
   自定义字段的「显示位置」下拉也跟着选错。 */
/* 返回字段定义对象数组。tpl = 指定录入模板（'' / 不传 = 各模板合并后的全集） */
function builtinFieldDefs(module, tpl){
  var out = [], seen = {};
  function add(fs){
    (fs || []).forEach(function(f){
      if (!f || !f.k || seen[f.k]) return;
      if (String(f.k).charAt(0) === '_') return;   /* 技术字段（如 _geo 地图）不给用户选位置 */
      seen[f.k] = 1; out.push(f);
    });
  }
  var m = MODS[module];
  if (tpl){
    /* 指定模板：只取这套录入表单真正会渲染的字段 */
    if (module === 'collection'){ if (tpl==='书籍') add(BOOK_FIELDS); else if (tpl==='杂志') add(MAG_FIELDS); }
    else if (module === 'av'){ if (tpl==='赏戏') add(MOVIE_FIELDS); else if (tpl==='留音') add(MUSIC_FIELDS); }
    if (!out.length && m && m.fields) add(m.fields);
  } else {
    if (m && m.fields) add(m.fields);
    /* 会按大类/标签切换模板的模块，把各套模板的字段都并进来 */
    if (module === 'av'){ add(MOVIE_FIELDS); add(MUSIC_FIELDS); }
    else if (module === 'study'){ add(BOOK_FIELDS); add(MAG_FIELDS); }
    else if (module === 'collection'){ add(BOOK_FIELDS); add(MAG_FIELDS); }
  }
  return out;
}
function builtinFieldsOf(module, tpl){
  var d = builtinFieldDefs(module, tpl);
  return d.length ? d.map(function(f){ return f.k; }) : (BUILTIN_FIELDS[module] || []);
}

/* ==========================================================================
   v76：内置字段的「显示 / 宽度」管理
   --------------------------------------------------------------------------
   配置存在 lifedesk.json 的 fieldLayout 里：
     { "av::赏戏": { "导演": {hide:1}, "上映年份": {w:1} }, "idea": { ... } }
   key = 模块名，或 模块::录入模板（collection 的 书籍/杂志、av 的 赏戏/留音）。

   隐藏的字段只从「录入表单」里剔除：不渲染、不校验必填。
   localUpsert 是以旧记录为底合并的，所以之前存过的值不会被清掉。
   ========================================================================== */
var FIELD_TPLS = { collection:['书籍','杂志'], av:['赏戏','留音'] };
/* 当前录入表单用的是哪套模板（'' = 模块通用表单）——必须与 activeFields 的分支保持一致 */
function fieldTplOf(key, vals){
  if (key === 'collection'){
    var c = String((vals && vals['大类']) || '');
    return (c === '书籍' || c === '杂志') ? c : '';
  }
  if (key === 'av'){
    var a = String((vals && vals['大类']) || '');
    if (a === '赏戏' || a === '戏' || a === '电影') return '赏戏';
    if (a === '留音' || a === '音' || a === '留声机') return '留音';
    return '';
  }
  return '';
}
function flKey(module, tpl){ return tpl ? (module + '::' + tpl) : String(module); }
var _flFallback = {};
function flAll(){
  var idx = _idxCache;
  if (idx && typeof idx === 'object'){
    if (!idx.fieldLayout || typeof idx.fieldLayout !== 'object') idx.fieldLayout = {};
    return idx.fieldLayout;
  }
  return _flFallback;
}
function getFieldLayout(module, tpl){ return flAll()[flKey(module, tpl)] || {}; }
/* 当前打开的表单所对应的布局配置（fieldHTML 里取宽度用） */
function curFieldLayout(){
  try {
    if (editing && editing.key) return getFieldLayout(editing.key, fieldTplOf(editing.key, editing.vals || {}));
  } catch(e){}
  return {};
}
function fieldIsHidden(f, lay){ var c = lay && lay[f.k]; return !!(c && c.hide); }
/* 字段占几格：1=25% 2=50% 3=75% 4=整行 */
function fieldDefaultSpan(f){ return f.full ? 4 : ((f.quarter || f.w === 1) ? 1 : 2); }
function fieldSpanOf(f, lay){
  var c = lay && lay[f.k];
  if (c && c.w) return c.w;
  return fieldDefaultSpan(f);
}
function fieldTypeLabel(t){
  return ({ text:'文本', number:'数字', currency:'金额', date:'日期', isbn:'ISBN',
            'year-date':'年月日', img:'图片', textarea:'多行文本', select:'下拉单选',
            multi:'预设多选', booktag:'标签分类', booksub:'小分类', stars:'星级',
            hearts:'心级', dyn:'关联选择', geopick:'地图选点', check:'勾选',
            checks:'多选勾选', locopt:'位置选项', loc3:'位置三段' })[t] || (t || '字段');
}
async function persistFieldLayout(pending){
  try {
    var snap = JSON.parse(JSON.stringify(pending || flAll()));
    var idx = await fsReadIndex();
    idx.fieldLayout = snap;
    await fsWriteIndex(idx);
    if (_idxCache) _idxCache.fieldLayout = snap;
  } catch(e){ console.warn('字段布局保存失败', e); }
}
function setFieldLayout(module, tpl, fk, patch){
  if (!fk) return;
  var all = flAll(), k = flKey(module, tpl);
  var cfg = all[k] || (all[k] = {});
  var c = cfg[fk] || (cfg[fk] = {});
  Object.keys(patch || {}).forEach(function(p){ if (patch[p]) c[p] = patch[p]; else delete c[p]; });
  if (!c.hide && !c.w) delete cfg[fk];
  if (!Object.keys(cfg).length) delete all[k];
  persistFieldLayout(all);
}
/* fk 为空 = 清空该模块（+模板）下的全部布局设置 */
function resetFieldLayout(module, tpl, fk){
  var all = flAll(), k = flKey(module, tpl);
  if (!fk){ delete all[k]; }
  else if (all[k]){ delete all[k][fk]; if (!Object.keys(all[k]).length) delete all[k]; }
  persistFieldLayout(all);
}

/* v69：页面管理面板 —— 录入字段管理（自定义字段增删改） */
function renderPageMgmt(module){
  var label = MODULE_LABELS[module] || module;
  var cf = getCustomFields(module);
  var editingIdx = ui.pagemgmt._editIdx;  /* 正在编辑的字段索引（-1=新增模式） */
  var h = '<div class="pagemgmt-overlay" data-act="closepagemgmt">'+
    '<div class="pagemgmt-panel">'+
    '<div class="pm-head"><div><h2>'+esc(label)+' · 页面管理</h2>'+
    '<div class="hint">管理录入字段 — 内置字段可隐藏 / 调宽度，也可增加自定义字段</div></div>'+
    '<button class="btn ghost sm" data-act="closepagemgmt">✕ 关闭</button></div>';

  /* v76：内置字段 —— 可隐藏、可调宽度（按录入模板分组，设置只对当前这套表单生效） */
  var tpls = FIELD_TPLS[module] || [];
  var curTpl = ui.pagemgmt._tpl || '';
  if (tpls.indexOf(curTpl) < 0) curTpl = '';
  ui.pagemgmt._tpl = curTpl;
  var bdefs = builtinFieldDefs(module, curTpl);
  var lay = getFieldLayout(module, curTpl);
  h += '<div class="pm-section"><h3>内置字段 · 显示与宽度 <i style="font-weight:400;font-size:11px;color:var(--muted)">('+bdefs.length+' 个 · 隐藏后不再出现在录入表单，已存的内容不会丢)</i></h3>';
  if (tpls.length){
    h += '<div class="pm-tplbar"><span>按录入表单：</span>'+
      '<button class="pm-tpl'+(curTpl?'':' on')+'" type="button" data-act="pmtpl" data-v="">通用</button>'+
      tpls.map(function(t){
        return '<button class="pm-tpl'+(curTpl===t?' on':'')+'" type="button" data-act="pmtpl" data-v="'+esc(t)+'">'+esc(t)+'</button>';
      }).join('')+'</div>';
  }
  h += '<div class="pm-field-list">';
  bdefs.forEach(function(f){
    var c = lay[f.k] || {};
    var span = fieldSpanOf(f, lay);
    var changed = !!c.hide || (!!c.w && c.w !== fieldDefaultSpan(f));
    h += '<div class="pm-field bi'+(c.hide?' off':'')+'">'+
      '<span class="pm-fk">'+esc(f.k)+(f.req?'<i class="pm-req" title="必填项">必填</i>':'')+'</span>'+
      '<span class="pm-ft">'+esc(fieldTypeLabel(f.t))+'</span>'+
      '<div class="pm-fctl">'+
        '<button class="pm-eye'+(c.hide?'':' on')+'" type="button" data-act="pmfhide" data-fk="'+esc(f.k)+'" title="'+(c.hide?'已隐藏，点这里重新显示':'点这里从录入表单里隐藏')+'">'+(c.hide?'🚫':'👁')+'</button>'+
        '<div class="pm-wseg">'+
          [1,2,3,4].map(function(w){
            return '<button class="pm-w'+(span===w?' on':'')+'" type="button" data-act="pmfw" data-fk="'+esc(f.k)+'" data-w="'+w+'">'+({1:'25%',2:'50%',3:'75%',4:'整行'})[w]+'</button>';
          }).join('')+
        '</div>'+
        '<button class="pm-reset'+(changed?'':' dim')+'" type="button" data-act="pmfreset" data-fk="'+esc(f.k)+'" title="恢复默认">↺</button>'+
      '</div></div>';
  });
  h += '</div>';
  h += '<div class="pm-foot"><button class="btn ghost xs" type="button" data-act="pmresetall" data-mk="'+esc(module)+'">↺ 全部恢复默认'+(curTpl?'（'+esc(curTpl)+'）':'')+'</button></div></div>';

  /* 自定义字段 */
  h += '<div class="pm-section"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'+
    '<h3>自定义字段 <i style="font-weight:400;font-size:11px;color:var(--muted)">(可增删改)</i></h3>'+
    '<button class="btn sm" data-act="addcfield" data-mk="'+module+'">＋ 增加字段</button></div>'+
    '<div class="pm-field-list">';
  if (!cf.length){
    h += '<div class="pm-empty">还没有自定义字段，点上方「增加字段」开始添加</div>';
  } else {
    cf.forEach(function(f, i){
      var typeLabel = f.t==='text' ? '文本输入' : (f.t==='multi' ? '预设多选' : '预设单选');
      h += '<div class="pm-field custom">'+
        '<span class="pm-fk">'+esc(f.k)+'</span>'+
        '<span class="pm-ft">'+typeLabel+'</span>'+
        '<span class="pm-fscope">范围：'+esc(fieldScopeLabel(f, module))+'</span>'+
        '<span class="pm-fafter">位置：'+(f.after?('在「'+esc(f.after)+'」后'):'最后')+'</span>'+
        '<span class="pm-fw">宽度：'+(f.w===1?'25%':'50%')+'</span>'+
        (f.o && f.o.length ? '<span class="pm-fo">'+f.o.slice(0,3).map(esc).join(', ')+(f.o.length>3?' 等'+f.o.length+'项':'')+'</span>' : '')+
        '<div class="pm-fops">'+
          '<button class="btn ghost xs" data-act="editcfield" data-mk="'+module+'" data-i="'+i+'">编辑</button>'+
          '<button class="btn ghost xs" data-act="delcfield" data-mk="'+module+'" data-i="'+i+'" style="color:var(--red)">删除</button>'+
        '</div></div>';
    });
  }
  h += '</div></div>';

  /* 自定义分类管理（改名入口：修正创建时的错别字） */
  h += '<div class="pm-section"><h3>自定义分类管理 <i style="font-weight:400;font-size:11px;color:var(--muted)">(点 ✎ 改名)</i></h3>';
  if (!USER_CATS.length){
    h += '<div class="pm-empty">还没有自定义大类 / 小类。在「增加字段」的作用域里点「＋ 新建大类 / 新建小类」即可创建，创建后可在这里改名。</div>';
  } else {
    USER_CATS.forEach(function(c){
      var subs = (USER_SUBS[c]||[]);
      h += '<div class="pm-cat-row"><span class="pm-cat-name">'+esc(c)+'</span>'+
        '<button class="btn ghost xs" type="button" data-act="renamecat" data-v="'+esc(c)+'">✎ 改名</button>';
      if (subs.length){
        h += '<div class="pm-cat-subs">'+
          subs.map(function(s){
            return '<span class="pm-sub-chip">'+esc(s)+
              '<button type="button" class="pm-sub-rename" data-act="renamesub" data-cat="'+esc(c)+'" data-v="'+esc(s)+'" title="改名">✎</button></span>';
          }).join('')+'</div>';
      }
      h += '</div>';
    });
  }
  h += '</div>';

  /* 新增/编辑字段表单（内联） */
  if (editingIdx !== undefined && editingIdx !== null){
    var isEdit = editingIdx >= 0;
    var ef = isEdit ? cf[editingIdx] : { k:'', t:'select', o:[''], ph:'', multi:false };
    h += '<div class="pm-section pm-edit-sec"><h3>'+(isEdit ? '编辑字段' : '新增字段')+'</h3>'+
      '<div class="pm-edit-form">'+
      '<div class="pm-row"><label>字段名称 <b style="color:var(--red)">*</b></label>'+
        '<input id="pm_fk" type="text" placeholder="如：属性、稀有度、版本" value="'+esc(ef.k)+'" autocomplete="off"></div>'+
      pmScopePickerHTML(ui.pagemgmt._scope || {type:'module',value:''}, module)+
      /* v75fix：显示位置 + 显示宽度，两个下拉并排，用户自己就能排好 */
      '<div style="display:flex;gap:10px;flex-wrap:wrap">'+
        '<div style="flex:1 1 150px;min-width:0">'+pmAfterRowHTML(module, editingIdx)+'</div>'+
        '<div style="flex:0 1 130px;min-width:0">'+pmWidthRowHTML(module, editingIdx)+'</div>'+
      '</div>'+
      '<div class="pm-row"><label>字段类型</label>'+
        '<div class="pm-type-sel">'+
          '<button type="button" class="pm-type pm-ftype'+(ef.t==='text'?' on':'')+'" data-act="pmtype" data-pmt="text">文本输入</button>'+
          '<button type="button" class="pm-type pm-ftype'+(ef.t==='select'?' on':'')+'" data-act="pmtype" data-pmt="select">预设单选</button>'+
          '<button type="button" class="pm-type pm-ftype'+(ef.t==='multi'?' on':'')+'" data-act="pmtype" data-pmt="multi">预设多选</button>'+
        '</div></div>'+
      (ef.t!=='text' ? '<div class="pm-row" id="pm_fo_row"><label>预设值 <i style="font-weight:400;font-size:11px;color:var(--muted)">(每行一个)</i></label>'+
        '<textarea id="pm_fo" placeholder="如：&#10;水属性&#10;火属性&#10;草属性">'+esc((ef.o||[]).join('\n'))+'</textarea></div>' :
      '<div class="pm-row" id="pm_fph_row"><label>占位提示</label>'+
        '<input id="pm_fph" type="text" placeholder="输入框内的提示文字" value="'+esc(ef.ph||'')+'" autocomplete="off"></div>')+
      '<div class="pm-row" style="display:flex;gap:16px;margin-top:14px">'+
        '<button class="btn" id="pm_save_btn" data-act="savecfield" data-mk="'+module+'" data-i="'+editingIdx+'">保存字段</button>'+
        '<button class="btn ghost" data-act="cancelcfield">取消</button></div>'+
      '</div></div>';
  }

  h += '</div></div>';
  return h;
}

/* v75fix：给定录入表单（key + 当前值），返回要读取自定义字段的模块来源列表。
   书籍/杂志 表单（collection + 大类=书籍/杂志）的自定义字段在文渊斋页面管理里维护 → 读 study。
   其余按自身模块读。 */
function customFieldSources(key, vals){
  if (key === 'collection'){
    var big = String(vals && vals['大类'] || '');
    if (big === '书籍' || big === '杂志') return ['study', 'collection'];
    return ['collection'];
  }
  if (key === 'av' || key === 'study' || key === 'travel' || key === 'food' || key === 'idea') return [key];
  if (key === 'checkin') return ['travel'];
  return [key];
}

function activeFields(key, vals){
  var base;
  if (MODE === 'db') base = (MODS[key] && MODS[key].fields) ? MODS[key].fields : [];
  else {
    if (key==='collection' && vals){
      var c = vals['大类'];
      if (c==='书籍') base = BOOK_FIELDS;
      else if (c==='杂志') base = MAG_FIELDS;
      else base = (MODS[key] && MODS[key].fields) ? MODS[key].fields : [];
    } else if (key==='av' && vals){
      var a = vals['大类'];
      /* v75fix：大类改名 电影→戏→赏戏、留声机→音→留音（旧值一并兼容） */
      if (a==='赏戏' || a==='戏' || a==='电影') base = MOVIE_FIELDS;
      else if (a==='留音' || a==='音' || a==='留声机') base = MUSIC_FIELDS;
      else base = (MODS[key] && MODS[key].fields) ? MODS[key].fields : [];
    } else {
      base = (MODS[key] && MODS[key].fields) ? MODS[key].fields : [];
    }
  }
  /* v75：追加自定义字段（按适用范围过滤，只保留作用于当前 item 的字段）
     v75fix：插到「状态」之后（状态紧随编号，自定义字段紧接其后），集中在表单上方，
             不再堆到末尾被长表单淹没 */
  /* v75fix：兜底修正 —— 早期因 .pm-type 选择器冲突，可能存下 t 为 null 的自定义字段，
     渲染时 fieldHTML 没有任何分支匹配 → body 为空 → 下拉框「消失」。
     这里把未知/缺失的 t 规范化：有预设值就退回 select（下拉框），否则退回 text。 */
  var KNOWN_T = ['text','number','currency','date','isbn','year-date','img','textarea',
                 'select','multi','booktag','booksub','stars','hearts','dyn','geopick','check','checks',
                 'locopt'];   /* v75fix：存储地点三段 */
  /* v75fix：自定义字段来源 —— 文渊斋的 书籍/杂志 表单其实是 collection 里的「大类=书籍/杂志」录入，
     但它们的自定义字段在「文渊斋 · 页面管理」里维护（存在 customFields.study），
     所以书籍/杂志表单要同时读 study + collection 两处，其它表单读各自模块。 */
  var cf = [];
  customFieldSources(key, vals).forEach(function(src){
    getCustomFields(src).forEach(function(f){ cf.push(f); });
  });
  var seenC = {};
  cf = cf.filter(function(f){ var kk=f && f.k; if(!kk || seenC[kk]) return false; seenC[kk]=1; return true; });
  cf = cf.map(function(f){
    if (f.t && KNOWN_T.indexOf(f.t)>=0) return f;
    var c={}; for (var kk in f) if (Object.prototype.hasOwnProperty.call(f,kk)) c[kk]=f[kk];
    c.t = (f.o && f.o.length) ? 'select' : 'text';
    return c;
  }).filter(function(f){ return fieldMatchesScope(f, key, vals); });
  if (cf.length){
    /* v75fix：位置完全由用户在页面管理里选的 after 决定（放在哪个字段后面）；
       没选的放最后。改顺序不用改代码，用户自己就能调。 */
    var withAfter=[], noAfter=[];
    cf.forEach(function(f){ (f.after ? withAfter : noAfter).push(f); });
    var result = base.slice();
    /* 倒序插入：同一锚点下有多个字段时，最终顺序仍与定义顺序一致 */
    for (var wi=withAfter.length-1; wi>=0; wi--){
      var wf=withAfter[wi], anchor=-1;
      for (var rj=0; rj<result.length; rj++){ if (result[rj].k===wf.after){ anchor=rj; break; } }
      if (anchor>=0) result.splice(anchor+1, 0, wf);
      else noAfter.unshift(wf);      /* 锚点字段不存在 → 退化到末尾，且不打乱顺序 */
    }
    noAfter.forEach(function(f){ result.push(f); });
    base = result;
  }
  /* v76：按「页面管理 → 内置字段」的设置剔除隐藏字段。
     只作用于内置字段（自定义字段有自己的增删入口，不受影响）。 */
  var _tpl = fieldTplOf(key, vals);
  var _lay = getFieldLayout(key, _tpl);
  if (Object.keys(_lay).length){
    var _bs = {}; builtinFieldsOf(key, _tpl).forEach(function(n){ _bs[n] = 1; });
    base = base.filter(function(f){ return !(_bs[f.k] && fieldIsHidden(f, _lay)); });
  }
  return base;
}
/* v75：自定义字段适用范围匹配：module=全模块；cat/sub/ip/series 仅匹配该范围值的 item。
   v75fix：cat 维度按模块取 —— 遐方坞的 目的地/打卡点、文渊斋的 学习计划 是按「录入表单」区分，
   靠 key（表单模块）判断；馐馔坊/灵思阁的 cat 分别映射到 类型/分类 字段。 */
function fieldMatchesScope(f, key, vals){
  var sc = f.scope || { type:'module', value:'' };
  if (!sc.type || sc.type==='module') return true;
  if (!vals) return false;
  if (sc.type==='ip') return String(vals['IP']||'') === String(sc.value||'');
  if (sc.type==='series') return String(vals['系列']||'') === String(sc.value||'');
  if (sc.type==='sub') return String(vals['小类']||'') === String(sc.value||'');
  if (sc.type==='cat'){
    var v = String(sc.value||'');
    if (v==='目的地') return key==='travel';
    if (v==='打卡点') return key==='checkin';
    if (v==='学习计划') return key==='study';
    var col = (key==='food') ? '类型' : (key==='idea') ? '分类' : '大类';
    return String(vals[col]||'') === v;
  }
  return true;
}
function fieldScopeLabel(f, module){
  var sc = f.scope || { type:'module', value:'' };
  if (!sc.type || sc.type==='module') return '全部';
  var name = sc.type==='cat' ? pmScopeCatLabel(module) : ({sub:'小类',ip:'IP',series:'系列'})[sc.type] || sc.type;
  return name + (sc.value ? ' · '+sc.value : '');
}
/* v75：页面管理 —— 适用范围（scope）辅助函数 */
function pmAllCats(){ return CATS.slice(); }
function pmAllSubs(){
  var seen={}, out=[];
  function add(list){ (list||[]).forEach(function(s){ if(s && !seen[s]){ seen[s]=1; out.push(s); } }); }
  Object.keys(SUBS).forEach(function(c){ add(SUBS[c]); });
  Object.keys(USER_SUBS).forEach(function(c){ add(USER_SUBS[c]); });
  (store.collection.rows||[]).forEach(function(r){ if(r['小类']) add([r['小类']]); });
  return out;
}
function scopeTypeName(t){ return ({module:'全部模块',cat:'大类',sub:'小类',ip:'IP',series:'系列'})[t] || '全部模块'; }
/* v75fix：适用范围维度的可读名 —— cat 按模块取（大类/录入界面/类型/分类），其余固定 */
function pmScopeTypeLabel(module, t){
  if (t==='cat') return pmScopeCatLabel(module);
  return ({module:'全部模块',sub:'小类',ip:'IP',series:'系列'})[t] || '';
}
/* v75fix：适用范围按模块个性化 —— 每个模块的「大类」维度含义不同：
   藏品馆=6 大类、影音厅=赏戏/留音、文渊斋=书籍/杂志/学习计划、
   遐方坞=目的地/打卡点两个录入界面、馐馔坊=类型、灵思阁=分类。 */
function pmScopeCatLabel(module){
  if (module==='travel') return '录入界面';
  if (module==='food') return '类型';
  if (module==='idea') return '分类';
  return '大类';
}
function pmScopeCats(module){
  if (module==='av') return AV_CATS.slice();
  if (module==='study') return ['书籍','杂志','学习计划'];
  if (module==='travel') return ['目的地','打卡点'];
  if (module==='food') return ['餐厅','外卖','自炊','咖啡甜品','街边小吃'];
  if (module==='idea') return ['想法','金句','待办','观察','选题'];
  return CATS.slice();
}
function pmScopeSubs(module){
  if (module==='av'){
    var out=[], seen={};
    AV_CATS.forEach(function(c){ (SUBS[c]||[]).forEach(function(s){ if(!seen[s]){ seen[s]=1; out.push(s); } }); });
    return out;
  }
  if (module==='collection') return pmAllSubs();
  return [];
}
/* 各模块可选的适用范围维度（按钮）：文渊斋无小类，遐方坞/馐馔坊/灵思阁只有「界面/类型/分类」这一级 */
function pmScopeTypes(module){
  var t=[['module','全部模块'],['cat', pmScopeCatLabel(module)]];
  if (module==='collection' || module==='av') t.push(['sub','小类']);
  if (module==='collection' || module==='av' || module==='study'){ t.push(['ip','IP']); t.push(['series','系列']); }
  return t;
}
function pmScopeValueOptionsHTML(sc, module){
  sc = sc || {type:'module',value:''};
  var h='<select id="pm_scopeval" class="pm-scope-sel">';
  if (sc.type==='cat'){
    h += '<option value="">（请选择'+pmScopeCatLabel(module)+'）</option>';
    pmScopeCats(module).forEach(function(c){ h += '<option value="'+esc(c)+'"'+(c===sc.value?' selected':'')+'>'+esc(c)+'</option>'; });
    if (module==='collection') h += '<option value="__new__">＋ 新建大类…</option>';
  } else if (sc.type==='sub'){
    h += '<option value="">（请选择小类）</option>';
    pmScopeSubs(module).forEach(function(s){ h += '<option value="'+esc(s)+'"'+(s===sc.value?' selected':'')+'>'+esc(s)+'</option>'; });
    if (module==='collection') h += '<option value="__new__">＋ 新建小类…</option>';
  } else if (sc.type==='ip'){
    h += '<option value="">（请选择 IP）</option>';
    (store.ip.rows||[]).forEach(function(r){ var n=r['IP名称']; if(n) h += '<option value="'+esc(n)+'"'+(n===sc.value?' selected':'')+'>'+esc(n)+'</option>'; });
    h += '<option value="__new__">＋ 新建 IP…</option>';
  } else if (sc.type==='series'){
    h += '<option value="">（请选择系列）</option>';
    (store.series.rows||[]).forEach(function(r){ var n=r['系列名称']; if(n) h += '<option value="'+esc(n)+'"'+(n===sc.value?' selected':'')+'>'+esc(n)+'</option>'; });
    h += '<option value="__new__">＋ 新建系列…</option>';
  }
  h += '</select>';
  if (sc.type!=='module' && (sc.type==='ip' || sc.type==='series' || module==='collection')){
    h += '<button type="button" class="btn ghost sm" data-act="pmnew_'+sc.type+'" style="margin-left:8px">＋ 新建</button>';
  }
  return h;
}
function pmScopePickerHTML(sc, module){
  sc = sc || {type:'module',value:''};
  var types=pmScopeTypes(module);
  var h='<div class="pm-row"><label>适用范围 <i style="font-weight:400;font-size:11px;color:var(--muted)">字段只在匹配的录入表单里出现</i></label>'+
    '<div class="pm-type-sel">';
  types.forEach(function(t){
    h += '<button type="button" class="pm-type'+(sc.type===t[0]?' on':'')+'" data-act="pmscope" data-v="'+t[0]+'">'+t[1]+'</button>';
  });
  h += '</div>';
  if (sc.type==='module'){
    h += '<div class="pm-scope-note">该字段会出现在「'+esc(MODULE_LABELS[module]||module)+'」所有物品的录入表单中。</div>';
  } else {
    h += '<div class="pm-row" style="margin-top:6px"><label>选择'+pmScopeTypeLabel(module, sc.type)+'</label>'+pmScopeValueOptionsHTML(sc, module)+'</div>';
    if (sc.type==='series' && sc.value){
      var _se = (store.series.rows||[]).filter(function(r){ return r['系列名称']===sc.value; })[0];
      if (_se && _se['所属IP']) h += '<div class="pm-scope-note">该系列所属 IP：<b>'+esc(_se['所属IP'])+'</b>（自动带入，无需重复设置）</div>';
    }
    if (sc.type==='sub' && ui.pagemgmt && ui.pagemgmt._newsubOpen){
      h += '<div class="pm-newsub">'+
        '<input id="pm_newsub_name" type="text" placeholder="小类名称，如：德语" autocomplete="off">'+
        '<select id="pm_newsub_cat">'+pmScopeCats(module).map(function(c){ return '<option value="'+esc(c)+'">'+esc(c)+'</option>'; }).join('')+'</select>'+
        '<button type="button" class="btn sm" data-act="pmnewsubok">创建</button>'+
        '<button type="button" class="btn ghost sm" data-act="pmnewsubcancel">取消</button></div>';
    }
  }
  h += '</div>';
  return h;
}
/* v75fix：自定义字段「显示位置」——由用户在页面管理里自己选：放在哪个内置字段后面。
   这样调整顺序不用改代码，用户自己就能搞定。 */
function pmAfterOptionsHTML(module, editIdx){
  var cf = getCustomFields(module);
  var cur = (editIdx>=0 && cf[editIdx]) ? (cf[editIdx].after || '') : '';
  var builtin = builtinFieldsOf(module);   /* v75fix：按模块实际字段模板取 */
  var h = '<option value=""'+(cur===''?' selected':'')+'>（放在最后）</option>';
  builtin.forEach(function(n){
    h += '<option value="'+esc(n)+'"'+(cur===n?' selected':'')+'>在「'+esc(n)+'」后面</option>';
  });
  return h;
}
function pmAfterRowHTML(module, editIdx){
  return '<div class="pm-row"><label>显示位置 <i style="font-weight:400;font-size:11px;color:var(--muted)">选一个字段，本字段就排在它后面</i></label>'+
    '<select id="pm_after">'+pmAfterOptionsHTML(module, editIdx)+'</select></div>';
}
/* v75fix：显示宽度——一行按 4 格算，可选 1 格(25%) 或 2 格(50%) */
function pmWidthRowHTML(module, editIdx){
  var cf = getCustomFields(module);
  var cur = (editIdx>=0 && cf[editIdx]) ? (cf[editIdx].w || 2) : 2;
  var opts = [[1,'1 格（25%）'],[2,'2 格（50%）']];
  return '<div class="pm-row"><label>显示宽度 <i style="font-weight:400;font-size:11px;color:var(--muted)">一行按 4 格算</i></label>'+
    '<select id="pm_w">'+opts.map(function(o){
      return '<option value="'+o[0]+'"'+(cur===o[0]?' selected':'')+'>'+o[1]+'</option>';
    }).join('')+'</select></div>';
}
function saveUserTaxonomy(){
  try {
    var idx = _idxCache || {};
    idx.userCats = USER_CATS.slice();
    idx.userSubs = JSON.parse(JSON.stringify(USER_SUBS));
    fsWriteIndex(idx);
  } catch(e){ console.warn('saveUserTaxonomy', e); }
}
/* v75fix：存储地点 —— 三段选项持久化 + 「地点名称」自动组合 */
function saveLocOptions(){
  try {
    var idx = _idxCache || {};
    idx.locOptions = JSON.parse(JSON.stringify(LOC_OPTS));
    fsWriteIndex(idx);
  } catch(e){ console.warn('saveLocOptions', e); }
}
function addLocOpt(dim, name){
  name = String(name||'').trim();
  if (!name) return false;
  if (LOC_DIMS.indexOf(dim)<0) return false;
  if (!LOC_OPTS[dim]) LOC_OPTS[dim] = [];
  if (LOC_OPTS[dim].indexOf(name)<0) LOC_OPTS[dim].push(name);
  saveLocOptions();
  return true;
}
function delLocOpt(dim, name){
  if (!LOC_OPTS[dim]) return false;
  var i = LOC_OPTS[dim].indexOf(name);
  if (i<0) return false;
  LOC_OPTS[dim].splice(i,1);
  saveLocOptions();
  return true;
}
/* 显示名 = 房间 · 柜体墙面 · 所在层（缺哪段就跳过）；老数据没有三段时回退到「地点名称」 */
function locDisplayName(r){
  if (!r) return '';
  var parts = [r['房间'], r['柜体墙面'], r['所在层']]
    .map(function(x){ return String(x==null?'':x).trim(); }).filter(Boolean);
  if (parts.length) return parts.join(' · ');
  return String(r['地点名称']||'').trim();
}
/* 写库前把三段合成「地点名称」，保证藏品里的「存储地点」下拉还能取到值 */
function withLocName(vals){
  if (!vals) return vals;
  var n = locDisplayName(vals);
  if (n) vals['地点名称'] = n;
  return vals;
}
/* v75fix：藏品这边的「存储地点」同样拆三段（房间 / 柜墙 / 层），
   用与地点库一致的「 · 」分隔，这样合成结果能和地点库里的地点对上。 */
function collLocName(vals){
  if (!vals) return '';
  return [vals['房间'], vals['柜墙'], vals['层']]
    .map(function(x){ return String(x==null?'':x).trim(); })
    .filter(Boolean).join(' · ');
}
function withCollLoc(vals){
  if (!vals) return vals;
  var n = collLocName(vals);
  if (n) vals['存储地点'] = n;
  return vals;
}
/* 编辑老藏品时：老数据只有「存储地点」一个串，拆回三段给下拉回填 */
function splitCollLoc(vals){
  if (!vals) return vals;
  if (vals['房间'] || vals['柜墙'] || vals['层']) return vals;
  var s = String(vals['存储地点'] || '').trim();
  if (!s) return vals;
  var segs = s.split('·').map(function(x){ return String(x).trim(); });
  vals['房间'] = segs[0] || '';
  vals['柜墙'] = segs[1] || '';
  vals['层']   = segs[2] || '';
  return vals;
}
function addUserCat(name){
  if (!name) return false;
  if (CATS.indexOf(name)<0) CATS.push(name);
  if (USER_CATS.indexOf(name)<0) USER_CATS.push(name);
  saveUserTaxonomy();
  return true;
}
function addUserSub(cat, name){
  if (!cat || !name) return false;
  if (CATS.indexOf(cat)<0) CATS.push(cat);
  if (USER_CATS.indexOf(cat)<0) USER_CATS.push(cat);
  if (!SUBS[cat]) SUBS[cat]=[];
  if (SUBS[cat].indexOf(name)<0) SUBS[cat].push(name);
  if (!USER_SUBS[cat]) USER_SUBS[cat]=[];
  if (USER_SUBS[cat].indexOf(name)<0) USER_SUBS[cat].push(name);
  saveUserTaxonomy();
  return true;
}
/* v75fix：把藏品行改动落盘（改名后迁移引用用） */
function persistCollectionRows(){
  if (MODE === 'gh'){ queueGhSave(); localCacheSet(); }
  else if (MODE === 'localfile'){ queueLocalSave(); }
  else { lsSet('collection', store.collection.rows); localCacheSet(); }
}
/* v75fix：重命名自定义大类（同时迁移其下小类归属 + 藏品里的大类引用） */
function renameUserCat(oldName, newName){
  if (!oldName || !newName || oldName===newName) return {ok:false, msg:'名称没变化'};
  newName = String(newName).trim();
  if (!newName) return {ok:false, msg:'名称不能为空'};
  if (CATS.indexOf(newName)>=0) return {ok:false, msg:'已存在该大类'};
  var ci = CATS.indexOf(oldName); if (ci>=0) CATS[ci]=newName;
  var ui2 = USER_CATS.indexOf(oldName); if (ui2>=0) USER_CATS[ui2]=newName;
  if (SUBS[oldName]){ SUBS[newName]=SUBS[oldName]; delete SUBS[oldName]; }
  if (USER_SUBS[oldName]){ USER_SUBS[newName]=USER_SUBS[oldName]; delete USER_SUBS[oldName]; }
  (store.collection.rows||[]).forEach(function(r){ if (r['大类']===oldName) r['大类']=newName; });
  saveUserTaxonomy(); persistCollectionRows();
  return {ok:true};
}
/* v75fix：重命名自定义小类（迁移藏品里的小类引用） */
function renameUserSub(cat, oldName, newName){
  if (!cat || !oldName || !newName || oldName===newName) return {ok:false, msg:'名称没变化'};
  newName = String(newName).trim();
  if (!newName) return {ok:false, msg:'名称不能为空'};
  if ((SUBS[cat]||[]).indexOf(newName)>=0) return {ok:false, msg:'该大类下已存在小类「'+newName+'」'};
  var si = (SUBS[cat]||[]).indexOf(oldName); if (si>=0) SUBS[cat][si]=newName;
  var usi = (USER_SUBS[cat]||[]).indexOf(oldName); if (usi>=0) USER_SUBS[cat][usi]=newName;
  (store.collection.rows||[]).forEach(function(r){ if (r['大类']===cat && r['小类']===oldName) r['小类']=newName; });
  saveUserTaxonomy(); persistCollectionRows();
  return {ok:true};
}

/* v75：按范围过滤自定义字段后，重画表单字段区（保留已填值），让适用范围匹配的字段即时出现 / 消失 */
function rebuildFormGrid(host){
  if (!editing) return;
  var grid = host.querySelector('.fgrid');
  if (!grid) return;
  try { grid.innerHTML = activeFields(editing.key, editing.vals).map(function(f){ return fieldHTML(f, editing.vals[f.k]); }).join(''); } catch(e){ return; }
  wireFormControls(host, function(){
    if (!editing) return;
    try { localStorage.setItem('lifedesk_draft_'+editing.key+(editing.id?('_'+editing.id):''), JSON.stringify(editing.vals)); } catch(e){}
  });
}
var ORDER = ['overview','collection','travel','av','study','food','idea'];
var EXTRA = ['ip','series','loc','checkin','recipe'];   /* 不单独进导航：ip/series/loc 在「藏品」里管理；checkin 在「遐方坞」里管理；recipe 在「馐馔坊」里管理（v48 拆分） */

/* ============ 状态 ============ */
var store = {};
ORDER.concat(EXTRA).forEach(function(k){ if(k!=='overview') store[k] = { rows:[], status:'loading' }; });
/* v59：拾纪（本地记事本）不依赖任何线上表，单独存在 localStorage */
store.notes = { rows:[], status:'ok' };
function loadNotes(){
  try {
    var raw = localStorage.getItem('lifedesk_notes');
    if (raw) store.notes.rows = JSON.parse(raw);
  } catch(e){}
}
function saveNotes(){
  try { localStorage.setItem('lifedesk_notes', JSON.stringify(store.notes.rows)); } catch(e){}
}

