function loadAll(){
  var keys = ORDER.filter(function(k){ return k!=='overview'; }).concat(EXTRA);
  keys.forEach(function(k){
    store[k]={rows:[],status:'loading'};
    fetchAll(k, function(rows){
      if (rows===null){ store[k].status='error'; renderSoon(); return; }
      store[k].rows=normalizeRows(rows);
      if (k==='travel') store[k].rows.forEach(migrateTravelRow);
      if (k==='food' || k==='recipe') tryMigrateFoodRecipe();
      store[k].status= rows.length? 'ok' : 'empty';
      /* 关键：所有模式（含 local / gh）都要把相对路径封面解析成可显示 URL，否则封面整块空白 */
      resolveImagesFor(store[k].rows).then(function(){ renderSoon(); });   /* v75fix perf：合并重绘 */
      /* v54：collection/av 都读完后，把错放在 collection 里的影视/音乐迁回 av */
      if (store.collection && store.collection.status !== 'loading' &&
          store.av && store.av.status !== 'loading') migrateAvFromCollection();
      /* v54：food/recipe 都读完后，把主文件里的美食/菜谱拆到各自独立分片文件 */
      if (store.food && store.food.status !== 'loading' &&
          store.recipe && store.recipe.status !== 'loading') migrateFoodRecipeToOwnFiles();
    });
  });
  render();
  /* v75fix：加载看门狗 —— 万一某张表（如本地目录读取 / 图片解析）卡住，
     15 秒后强制把仍在 loading 的表置为 error 并给出提示，绝不永远停在「读取中」。 */
  clearTimeout(_loadWatchdogTimer);
  _loadWatchdogTimer = setTimeout(function(){
    var stuck = keys.filter(function(k){ return store[k] && store[k].status==='loading'; });
    if (stuck.length){
      stuck.forEach(function(k){ store[k].status='error'; });
      renderSoon();
      toast('「'+stuck.join('、')+'」读取超时，请按 F12 打开控制台查看红色报错，或点右下角「重新拉取」重试');
    }
  }, 15000);
}
/* v54：启动时把错放在 collection 里的电影/留声机记录迁回 store.av，避免两边计数对不上 */
function migrateAvFromCollection(){
  if (!store.collection || !store.av) return;
  var moved=[];
  store.collection.rows = store.collection.rows.filter(function(r){
    if (r && AV_CATS.indexOf(r['大类']) >= 0){
      moved.push(r); return false;
    }
    return true;
  });
  if (!moved.length) return;
  var existing={}; (store.av.rows||[]).forEach(function(r){ if(r && r._id) existing[String(r._id)]=true; });
  moved.forEach(function(r){ if(!existing[String(r._id)]) store.av.rows.push(r); });
  store.av.status = store.av.rows.length ? 'ok' : 'empty';
  store.collection.status = store.collection.rows.length ? 'ok' : 'empty';
  if (MODE !== 'db'){ if (MODE === 'localfile') queueLocalSave(); else persistAll(); render(); }
}
