/* ============ 写入 ============ */
function propsFrom(fields, vals, key){
  var p={};
  fields.forEach(function(f){
    if (f.t==='geopick') return;
    var v = vals[f.k];
    if (f.t==='text' || f.t==='textarea' || f.t==='dyn'){
      if (v!=='' && v!=null) p[f.k]={text:String(v)};
    } else if (f.t==='img'){
      if (v){ var imgItem={title:f.k,imageUrl:String(v)}; if (vals[f.k+'_vp']) imgItem.viewport=vals[f.k+'_vp']; p[f.k]={image:{images:[imgItem]}}; }
    } else if (f.t==='select'){
      if (v) p[f.k]={select:String(v)};
    } else if (f.t==='multi'){
      if (v && v.length) p[f.k]={multi_select:v};
    } else if (f.t==='date'){
      if (v) p[f.k]={date:String(v)};
    } else if (f.t==='number' || f.t==='stars' || f.t==='hearts'){
      p[f.k]={number:num(v)};
    } else if (f.t==='currency'){
      p[f.k]={currency:num(v)};
    } else if (f.t==='check'){
      p[f.k]={checkbox:!!v};
    }
  });
  /* v48：food / recipe 在本地模式下用 _module 字段隔离；db 模式暂时共用一个线上表，不加 notion 不认识的字段 */
  if ((key==='food' || key==='recipe') && MODE !== 'db') p['_module']={text:key};
  return p;
}
/* 写入成功后立刻并入本地视图，再静默回拉一次线上做校对 */
function localUpsert(key, id, vals){
  if (!store[key]) return;
  /* v58：以旧记录为底合并，而不是从零重建。
     电影/留声机/书籍/杂志 的专用表单不含「大类」输入项，
     若从零重建，编辑保存一次大类就丢，导致分片筛选 0 部 + 主文件/分片各留一份旧新拷贝（计数翻倍）。 */
  var prev = (store[key].rows || []).filter(function(r){ return String(r._id)===String(id); })[0] || {};
  var row=Object.assign({}, prev, {_id:id});
  activeFields(key, vals).forEach(function(f){
    if (f.t==='geopick') return;
    var v=vals[f.k];
    if (f.t==='img'){
      var vp = vals[f.k+'_vp'];
      /* v77fix：v 可能已经是 [{imageUrl,viewport}] 数组（直接把 store 里的 row 传进来时）。
         原来一律 String(v)，数组会被转成 '[object Object]'，封面直接消失且不可逆。
         数组原样保留；字符串才按「URL + _vp」包装。 */
      if (Array.isArray(v)) row[f.k] = v;
      else row[f.k] = v ? [{imageUrl:String(v), viewport:(vp && vp.s ? vp : {s:1,x:0,y:0})}] : null;
    }
    else if (f.t==='multi') row[f.k] = (v && v.length) ? v : null;
    else if (f.t==='check') row[f.k] = !!v;
    else if (f.t==='stars' || f.t==='number' || f.t==='currency') row[f.k] = num(v);
    else if (f.t==='date') row[f.k] = v ? String(v) : null;
    else row[f.k] = (v===''||v==null) ? null : v;
  });
  /* v49：collection 的书籍/杂志录入 schema 不渲染「大类」字段，但存储仍需 大类，
     否则文渊斋「我的书架」按 大类 过滤时找不到它们 */
  if (key==='collection' && vals && vals['大类']) row['大类'] = vals['大类'];
  /* v54：av 的电影/留声机 schema 也不渲染「大类」，但渲染和分片都靠它，必须存回 row */
  if (key==='av' && vals && vals['大类']) row['大类'] = vals['大类'];
  /* v48：food / recipe 在 db 模式下暂时共表，用隐藏字段 _module 区分；本地模式下也保留，方便后续拆分 */
  if (key==='food' || key==='recipe') row['_module'] = key;
  /* food 的经纬度通过 geopick 预填进 vals，但 fields 里已删除经纬度输入框，这里额外写回 row。
     v58：只有 vals 里真的带了坐标才覆盖——编辑时不带坐标输入项，
     原来直接写 0 会把已保存的位置挤掉（编辑保存一次位置就丢）。 */
  if (key==='food'){
    if (vals['纬度']!=null && vals['纬度']!=='') row['纬度']=num(vals['纬度'])||0;
    if (vals['经度']!=null && vals['经度']!=='') row['经度']=num(vals['经度'])||0;
  }
  var rows = store[key].rows.filter(function(r){ return String(r._id)!==String(id); });
  rows.unshift(row);
  store[key].rows = rows;
  store[key].status = rows.length ? 'ok' : 'empty';
  if (MODE === 'gh'){ queueGhSave(); localCacheSet(); }
  else if (MODE === 'localfile'){ queueLocalSave(); }
  else if (MODE === 'local'){ lsSet(key, rows); localCacheSet(); }
}
function refreshKey(key, after){
  fetchAll(key, function(rows){
    if (rows!==null){
      store[key].rows=normalizeRows(rows);
      store[key].status = rows.length?'ok':'empty';
      render();
    }
    if (after) after();
  });
}
function mutate(label, run, optimistic, key, after){
  if (MODE !== 'db'){
    toast('当前没连上线上数据，改动没能保存', '重试', function(){ mutate(label,run,optimistic,key,after); });
    return;
  }
  if (optimistic) optimistic();
  run().then(function(){
    queue = queue.filter(function(q){ return q.run!==run; });
    renderSyncBar();
    if (key) refreshKey(key, after);
    else if (after) after();
    render();
  }).catch(function(e){
    if (!queue.some(function(q){ return q.run===run; })) queue.push({label:label, run:run, key:key});
    renderSyncBar();
    toast('「'+label+'」没保存成功，已放进待同步', '重试', retryQueue);
    if (optimistic) render();
  });
}
/* v54：本地文件模式下，向一个尚无任何条目的专属类目（电影/留声机/书籍/杂志）添加第一条时，
   先弹窗询问是否新建该类目的 data/{类目}-data.json 与 images/{类目}-封面/ 目录，
   让用户明确知道数据落到了哪个文件。返回需要新建的类目名，否则返回 null。 */
var DEDICATED_CATS = ['赏戏','留音','书籍','杂志','美食','菜谱','学习计划'];
function firstEntryForCategory(key, vals){
  /* v58+：只要是第一次向某个专属类目录入，不管当前是否已经连接本地目录，都返回类目名。
     调用方（addRow）根据 MODE 决定：localfile 直接建文件；其它模式先引导选目录再建文件。 */
  var cat = shardCatOf(key, vals);
  if (!cat || DEDICATED_CATS.indexOf(cat) < 0) return null;
  var has = (store[key] && store[key].rows || []).some(function(r){ return shardCatOf(key, r) === cat; });
  return has ? null : cat;
}
function addRow(key, vals, after){
  if (key==='loc') vals = withLocName(vals);      /* v75fix：三段合成「地点名称」 */
  /* 注：藏品「存储地点」由 loc3 三段式字段自己合成，不再需要 withCollLoc */
  if (MODE !== 'db'){
    var id = 'l_' + Date.now().toString(36) + Math.random().toString(36).slice(2,7);
    var newCat = firstEntryForCategory(key, vals);
    if (newCat){
      var fname = shardFileName(newCat), cdir = coverDirName(newCat);
      /* 必须先关掉表单再弹确认窗；否则 saveBtn.onclick 紧接着会 closeSheet()，把确认窗一起隐藏 */
      closeSheet();
      askConfirm(
        '你正在添加第一个「'+newCat+'」条目。\n确认后将在本地 data 文件夹新建：\n• '+fname+'（该类专属数据文件）\n• images/'+cdir+'/（封面图片目录）\n\n确定创建这个专属数据文件吗？',
        function(){
          if (MODE === 'localfile'){
            /* 已连接目录：先并入内存，再显式建分片文件（保证是 v2 分片格式，而不是单文件 lifedesk.json） */
            localUpsert(key, id, vals);
            if (_fsaTimer){ clearTimeout(_fsaTimer); _fsaTimer = null; }
            createShard(newCat, key).then(function(){
              if (after) after();
              render();
              toast('已创建「'+newCat+'」数据文件，并保存了首条记录');
            });
          } else if (_FSA_SUPPORT){
            /* 未连接目录但浏览器支持 FSA：先选目录，再保存 */
            saveFirstDedicatedEntry(newCat, key, id, vals, after);
          } else {
            /* 浏览器不支持 FSA：回退 localStorage */
            toast('当前浏览器不支持本地目录，数据将临时保存在浏览器 localStorage');
            localUpsert(key, id, vals);
            if (after) after();
            render();
          }
        },
        { yesLabel:'创建并保存', yesColor:'#2f8f5b', title:'新建类目数据文件' }
      );
      return;
    }
    localUpsert(key, id, vals);
    if (after) after();
    render();
    toast(MODE === 'localfile' ? '已保存到本地 data 文件夹' : '已保存到本地（当前浏览器）');
    return;
  }
  var m=MODS[key], props=propsFrom(m.fields, vals, key);
  mutate('新增'+m.name, function(){
    return T[key].add(props).then(function(res){
      var id = res && (res.id || res.record_id || res._id);
      if (id) localUpsert(key, id, vals);
      return res;
    });
  }, null, key, after);
}
/* 首次向专属类目录入且尚未连接本地目录时：先选目录，再保存。
   目录为空则直接把当前内存（含本条新记录）写进去；目录已有数据则先加载再合并本条记录。 */
async function saveFirstDedicatedEntry(newCat, key, id, vals, after){
  if (!('showDirectoryPicker' in window)){
    toast('当前浏览器不支持选择本地目录，请用 Chrome / Edge / Opera 桌面版打开');
    localUpsert(key, id, vals);
    if (after) after();
    render();
    return;
  }
  var h = null;
  try {
    h = await window.showDirectoryPicker({ mode:'readwrite' });
    _fsaHandle = h;
    await _fsaSaveHandle(h);
  } catch(e){
    if (e && e.name === 'AbortError'){ toast('已取消选择目录'); return; }
    console.warn('选择目录失败', e);
    toast('选择目录失败：' + ((e && (e.message || e.name)) || '未知错误'));
    return;
  }
  if (!h) return;
  MODE = 'localfile';
  /* 清掉刚 localUpsert 可能排上的防抖写盘，交给下面的 createShard 一次性按分片格式写入，
     避免先写一份单文件 lifedesk.json、再写分片造成格式不一致 */
  if (_fsaTimer){ clearTimeout(_fsaTimer); _fsaTimer = null; }
  var existing = await new Promise(function(res){ localfsRead(function(o){ res(o); }); });
  var isEmpty = !existing || Object.keys(existing).length === 0;
  if (isEmpty){
    localUpsert(key, id, vals);
    if (_fsaTimer){ clearTimeout(_fsaTimer); _fsaTimer = null; }
    await createShard(newCat, key);
  } else {
    await new Promise(function(res){
      loadLocalAll(function(obj){
        Object.keys(obj || {}).forEach(function(mk){
          if (!store[mk]) store[mk] = {rows:[], status:'ok'};
          store[mk].rows = normalizeRows(obj[mk] || []);
          store[mk].status = store[mk].rows.length ? 'ok' : 'empty';
        });
        localUpsert(key, id, vals);
        if (_fsaTimer){ clearTimeout(_fsaTimer); _fsaTimer = null; }
        createShard(newCat, key).then(function(){ res(); });
      });
    });
  }
  await writeReadme();
  setGhStatus('localfile');
  refreshFsaButtons();
  if (after) after();
  render();
  toast('已连接本地数据目录，并创建「'+newCat+'」专属文件');
}
function updateRow(key, id, vals, after){
  if (key==='loc') vals = withLocName(vals);      /* v75fix：三段合成「地点名称」 */
  /* 注：藏品「存储地点」由 loc3 三段式字段自己合成，不再需要 withCollLoc */
  if (MODE !== 'db'){
    localUpsert(key, id, vals);
    if (after) after();
    render();
    toast(MODE === 'localfile' ? '已保存到本地 data 文件夹' : '已保存到本地');
    return;
  }
  var m=MODS[key], props=propsFrom(m.fields, vals, key);
  mutate('修改'+m.name, function(){
    return T[key].upd(id, props).then(function(res){
      localUpsert(key, id, vals);
      return res;
    });
  }, null, key, after);
}
function deleteRow(key, id, name, after){
  if (MODE !== 'db'){
    var sid=String(id);
    store[key].rows = store[key].rows.filter(function(r){ return String(r._id)!==sid; });
    store[key].status = store[key].rows.length ? 'ok' : 'empty';
    if (MODE === 'gh'){ queueGhSave(); localCacheSet(); }
    else if (MODE === 'localfile'){ queueLocalSave(); }
    else { lsSet(key, store[key].rows); localCacheSet(); }
    if (after) after();
    render();
    toast('已从本地删除');
    return;
  }
  var m=MODS[key];
  mutate('删除「'+name+'」', function(){ return T[key].del(id); },
    function(){ store[key].rows = store[key].rows.filter(function(r){ return r._id!==id; }); }, key, after);
}

/* ============ 筛选 ============ */
function filtered(key){
  var rows = store[key].rows.slice(), f=ui[key]||{};
  var q = (f.q||'').trim().toLowerCase();
  if (key==='collection'){
    /* v58：书籍/杂志完全归文渊斋管，藏品馆所有视图不再显示它们 */
    rows=rows.filter(function(r){ return LEGACY_BOOK_CATS.indexOf(r['大类'])<0; });
    if (f.cat) rows=rows.filter(function(r){ return r['大类']===f.cat; });
    if (f.sub) rows=rows.filter(function(r){ return r['小类']===f.sub; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['IP']||'')+' '+(r['系列']||'')+' '+(r['编号']||'')+' '+(r['存储地点']||'')+' '+(r['购入渠道']||'')+' '+(r['短评']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){
      var na=parseInt(String(a['编号']||'').replace(/^[#＃]/,''),10);
      var nb=parseInt(String(b['编号']||'').replace(/^[#＃]/,''),10);
      if (!isNaN(na) && !isNaN(nb) && na!==nb) return na-nb;
      return dstr(b['购入日期']).localeCompare(dstr(a['购入日期']));
    });
  } else if (key==='av'){
    if (f.cat) rows=rows.filter(function(r){ return r['大类']===f.cat; });
    if (f.sub) rows=rows.filter(function(r){ return (r['小类']||'未分类')===f.sub; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['导演/音乐人']||'')+' '+(r['演员/乐队']||'')+' '+(r['简介']||'')+' '+(r['短评']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return dstr(b['完成日期']||b['购入日期']).localeCompare(dstr(a['完成日期']||a['购入日期'])); });
  } else if (key==='travel'){
    if (f.status) rows=rows.filter(function(r){ return r['状态']===f.status; });
    if (q) rows=rows.filter(function(r){
      return ((r['地点']||'')+' '+(r['地区']||'')+' '+(r['国家']||r['国家地区']||'')+' '+(Array.isArray(r['类型'])?r['类型'].join(' '):'')+' '+(r['备注']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){
      var s={'想去':0,'去过':1};
      var d=(s[a['状态']]||0)-(s[b['状态']]||0);
      return d?d:(num(b['心愿等级'])-num(a['心愿等级']));
    });
  } else if (key==='study'){
    if (f.field) rows=rows.filter(function(r){ return r['领域']===f.field; });
    if (q) rows=rows.filter(function(r){
      return ((r['计划']||'')+' '+(r['备注']||'')).toLowerCase().indexOf(q)>=0; });
    var ord={'进行中':0,'未开始':1,'已暂停':2,'已完成':3};
    rows.sort(function(a,b){ return (ord[a['状态']]||1)-(ord[b['状态']]||1); });
  } else if (key==='food'){
    if (f.type) rows=rows.filter(function(r){ return r['类型']===f.type; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['城市']||'')+' '+(r['短评']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return dstr(b['打卡日期']).localeCompare(dstr(a['打卡日期'])); });
  } else if (key==='recipe'){
    if (f.type) rows=rows.filter(function(r){ return r['类型']===f.type; });
    if (q) rows=rows.filter(function(r){
      return ((r['名称']||'')+' '+(r['来源']||'')+' '+(r['食材']||'')+' '+(r['菜谱']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return String(b._id).localeCompare(String(a._id)); });
  } else if (key==='idea'){
    if (f.cat) rows=rows.filter(function(r){ return r['分类']===f.cat; });
    if (f.star) rows=rows.filter(function(r){ return !!r['星标']; });
    if (q) rows=rows.filter(function(r){
      return ((r['内容']||'')+' '+(r['来源']||'')).toLowerCase().indexOf(q)>=0; });
    rows.sort(function(a,b){ return dstr(b['记录日期']).localeCompare(dstr(a['记录日期'])); });
  }
  return rows;
}

/* ============ 小组件 ============ */
function stripHTML(key){
  var s=store[key];
  if (s.status==='loading') return '<span class="dot load"></span>正在从线上读取…';
  if (s.status==='error') return '<span class="dot err"></span>读取失败，数据没能拉回来 '+
    '<button class="btn link" type="button" data-act="reload" data-key="'+key+'">重试</button>';
  return '<span class="dot ok"></span>已同步 '+s.rows.length+' 条 · 数据在资料库里，换设备也在';
}
function emptyHTML(title, tip){
  return '<div class="empty"><b>'+esc(title)+'</b><span>'+esc(tip)+'</span></div>';
}
/* v59：编号解析与排序（001/002…；允许字母后缀 005-A / 005-B；没有编号的排最后） */
function numOf(r){ var v=parseInt(String(r['编号']||'').replace(/^[#＃]/,''),10); return isNaN(v)?null:v; }
/* 拆出「数字基底 + 字母后缀」，如 005-A → {n:5, s:'A'}；无数字 → null */
function numKey(r){
  var v=String(r['编号']||'').replace(/^[#＃]/,'').trim();
  var m=/^(\d+)([A-Za-z]*)/.exec(v);
  if (!m) return null;
  return { n: parseInt(m[1],10), s: m[2]||'' };
}
function sortByNum(arr, order){
  var asc = order!=='desc';
  return arr.slice().sort(function(a,b){
    var ka=numKey(a), kb=numKey(b);
    if (!ka && !kb) return 0;
    if (!ka) return 1;
    if (!kb) return -1;
    if (ka.n!==kb.n) return asc ? ka.n-kb.n : kb.n-ka.n;
    /* 同号：永远按字母序排（A→B…），不随升降序翻转 */
    if (ka.s<kb.s) return -1;
    if (ka.s>kb.s) return 1;
    return 0;
  });
}
function numOrderSeg(order, act, label, viewOn, viewAct){
  /* v58：与面包屑同行的小药丸组（深底金字，风格同 crumb）；label 可为「序号/年份」，可带「按年份」视图切换 */
  label = label || '序号';
  var h='<span class="numseg">'+
    '<button type="button" data-act="'+act+'" data-v="asc" class="'+(order!=='desc'?'on':'')+'">'+label+' ↑</button>'+
    '<button type="button" data-act="'+act+'" data-v="desc" class="'+(order==='desc'?'on':'')+'">'+label+' ↓</button>';
  if (viewAct){
    h+='<button type="button" data-act="'+viewAct+'" data-v="'+(viewOn?'off':'on')+'" class="'+(viewOn?'on':'')+'">按年份</button>';
  }
  return h+'</span>';
}
/* v58：影音厅按年份排序（上映年份/年份，缺省用完成或购入日期的年份；无年份排最后） */
function avYearKey(r){
  var y=parseInt(String(r['上映年份']||r['年份']||''),10);
  if (!isFinite(y) || y<=0){
    var d=String(r['完成日期']||r['购入日期']||'');
    y=parseInt(d.slice(0,4),10)||0;
  }
  return y;
}
function sortByYear(arr, order){
  var asc = order!=='desc';
  return arr.slice().sort(function(a,b){
    var ya=avYearKey(a), yb=avYearKey(b);
    if (!ya && !yb) return 0;
    if (!ya) return 1;
    if (!yb) return -1;
    return asc ? ya-yb : yb-ya;
  });
}
/* v58：通用分页——ui._pg 存每处的页码；perPage 按当前卡片宽度估算（约 3 行） */
ui._pg = ui._pg || {};
ui._yopen = ui._yopen || {};
function perPageNow(){
  var w=140; try{ w=parseInt(localStorage.getItem('lifedesk_cardw')||'140',10)||140; }catch(e){}
  var cols=Math.max(2, Math.floor(1100/(w+14)));
  return cols*3;
}
function pageSlice(arr, pkey, per){
  per = per || perPageNow();
  var total=Math.max(1, Math.ceil(arr.length/per));
  var p=parseInt(ui._pg[pkey]||'1',10); if(!isFinite(p)||p<1) p=1; if(p>total) p=total;
  ui._pg[pkey]=p;
  return { rows: arr.slice((p-1)*per, p*per), page:p, total:total };
}
function pageBar(pkey, page, total){
  if (total<=1) return '';
  function btn(label, n, opts){
    opts=opts||'';
    return '<button type="button" data-act="pg" data-key="'+esc(pkey)+'" data-v="'+n+'" '+opts+'>'+label+'</button>';
  }
  var start=Math.max(1, Math.min(page-2, total-4));
  var nums=''; for(var n=start;n<=Math.min(total,start+4);n++){
    nums += btn(n, n, n===page?'class="on"':'');
  }
  return '<div class="pgbar">'+
    btn('‹', Math.max(1,page-1), (page<=1?'disabled':''))+
    nums+
    btn('›', Math.min(total,page+1), (page>=total?'disabled':''))+
    '<span class="pginfo">'+page+' / '+total+' 页</span></div>';
}
/* 状态可多值共存（如「云游」+「想收」）：统一按集合处理，兼容字符串与数组两种存储 */
function stArr(r){
  var v = r==null ? '' : r['状态'];
  if (Array.isArray(v)) return v.map(function(s){ return String(s).trim(); }).filter(Boolean);
  return String(v||'').split(',').map(function(s){ return s.trim(); }).filter(Boolean);
}
function hasStatus(r, v){ return stArr(r).indexOf(v) >= 0; }
/* 持有数量的有效值：在库藏品若没填过，默认视作 1（「手里至少这一件」）；
   非在库或已填过则按原值。用于详情卡展示、内联编辑、新增表单默认值。 */
function effHold(r){
  if (r['持有']!=null && r['持有']!=='') return r['持有'];
  return hasStatus(r,'在库') ? 1 : null;
}
function statusPill(v){
  var map={'想看':0,'在看':1,'看完':2,'搁置':3,'想去':0,'去过':2,
    '待启程':0,'进行中':1,'已完成':2,'未开始':0,'已暂停':3,
    '想收':0,'已预订':1,'在库':2,'已出':3,'云游':4};
  var arr = Array.isArray(v) ? v : String(v||'').split(',').map(function(s){ return s.trim(); }).filter(Boolean);
  if (!arr.length) return '<span class="pill s0">—</span>';
  return arr.map(function(x){
    var c = map[x]==null?0:map[x];
    return '<span class="pill s'+c+'">'+esc(x)+'</span>';
  }).join('');
}

/* ============ 各模块渲染 ============ */
/* 各模块封面 CDN + v13 各分类封面（侧栏/主页/藏品筛选共用；缺图时回退汉字 icon） */
var MOD_BG = {
  collection: 'images/museum-bg.png',                                                          /* v16.0：替换为无水印博物馆背景图 */
  travel:     'images/earth-cover.png',                                                        /* v15.18：基于 16K 颜色 + 4K 高程的地球封面 */
  av:         'images/opera-bg.png',                                                          /* v16.0：新模块「影音厅」用歌剧院背景 */
  study:      'images/study-bg.png',                                                          /* v15.19/v16.0：古典文渊斋（无水印） */
  food:       'images/mod_food.png',
  idea:       'images/idea-sky.png'                                                           /* v15.18：本地银河照片 */
};
function renderOverview(){
  var h='';
  var cards = [
    ['collection','藏'],['travel','旅'],['av','音'],['study','学'],['food','食'],['idea','感']
  ].map(function(p){
    var m=MODS[p[0]], s=store[p[0]];
    /* v58：统一用 moduleCount（藏品排除书籍杂志、馐馔坊含菜谱、文渊斋含书籍杂志） */
    var count = moduleCount(p[0]);
    var n = s.status==='loading' ? '读取中' : (s.status==='error' ? '读取失败' : String(count)+(m.unit||' 条'));
    var bg = MOD_BG[p[0]] || '';
    return '<button class="ovcard" type="button" data-act="go" data-key="'+p[0]+'"'+
      ' style="--ovbg:url(\''+bg+'\')">'+
      '<div class="ovcover" style="background-image:url(\''+bg+'\')"></div>'+
      '<div class="ovmask"></div>'+
      '<div class="ovbody"><em>'+esc(m.eyebrow||m.name)+'</em><b>'+esc(m.name)+'</b><span>'+esc(n)+'</span></div>'+
      '</button>';
  }).join('');
  h += '<section class="panel"><div class="panel-head"><div><h2>六个地方</h2>'+
    '<div class="hint">点一下进到某个模块</div></div></div><div class="ovgrid">'+cards+'</div></section>';

  /* 藏品概览（v58：书籍/杂志已完全归文渊斋管，这里全部排除，避免两边重复计数） */
  var cs=store.collection;
  var csRows = cs.rows.filter(function(r){ return LEGACY_BOOK_CATS.indexOf(r['大类']) < 0; });
  var year=ui.year;
  var owned=csRows.filter(function(r){ return hasStatus(r,'在库'); });
  /* v59：年份未选时默认统计全部 */
  var isAll = !year;
  var bought = isAll ? csRows : csRows.filter(function(r){ return yr(r['购入日期'])===year; });
  var spend=0; bought.forEach(function(r){ spend += num(r['购入价格']); });
  var allCost = 0; csRows.forEach(function(r){ allCost += num(r['购入价格']); });
  /* v58：有价格但没填购入日期的藏品不会计入「年投入」，给出明确提示避免误解 */
  var noDateCost = csRows.filter(function(r){ return !yr(r['购入日期']) && num(r['购入价格'])>0; });
  var byCat={}; csRows.forEach(function(r){ var k=r['大类']||'其他'; byCat[k]=(byCat[k]||0)+1; });
  var maxC=1; Object.keys(byCat).forEach(function(k){ if(byCat[k]>maxC) maxC=byCat[k]; });
  var ys={}; csRows.forEach(function(r){ var y=yr(r['购入日期']); if(y) ys[y]=1; });
  var curY = String(new Date().getFullYear());
  for (var y=2000; y<=parseInt(curY,10); y++) ys[String(y)]=1;
  ys[ui.year]=1;
  var ysel='<select id="yearSel" style="min-height:34px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:#fbf8f3;font-size:12px">'+
    '<option value=""'+(isAll?' selected':'')+'>全部</option>'+
    Object.keys(ys).filter(function(y){ return y!==''; }).sort().reverse().map(function(y){
      return '<option value="'+y+'"'+(y===ui.year?' selected':'')+'>'+y+'</option>'; }).join('')+'</select>';
  var yearLabel = isAll ? '全部的藏品' : (year+' 年的藏品');
  var boughtLabel = isAll ? '总入手' : (year+' 年入手');
  var spendLabel = isAll ? '总投入' : (year+' 年投入');

  h += '<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>'+yearLabel+'</h2>'+
    '<div class="hint">按购入日期统计'+(noDateCost.length ? ' · '+noDateCost.length+' 件没填「购入日期」未计入当年投入' : '')+'</div></div>'+ysel+'</div>'+
    '<div class="statgrid">'+
      '<div class="stat"><u>在库</u><b>'+owned.length+'</b><i>件</i></div>'+
      '<div class="stat"><u>'+boughtLabel+'</u><b>'+bought.length+'</b><i>件</i></div>'+
      '<div class="stat"><u>IP 数</u><b>'+store.ip.rows.length+'</b><i>个</i></div>'+
    '</div>'+
    '<div class="charge-pop'+(ui.showCharge?' open':'')+'">'+
      '<div class="statgrid charge-grid">'+
        '<div class="stat"><u>'+spendLabel+'</u><b>¥'+Math.round(spend)+'</b></div>'+
        '<div class="stat"><u>累计投入</u><b>¥'+Math.round(allCost)+'</b></div>'+
      '</div>'+
    '</div>';
  if (csRows.length){
    h += '<div class="barlist" style="margin-top:18px">'+CATS.map(function(k){
      if (!byCat[k]) return '';
      return '<div class="barrow"><span>'+k+'</span><div class="track"><div class="fill" style="width:'+
        Math.round(byCat[k]/maxC*100)+'%"></div></div><em>'+byCat[k]+'</em></div>';
    }).join('')+'</div>';
  } else {
    h += emptyHTML('还没有藏品','点「添加藏品」，从最近入手的那件开始。');
  }
  h += '</section>';

  /* 最近留下的 */
  var feed=[];
  function push(key, rows, dateF, titleF, subF){
    rows.forEach(function(r){
      var d=dstr(dateF(r)); if(!d) return;
      feed.push({d:d, key:key, title:titleF(r), sub:subF(r)});
    });
  }
  push('collection', store.collection.rows, function(r){return r['购入日期'];},
    function(r){return r['名称'];}, function(r){return '入手 · '+esc(r['大类']||'');});
  push('travel', store.travel.rows.filter(function(r){return r['状态']==='去过';}),
    function(r){return r['出行日期'];}, function(r){return r['地区']||r['地点']||'';}, function(r){return '去过 · '+(r['国家']||r['国家地区']||'');});
  push('food', store.food.rows, function(r){return r['打卡日期'];},
    function(r){return r['名称'];}, function(r){return (r['类型']||'')+' · '+stars(r['星级']);});
  push('idea', store.idea.rows, function(r){return r['记录日期'];},
    function(r){return String(r['内容']||'').slice(0,40);}, function(r){return '灵感 · '+(r['分类']||'');});
  feed.sort(function(a,b){ return b.d.localeCompare(a.d); });
  feed = feed.slice(0,12);
  h += '<section class="panel"><div class="panel-head"><div><h2>最近留下的</h2>'+
    '<div class="hint">跨模块按时倒序</div></div></div>';
  if (feed.length){
    h += '<div class="timeline">'+feed.map(function(f){
      return '<div class="tl"><time>'+esc(mdText(f.d))+'</time><div><b>'+esc(f.title)+'</b>'+
        '<span>'+f.sub+' · '+esc(MODS[f.key].name)+'</span></div></div>';
    }).join('')+'</div>';
  } else {
    h += emptyHTML('还没有动态','加几条记录，这里会长成一条时间线。');
  }
  h += '</section>';
  return h;
}

/* ==================== 藏品 ==================== */
function extraStrip(){
  var out=[];
  if (store.ip.status==='error')
    out.push('IP 库读取失败 <button class="btn link" type="button" data-act="reload" data-key="ip">重试</button>');

  if (store.series.status==='error')
    out.push('系列读取失败 <button class="btn link" type="button" data-act="reload" data-key="series">重试</button>');
  if (store.loc.status==='error')
    out.push('存储地点读取失败 <button class="btn link" type="button" data-act="reload" data-key="loc">重试</button>');
  return out.length ? '<div style="margin-top:6px;color:var(--red)">'+out.join(' · ')+'</div>' : '';
}
function collStats(){
  var s=store.collection, year=ui.year;
  /* v58：书籍/杂志归文渊斋，藏品馆统计排除 */
  var rows=s.rows.filter(function(r){ return LEGACY_BOOK_CATS.indexOf(r['大类'])<0; });
  var owned=rows.filter(function(r){ return hasStatus(r,'在库'); });
  var isAll = !year;
  var bought = isAll ? rows : rows.filter(function(r){ return yr(r['购入日期'])===year; });
  var spend=0; bought.forEach(function(r){ spend += num(r['购入价格']); });
  var byCat={}; rows.forEach(function(r){ var k=r['大类']||'其他'; byCat[k]=(byCat[k]||0)+1; });
  var maxC=1; Object.keys(byCat).forEach(function(k){ if(byCat[k]>maxC) maxC=byCat[k]; });
  var boughtLabel = isAll ? '总入手' : (year+' 年入手');
  var spendLabel = isAll ? '总投入' : (year+' 年投入');
  var h='<div class="statgrid">'+
    '<div class="stat"><u>在库</u><b>'+owned.length+'</b><i>件</i></div>'+
    '<div class="stat"><u>'+boughtLabel+'</u><b>'+bought.length+'</b><i>件</i></div>'+
    '<div class="stat"><u>IP 数</u><b>'+store.ip.rows.length+'</b><i>个</i></div>'+
    '<div class="stat"><u>系列数</u><b>'+store.series.rows.length+'</b><i>套</i></div>'+
    '</div>';
  /* v70：总投入金额面板（仿充电量逻辑，点击「总投入」按钮切换） */
  h += '<div class="charge-pop'+(ui.showInvest?' open':'')+'">'+
    '<div class="statgrid charge-grid">'+
      '<div class="stat"><u>'+spendLabel+'</u><b>¥'+Math.round(spend)+'</b></div>'+
    '</div>'+
    '</div>';
  if (s.rows.length){
    h += '<div class="barlist" style="margin-top:18px">'+CATS.map(function(k){
      if (!byCat[k]) return '';
      return '<div class="barrow"><span>'+k+'</span><div class="track"><div class="fill" style="width:'+
        Math.round(byCat[k]/maxC*100)+'%"></div></div><em>'+byCat[k]+'</em></div>';
    }).join('')+'</div>';
  }
  return h;
}
function collectionWall(rows){
  return '<div class="wall">'+rows.map(function(r){
    var t=r['名称']||'未命名';
    var sub=(r['小类']||'')+(r['IP']?' · '+r['IP']:'');
    var no=String(r['编号']||'');
    return '<div class="poster" data-act="item" data-key="collection" data-id="'+esc(r._id)+'"'+
      ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
      '<div class="cover'+(hasCover(r)?'':' noimg')+'" style="'+coverStyle(r,t)+'">'+
      (hasCover(r)?'':'<b>'+esc(String(t).slice(0,1))+'</b>')+
      '<span class="tag">'+esc(r['大类']||'')+'</span>'+
      (no?'<span class="no">'+esc(no)+'</span>':'')+
      (num(r['星级'])?'<span class="score">'+stars(r['星级'])+'</span>':'')+
      pkQuickBtnsHTML(r)+
      pkTypeIconsHTML(r)+
      '</div><h4>'+esc(t)+'</h4><p>'+esc(sub||'—')+'</p></div>';
  }).join('')+'</div>';
}
function collectionList(rows){
  return '<div class="rows">'+rows.map(function(r){
    return '<div class="crow" data-act="item" data-key="collection" data-id="'+esc(r._id)+'"'+
      ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
      '<div class="t"><b>'+esc(r['名称']||'未命名')+'</b>'+
      '<span>'+esc(r['大类']||'')+(r['小类']?' · '+esc(r['小类']):'')+
      (r['编号']?' · #'+esc(r['编号']):'')+
      (r['IP']?' · '+esc(r['IP']):'')+
      (r['系列']?' · '+esc(r['系列']):'')+
      (dstr(r['购入日期'])?' · 入手 '+dstr(r['购入日期']):'')+'</span>'+
      (r['短评']?'<em>'+esc(r['短评'])+'</em>':'')+'</div>'+
      '<span class="loc">'+(r['存储地点']?esc(r['存储地点']):'未指定位置')+'</span>'+
      statusPill(r['状态'])+'</div>';
  }).join('')+'</div>';
}
function modeSeg(){
  var cur=ui.collection.mode;
  return '<div class="seg">'+[['cat','按类别'],['ip','按 IP'],['series','按系列']].map(function(o){
    return '<button type="button" data-act="cmode" data-v="'+o[0]+'" class="'+(cur===o[0]?'on':'')+'">'+o[1]+'</button>';
  }).join('')+'</div>';
}
function renderCollection(){
  var s=store.collection;
  var strip='<div class="strip">'+stripHTML('collection')+extraStrip()+'</div>';
  var ys={}; s.rows.forEach(function(r){ var y=yr(r['购入日期']); if(y) ys[y]=1; });
  var curY2 = String(new Date().getFullYear());
  for (var y2=2000; y2<=parseInt(curY2,10); y2++) ys[String(y2)]=1;
  ys[ui.year]=1;
  var isAll = !ui.year;
  var ysel='<select id="yearSel" style="min-height:34px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:#fbf8f3;font-size:12px">'+
    '<option value=""'+(isAll?' selected':'')+'>全部</option>'+
    Object.keys(ys).filter(function(y){ return y!==''; }).sort().reverse().map(function(y){
      return '<option value="'+y+'"'+(y===ui.year?' selected':'')+'>'+y+'</option>'; }).join('')+'</select>';
  /* v75fix：标题块 flex:1 占满左侧，把「总投入 + 年份下拉」一起顶到最右；顺序为 总投入 → 年份 */
  var head='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div style="flex:1;min-width:0"><h2>概览</h2>'+
    '<div class="hint">在库 / '+(isAll?'全部':ui.year+' 年')+'入手 / 投入 / 分类分布</div></div>'+
    '<button class="btn ghost sm'+(ui.showInvest?' on':'')+'" type="button" data-act="toggleinvest">总投入</button>'+
    ysel+'</div>'+collStats()+'</section>';
  var m=ui.collection.mode;
  /* v75fix：seriesId/ipId 优先于 mode 路由——从 cat 模式点系列卡片时 mode 仍是 cat，
     但 seriesId 已设，必须进系列详情（否则 renderCatMode 不检查 seriesId，详情永远不出现） */
  var body = ui.collection.seriesId ? renderSeriesMode()
    : (ui.collection.ipId ? renderIpMode()
    : (m==='ip' ? renderIpMode() : (m==='series' ? renderSeriesMode() : renderCatMode())));
  return strip + head + body;
}
function renderCatMode(){
  var f=ui.collection, s=store.collection, rows=filtered('collection');
  var h='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>藏品</h2>'+
    '<div class="hint">点开任意一件，看它的购入信息和存放位置</div></div>'+modeSeg()+'</div>'+
    /* v75fix：用块级 flex 铺满整行（.searchwrap 默认 inline-flex 会收缩到内容宽，× 会被挤到可视区外） */
    '<div class="searchwrap" style="margin-bottom:12px;display:flex"><input class="search" autocomplete="off" id="q_collection" placeholder="搜名称 / IP / 系列 / 地点 / 短评" value="'+esc(f.q)+'"></div>'+
    '<div class="chips">'+
    '<button class="chip'+(f.cat?'':' on')+'" type="button" data-act="f" data-k="cat" data-v="">全部</button>'+
    CATS.map(function(t){
      var n=s.rows.filter(function(r){ return r['大类']===t; }).length;
      return '<button class="chip'+(f.cat===t?' on':'')+'" type="button" data-act="f" data-k="cat" data-v="'+t+'">'+
        t+(n?' '+n:'')+'</button>';
    }).join('')+'</div>';
  var used={};
  (SUBS[f.cat]||[]).forEach(function(x){ used[x]=1; });
  s.rows.forEach(function(r){ if (r['大类']===f.cat && r['小类']) used[r['小类']]=1; });
  var subList=Object.keys(used);
  if (f.cat && subList.length){
    h += '<div class="subchips">'+
      '<button class="chip'+(f.sub?'':' on')+'" type="button" data-act="f" data-k="sub" data-v="">不限</button>'+
      subList.map(function(t){
        return '<button class="chip'+(f.sub===t?' on':'')+'" type="button" data-act="f" data-k="sub" data-v="'+esc(t)+'">'+esc(t)+'</button>';
      }).join('')+'</div>';
  }
  h += '<div class="segline" style="margin-top:14px">'+
    '<div class="seg"><button type="button" data-act="view" data-v="wall" class="'+(f.view==='wall'?'on':'')+'">封面墙</button>'+
    '<button type="button" data-act="view" data-v="list" class="'+(f.view==='list'?'on':'')+'">列表</button></div>'+
    '<button class="btn ghost sm" type="button" data-act="locmgr">管理存储地点</button></div>';
  if (s.status==='loading'){ h += emptyHTML('正在读线上数据…','第一次打开会稍微等一下。'); return h+'</section>'; }
  if (s.status==='error'){ h += emptyHTML('没能读到数据','点上面的「重试」再拉一次。'); return h+'</section>'; }
  if (!rows.length){
    h += emptyHTML(s.rows.length?'没有符合筛选的条目':'还没有藏品','点右上角「添加藏品」，从最近入手的那件开始。');
    return h+'</section>';
  }

  /* v75：封面墙视图下，只要 wall 模式就按系列分组（全部 / 大类 / 小类不限 / 小类 都生效），
     系列卡片可点击进入系列详情；未归类 items 单独一组并分页 */
  if (f.view==='wall'){
    var seriesMap={}, sOrder=[], unclass=[];
    rows.forEach(function(r){
      var sn = r['系列']||'';
      if (!sn){ unclass.push(r); return; }
      if (!seriesMap[sn]){ seriesMap[sn]=[]; sOrder.push(sn); }
      seriesMap[sn].push(r);
    });

    /* 系列卡片（点击进入系列详情） */
    if (sOrder.length){
      h += '<div class="grp"><h4>系列 <i>'+sOrder.length+'</i></h4><div class="ipseries-grid">';
      sOrder.forEach(function(sn){
        var srows = seriesMap[sn];
        var se = store.series.rows.filter(function(r){ return r['系列名称']===sn; })[0];
        var sid = se ? se._id : '';
        var cover = se && hasCover(se) ? coverStyle(se, sn) : (srows[0] && hasCover(srows[0]) ? coverStyle(srows[0], sn) : '');
        var subcats={}; srows.forEach(function(r){ var k=r['大类']||'其他'; subcats[k]=(subcats[k]||0)+1; });
        var desc = Object.keys(subcats).map(function(k){ return k+' '+subcats[k]; }).join(' · ') || srows.length+' 件';
        h += '<div class="ipcard ipseries-card" data-act="seriesopen" data-id="'+esc(sid)+'"'+
          ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
          '<div class="ph" style="'+cover+'">'+(cover?'':'<b>'+esc(String(sn).slice(0,1))+'</b>')+'</div>'+
          '<div class="bd"><strong>'+esc(sn)+'</strong><span>'+esc(desc)+'</span></div></div>';
      });
      h += '</div></div>';
    }

    /* 未归类 items（分页；没有任何系列属性时整组即全部 items） */
    if (unclass.length){
      h += renderPagedWall(unclass, sOrder.length ? '未归类' : (f.sub || f.cat || '全部'));
    } else if (!sOrder.length){
      h += renderPagedWall(rows, f.sub || f.cat || '全部');
    }
  } else {
    /* 列表视图：原有逻辑 + 分页 */
    h += renderPagedWall(rows, f.sub || f.cat || '全部');
  }

  return h+'</section>';
}

/* v70：分页墙渲染 —— 超过阈值时自动分页，用户可选每页数目 */
function renderPagedWall(rows, label){
  var f = ui.collection;
  var total = rows.length;
  /* 默认不分页（pageSize=0）；用户选了才分；列表模式强制不分页 */
  var ps = f.pageSize || 0;
  if (f.view==='list' || (ps <= 0 && total <= 200)){
    return '<div class="grp"><h4>'+esc(label)+' <em>'+total+'</em></h4>'+
      (f.view==='wall'?collectionWall(rows):collectionList(rows))+'</div>';
  }
  /* 自动分页：没手动设过且超过200条，默认200/页 */
  if (!ps && total > 200) ps = 200;
  var totalPages = Math.ceil(total / ps);
  var p = Math.max(1, Math.min(f.page || 1, totalPages));
  var start = (p - 1) * ps;
  var pageRows = rows.slice(start, start + ps);
  var h = '<div class="grp"><h4>'+esc(label)+' <em>'+total+'</em></h>';

  /* 分页控制栏 */
  h += '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0 12px;font-size:11.5px;color:var(--muted)">';
  h += '<span>每页</span>';
  [0,100,200,500,1000].forEach(function(sz){
    var lbl = sz===0?'全部':String(sz);
    h += '<button type="button" data-act="setpagesize" data-v="'+sz+'" class="btn '+((f.pageSize||0)===sz?'primary sm':'ghost sm')+'" style="padding:3px 8px;font-size:11px">'+lbl+'</button>';
  });
  if (totalPages > 1){
    h += '<span style="margin-left:auto">'+p+'/'+totalPages+' 页</span>';
    if (p > 1) h += '<button type="button" data-act="setpage" data-v="'+(p-1)+'" class="btn ghost sm" style="padding:3px 8px;font-size:11px">← 上一页</button>';
    if (p < totalPages) h += '<button type="button" data-act="setpage" data-v="'+(p+1)+'" class="btn ghost sm" style="padding:3px 8px;font-size:11px">下一页 →</button>';
  }
  h += '</div>';

  h += (f.view==='wall'?collectionWall(pageRows):collectionList(pageRows))+'</div>';
  return h;
}
function renderIpMode(){
  if (ui.collection.ipId) return renderIpDetail();
  var s=store.ip, c=store.collection;
  var h='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>IP 库</h2>'+
    '<div class="hint">同一个 IP 下的手办、毛绒、卡牌、周边都归在一起</div></div>'+modeSeg()+'</div>';
  if (s.status==='loading'){ h += emptyHTML('正在读线上数据…',''); return h+'</section>'; }
  if (s.status==='error'){ h += emptyHTML('没能读到 IP 库','点上面的「重试」再拉一次。'); return h+'</section>'; }
  h += '<div class="ipgrid">'+s.rows.map(function(ip){
    var name=ip['IP名称']||'未命名';
    var items=c.rows.filter(function(r){ return r['IP']===name; });
    var by={}; items.forEach(function(r){ var k=r['大类']||'其他'; by[k]=(by[k]||0)+1; });
    var desc=Object.keys(by).map(function(k){ return k+' '+by[k]; }).join(' · ') || '还没挂东西';
    return '<div class="ipcard" data-act="ipopen" data-id="'+esc(ip._id)+'"'+
      ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
      '<div class="ph" style="'+coverStyle(ip,name)+'">'+(hasCover(ip)?'':'<b>'+esc(String(name).slice(0,1))+'</b>')+'</div>'+
      '<div class="bd"><strong>'+esc(name)+'</strong><span>'+esc(desc)+'</span></div></div>';
  }).join('')+
  '<div class="ipcard add" data-act="add" data-key="ip">'+
    '<div class="ph">＋</div><div class="bd"><strong>新增 IP</strong><span>先建 IP，再往里挂东西</span></div></div>'+
  '</div>';
  var ipNames={}; s.rows.forEach(function(r){ var n=r['IP名称']; if(n) ipNames[n]=1; });
  /* v58：书籍/杂志归文渊斋，不进 IP 库的未绑定列表 */
  var loose=c.rows.filter(function(r){ return LEGACY_BOOK_CATS.indexOf(r['大类'])<0 && (!r['IP'] || !ipNames[r['IP']]); });
  if (loose.length){
    h += '<div class="grp" style="margin-top:24px"><h4>未绑定 IP <i>'+loose.length+' 件</i></h4>'+collectionWall(loose)+'</div>';
  }
  return h+'</section>';
}
function renderIpDetail(){
  var ip=store.ip.rows.filter(function(r){ return String(r._id)===String(ui.collection.ipId); })[0];
  if (!ip){ ui.collection.ipId=null; return renderIpMode(); }
  var name=ip['IP名称']||'未命名';
  /* v58/v70：书籍/杂志归文渊斋管，IP 详情里不显示它们 */
  var items=store.collection.rows.filter(function(r){ return r['IP']===name && LEGACY_BOOK_CATS.indexOf(r['大类'])<0; });
  var h='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>'+esc(name)+'</h2>'+
    '<div class="hint">这个 IP 下的全部东西</div></div>'+modeSeg()+'</div>'+
    '<div style="margin-bottom:14px"><button class="btn link" type="button" data-act="ipback">← 返回 IP 库</button></div>'+
    '<div class="iphero">'+
      '<div class="ph" style="'+coverStyle(ip,name)+'">'+(hasCover(ip)?'':'<b>'+esc(String(name).slice(0,1))+'</b>')+'</div>'+
      '<div><h3>'+esc(name)+'</h3>'+
      (ip['简介']?'<p>'+esc(ip['简介'])+'</p>':'')+
      '<div class="acts">'+
        '<button class="btn primary sm" type="button" data-act="addinitem" data-ip="'+esc(name)+'">+ 在这个 IP 下添加</button>'+
        '<button class="btn ghost sm" type="button" data-act="edit" data-key="ip" data-id="'+esc(ip._id)+'">编辑 IP</button>'+
        '<button class="btn ghost sm" type="button" data-act="delip" data-id="'+esc(ip._id)+'" style="color:var(--red)">删除 IP</button>'+
      '</div></div></div>';
  if (!items.length){
    h += emptyHTML('这个 IP 下还没有东西','点「在这个 IP 下添加」，手办、毛绒、卡牌，或者任何别的都行。');
    return h+'</section>';
  }

  /* v70：IP 详情按系列分组展示 —— 系列在前，未归类 items 在后 */
  var seriesMap={}, order=[];
  var unclassified=[];
  items.forEach(function(r){
    var sn = r['系列']||'';
    if (!sn){ unclassified.push(r); return; }
    if (!seriesMap[sn]){ seriesMap[sn]=[]; order.push(sn); }
    seriesMap[sn].push(r);
  });

  /* 系列卡片：每个系列一张卡片，点击进入系列详情 */
  if (order.length){
    h += '<div class="grp"><h4>系列 <i>'+order.length+'</i></h4><div class="ipseries-grid">';
    order.forEach(function(sn){
      var srows = seriesMap[sn];
      var se = store.series.rows.filter(function(r){ return r['系列名称']===sn; })[0];
      var sid = se ? se._id : '';
      var cover = se && hasCover(se) ? coverStyle(se, sn) : (srows[0] && hasCover(srows[0]) ? coverStyle(srows[0], sn) : '');
      var subcats={}; srows.forEach(function(r){ var k=r['大类']||'其他'; subcats[k]=(subcats[k]||0)+1; });
      var desc = Object.keys(subcats).map(function(k){ return k+' '+subcats[k]; }).join(' · ') || srows.length+' 件';
      h += '<div class="ipcard ipseries-card" data-act="seriesopen" data-id="'+esc(sid)+'"'+
        ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
        '<div class="ph" style="'+cover+'">'+(cover?'':'<b>'+esc(String(sn).slice(0,1))+'</b>')+'</div>'+
        '<div class="bd"><strong>'+esc(sn)+'</strong><span>'+esc(desc)+'</span></div></div>';
    });
    h += '</div></div>';
  }

  /* 未归类的 items：按 大类 分组 */
  if (unclassified.length){
    var groups={}, gorder=[];
    unclassified.forEach(function(r){ var k=r['大类']||'其他'; if(!groups[k]){ groups[k]=[]; gorder.push(k); } groups[k].push(r); });
    h += gorder.map(function(k){
      return '<div class="grp"><h4>'+esc(k)+'（未归类） <em>'+groups[k].length+'</em></h4>'+collectionWall(groups[k])+'</div>';
    }).join('');
  }

  return h+'</section>';
}

/* ---------- 打卡点 ----------
   打卡点是「遐方坞」里的一类独立记录：在地图上标记一个去过 / 想记的地方，
   字段：地点名字、日期、城市景区、封面图片、内容，外加经纬度。
   与「目的地」分开：目的地显示在 3D 地球上（想去 / 去过），打卡点只显示在高德地图上。
   打卡点存在独立的 store.checkin 表里，随其它数据一起落盘（localfile / gh / local 都支持）。 */
function checkinTotal(){
  var rows = (store.checkin && store.checkin.rows) || [];
  return rows.length;
}
/* 打卡点入口：先选景区 / 城市 */
/* ============================================================
   坐标系转换：WGS-84 ↔ GCJ-02（火星坐标）
   ------------------------------------------------------------
   项目里所有经纬度都是 WGS-84（Open-Meteo 地理编码、3D 地球点选都用它）。
   高德 / 腾讯地图用的是 GCJ-02，两者在国内相差约 300~600 米。
   不转换的话，打卡点会飘到几百米外。
   显示：WGS-84 → GCJ-02；点地图存回：GCJ-02 → WGS-84。
   ============================================================ */
var _GEO_PI = 3.1415926535897932384626;
var _GEO_A  = 6378245.0;                    /* 克拉索夫斯基椭球长半轴 */
var _GEO_EE = 0.00669342162296594323;       /* 偏心率平方 */
function outOfChina(lat, lon){
  return (lon < 72.004 || lon > 137.8347 || lat < 0.8293 || lat > 55.8271);
}
function _tLat(x, y){
  var ret = -100.0 + 2.0*x + 3.0*y + 0.2*y*y + 0.1*x*y + 0.2*Math.sqrt(Math.abs(x));
  ret += (20.0*Math.sin(6.0*x*_GEO_PI) + 20.0*Math.sin(2.0*x*_GEO_PI)) * 2.0/3.0;
  ret += (20.0*Math.sin(y*_GEO_PI) + 40.0*Math.sin(y/3.0*_GEO_PI)) * 2.0/3.0;
  ret += (160.0*Math.sin(y/12.0*_GEO_PI) + 320*Math.sin(y*_GEO_PI/30.0)) * 2.0/3.0;
  return ret;
}
function _tLon(x, y){
  var ret = 300.0 + x + 2.0*y + 0.1*x*x + 0.1*x*y + 0.1*Math.sqrt(Math.abs(x));
  ret += (20.0*Math.sin(6.0*x*_GEO_PI) + 20.0*Math.sin(2.0*x*_GEO_PI)) * 2.0/3.0;
  ret += (20.0*Math.sin(x*_GEO_PI) + 40.0*Math.sin(x/3.0*_GEO_PI)) * 2.0/3.0;
  ret += (160.0*Math.sin(x/12.0*_GEO_PI) + 320*Math.sin(x*_GEO_PI/30.0)) * 2.0/3.0;
  return ret;
}
function wgs84ToGcj02(lat, lon){
  lat = Number(lat); lon = Number(lon);
  if (!isFinite(lat) || !isFinite(lon) || outOfChina(lat, lon)) return { lat: lat, lon: lon };
  var dLat = _tLat(lon - 105.0, lat - 35.0);
  var dLon = _tLon(lon - 105.0, lat - 35.0);
  var radLat = lat / 180.0 * _GEO_PI;
  var magic = Math.sin(radLat); magic = 1 - _GEO_EE * magic * magic;
  var sqrtMagic = Math.sqrt(magic);
  dLat = (dLat * 180.0) / ((_GEO_A * (1 - _GEO_EE)) / (magic * sqrtMagic) * _GEO_PI);
  dLon = (dLon * 180.0) / (_GEO_A / sqrtMagic * Math.cos(radLat) * _GEO_PI);
  return { lat: lat + dLat, lon: lon + dLon };
}
/* 反解：迭代逼近，3~5 次即可到亚米级 */
function gcj02ToWgs84(lat, lon){
  lat = Number(lat); lon = Number(lon);
  if (!isFinite(lat) || !isFinite(lon) || outOfChina(lat, lon)) return { lat: lat, lon: lon };
  var wLat = lat, wLon = lon;
  for (var i = 0; i < 6; i++){
    var g = wgs84ToGcj02(wLat, wLon);
    var dLat = g.lat - lat, dLon = g.lon - lon;
    if (Math.abs(dLat) < 1e-7 && Math.abs(dLon) < 1e-7) break;
    wLat -= dLat; wLon -= dLon;
  }
  return { lat: wLat, lon: wLon };
}

/* ============================================================
   打卡地图：高德地图 JS API 2.0（需要 Key + 安全密钥，存 localStorage）
   ============================================================ */
var CKMAP = null;
function stopCheckinMap(){ CKMAP = null; }
function amapKey(){    try { return localStorage.getItem('lifedesk_amap_key') || ''; } catch(e){ return ''; } }
function amapSecret(){ try { return localStorage.getItem('lifedesk_amap_secret') || ''; } catch(e){ return ''; } }

/* 动态加载高德 SDK（带队列，多次调用只加载一次） */
var _amapQueue = null;
function loadAMap(key, secret, cb){
  if (window.AMap && window.AMap.Map){ cb(true); return; }
  if (_amapQueue){ _amapQueue.push(cb); return; }
  _amapQueue = [cb];
  /* 2.0 起必须先注入安全密钥，否则地图不显示 */
  window._AMapSecurityConfig = { securityJsCode: secret || '' };
  var sc = document.createElement('script');
  /* 2.0 起 Scale / ToolBar / PlaceSearch 都是「插件」，必须在 URL 里用 plugin= 显式加载，
     否则 new AMap.Scale() 会报「AMap.Scale is not a constructor」 */
  sc.src = 'https://webapi.amap.com/maps?v=2.0&key=' + encodeURIComponent(key) +
           '&plugin=AMap.Scale,AMap.ToolBar,AMap.PlaceSearch';
  sc.onload = function(){
    var q = _amapQueue; _amapQueue = null;
    (q || []).forEach(function(f){ try { f(true); } catch(e){ f(false); } });
  };
  sc.onerror = function(){
    var q = _amapQueue; _amapQueue = null;
    (q || []).forEach(function(f){ try { f(false); } catch(e){} });
  };
  document.head.appendChild(sc);
}
