$('brandBtn').onclick = function(){ openBrand(); };

function reloadOne(key){
  store[key]={rows:[],status:'loading'}; render();
  fetchAll(key, function(rows){
    if (rows===null){ store[key].status='error'; toast('「'+MODS[key].name+'」没读到，再试一次看看'); }
    else { store[key].rows=rows; store[key].status= rows.length?'ok':'empty'; }
    render();
  });
}

/* ============ 表单 ============ */
/* ---------- 动态下拉：小类 / IP / 存储地点 ---------- */
function dynOptions(src){
  if (src==='sub') return SUBS[(editing && editing.vals) ? editing.vals['大类'] : ''] || [];
  if (src==='ip')  return (store.ip.rows  || []).map(function(r){ return r['IP名称'];   }).filter(Boolean);
  if (src==='series') return (store.series.rows || []).map(function(r){ return r['系列名称']; }).filter(Boolean);
  /* v75fix：用 locDisplayName —— 新数据是「房间 · 柜体墙面 · 所在层」三段合成，
     老数据只有「地点名称」，两种都能取到展示名 */
  if (src==='loc') return (store.loc.rows || []).map(locDisplayName).filter(Boolean);
  return [];
}
function fillDynField(host, k){
  var w=host.querySelector('.dynwrap[data-k="'+k+'"]'); if (!w) return;
  var src=w.getAttribute('data-src');
  var sel=w.querySelector('[data-dyn-sel]'), cus=w.querySelector('[data-dyn-cus]');
  if (!sel) return;
  var opts=dynOptions(src);
  var cur=String(editing.vals[k]||'');
  var known=opts.indexOf(cur)>=0;
  var emptyLabel = src==='ip' ? '（不属于任何 IP）' : (src==='loc' ? '（暂不指定）' : '（无）');
  var html='<option value=""'+(cur===''?' selected':'')+'>'+emptyLabel+'</option>';
  opts.forEach(function(o){
    html += '<option value="'+esc(o)+'"'+(o===cur?' selected':'')+'>'+esc(o)+'</option>';
  });
  html += '<option value="__custom__"'+((cur && !known)?' selected':'')+'>＋ 自定义…</option>';
  sel.innerHTML=html;
  var showCus=!!(cur && !known);
  cus.style.display = showCus ? 'block' : 'none';
  cus.value = showCus ? cur : '';
}
function statesFor(cat){ return cat==='观影' ? STATES_VIEW : STATES_OWN; }
function refillStateOptions(host){
  var sel=host.querySelector('[data-f="状态"]'); if (!sel || sel.tagName!=='SELECT') return;
  var list=statesFor(editing.vals['大类']);
  var cur=editing.vals['状态'];
  if (list.indexOf(cur)<0){ cur = list[0]; editing.vals['状态']=cur; }
  sel.innerHTML = list.map(function(o){
    return '<option value="'+esc(o)+'"'+(o===cur?' selected':'')+'>'+esc(o)+'</option>'; }).join('');
}
/* ---------- 图片压缩：长边 800px，PNG 优先保留透明，否则 JPEG ----------
 * 体积上限收紧到 ~160KB（原 380KB）。原因：封面 / 图片是以 base64 内联在
 * lifedesk.json 里的，若每个条目都配图，单文件会迅速膨胀
 * （100 张 × 380KB ≈ 38MB），既拖慢整体加载与上传，也容易顶到
 * GitHub Contents API 的单文件上限。卡片封面实际显示尺寸很小，160KB 足够清晰。 */
var IMG_MAX_BYTES = 160000;   /* base64 字符串长度上限（约合 120KB 二进制） */
function compressImage(file, maxSide, cb){
  var fr=new FileReader();
  fr.onload=function(){
    var img=new Image();
    img.onload=function(){
      var w=img.width, h=img.height;
      var scale=Math.min(1, maxSide/Math.max(w,h));
      var cw=Math.max(1,Math.round(w*scale)), ch=Math.max(1,Math.round(h*scale));
      var cv=document.createElement('canvas'); cv.width=cw; cv.height=ch;
      var ctx=cv.getContext('2d');
      if (/png|webp|gif/i.test(file.type||'')){
        ctx.drawImage(img,0,0,cw,ch);
        var png='';
        try { png=cv.toDataURL('image/png'); } catch(e){}
        if (png && png.length < IMG_MAX_BYTES){ cb(png); return; }
      }
      ctx.fillStyle='#fff'; ctx.fillRect(0,0,cw,ch);
      ctx.drawImage(img,0,0,cw,ch);
      var q=0.78, out='';
      try { out=cv.toDataURL('image/jpeg', q); } catch(e){ cb(''); return; }
      while (out.length > IMG_MAX_BYTES && q > 0.45){ q-=0.10; out=cv.toDataURL('image/jpeg', q); }
      cb(out);
    };
    img.onerror=function(){ cb(''); };
    img.src=fr.result;
  };
  fr.onerror=function(){ cb(''); };
  fr.readAsDataURL(file);
}

var editing=null, formAfter=null;
function fieldVal(row, f){
  if (!row) return f.t==='check'?false:(f.t==='checks'||f.t==='multi'?(f.def!=null?(Array.isArray(f.def)?f.def.slice():[f.def]):[]):(f.def!=null?f.def:''));
  var v=row[f.k];
  if (f.t==='img'){
    if (v && v[0] && v[0].imageUrl){
      if (editing && v[0].viewport) editing.vals[f.k+'_vp'] = v[0].viewport;
      return v[0].imageUrl;
    }
    return '';
  }
  if (f.t==='multi' || f.t==='checks') return v || [];
  if (f.t==='check') return !!v;
  if (f.t==='stars' || f.t==='hearts') return num(v) || (f.def||0);
  if (f.t==='number' || f.t==='currency') return v==null?'':num(v);
  return v==null?'':v;
}
/* 设置图片预览：用与展示卡一致的 background-image + background-position/size */
function setImgPreview(prev, url, k){
  if (!url){
    prev.style.backgroundImage = '';
    prev.style.backgroundRepeat = '';
    prev.style.backgroundPosition = '';
    prev.style.backgroundSize = '';
    var hint = prev.querySelector('.imgvp-hint'); if (hint) hint.hidden = true;
    var bar = prev.parentNode.querySelector('.imgvp-bar'); if (bar) bar.hidden = true;
    return;
  }
  var resolved = resolveImgUrl(url);
  prev.style.backgroundImage = "url('"+resolved.replace(/[\"'()\\]/g,'')+"')";
  prev.style.backgroundRepeat = 'no-repeat';
  applyImgViewport(prev, k);
  var hint = prev.querySelector('.imgvp-hint'); if (hint) hint.hidden = false;
  var bar = prev.parentNode.querySelector('.imgvp-bar'); if (bar) bar.hidden = false;
}
function applyImgViewport(prev, k){
  if (!prev || !k) return;
  var vp = (editing && editing.vals && editing.vals[k+'_vp']) || {s:1,x:0,y:0};
  prev.style.backgroundPosition = (50+vp.x)+'% '+(50+vp.y)+'%';
  prev.style.backgroundSize = Math.max(100, Math.round(vp.s*100))+'% auto';
}
/* ---------- 表单控件绑定（单个表单 / 批量表单共用） ---------- */
function wireFormControls(host, saveDraft){
  host.querySelectorAll('.starsel').forEach(function(box){
    var k=box.getAttribute('data-k');
    /* v58：半星版——左半 hit 设 i-0.5，右半设 i；点击当前值再点同值可清零递减 */
    function setStars(n){
      n=Math.max(0, Math.min(5, num(n)));
      var cur=num(box.getAttribute('data-v'));
      if (n===cur) n=Math.max(0, n-0.5);       /* 点同一个值 → 递减半星，方便改小 */
      editing.vals[k]=n;
      box.setAttribute('data-v', n);
      box.querySelectorAll('.star-btn').forEach(function(btn, idx){
        var i=idx+1, ic=btn.querySelector('.star-ic');
        if (ic) ic.className='star-ic '+((n>=i)?'on':((n>=i-0.5)?'half':''));
      });
      if (saveDraft) saveDraft();
    }
    box.querySelectorAll('.hit').forEach(function(b){
      b.onclick=function(){ setStars(b.getAttribute('data-i')); };
    });
  });
  /* 粉色马卡龙心级：支持半颗心；点击心形左半设 i-0.5，右半设 i */
  host.querySelectorAll('.heartsel').forEach(function(box){
    var k=box.getAttribute('data-k');
    function setHearts(n){
      n = Math.max(0, Math.min(5, num(n)));
      editing.vals[k]=n;
      box.setAttribute('data-v', n);
      box.querySelectorAll('.heart-btn').forEach(function(btn, idx){
        var i=idx+1, h=btn.querySelector('.hheart');
        if(!h) return;
        h.className = 'hheart ' + (n>=i?'on':(n>=i-0.5?'half':''));
      });
      if (saveDraft) saveDraft();
    }
    box.querySelectorAll('.hit').forEach(function(b){
      b.onclick=function(){ setHearts(parseFloat(b.getAttribute('data-i'))); };
    });
  });

  host.querySelectorAll('.multisel').forEach(function(box){
    var k=box.getAttribute('data-k');
    box.querySelectorAll('button').forEach(function(b){
      b.onclick=function(){
        var v=b.getAttribute('data-v'); var arr=editing.vals[k]||[];
        var i=arr.indexOf(v); if(i>=0) arr.splice(i,1); else arr.push(v);
        editing.vals[k]=arr; b.className = arr.indexOf(v)>=0?'on':'';
        if (saveDraft) saveDraft();
      };
    });
  });
  /* v67：书籍「标签分类」↔「小分类」联动。换大类时小分类作废并重建选项；
     小分类里选「＋ 新建小分类…」会真的建 书籍/{名字}-data.json + images/{名字}-封面/。 */
  host.querySelectorAll('select[data-booktag]').forEach(function(sel){
    sel.addEventListener('change', function(){
      if (!editing) return;
      var fk = sel.getAttribute('data-f') || '标签分类';
      editing.vals[fk] = sel.value;
      editing.vals['小分类'] = '';
      var subSel = host.querySelector('select[data-booksub]');
      var tip = host.querySelector('[data-booksub-tip]');
      if (subSel){ subSel.innerHTML = bookSubOptionsHTML(sel.value, ''); subSel.value = ''; subSel.disabled = !sel.value; }
      if (tip) tip.textContent = sel.value
        ? '「' + sel.value + '」下面再细分一层，比如「德语」。新建会自动生成 书籍/德语-data.json 和同名图片文件夹。'
        : '先在上面选一个「标签分类」，才能建它下面的小分类';
      if (saveDraft) saveDraft();
    });
  });
  host.querySelectorAll('select[data-booksub]').forEach(function(sel){
    sel.addEventListener('change', function(){
      if (!editing) return;
      if (sel.value !== '__new__'){ editing.vals['小分类'] = sel.value; if (saveDraft) saveDraft(); return; }
      var parent = String(editing.vals['标签分类'] || '').trim();
      if (!parent){ sel.value = editing.vals['小分类'] || ''; toast('先选好「标签分类」，再建它下面的小分类'); return; }
      sel.value = editing.vals['小分类'] || '';
      promptDialog('在「' + parent + '」下面新建小分类', '小分类名字（如：德语）', '', '创建', function(name){
        if (!name) return '名字不能为空';
        if (BOOK_TAGS.indexOf(name) >= 0) return '不能和五个大分类重名';
        ensureBookSubCat(parent, name).then(function(res){
          if (!res || !res.ok){ toast((res && res.msg) || '创建失败'); return; }
          sel.innerHTML = bookSubOptionsHTML(parent, res.cat);
          sel.value = res.cat;
          editing.vals['小分类'] = res.cat;
          if (saveDraft) saveDraft();
          toast(res.msg);
        });
        return null;
      });
    });
  });
  /* v67：图片链接一变，就同步「存进本地图库」那一行（只有外链/粘贴图时才显示按钮） */
  host.querySelectorAll('.imgwrap input[data-f]').forEach(function(inp){
    var k = inp.getAttribute('data-f');
    function syncImgDl(){
      var tip = host.querySelector('[data-img-dltip="' + k + '"]');
      var btn = host.querySelector('[data-act="dlcover"][data-k="' + k + '"]');
      var rm = imgIsRemote(inp.value);
      if (tip) tip.textContent = rm
        ? '现在是网络链接，点上面「⬇ 下载」把它存进 data/images（同一张图只会存一次）'
        : (inp.value ? '这张已经是本地图片了' : '粘贴一个图片链接后，点「⬇ 下载」即可存进本地图库');
      /* v75fix：按钮常驻（不再 display:none 藏起来），非外链时置灰禁用，用户看得到入口 */
      if (btn){ btn.disabled = !rm; btn.style.opacity = rm ? '' : '.45'; }
    }
    inp.addEventListener('input', syncImgDl);
    inp.addEventListener('change', syncImgDl);
    inp.addEventListener('paste', function(){ setTimeout(syncImgDl, 0); });
    syncImgDl();
  });
  /* 多选 checkbox（同一 key 多个 data-v） */
  host.querySelectorAll('[data-f][data-v][type="checkbox"]').forEach(function(inp){
    var k=inp.getAttribute('data-f');
    function syncChecks(){
      var arr=[];
      host.querySelectorAll('[data-f="'+k+'"][data-v]').forEach(function(cb){ if(cb.checked) arr.push(cb.getAttribute('data-v')); });
      editing.vals[k]=arr;
      if (saveDraft) saveDraft();
    }
    inp.addEventListener('change', syncChecks);
  });
  host.querySelectorAll('[data-f]:not([data-v])').forEach(function(inp){
    var k=inp.getAttribute('data-f');
    inp.addEventListener('input', function(){
      editing.vals[k] = inp.type==='checkbox' ? inp.checked : inp.value;
      if (saveDraft) saveDraft();
    });
    inp.addEventListener('change', function(){
      editing.vals[k] = inp.type==='checkbox' ? inp.checked : inp.value;
      if (saveDraft) saveDraft();
    });
  });
  /* 购入日期：年 / 月 / 日 三段共用一个 hidden input（data-f），
     左边选年右边就预存这个年，月日不填则只存 "2026"；右边选了月/日，年份自动补上 */
  host.querySelectorAll('[data-fy]').forEach(function(yinp){
    var k=yinp.getAttribute('data-fy');
    var minp=host.querySelector('[data-fm="'+k+'"]');
    var dinp=host.querySelector('[data-fd="'+k+'"]');
    var real=host.querySelector('[data-f="'+k+'"]');
    if (!minp || !dinp || !real) return;
    function yv(){ var t=String(yinp.value||'').trim(); return /^\d{4}$/.test(t) ? t : ''; }
    function mv(){ var n=parseInt(String(minp.value||''),10); return (n>=1&&n<=12)?n:0; }
    function dvv(){ var n=parseInt(String(dinp.value||''),10); return (n>=1&&n<=31)?n:0; }
    function p2(n){ return n<10 ? '0'+n : String(n); }
    /* 按年月重画「日」的下拉，平年闰年、大小月都对 */
    function fillDays(){
      var mm=mv(), yy=parseInt(yv(),10)||2000;
      var leap=(yy%4===0 && yy%100!==0) || yy%400===0;
      var max = mm===2 ? (leap?29:28) : ([31,28,31,30,31,30,31,31,30,31,30,31][mm-1] || 31);
      var cur=parseInt(String(dinp.value||''),10)||0;
      var o='<option value="">（日）</option>';
      for (var i=1;i<=max;i++) o += '<option value="'+i+'"'+(i===cur?' selected':'')+'>'+i+' 日</option>';
      dinp.innerHTML=o;
      if (cur>max) dinp.value='';
    }
    function commit(){
      var val='';
      if (yv()){
        if (mv()){ val = yv()+'-'+p2(mv())+(dvv()?'-'+p2(dvv()):''); }
        else val = yv();
      }
      real.value=val;
      editing.vals[k]=val;
      if (saveDraft) saveDraft();
    }
    fillDays();
    yinp.addEventListener('change', function(){ fillDays(); commit(); });
    minp.addEventListener('change', function(){
      if (mv() && !yv()) yinp.value=String(new Date().getFullYear());   /* 右边选了，左边自动补年 */
      fillDays(); commit();
    });
    dinp.addEventListener('change', function(){
      if ((dvv()||mv()) && !yv()) yinp.value=String(new Date().getFullYear());
      fillDays(); commit();
    });
  });
  /* v75fix：存放位置三段式（房间 / 柜墙 / 层）——三段下拉合成一个「 · 」分隔的值，
     写进 hidden[data-f]，与「购入日期」的年/月/日同一套路 */
  host.querySelectorAll('[data-lr]').forEach(function(rsel){
    var k=rsel.getAttribute('data-lr');
    var csel=host.querySelector('[data-lc="'+k+'"]');
    var lsel=host.querySelector('[data-ll="'+k+'"]');
    var real=host.querySelector('[data-f="'+k+'"]');
    if (!csel || !lsel || !real) return;
    function commit3(){
      var val=[rsel.value, csel.value, lsel.value]
        .map(function(x){ return String(x||'').trim(); })
        .filter(Boolean).join(' · ');
      real.value=val;
      if (editing) editing.vals[k]=val;
      if (saveDraft) saveDraft();
    }
    rsel.addEventListener('change', commit3);
    csel.addEventListener('change', commit3);
    lsel.addEventListener('change', commit3);
  });
  /* v75fix：存储地点三段（房间 / 柜体墙面 / 所在层）——
     选「＋ 新建…」就弹窗新增选项，成功后立刻选中并写入 editing.vals */
  host.querySelectorAll('select[data-locopt]').forEach(function(sel){
    if (sel._locBound) return; sel._locBound = true;
    var dim = sel.getAttribute('data-locopt') || '';
    var fk  = sel.getAttribute('data-f') || '';
    var prev = sel.value || '';
    var ph = dim==='房间' ? '书房 / 客厅 / 卧室'
           : (dim==='柜体墙面' ? '玻璃柜 / 书架 / 电视柜' : '第 2 层 / 上层 / 底层');
    sel.addEventListener('change', function(){
      if (sel.value!=='__new__'){ prev = sel.value || ''; return; }
      sel.value = prev;                       /* 先还原，避免停在「＋ 新建…」上 */
      promptDialog('新增'+dim, dim+'名称（如：'+ph+'）', '', '创建', function(name){
        if (!name) return '名称不能为空';
        if ((LOC_OPTS[dim]||[]).indexOf(name)>=0) return '已存在该'+dim;
        addLocOpt(dim, name);
        var opts = LOC_OPTS[dim] || [];
        sel.innerHTML = '<option value="">（不选）</option>' +
          opts.map(function(o){
            return '<option value="'+esc(o)+'"'+(o===name?' selected':'')+'>'+esc(o)+'</option>'; }).join('') +
          '<option value="__new__">＋ 新建…</option>';
        sel.value = name; prev = name;
        if (editing) editing.vals[fk] = name;
        toast('已新增'+dim+'「'+name+'」');
        if (saveDraft) saveDraft();
        return null;
      });
    });
  });
  host.querySelectorAll('.dynwrap').forEach(function(w){
    var k=w.getAttribute('data-k');
    var sel=w.querySelector('[data-dyn-sel]'), cus=w.querySelector('[data-dyn-cus]');
    sel.onchange=function(){
      if (sel.value==='__custom__'){ cus.style.display='block'; cus.focus(); editing.vals[k]=cus.value||''; }
      else {
        cus.style.display='none'; cus.value=''; editing.vals[k]=sel.value;
        /* 选了系列就把它的 IP 带上，省得再选一次 */
        if (w.getAttribute('data-src')==='series' && sel.value){
          var se=store.series.rows.filter(function(r){ return r['系列名称']===sel.value; })[0];
          if (se && se['所属IP'] && !editing.vals['IP']) fillDynField(host,'IP');
          if (se && se['所属IP'] && editing.vals['IP']!==se['所属IP']){
            editing.vals['IP']=se['所属IP'];
            var ipw=host.querySelector('.dynwrap[data-k="IP"]');
            if (ipw){ var ipsel=ipw.querySelector('[data-dyn-sel]'); if (ipsel) ipsel.value=se['所属IP']; }
          }
        }
        if (saveDraft) saveDraft();
      }
      /* v75：IP/系列/小类 切换后重算范围字段 */
      rebuildFormGrid(host);
    };
    cus.addEventListener('input', function(){ editing.vals[k]=cus.value; if (saveDraft) saveDraft(); });
    fillDynField(host, k);
  });
  host.querySelectorAll('.imgwrap input[data-f]').forEach(function(inp){
    inp.addEventListener('input', function(){
      var k=inp.getAttribute('data-f');
      var prev=host.querySelector('[data-img-prev="'+k+'"]');
      if (prev) setImgPreview(prev, inp.value, k);
    });
  });
  host.querySelectorAll('[data-img-file]').forEach(function(inp){
    inp.onchange=function(){
      var file=inp.files && inp.files[0]; if (!file) return;
      var k=inp.getAttribute('data-img-file');
      var note=host.querySelector('[data-img-note="'+k+'"]');
      if (note) note.textContent='正在压缩…';
      compressImage(file, 800, function(dataUrl){
        if (!dataUrl){ if (note) note.textContent='这张图读不出来，换个文件试试'; return; }
        editing.vals[k]=dataUrl;
        editing.vals[k+'_vp']={s:1,x:0,y:0};
        var urlInput=host.querySelector('[data-f="'+k+'"]'); if (urlInput) urlInput.value=dataUrl;
        var prev=host.querySelector('[data-img-prev="'+k+'"]');
        if (prev) setImgPreview(prev, dataUrl, k);
        if (note) note.textContent='已压到约 '+Math.round(dataUrl.length/1024)+' KB';
        if (saveDraft) saveDraft();
      });
    };
  });
  var catSel=host.querySelector('[data-f="大类"]');
  if (catSel){
    refillStateOptions(host);
    catSel.addEventListener('change', function(){
      editing.vals['小类']='';
      fillDynField(host,'小类');
      refillStateOptions(host);
      /* v75：大类切换后重算范围字段（按小类/IP/系列/系列归属IP 匹配） */
      rebuildFormGrid(host);
      /* v59：大类切换后同步更新表单标题与眉标 */
      var headH2 = host.querySelector('.sheet-head h2');
      var headP = host.querySelector('.sheet-head p');
      if (headH2){
        var prefix = editing.id ? '编辑 · ' : '添加 · ';
        headH2.textContent = prefix + catSel.value;
      }
      if (headP && editing && editing.key==='collection'){
        if (catSel.value === '书籍') headP.textContent = 'Learning';
        else if (catSel.value === '杂志') headP.textContent = 'Periodical';
        else headP.textContent = MODS.collection.eyebrow;
      }
      if (saveDraft) saveDraft();
    });
  }

  /* 图片视口：拖拽移动、滚轮缩放、按钮缩放/平移、方向键微调、双击重置、Ctrl+V 粘贴 */
  /* v75fix：封面右上角的「✕」——只拦 mousedown（否则会被图片拖拽逻辑接管）；
     click 务必让它继续冒泡到 document，全局 dispatch 才收得到 act=imgdel */
  host.querySelectorAll('.imgdel').forEach(function(b){
    b.addEventListener('mousedown', function(e){ e.stopPropagation(); });
  });
  host.querySelectorAll('.imgprev').forEach(function(prev){
    var k=prev.getAttribute('data-img-prev'); if (!k) return;
    function vp(){ return (editing && editing.vals && editing.vals[k+'_vp']) || {s:1,x:0,y:0}; }
    function setVp(o){
      if (!editing) return;
      editing.vals[k+'_vp']=o; applyImgViewport(prev, k);
      if (saveDraft) saveDraft();
    }
    var zbar = prev.parentNode.querySelector('.imgvp-bar');
    if (zbar){
      zbar.querySelectorAll('[data-img-zoom]').forEach(function(btn){
        btn.onclick=function(){
          var o=vp(); o.s=Math.max(1, Math.min(4, o.s+parseFloat(btn.getAttribute('data-d')))); setVp(o);
        };
      });
      zbar.querySelectorAll('[data-img-pan]').forEach(function(btn){
        btn.onclick=function(){
          var o=vp();
          var dx=parseFloat(btn.getAttribute('data-dx')||0);
          var dy=parseFloat(btn.getAttribute('data-dy')||0);
          if (dx) o.x = Math.max(-80, Math.min(80, o.x+dx));
          if (dy) o.y = Math.max(-80, Math.min(80, o.y+dy));
          setVp(o);
        };
      });
      zbar.querySelectorAll('[data-img-reset]').forEach(function(btn){
        btn.onclick=function(){ setVp({s:1,x:0,y:0}); };
      });
    }
    prev.ondblclick=function(){ setVp({s:1,x:0,y:0}); };
    prev.onwheel=function(e){
      if (!prev.style.backgroundImage) return;
      e.preventDefault();
      var o=vp(); o.s=Math.max(1, Math.min(4, o.s+(e.deltaY<0?0.1:-0.1))); setVp(o);
    };
    /* 键盘方向键微调（焦点在预览框时） */
    prev.addEventListener('keydown', function(e){
      if (!prev.style.backgroundImage) return;
      var step = 2;
      var o=vp(), moved=false;
      if (e.key==='ArrowLeft'){ o.x=Math.max(-80,Math.min(80,o.x-step)); moved=true; }
      else if (e.key==='ArrowRight'){ o.x=Math.max(-80,Math.min(80,o.x+step)); moved=true; }
      else if (e.key==='ArrowUp'){ o.y=Math.max(-80,Math.min(80,o.y-step)); moved=true; }
      else if (e.key==='ArrowDown'){ o.y=Math.max(-80,Math.min(80,o.y+step)); moved=true; }
      if (moved){ e.preventDefault(); setVp(o); }
    });
    var dragging=false, sx=0, sy=0, ix=0, iy=0;
    prev.onmousedown=function(e){
      if (!prev.style.backgroundImage) return;
      dragging=true; sx=e.clientX; sy=e.clientY; var o=vp(); ix=o.x; iy=o.y; prev.style.cursor='grabbing';
    };
    window.addEventListener('mousemove', function(e){
      if (!dragging) return;
      var dx=(e.clientX-sx), dy=(e.clientY-sy);
      var o=vp(); o.x=Math.max(-80,Math.min(80,ix+dx/3)); o.y=Math.max(-80,Math.min(80,iy+dy/3)); setVp(o);
    });
    window.addEventListener('mouseup', function(){ dragging=false; prev.style.cursor=''; });
    /* 触摸支持 */
    prev.ontouchstart=function(e){
      if (!prev.style.backgroundImage) return;
      dragging=true; sx=e.touches[0].clientX; sy=e.touches[0].clientY; var o=vp(); ix=o.x; iy=o.y;
    };
    window.addEventListener('touchmove', function(e){
      if (!dragging) return;
      var dx=(e.touches[0].clientX-sx), dy=(e.touches[0].clientY-sy);
      var o=vp(); o.x=Math.max(-80,Math.min(80,ix+dx/3)); o.y=Math.max(-80,Math.min(80,iy+dy/3)); setVp(o);
    });
    window.addEventListener('touchend', function(){ dragging=false; });
    /* 剪切板粘贴 */
    prev.addEventListener('paste', function(e){
      var items=e.clipboardData && e.clipboardData.items; if (!items) return;
      var file=null;
      for (var i=0;i<items.length;i++){ if (items[i].kind==='file' && items[i].type.indexOf('image/')===0){ file=items[i].getAsFile(); break; } }
      if (!file) return;
      e.preventDefault();
      var note=host.querySelector('[data-img-note="'+k+'"]'); if (note) note.textContent='正在压缩…';
      compressImage(file, 800, function(dataUrl){
        if (!dataUrl){ if (note) note.textContent='这张图读不出来，换个文件试试'; return; }
        editing.vals[k]=dataUrl; editing.vals[k+'_vp']={s:1,x:0,y:0};
        var urlInput=host.querySelector('[data-f="'+k+'"]'); if (urlInput) urlInput.value=dataUrl;
        setImgPreview(prev, dataUrl, k);
        if (note) note.textContent='已压到约 '+Math.round(dataUrl.length/1024)+' KB';
        if (saveDraft) saveDraft();
      });
    });
    /* URL 输入框也支持粘贴图片文件（焦点在输入框时 Ctrl+V） */
    var urlInp=host.querySelector('[data-f="'+k+'"]');
    if (urlInp){
      urlInp.addEventListener('paste', function(e){
        var items=e.clipboardData && e.clipboardData.items; if (!items) return;
        var file=null;
        for (var i=0;i<items.length;i++){ if (items[i].kind==='file' && items[i].type.indexOf('image/')===0){ file=items[i].getAsFile(); break; } }
        if (!file) return;
        e.preventDefault();
        var note=host.querySelector('[data-img-note="'+k+'"]'); if (note) note.textContent='正在压缩…';
        compressImage(file, 800, function(dataUrl){
          if (!dataUrl){ if (note) note.textContent='这张图读不出来，换个文件试试'; return; }
          editing.vals[k]=dataUrl; editing.vals[k+'_vp']={s:1,x:0,y:0};
          urlInp.value=dataUrl; setImgPreview(prev, dataUrl, k);
          if (note) note.textContent='已压到约 '+Math.round(dataUrl.length/1024)+' KB';
          if (saveDraft) saveDraft();
        });
      });
    }
  });
}

/* ---------- 系列 ---------- */
function pad3(n){ n=String(n); while(n.length<3) n='0'+n; return n; }

/* ============================================================
   v77：宝可梦 30 周年冰箱贴 —— 属性图标 / 三维筛选 / 号码索引
   ------------------------------------------------------------
   仅对 IP=宝可梦 + 系列=30周年冰箱贴 生效；其他类目零影响。
   属性图标直接引用 data/images/types/*.png（swsh 官方 18 张），
   不重做框、不重做配色；容器形状由「圆形 / 方形」开关控制。
   ============================================================ */
var PK_IP = '宝可梦', PK_SERIES = '30周年冰箱贴';
var PK_TYPE_EN = {一般:'normal',火:'fire',水:'water',电:'electric',草:'grass',冰:'ice',格斗:'fighting',毒:'poison',地面:'ground',飞行:'flying',超能力:'psychic',虫:'bug',岩石:'rock',幽灵:'ghost',龙:'dragon',恶:'dark',钢:'steel',妖精:'fairy'};
var PK_TYPES = ['一般','火','水','电','草','冰','格斗','毒','地面','飞行','超能力','虫','岩石','幽灵','龙','恶','钢','妖精'];
var PK_FORMS = ['常规图鉴','超级进化','地区形态','超极巨化','原始回归','无极巨化'];
var PK_GROUPS = ['传说宝可梦','幻之宝可梦','究极异兽','初始的伙伴'];
/* v77：地区形态的下级选项——只有「特殊形态 = 地区形态」时才显示这一行 */
var PK_REGIONS = ['阿罗拉','伽勒尔','洗翠','帕底亚'];
/* 世代：a/b 为全国图鉴 dex 区间；bg 底 / bd 描边 / fg 文字（马卡龙配色） */
var PK_GENS = [
  {n:'第一世代',a:1,b:151,bg:'#FCF3DC',bd:'#D4B95A',fg:'#5C4A1F'},
  {n:'第二世代',a:152,b:251,bg:'#FCEBEB',bd:'#E8A0A0',fg:'#8B3535'},
  {n:'第三世代',a:252,b:386,bg:'#E8F5E9',bd:'#A5D6A7',fg:'#2E7D32'},
  {n:'第四世代',a:387,b:493,bg:'#E3F2FD',bd:'#90CAF9',fg:'#1565C0'},
  {n:'第五世代',a:494,b:649,bg:'#F3E5F5',bd:'#CE93D8',fg:'#6A1B9A'},
  {n:'第六世代',a:650,b:721,bg:'#FFEBEE',bd:'#F48FB1',fg:'#AD1457'},
  {n:'第七世代',a:722,b:809,bg:'#FFF8E1',bd:'#FFE082',fg:'#8B6914'},
  {n:'第八世代',a:810,b:905,bg:'#E0F2F1',bd:'#80CBC4',fg:'#00695C'},
  {n:'第九世代',a:906,b:1025,bg:'#FCE4EC',bd:'#F48FB1',fg:'#880E4F'}
];
function pkGenOf(no){
  var n = parseInt(String(no||'').replace(/^[#＃]/,''),10);
  if (isNaN(n)) return PK_GENS[0];
  for (var i=0;i<PK_GENS.length;i++) if (n>=PK_GENS[i].a && n<=PK_GENS[i].b) return PK_GENS[i];
  return PK_GENS[PK_GENS.length-1];
}
function pkIsPkm(r){ return !!r && r['IP']===PK_IP && r['系列']===PK_SERIES; }
function pkIsPkmSeries(se){ return !!se && (se['系列名称']||'')===PK_SERIES && (se['所属IP']||'')===PK_IP; }
function pkTypeSrc(t, sh){
  var en = PK_TYPE_EN[t];
  if (!en) return '';
  var sub = (sh || pkShape()) === 'circle' ? 'swsh' : 'sv';
  return 'data/images/types/'+sub+'/'+en+'.png';
}
/* 圆形 / 方形：偏好存 localStorage，默认圆形（swsh 圆形图标） */
function pkShape(){
  try { return localStorage.getItem('pk_icon_shape')==='square' ? 'square' : 'circle'; } catch(e){ return 'circle'; }
}
function pkSetShape(v){ try { localStorage.setItem('pk_icon_shape', v==='circle'?'circle':'square'); } catch(e){} }
/* 展示卡内属性图标：主属性 + 副属性并排；副属性为空则只显示主属性
   「方形 / 圆形」开关决定图标来源（sv/ 或 swsh/） */
function pkTypeIconsHTML(r){
  if (!pkIsPkm(r)) return '';
  var t1 = r['属性'] || '', t2 = r['副属性'] || '';
  if (!t1 && !t2) return '';
  var sh = pkShape();
  var out = '<div class="pktypes pk-'+sh+'">';
  [t1,t2].forEach(function(t){
    if (!t) return;
    var src = resolveImgUrl(pkTypeSrc(t, sh));
    out += '<span class="pktype" title="'+esc(t)+'">'+
      (src ? '<img src="'+esc(src)+'" alt="'+esc(t)+'">' : '<b>'+esc(String(t).slice(0,1))+'</b>')+'</span>';
  });
  return out+'</div>';
}
/* v77：改一行的状态（在库 / 想收 / 云游…）并落盘，返回切换后是否选中。
   坑：不能把 store 里的 row 原样丢给 updateRow —— localUpsert 对 img 字段是按
   「字符串 URL + 封面_vp」处理的，传数组会被 String() 成 '[object Object]'，封面直接消失。
   所以这里先把封面摊平成 updateRow 认识的形状再写回。 */
function toggleRowStatus(key, id, status){
  var row = ((store[key] && store[key].rows) || []).filter(function(r){ return String(r._id)===String(id); })[0];
  if (!row || !status) return false;
  var arr = stArr(row);
  var ix = arr.indexOf(status);
  var on;
  if (ix >= 0){ arr.splice(ix,1); on = false; }
  else { arr.push(status); on = true; }
  if (MODE === 'db'){
    /* db 模式：走 updateRow，字段值先用 fieldVal 摊平成表单形状（img → 字符串 URL） */
    var vals = {};
    activeFields(key, row).forEach(function(f){ vals[f.k] = fieldVal(row, f); });
    vals['状态'] = arr;
    updateRow(key, id, vals);
  } else {
    /* 本地 / gh / localfile：直接改行内字段再落盘，不经过 localUpsert 的 img 转换 */
    patchRowFields(key, id, { 状态: arr });
  }
  return on;
}
/* 收服 / 想收 快速按钮的作用域是整个「宝可梦」IP（含旗下所有系列）；
   属性图标仍然只属于「30周年冰箱贴」系列（属性 / 副属性字段是挂在这个系列上的） */
function pkIsPkmIp(r){ return !!r && r['IP']===PK_IP; }
/* v77：展示卡左下角两个快速按钮——「收服 / 在库」「想收」，点一次写入、再点一次取消 */
function pkQuickBtnsHTML(r){
  if (!pkIsPkmIp(r)) return '';
  function btn(s){
    var on = hasStatus(r, s);
    var cls = s==='在库' ? 'pkq-lib' : 'pkq-wish';
    /* 在库：没点时是动作「收服」，点过之后是状态「在库」 */
    var label = (s==='在库' && !on) ? '收服' : s;
    return '<button type="button" class="pkq '+cls+(on?' on':'')+'"'+
      ' data-act="pkquick" data-s="'+esc(s)+'" data-id="'+esc(r._id)+'"'+
      ' title="'+(on ? '已「'+esc(s)+'」，再点一次取消' : (s==='在库' ? '收服了（标记为在库）' : '标记为「'+esc(s)+'」'))+'">'+esc(label)+'</button>';
  }
  return '<div class="pkquick">'+btn('在库')+btn('想收')+'</div>';
}
/* 18 个属性图标的两种版本走一遍 resolveImagesFor，保证 FSA / 静态模式都能显示 */
function pkIconProbeRows(){
  var rows = [];
  PK_TYPES.forEach(function(t){
    ['sv','swsh'].forEach(function(sub){
      var en = PK_TYPE_EN[t];
      rows.push({封面:[{imageUrl:'data/images/types/'+sub+'/'+en+'.png'}]});
    });
  });
  return rows;
}
function seriesItems(name){
  /* v58：书籍/杂志归文渊斋管，系列详情里不显示它们 */
  return store.collection.rows.filter(function(r){ return r['系列']===name && LEGACY_BOOK_CATS.indexOf(r['大类'])<0; });
}
function sortByNo(items){
  function key(r){
    var v=String(r['编号']||'').replace(/^[#＃]/,'').trim();
    var m=/^(\d+)([A-Za-z]*)/.exec(v);
    return { n: m? parseInt(m[1],10) : 99999, s: m? m[2] : '' };
  }
  return items.slice().sort(function(a,b){
    var ka=key(a), kb=key(b);
    if (ka.n!==kb.n) return ka.n-kb.n;
    if (ka.s!==kb.s) return ka.s<kb.s ? -1 : 1;   /* 同号永远按字母序 */
    return String(a['名称']||'').localeCompare(String(b['名称']||''),'zh');
  });
}
function missingNos(items, target){
  var have={};
  items.forEach(function(r){
    var n=parseInt(String(r['编号']||'').replace(/^[#＃]/,''),10);
    if(!isNaN(n)) have[n]=1;
  });
  var miss=[];
  for(var i=1;i<=target;i++) if(!have[i]) miss.push(i);   /* 存原始整数，显示时再按目标位数补零 */
  return miss;
}
function renderSeriesMode(){
  if (ui.collection.seriesId) return ui.collection.pkIndex ? renderPkIndex() : renderSeriesDetail();
  var s=store.series, c=store.collection;
  var h='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>系列</h2>'+
    '<div class="hint">成套的东西按套记，还差哪几个一眼看到</div></div>'+modeSeg()+'</div>';
  if (s.status==='loading'){ h += emptyHTML('正在读线上数据…',''); return h+'</section>'; }
  if (s.status==='error'){ h += emptyHTML('没能读到系列','点上面的「重试」再拉一次。'); return h+'</section>'; }
  h += '<div class="ipgrid">'+s.rows.map(function(se){
    var name=se['系列名称']||'未命名';
    var target=num(se['目标数量']);
    var items=seriesItems(name);
    var pct= target? Math.min(100, Math.round(items.length/target*100)) : 0;
    return '<div class="ipcard" data-act="seriesopen" data-id="'+esc(se._id)+'"'+
      ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
      '<div class="ph" style="'+coverStyle(se,name)+'">'+(hasCover(se)?'':'<b>'+esc(String(name).slice(0,1))+'</b>')+'</div>'+
      '<div class="bd"><strong>'+esc(name)+'</strong>'+
        '<span>'+esc(se['所属IP']||'未绑 IP')+'</span>'+
        (target
          ? '<div class="track2" style="margin-top:8px"><i style="width:'+pct+'%"></i></div>'+
            '<span>'+items.length+' / '+target+' · 还差 '+Math.max(0,target-items.length)+'</span>'
          : '<span>'+items.length+' 件</span>')+
      '</div></div>';
  }).join('')+
  '<div class="ipcard add" data-act="add" data-key="series">'+
    '<div class="ph">＋</div><div class="bd"><strong>新增系列</strong><span>先建套，再批量往里加</span></div></div>'+
  '</div>';
  var names={}; s.rows.forEach(function(r){ var n=r['系列名称']; if(n) names[n]=1; });
  /* v58：书籍/杂志归文渊斋，不进系列的未归入列表 */
  var loose=c.rows.filter(function(r){ return LEGACY_BOOK_CATS.indexOf(r['大类'])<0 && (!r['系列'] || !names[r['系列']]); });
  if (loose.length){
    h += '<div class="grp" style="margin-top:24px"><h4>未归入系列 <i>'+loose.length+' 件</i></h4>'+collectionWall(loose)+'</div>';
  }
  return h+'</section>';
}
/* 系列详情·云游视图专用墙：每张卡带「点击想要」标签；点过则显示「已想要」
   （云游状态仍在，想收叠加共存，不再显示「云游（心愿）」合并字样） */
function seriesCloudWall(rows){
  return '<div class="wall">'+rows.map(function(r){
    var t=r['名称']||'未命名';
    var sub=(r['小类']||'')+(r['IP']?' · '+r['IP']:'');
    var no=String(r['编号']||'');
    var isWished = hasStatus(r,'想收');
    var wishTag = isWished
      ? '<span class="wish-tag wished" data-act="serieswish" data-id="'+esc(r._id)+'" title="点此取消想要">已想要</span>'
      : '<span class="wish-tag" data-act="serieswish" data-id="'+esc(r._id)+'">点击想要</span>';
    return '<div class="poster" data-act="item" data-key="collection" data-id="'+esc(r._id)+'"'+
      ' data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
      '<div class="cover'+(hasCover(r)?'':' noimg')+'" style="'+coverStyle(r,t)+'">'+
      (hasCover(r)?'':'<b>'+esc(String(t).slice(0,1))+'</b>')+
      '<span class="tag">'+esc(r['大类']||'')+'</span>'+
      (no?'<span class="no">'+esc(no)+'</span>':'')+
      (num(r['星级'])?'<span class="score">'+stars(r['星级'])+'</span>':'')+
      pkQuickBtnsHTML(r)+
      pkTypeIconsHTML(r)+
      '</div>'+
      wishTag+
      '<h4>'+esc(t)+'</h4><p>'+esc(sub||'—')+'</p></div>';
  }).join('')+'</div>';
}
/* v77：系列详情右上工具条 —— 号码索引入口 + 属性图标形状开关 */
function pkToolsBar(){
  var sh = pkShape();
  return '<div class="pktools">'+
    '<button class="btn ghost sm" type="button" data-act="pkindex">号码索引</button>'+
    '<span class="pkseg pkseg-sm">'+
      '<button type="button" data-act="pkshape" data-v="circle" class="'+(sh==='circle'?'on':'')+'">圆形</button>'+
      '<button type="button" data-act="pkshape" data-v="square" class="'+(sh==='square'?'on':'')+'">方形</button>'+
    '</span>'+
    '<span class="pkhint">属性图标形状</span>'+
  '</div>';
}
var PK_FIELD_OF = { form:'特殊形态', group:'图鉴组', gen:'世代组', region:'地区' };
/* v77：属性图标栏 + 三个正交维度筛选栏（仅宝可梦冰箱贴系列） */
function pkFilterBar(rows){
  var p = ui.collection.pk || (ui.collection.pk = { type:'', both:false, form:'', region:'', group:'', gen:'' });
  var sh = pkShape();
  function cnt(f, v){ return (rows||[]).filter(function(r){ return String(r[PK_FIELD_OF[f]]||'')===v; }).length; }
  var h = '<div class="pkbar">';
  h += '<div class="pkrow"><u>属性</u><div class="pktypebar">'+
    '<button type="button" class="pktbtn pktxt'+(p.type?'':' on')+'" data-act="pktype" data-v="">全部</button>';
  PK_TYPES.forEach(function(t){
    var src = resolveImgUrl(pkTypeSrc(t, sh));
    h += '<button type="button" class="pktbtn'+(p.type===t?' on':'')+'" data-act="pktype" data-v="'+esc(t)+'" title="'+esc(t)+'">'+
      (src ? '<img src="'+esc(src)+'" alt="'+esc(t)+'">' : '<b>'+esc(String(t).slice(0,1))+'</b>')+'</button>';
  });
  h += '<span class="pkseg pkseg-sm">'+
    '<button type="button" data-act="pkboth" data-v="first" class="'+(p.both?'':' on')+'">第一属性</button>'+
    '<button type="button" data-act="pkboth" data-v="both" class="'+(p.both?' on':'')+'">两者皆可</button></span>';
  h += '</div></div>';
  /* v77：每个按钮都是「再点一次取消」的开关——点当前选中项会把值清回空（=全部） */
  function chipRow(label, f, list, extraCls){
    var s = '<div class="pkrow'+(extraCls?' '+extraCls:'')+'"><u>'+label+'</u><div class="pkchips">'+
      '<button type="button" class="pkchip'+(p[f]?'':' on')+'" data-act="pkfilt" data-f="'+f+'" data-v="">全部</button>';
    list.forEach(function(v){
      s += '<button type="button" class="pkchip'+(p[f]===v?' on':'')+'" data-act="pkfilt" data-f="'+f+'" data-v="'+esc(v)+'"'+
        ' title="'+(p[f]===v?'再点一次取消筛选':'')+'">'+esc(v)+'<i>'+cnt(f,v)+'</i></button>';
    });
    return s+'</div></div>';
  }
  h += chipRow('特殊形态','form',PK_FORMS);
  /* v77：选中「地区形态」后，下面多出一行地区选项（阿罗拉 / 伽勒尔 / 洗翠 / 帕底亚） */
  if (p.form === '地区形态') h += chipRow('地区','region',PK_REGIONS,'pkrow-sub');
  h += chipRow('图鉴组','group',PK_GROUPS);
  h += chipRow('世代组','gen',PK_GENS.map(function(g){ return g.n; }).concat(['第十世代']));
  return h+'</div>';
}
/* v77：三维 + 属性 联合过滤 */
function pkApplyFilters(items){
  var p = ui.collection.pk || {};
  return items.filter(function(r){
    if (p.type){
      var t1 = r['属性']||'', t2 = r['副属性']||'';
      if (!(t1===p.type || (p.both && t2===p.type))) return false;
    }
    if (p.form  && String(r['特殊形态']||'')!==p.form) return false;
    if (p.region&& String(r['地区']||'')!==p.region) return false;
    if (p.group && String(r['图鉴组']||'')!==p.group) return false;
    if (p.gen   && String(r['世代组']||'')!==p.gen) return false;
    return true;
  });
}
/* v77：号码索引页的数据 —— base 在前、形态按 formCode 升序（origin 类排最后） */
/* v77：形态排序键 —— 无副编号（基础形态）排最前，其余按 formCode 数字升序，字母型（origin 等）排最后 */
function pkFormKey(r){
  var c = String(r.formCode||'');
  if (!c) return -1;
  return /^\d+$/.test(c) ? parseInt(c,10) : 900;
}
/* v77：宝可梦排序 —— 先按图鉴号；同号时基础形态（无副编号）在前，其余按副编号升序 */
function pkSortItems(items){
  return items.slice().sort(function(a,b){
    var na = parseInt(String(a['编号']||''),10)||0, nb = parseInt(String(b['编号']||''),10)||0;
    if (na!==nb) return na-nb;
    var fa = pkFormKey(a), fb = pkFormKey(b);
    if (fa!==fb) return fa-fb;
    return String(a['名称']||'').localeCompare(String(b['名称']||''),'zh');
  });
}
function pkSortedItems(){
  return pkSortItems(seriesItems(PK_SERIES).filter(pkIsPkm));
}
/* v77：一张号码卡：4 位编号 + 形态幂次上标，底色按世代 */
function pkCardHTML(r, g){
  var no = String(r['编号']||'');
  var fc = String(r.formCode||'');
  var owned = hasStatus(r,'在库'), wish = hasStatus(r,'想收');
  return '<button type="button" class="pkno'+(owned?' owned':'')+(wish?' wish':'')+'"'+
    ' data-act="item" data-key="collection" data-id="'+esc(r._id)+'"'+
    ' style="background:'+g.bg+';border-color:'+g.bd+';color:'+g.fg+'"'+
    ' title="'+esc((r['名称']||'')+(owned?' · 已收':''))+'">'+esc(no)+(fc?'<sup>'+esc(fc)+'</sup>':'')+'</button>';
}
function renderPkIndex(){
  var se = store.series.rows.filter(function(r){
    return (r['系列名称']||'')===PK_SERIES && (r['所属IP']||'')===PK_IP;
  })[0];
  var target = se ? num(se['目标数量']) : 0;
  var items = pkSortedItems();
  var base = items.filter(function(r){ return !String(r.formCode||''); });
  var ownedBase = base.filter(function(r){ return hasStatus(r,'在库'); }).length;
  var miss = target ? Math.max(0, target-ownedBase) : 0;
  var pct = target ? Math.min(100, Math.round(ownedBase/target*100)) : 0;
  var open = ui.collection.pkGenOpen || (ui.collection.pkGenOpen = {});
  var sh = pkShape();
  var h = '<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>号码索引</h2>'+
    '<div class="hint">'+items.length+' 张卡牌（基础 '+base.length+' + 形态 '+(items.length-base.length)+'）· 点编号打开展示卡</div></div>'+
    '<span class="pkseg pkseg-sm">'+
      '<button type="button" data-act="pkshape" data-v="circle" class="'+(sh==='circle'?'on':'')+'">圆形</button>'+
      '<button type="button" data-act="pkshape" data-v="square" class="'+(sh==='square'?'on':'')+'">方形</button>'+
    '</span></div>'+
    '<div style="margin-bottom:14px"><button class="btn link" type="button" data-act="pkindexback">← 返回系列</button></div>';
  h += '<div class="buybox pkidx-head"><h4>收集进度</h4>'+
    '<div class="track2" style="margin-bottom:11px"><i style="width:'+pct+'%"></i></div>'+
    '<div class="pkidx-stats">'+
      '<span>已收 <b style="color:var(--ink)">'+ownedBase+'</b> / '+target+'</span>'+
      '<span>还差 <b style="color:var(--ink)">'+miss+'</b></span>'+
      '<span>完成度 <b style="color:var(--ink)">'+pct+'%</b></span>'+
    '</div>'+
    '<div class="pkidx-acts">'+
      '<button class="btn ghost xs" type="button" data-act="pkgenall" data-v="1">全部展开</button>'+
      '<button class="btn ghost xs" type="button" data-act="pkgenall" data-v="0">全部折叠</button>'+
    '</div></div>';
  var gensHTML = '', expHTML = '';
  PK_GENS.forEach(function(g){
    var rows = items.filter(function(r){ return pkGenOf(r['编号']).n === g.n; });
    if (!rows.length) return;
    var isOpen = !!open[g.n];
    gensHTML += '<div class="pkgen'+(isOpen?' open':'')+'">'+
      '<button type="button" class="pkgenbtn" data-act="pkgen" data-v="'+esc(g.n)+'"'+
        ' style="background:'+g.bg+';border-color:'+g.bd+';color:'+g.fg+'">'+esc(g.n)+'<i>'+rows.length+'</i></button>';
    if (!isOpen){
      var first = rows[0], last = rows[rows.length-1];
      gensHTML += '<div class="pkgen-peek">'+pkCardHTML(first,g)+
        '<button type="button" class="pkno ellipsis" data-act="pkgen" data-v="'+esc(g.n)+'"'+
          ' style="border-color:'+g.bd+';color:'+g.fg+'" title="展开 '+esc(g.n)+'">…</button>'+
        pkCardHTML(last,g)+'</div>';
    }
    gensHTML += '</div>';
    if (isOpen){
      expHTML += '<div class="grp pkgenblock"><h4>'+esc(g.n)+' <i>'+rows.length+' 张</i></h4>'+
        '<div class="pkcards">'+rows.map(function(r){ return pkCardHTML(r,g); }).join('')+'</div></div>';
    }
  });
  h += '<div class="pkidx-gens">'+gensHTML+'</div>' + expHTML;
  if (!items.length) h += emptyHTML('这个系列还没有子项','先回到系列页录入几件再看索引。');
  return h+'</section>';
}
function renderSeriesDetail(){
  var se=store.series.rows.filter(function(r){ return String(r._id)===String(ui.collection.seriesId); })[0];
  if (!se){ ui.collection.seriesId=null; return renderSeriesMode(); }
  var name=se['系列名称']||'未命名';
  var target=num(se['目标数量']);
  /* v77：宝可梦冰箱贴按「图鉴号 + 基础形态优先」排序，保证无副编号的那张排在其他形态前面
     （通用 sortByNo 在同号时按名称排，会把基础形态插到形态中间） */
  var isPk = pkIsPkmSeries(se);
  var itemsAll = isPk ? pkSortItems(seriesItems(name)) : sortByNo(seriesItems(name));
  var inLib=itemsAll.filter(function(r){ return hasStatus(r,'在库'); });
  var miss= target ? missingNos(itemsAll, target) : [];
  var pct= target ? Math.min(100, Math.round(itemsAll.length/target*100)) : 0;
  /* v77：宝可梦冰箱贴 —— 完成度只数 base 槽位（formCode 为空），形态卡不计入目标 */
  var pkBase = isPk ? itemsAll.filter(function(r){ return !String(r.formCode||''); }) : itemsAll;
  var cntAll = isPk ? pkBase.length : itemsAll.length;
  if (isPk){
    miss = target ? missingNos(pkBase, target) : [];
    pct  = target ? Math.min(100, Math.round(pkBase.length/target*100)) : 0;
  }
  var h='<section class="panel" data-sp-bindable="database" data-sp-database-id="6xC81f403Az4cQm0QIX2TK">'+
    '<div class="panel-head"><div><h2>'+esc(name)+'</h2>'+
    '<div class="hint">'+(target? '目标 '+target+' 件 · 已有 '+cntAll+' 件' : '已有 '+cntAll+' 件')+'</div></div>'+modeSeg()+'</div>'+
    '<div style="margin-bottom:14px"><button class="btn link" type="button" data-act="seriesback">← 返回系列列表</button></div>'+
    '<div class="iphero">'+
      '<div class="ph" style="'+coverStyle(se,name)+'">'+(hasCover(se)?'':'<b>'+esc(String(name).slice(0,1))+'</b>')+'</div>'+
      '<div><h3>'+esc(name)+'</h3>'+
      (se['所属IP']?'<p>IP · '+esc(se['所属IP'])+'</p>':'')+
      (se['说明']?'<p>'+esc(se['说明'])+'</p>':'')+
      '<div class="acts">'+

        '<button class="btn ghost sm" type="button" data-act="edit" data-key="series" data-id="'+esc(se._id)+'">编辑系列</button>'+
        '<button class="btn ghost sm" type="button" data-act="delseries" data-id="'+esc(se._id)+'" style="color:var(--red)">删除系列</button>'+
      '</div></div></div>';
  /* v77：宝可梦冰箱贴 —— 右上角「号码索引」入口 + 圆形/方形属性图标开关 */
  if (isPk) h += pkToolsBar();
  if (target){
    h += '<div class="buybox" style="margin-bottom:20px"><h4>收集进度</h4>'+
      '<div class="track2" style="margin-bottom:11px"><i style="width:'+pct+'%"></i></div>'+
      '<div style="display:flex;gap:20px;flex-wrap:wrap;font-size:12.5px;color:var(--muted)">'+
        '<span>已有 <b style="color:var(--ink)">'+cntAll+'</b> / '+target+'</span>'+
        '<span>还差 <b style="color:var(--ink)">'+miss.length+'</b> 个</span>'+
        '<span>完成度 <b style="color:var(--ink)">'+pct+'%</b></span>'+
      '</div>';
    if (miss.length){
      /* v59：缺失编号默认只显示前 8 个，其余收进「…还有 N 个」（点击展开）；
         展开后显示「收起」回到折叠态；编号按目标数量位数补零（不再多补一位 0）。
         每个编号都可点击 → 直接进录入页并自动填 大类/小类/IP/系列/编号 */
      if (ui._missOpenFor!==String(se._id)){ ui._missOpenFor=String(se._id); ui._missOpen=false; }
      var padW = target ? String(target).length : 3;     /* 151→3 位，1200→4 位 */
      function padN(n){ n=String(n); while(n.length<padW) n='0'+n; return n; }
      var missChips='';
      if (!ui._missOpen){
        missChips = miss.slice(0,8).map(function(n){
          var s=padN(n);
          return '<button type="button" class="misschip" data-act="fillmiss" data-v="'+s+'">'+s+'</button>';
        }).join('');
        if (miss.length>8){
          missChips += '<button type="button" class="missmore" data-act="missmore">…还有 '+(miss.length-8)+' 个</button>';
        }
      } else {
        missChips = miss.map(function(n){
          var s=padN(n);
          return '<button type="button" class="misschip" data-act="fillmiss" data-v="'+s+'">'+s+'</button>';
        }).join('') + '<button type="button" class="missmore" data-act="missless">收起 ▲</button>';
      }
      h += '<div style="margin-top:13px">'+
        '<u style="display:block;color:var(--muted);font-size:10.5px;letter-spacing:.12em;text-decoration:none;margin-bottom:8px">还缺这些编号（点编号直接录入，自动带出大类 / 小类 / IP / 系列）</u>'+
        '<div style="display:flex;gap:5px;flex-wrap:wrap">'+missChips+'</div></div>';
    }
    h += '</div>';
  }
  if (!itemsAll.length){
    h += emptyHTML('这个系列还没有子项','点「批量添加子项」，把一整串名字一次贴进去就行。');
    return h+'</section>';
  }
  /* 全部 / 在库 / 云游 / 想收 四段切换：默认「全部」，单击切换；子项按 状态 过滤
     云游 = 状态含「云游」（未入手）；想收 = 状态含「想收」（可与其他状态共存） */
  var wandering=itemsAll.filter(function(r){ return hasStatus(r,'云游'); });
  var wishedAll=itemsAll.filter(function(r){ return hasStatus(r,'想收'); });
  var sf = ui.collection.seriesStatus;
  function segBtn(v, n){
    return '<button type="button" data-act="seriesfilt" data-v="'+v+'" class="'+(sf===v?'on':'')+'">'+
      v+'<i class="fb">'+n+'</i></button>';
  }
  h += '<div class="segline" style="margin:0 0 14px"><div class="seg seriesfilt">'+
    segBtn('全部', itemsAll.length)+segBtn('在库', inLib.length)+
    segBtn('云游', wandering.length)+segBtn('想收', wishedAll.length)+'</div></div>';
  var items = sf==='在库' ? inLib : sf==='云游' ? wandering : sf==='想收' ? wishedAll : itemsAll;
  if (isPk){
    h += pkFilterBar(itemsAll);
    items = pkApplyFilters(items);
  }
  /* 云游/想收视图：默认按序号；「按想收排列」时，含想收的子项排到最前（序号兜底） */
  if ((sf==='云游'||sf==='想收') && ui.collection.seriesSort==='wish'){
    items = items.slice().sort(function(a,b){
      var wa=hasStatus(a,'想收')?0:1, wb=hasStatus(b,'想收')?0:1;
      if (wa!==wb) return wa-wb;
      return num(a['编号'])-num(b['编号']);
    });
  }
  var showHdr = sf==='全部' ? '全部子项' : sf==='在库' ? '在库子项' : sf==='云游' ? '云游子项' : '想收子项';
  if (!items.length){
    h += emptyHTML('「'+sf+'」下没有子项',
      sf==='在库' ? '把这些子项的状态改成「在库」就会显示在这里。'
                  : sf==='想收' ? '点云游视图里的「点击想要」就能把物品标记为想收。'
                  : '把状态标记为「云游」就会显示在这里。');
    return h+'</section>';
  }
  /* 云游/想收视图：加「按想收排列」切换 + 每张卡「点击想要」标签；其余视图普通墙 */
  if (sf==='云游' || sf==='想收'){
    h += '<div class="segline" style="margin:-2px 0 14px"><div class="seg seriessort">'+
      '<button type="button" data-act="seriessort" data-v="no" class="'+(ui.collection.seriesSort!=='wish'?'on':'')+'">按序号</button>'+
      '<button type="button" data-act="seriessort" data-v="wish" class="'+(ui.collection.seriesSort==='wish'?'on':'')+'">按想收排列</button></div></div>'+
      '<div class="grp"><h4>'+showHdr+' <i>'+items.length+'</i></h4>'+seriesCloudWall(items)+'</div>';
  } else {
    h += '<div class="grp"><h4>'+showHdr+' <i>'+items.length+'</i></h4>'+collectionWall(items)+'</div>';
  }
  return h+'</section>';
}

/* ---------- 批量写入 ---------- */
function batchWrite(key, list, onProgress, onDone){
  if (MODE !== 'db'){
    var total=list.length, ok=0;
    list.forEach(function(vals){
      var id='l_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
      localUpsert(key, id, vals);
      ok++;
      if (onProgress) onProgress(ok, total, ok, 0);
    });
    if (onDone) onDone(ok, []);
    render();
    toast('已批量保存到本地（'+ok+' 条）');
    return;
  }
  var i=0, ok=0, fails=[], total=list.length, CONC=4;
  function step(){
    if (i>=total){
      fails.forEach(function(v){
        queue.push({
          label:'批量新增「'+(v['名称']||'')+'」',
          key:key,
          run:function(){ return T[key].add(propsFrom(MODS[key].fields, v, key)); }
        });
      });
      renderSyncBar();
      if (key) refreshKey(key);
      if (onDone) onDone(ok, fails);
      return;
    }
    var slice=list.slice(i, i+CONC); i+=CONC;
    var pending=slice.length;
    slice.forEach(function(vals){
      T[key].add(propsFrom(MODS[key].fields, vals, key)).then(function(res){
        var id = res && (res.id || res.record_id || res._id);
        if (id) localUpsert(key, id, vals);
        ok++;
      }).catch(function(){ fails.push(vals); }).then(function(){
        pending--;
        if (onProgress) onProgress(ok+fails.length, total, ok, fails.length);
        if (pending===0) step();
      });
    });
  }
  step();
}
function progressBox(id){
  return '<div class="buybox" style="margin-top:14px"><h4>正在写入</h4>'+
    '<div class="track2"><i id="'+id+'Bar" style="width:0%"></i></div>'+
    '<div id="'+id+'Txt" style="margin-top:10px;font-size:12.5px;color:var(--muted)">准备中…</div></div>';
}
function tickProgress(id, done, total, ok, fail){
  var b=$(id+'Bar'), t=$(id+'Txt');
  if (b) b.style.width = Math.round(done/total*100)+'%';
  if (t) t.textContent = '已处理 '+done+' / '+total+' · 成功 '+ok+(fail?(' ，失败 '+fail):'');
}

/* ---------- 批量添加子项 ---------- */
var BATCH_COMMON = null;
function commonFields(){
  if (!BATCH_COMMON){
    BATCH_COMMON = MODS.collection.fields.filter(function(f){
      return ['大类','小类','IP','系列','状态','星级','存储地点','购入日期','购入价格','购入渠道'].indexOf(f.k)>=0;
    });
  }
  return BATCH_COMMON;
}
function batchDefaults(seriesName){
  var m=MODS.collection;
  editing={key:'collection', id:null, vals:{}};
  m.fields.forEach(function(f){ editing.vals[f.k]=fieldVal(null,f); });
  var se=store.series.rows.filter(function(r){ return r['系列名称']===seriesName; })[0];
  editing.vals['系列']=seriesName||'';
  editing.vals['状态']=['在库'];
  if (se && se['所属IP']) editing.vals['IP']=se['所属IP'];
  return se;
}/* ---------- 平台识别与链接判定 ---------- */
function platformOf(url){
  var u=String(url||'').toLowerCase();
  if (!u) return '其他';
  if (/tmall\.com/.test(u)) return '天猫';
  if (/taobao\.com/.test(u)) return /goofish|idle|2\.taobao/.test(u) ? '闲鱼' : '淘宝';
  if (/\bjd\.com|\bjd\.hk|jd\.hk/.test(u)) return '京东';
  if (/xiaohongshu\.com|xhslink\.com/.test(u)) return '小红书';
  if (/pinduoduo\.com|yangkeduo\.com/.test(u)) return '拼多多';
  if (/douyin\.com|iesdouyin/.test(u)) return '抖音';
  if (/1688\.com/.test(u)) return '其他';
  if (/amazon\./.test(u)) return '其他';
  return '其他';
}
/* 这些平台的页面助手也抓不动，要如实告诉用户 */
function platformReachable(p){
  return p==='京东';
}
var URL_LINE = /^https?:\/\/[^\s]+$/i;
function isUrlLine(line){ return URL_LINE.test(String(line||'').trim()); }

/* ---------- 从订单文本粘贴导入 ---------- */
function extractDate(s){
  var m=s.match(/(20\d{2})\s*[-/年.]\s*(\d{1,2})\s*[-/月.]\s*(\d{1,2})/);
  if (m) return {raw:m[0], val:m[1]+'-'+pad(+m[2])+'-'+pad(+m[3])};
  var m2=s.match(/(?:^|\D)(\d{1,2})\s*[-/]\s*(\d{1,2})(?:\D|$)/);
  if (m2) return {raw:m2[0], val:String(new Date().getFullYear())+'-'+pad(+m2[1])+'-'+pad(+m2[2])};
  return null;
}
function extractPrice(s){
  var m=s.match(/(?:¥|￥|\$)\s*(\d+(?:\.\d{1,2})?)/);
  if (m) return {raw:m[0], val:parseFloat(m[1])};
  var m3=s.match(/(\d+(?:\.\d{1,2})?)\s*元/);
  if (m3) return {raw:m3[0], val:parseFloat(m3[1])};
  var m2=s.match(/(\d+\.\d{2})(?!\d)/);
  if (m2) return {raw:m2[0], val:parseFloat(m2[1])};
  return null;
}
/* 返回 {items:[{name,price,date}], links:[{url,platform}]} */
function parseImportText(text){
  var items=[], links=[];
  text.split(/\r?\n/).forEach(function(raw){
    var line=String(raw||'').trim();
    if (!line) return;
    /* 纯链接行：不瞎猜，直接进候选箱 */
    if (isUrlLine(line)){ links.push({url:line, platform:platformOf(line)}); return; }
    var name='', price=null, date='', code='', image='';
    /* TSV：3 列 = 名称⇥价格⇥日期（订单/粘贴），5 列 = 名称⇥价格⇥日期⇥编号⇥图片（书签从商品详情页抓出的 SKU） */
    if (line.indexOf('\t')>=0){
      var p=line.split('\t');
      if (p.length >= 5){ name=p[0].trim(); price=parseFloat(p[1])||null; date=(p[2]||'').trim(); code=(p[3]||'').trim(); image=(p[4]||'').trim(); }
      else { name=p[0].trim(); price=parseFloat(p[1])||null; date=(p[2]||'').trim(); }
    } else if (line.indexOf(',')>=0 && /,\s*(?:¥|￥|\$)?\d/.test(line)){
      var q=line.split(',');
      name=q[0].trim(); price=parseFloat(String(q[1]).replace(/[^\d.]/g,''))||null; date=(q[2]||'').trim();
    } else {
      var d=extractDate(line);
      if (d){ date=d.val; line=line.replace(d.raw,' '); }
      var pz=extractPrice(line);
      if (pz){ price=pz.val; line=line.replace(pz.raw,' '); }
      name=line;
    }
    name = String(name)
      .replace(/[×xX*]\s*\d+\s*$/,'')
      .replace(/^\s*\d+\s*[\.、)]\s*/,'')
      .replace(/\s{2,}/g,' ')
      .trim();
    if (!name) return;
    items.push({name:name, price:price, date:date, code:code, image:image});
  });
  return {items:items, links:links};
}
function openForm(key, id, opts){
  var m=MODS[key];
  var row=null;
  if (id){ var arr=store[key].rows.filter(function(r){ return String(r._id)===String(id); }); row=arr[0]||null; }
  editing={key:key,id:id,vals:{}};
  /* v56：prefill（如 大类=电影/留声机/书籍/杂志）会决定最终字段集，先把它种进 seed，
     这样 activeFields 一开始就拿对字段，避免旧字段残留导致两个入口进同一套表单 */
  var seed = row || {};
  if (opts && opts.prefill){
    seed = Object.assign({}, row || {}, opts.prefill);
  }
  activeFields(key, seed).forEach(function(f){ editing.vals[f.k]=fieldVal(row,f); });
  /* v58：大类不在电影/留声机/书籍/杂志专用表单里渲染，但分片与筛选全靠它，必须带回 vals */
  if ((key==='av' || key==='collection') && seed['大类']!=null && editing.vals['大类']==null){
    editing.vals['大类']=seed['大类'];
  }

  /* 外部预填（比如在某个 IP 下添加时，把 IP 先带上） */
  if (opts && opts.prefill){
    Object.keys(opts.prefill).forEach(function(k){ editing.vals[k]=opts.prefill[k]; });
  }
  /* 注：老藏品「存储地点」是合成串，loc3 字段在 fieldHTML 里会自行按「 · 」拆开回填 */
  formAfter = (opts && opts.after) || null;

  /* 如果上次没写完就关了，把那条草稿恢复回来。
     v59：collection/av 的草稿按 大类 隔离，避免书籍/杂志/博物馆之间（或电影/留声机之间）的草稿互相覆盖 */
  var draftKey = 'lifedesk_draft_' + key + (id ? '_' + id : '');
  /* v59：collection/av 的草稿按 大类 隔离，避免书籍/杂志/博物馆之间（或电影/留声机之间）的草稿互相覆盖
     v78fix：原来只在 seed['大类'] 有值（即带 prefill 的入口，如「+ 书籍」）时才加后缀，
             于是「藏品馆 → 添加」这种没有 prefill 的入口用的是不带后缀的 key，
             会读到 v59 之前遗留的「大类=书籍」旧草稿，把大类覆盖成书籍 →
             点「添加藏品」却打开书籍表单（ISBN / 扫码那一套）。
             改为：新建时一律按「本次实际大类」隔离，没有 prefill 就用字段默认值。 */
  if ((key==='collection' || key==='av') && !id){
    var _dcat = seed['大类'] || editing.vals['大类'] || '';
    if (_dcat) draftKey += '_' + _dcat;
  }
  try {
    var raw = localStorage.getItem(draftKey);
    if (raw){
      var d = JSON.parse(raw);
      Object.keys(d).forEach(function(k){
        /* v78fix：再兜一道 —— 新建且没有明确大类预填时，不让草稿改写「大类」，
           否则残留的旧草稿仍能把「藏品馆 → 添加」拐去书籍表单。 */
        if (k==='大类' && (key==='collection'||key==='av') && !id
            && !(opts && opts.prefill && opts.prefill['大类']!=null)) return;
        if (k in editing.vals) editing.vals[k] = d[k];
      });
    }
    /* 若本次打开带有明确 大类 预填，确保草稿不会把大类覆盖错（如博物馆草稿覆盖书籍入口） */
    if (opts && opts.prefill && opts.prefill['大类']!=null){
      editing.vals['大类'] = opts.prefill['大类'];
    }
  } catch(e){}

  /* 持有默认：新藏品默认状态是在库，没填过持有则默认 1（手里至少这一件） */
  if (key==='collection' && !id && (editing.vals['持有']==null||editing.vals['持有']==='') && hasStatus(editing.vals,'在库')){
    editing.vals['持有']=1;
  }

  var host=$('sheetHost');
  /* 表单标题按具体类目个性化：影音厅的电影/留声机、文渊斋的书籍/杂志 */
  var titleName = m.name;
  if ((key==='av' || key==='collection') && editing.vals['大类']){
    titleName = editing.vals['大类'];
  }
  var eyebrowName = m.eyebrow;
  if (key==='collection' && editing.vals['大类'] === '书籍') eyebrowName = 'Learning';
  if (key==='collection' && editing.vals['大类'] === '杂志') eyebrowName = 'Periodical';
  var h='<div class="sheet"><div class="sheet-head"><div>'+
    '<p>'+esc(eyebrowName)+'</p><h2>'+(id?'编辑':'添加')+' · '+esc(titleName)+'</h2></div>'+
    '<button class="x" type="button" data-x="1" aria-label="关闭">×</button></div>'+
    '<div class="fgrid">'+activeFields(key, editing.vals).map(function(f){ return fieldHTML(f, editing.vals[f.k]); }).join('')+'</div>'+
    '<div class="sheet-actions">'+
    (id?'<button class="btn ghost" type="button" id="delBtn" style="margin-right:auto;color:var(--red)">删除</button>':'')+
    '<button class="btn ghost" type="button" data-x="1">取消</button>'+
    '<button class="btn primary" type="button" id="saveBtn">保存</button></div></div>';
  host.innerHTML=h; host.hidden=false;
  host.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=closeSheet; });
  bindSheetBackdrop(host);
  /* v58：杂志表单的「刊名」输入框挂 datalist——下拉列出数据库里已有的杂志刊名 */
  if (key==='collection' && editing.vals['大类']==='杂志'){
    var nameInp=host.querySelector('[data-f="名称"]');
    if (nameInp){
      nameInp.setAttribute('list','magNameList');
      var magNames={};
      ((store.collection&&store.collection.rows)||[]).forEach(function(r){
        if (r['大类']==='杂志' && r['名称']) magNames[r['名称']]=1;
      });
      var mdl=document.createElement('datalist'); mdl.id='magNameList';
      mdl.innerHTML=Object.keys(magNames).map(function(n){ return '<option value="'+esc(n)+'">'; }).join('');
      host.appendChild(mdl);
    }
  }
  /* 目的地表单的「高德搜索」框默认带当前地点名，减少重复输入 */
  if (key==='travel'){
    var as = host.querySelector('[data-amap-search]');
    if (as) as.value = String(editing.vals['地点']||editing.vals['地区']||'');
  }

  wireFormControls(host, function(){
    try { localStorage.setItem(draftKey, JSON.stringify(editing.vals)); } catch(e){}
  });

  $('saveBtn').onclick=function(){
    var bad=null;
    activeFields(key, editing.vals).forEach(function(f){
      if (f.req){
        var v=editing.vals[f.k];
        if (v==null || String(v).trim()===''){
          bad=f;
          var box=host.querySelector('[data-f="'+f.k+'"]');
          if (box && box.parentNode) box.parentNode.classList.add('bad');
        } else {
          var b2=host.querySelector('[data-f="'+f.k+'"]');
          if (b2 && b2.parentNode) b2.parentNode.classList.remove('bad');
        }
      }
    });
    if (bad){ toast('「'+bad.k+'」还没填'); return; }
    var after = formAfter; formAfter = null;
    var doSave = function(){
      if (id) updateRow(key, id, editing.vals, after);
      else addRow(key, editing.vals, after);
      try { localStorage.removeItem(draftKey); } catch(e){}
      closeSheet();
      if (MODE === 'db') toast('已保存', null, null);
    };
    /* 旅行：没填坐标时，自动按地点名地理编码，让目的地在地球上自动亮起来（查不到也不影响保存） */
    if (key==='travel' && !(Number(editing.vals['纬度']) && Number(editing.vals['经度']))){
      toast('正在按地点名定位坐标…');
      geocodeTravel(editing.vals, function(coords){
        if (coords){ editing.vals['纬度']=Math.round(coords.lat*100)/100; editing.vals['经度']=Math.round(coords.lon*100)/100; }
        else { toast('未自动找到坐标，请点「📍在地球上点选坐标」手动定位'); }
        doSave();
      });
    } else {
      doSave();
    }
  };
  var del=$('delBtn');
  if (del) del.onclick=function(){
    /* v58：必须先取名称再 closeSheet()——closeSheet 会把 editing 置空，
       之后再读 editing.vals 会抛 Cannot read properties of null，导致删除流程中断报错 */
    var _f0 = activeFields(key, (editing && editing.vals) || {})[0] || {k:'名称'};
    var delName = String((row && row[_f0.k]) || '这条记录');
    closeSheet();
    askConfirm('删除「'+delName+'」？删掉就找不回来了。', function(){
      deleteRow(key, id, delName);
    });
  };
}
function fieldHTML(f, v){
  /* v75fix：quarter:true 或自定义字段 w===1 → .q（占 1 格＝25%）；rowstart:true → .rs（强制新行开头）。
     一行按 4 格算：默认 2 格(50%)，w=1 时 1 格(25%)。
     v76：宽度可被「页面管理 → 内置字段」覆盖，1=25% / 2=50% / 3=75% / 4=整行。 */
  var _span = fieldSpanOf(f, curFieldLayout());
  var body='', cls='f'+(_span===4?' full':'')+(_span===1?' q':'')+(_span===3?' w3':'')+(f.rowstart?' rs':'');
  if (f.t==='text' || f.t==='number' || f.t==='currency' || f.t==='date'){
    var type = f.t==='number'||f.t==='currency' ? 'number' : (f.t==='date'?'date':'text');
    /* autocomplete=off：阻止 Chrome 把「国家地区」之类字段当成用户名去匹配已保存的密码 */
    body='<input data-f="'+f.k+'" type="'+type+'" value="'+esc(v)+'" placeholder="'+esc(f.ph||'')+'" autocomplete="off"'+
      (f.min!=null?' min="'+f.min+'"':'')+(f.max!=null?' max="'+f.max+'"':'')+'>';
  } else if (f.t==='isbn'){
    /* v77：ISBN 输入 + 正下方的「扫码 / 照片识别 / 书名搜索」模块。
       扫码或照片识别出的号码直接填进上面的 ISBN 框；条码扫不到时可用书名搜索。 */
    body='<div class="isbn-wrap">'+
      '<input data-f="'+f.k+'" type="text" inputmode="numeric" value="'+esc(v)+'" placeholder="'+esc(f.ph||'')+'" autocomplete="off">'+
      '<button type="button" class="btn ghost sm isbn-go" data-act="isbnlookup" title="按 ISBN 联网查书">搜书</button>'+
    '</div>'+
    '<div class="isbn-tools" data-isbn-tools="1">'+
      '<div class="isbn-tool-row">'+
        '<button type="button" class="btn ghost sm" data-act="isbnlivecam">📷 扫码</button>'+
        '<button type="button" class="btn ghost sm" data-act="isbnphoto">🖼 照片识别</button>'+
      '</div>'+
      '<div class="isbn-live" hidden>'+
        '<div class="isbn-reader"></div>'+
        '<div class="isbn-live-msg">准备中…</div>'+
        '<button type="button" class="btn ghost sm" data-act="isbnlivestop">停止扫码</button>'+
      '</div>'+
      '<div class="isbn-tsearch">'+
        '<input type="text" class="search isbn-title-q" placeholder="扫不到条码？直接输书名搜" autocomplete="off">'+
        '<button type="button" class="btn ghost sm" data-act="isbnsearchtitle">搜书名</button>'+
      '</div>'+
      '<div class="isbn-results"></div>'+
      '<input type="file" class="isbn-photo-input" accept="image/*" capture="environment" hidden>'+
    '</div>';
  } else if (f.t==='year-date'){
    /* v62：年 / 月 / 日 三段下拉。左边选年，右边补月日；月日都可以空着，
       只存年份（如 "2026"）。左右两段同一个数据源（就是下面那个 hidden input）。 */
    var dv = String(v||'');
    var yearVal  = /^\d{4}/.test(dv) ? dv.slice(0,4) : '';
    var monthVal = /^\d{4}-\d{2}/.test(dv) ? String(parseInt(dv.slice(5,7),10)) : '';
    var dayVal   = /^\d{4}-\d{2}-\d{2}$/.test(dv) ? String(parseInt(dv.slice(8,10),10)) : '';
    var curY = new Date().getFullYear();
    var yopts = '<option value="">（年份）</option>';
    for (var yy=curY+2; yy>=1980; yy--){
      yopts += '<option value="'+yy+'"'+(yy===parseInt(yearVal,10)?' selected':'')+'>'+yy+'</option>';
    }
    var mopts='<option value="">（月）</option>';
    for (var mm=1; mm<=12; mm++) mopts += '<option value="'+mm+'"'+(String(mm)===monthVal?' selected':'')+'>'+mm+' 月</option>';
    var dopts='<option value="">（日）</option>';
    for (var dd=1; dd<=31; dd++) dopts += '<option value="'+dd+'"'+(String(dd)===dayVal?' selected':'')+'>'+dd+' 日</option>';
    body = '<div class="year-date-wrap">'+
      '<select data-fy="'+f.k+'" title="年份">'+yopts+'</select>'+
      '<select data-fm="'+f.k+'" title="月份（可不选）">'+mopts+'</select>'+
      '<select data-fd="'+f.k+'" title="日期（可不选）">'+dopts+'</select>'+
      '<input type="hidden" data-f="'+f.k+'" value="'+esc(dv)+'">'+
      '</div>';
  } else if (f.t==='loc3'){
    /* v75fix：存放位置 = 一个字段、内部三段（房间 / 柜墙 / 层），
       完全模仿「购入日期」的年/月/日——三段下拉 + 一个 hidden 存合成值。
       不再拆成三个独立字段。 */
    var lv3 = String(v || '');
    var lsegs = lv3.split('·').map(function(s){ return String(s).trim(); });
    function locOptHTML(dim, cur, ph){
      var o = '<option value="">' + ph + '</option>';
      (LOC_OPTS[dim] || []).forEach(function(x){
        o += '<option value="'+esc(x)+'"'+(x===cur?' selected':'')+'>'+esc(x)+'</option>';
      });
      return o;
    }
    body = '<div class="year-date-wrap loc3-wrap">'+
      '<select data-lr="'+f.k+'" title="房间">'+locOptHTML('房间', lsegs[0]||'', '（房间）')+'</select>'+
      '<select data-lc="'+f.k+'" title="柜墙">'+locOptHTML('柜体墙面', lsegs[1]||'', '（柜墙）')+'</select>'+
      '<select data-ll="'+f.k+'" title="层">'+locOptHTML('所在层', lsegs[2]||'', '（层）')+'</select>'+
      '<input type="hidden" data-f="'+f.k+'" value="'+esc(lv3)+'">'+
      '</div>';
  } else if (f.t==='img'){
    var vp = (editing && editing.vals && editing.vals[f.k+'_vp']) || {s:1,x:0,y:0};
    var prevStyle = v ? ("background-image:url('"+resolveImgUrl(v).replace(/[\"'()\\]/g,'')+"');background-repeat:no-repeat;background-position:"+(50+vp.x)+"% "+(50+vp.y)+"%;background-size:"+Math.max(100,Math.round(vp.s*100))+"% auto") : '';
    var hasV = !!v;
    body='<div class="imgwrap" data-k="'+f.k+'" data-has-img="'+(hasV?1:0)+'">'+
      '<div class="imgprev" data-img-prev="'+f.k+'" tabindex="0" title="可拖拽移动、滚轮缩放、方向键微调、Ctrl+V 粘贴图片" style="'+prevStyle+'">'+
      /* v75fix：封面框右上角「✕」——一键清掉当前这张图 */
      (v?'<button type="button" class="imgdel" data-act="imgdel" data-k="'+esc(f.k)+'" title="清除这张图片">✕</button>':'')+
      '<div class="imgvp-hint" '+(v?'':'hidden')+'>拖动移动 · 滚轮缩放 · 方向键微调 · 双击重置</div>'+
      '</div>'+
      '<div class="imgvp-bar" '+(v?'':'hidden')+'>'+
      '<button type="button" class="btn ghost xs" data-img-zoom="'+f.k+'" data-d="-0.15">−</button>'+
      '<span>缩放</span>'+
      '<button type="button" class="btn ghost xs" data-img-zoom="'+f.k+'" data-d="0.15">+</button>'+
      '<span class="imgvp-sp"></span>'+
      '<button type="button" class="btn ghost xs" data-img-pan="'+f.k+'" data-dx="-2" title="左移">←</button>'+
      '<button type="button" class="btn ghost xs" data-img-pan="'+f.k+'" data-dx="2" title="右移">→</button>'+
      '<button type="button" class="btn ghost xs" data-img-pan="'+f.k+'" data-dy="-2" title="上移">↑</button>'+
      '<button type="button" class="btn ghost xs" data-img-pan="'+f.k+'" data-dy="2" title="下移">↓</button>'+
      '<span class="imgvp-sp"></span>'+
      '<button type="button" class="btn ghost xs" data-img-reset="'+f.k+'">重置</button>'+
      '</div>'+
      /* v75fix：下载按钮挪进这一行，夹在「链接输入框」和「上传」之间 */
      '<div class="imgrow"><input data-f="'+f.k+'" type="text" value="'+esc(v)+'" placeholder="'+esc(f.ph||'图片链接')+'" autocomplete="off">'+
      '<button type="button" class="btn ghost sm imgdl-btn" data-act="dlcover" data-k="'+esc(f.k)+'" title="把左边链接里的图片下载下来，直接显示在封面框里">⬇ 下载</button>'+
      '<label class="btn ghost sm upl" for="up_'+f.k+'">上传<input id="up_'+f.k+'" type="file" accept="image/*" data-img-file="'+f.k+'" hidden></label></div>'+
      '<span class="imgnote" data-img-note="'+f.k+'">上传的图会先在浏览器里压到长边 800px 再存；也可以直接粘贴图片</span>'+
      /* v67：外链封面一键落盘 —— 抓取/扫码带回来的豆瓣等外链只是个网址，
         换设备、手机端、或者对方防盗链时就打不开。点上面「⬇ 下载」即可存进 data/images。 */
      '<div class="imgdl" data-img-dl="'+f.k+'">'+
        '<span class="imgnote" data-img-dltip="'+f.k+'">'+
          (imgIsRemote(v) ? '现在是网络链接，点上面「⬇ 下载」把它存进 data/images（同一张图只会存一次）'
                          : (v ? '这张已经是本地图片了' : '粘贴一个图片链接后，点「⬇ 下载」即可存进本地图库'))+
        '</span>'+
      '</div>'+
      '</div>';
  } else if (f.t==='textarea'){
    body='<textarea data-f="'+f.k+'" placeholder="'+esc(f.ph||'')+'" autocomplete="off">'+esc(v)+'</textarea>';
  } else if (f.t==='select'){
    /* v77fix：值为空时必须在最前面放一个空选项并选中它。
       原来没有空选项，浏览器会默认选中第一项——比如「地区」字段数据里是空的，
       打开却显示「阿罗拉」，看着像有值；这时候一点保存，第一项就被写进数据里了。 */
    body='<select data-f="'+f.k+'">'+
      '<option value=""'+(String(v||'')===''?' selected':'')+'>'+esc(f.ph||'（不选）')+'</option>'+
      f.o.map(function(o){
        return '<option value="'+esc(o)+'"'+(o===v?' selected':'')+'>'+esc(o)+'</option>'; }).join('')+
      '</select>';
  } else if (f.t==='locopt'){
    /* v75fix：存储地点三段（房间 / 柜体墙面 / 所在层）——
       选项来自可管理列表 LOC_OPTS，末尾「＋ 新建…」点了就弹窗新增并立刻选中 */
    var ldim = f.dim || f.k;
    var lopts = LOC_OPTS[ldim] || [];
    var lv = String(v||'');
    body='<div class="locoptwrap" data-dim="'+esc(ldim)+'">'+
      '<select data-f="'+f.k+'" data-locopt="'+esc(ldim)+'">'+
      '<option value="">（不选）</option>'+
      lopts.map(function(o){
        return '<option value="'+esc(o)+'"'+(o===lv?' selected':'')+'>'+esc(o)+'</option>'; }).join('')+
      '<option value="__new__">＋ 新建…</option>'+
      '</select></div>';
  } else if (f.t==='multi'){
    var arr=v||[];
    body='<div class="multisel" data-k="'+f.k+'">'+f.o.map(function(o){
      return '<button type="button" class="'+(arr.indexOf(o)>=0?'on':'')+'" data-v="'+esc(o)+'">'+esc(o)+'</button>';
    }).join('')+'</div>';
  } else if (f.t==='booktag'){
    /* v67：书籍标签分类——五个预设大类，空值 = 未分类 */
    var tv = String(v || '').trim();
    body = '<select data-f="'+f.k+'" data-booktag="1">'+
      '<option value=""'+(tv===''?' selected':'')+'>未分类</option>'+
      (f.o || []).map(function(o){
        return '<option value="'+esc(o)+'"'+(o===tv?' selected':'')+'>'+esc(o)+'</option>';
      }).join('')+'</select>';
  } else if (f.t==='booksub'){
    /* v67：小分类——挂在「标签分类」下面。选「＋ 新建小分类…」会真的建一个 data.json + 图片文件夹 */
    var parent = (editing && editing.vals) ? String(editing.vals['标签分类'] || '').trim() : '';
    var sv = String(v || '').trim();
    body = '<select data-f="'+f.k+'" data-booksub="1"'+(parent?'':' disabled')+'>'+
      bookSubOptionsHTML(parent, sv)+'</select>'+
      '<span class="imgnote" data-booksub-tip="1">'+(parent
        ? '「'+esc(parent)+'」下面再细分一层，比如「德语」。新建会自动生成 书籍/'+esc('{小分类}')+'-data.json 和同名图片文件夹。'
        : '先在上面选一个「标签分类」，才能建它下面的小分类')+'</span>';
  } else if (f.t==='stars'){
    /* v58：支持半星（3.5 / 4.5），点星星左半=半星、右半=整星，与遐方坞心级一致 */
    var n=num(v)||0;
    body='<div class="starsel" data-k="'+f.k+'" data-v="'+n+'">';
    for(var i=1;i<=(f.max||5);i++){
      var sc=(n>=i)?'on':((n>=i-0.5)?'half':'');
      body+='<span class="star-btn"><span class="star-ic '+sc+'">★</span>'+
        '<button type="button" class="hit left" data-i="'+(i-0.5)+'" aria-label="'+(i-0.5)+' 星"></button>'+
        '<button type="button" class="hit right" data-i="'+i+'" aria-label="'+i+' 星"></button></span>';
    }
    body+='</div>'+
      '<span class="imgnote">点星星左半边=半星（如 3.5），右半边=整星；再点当前值可减</span>';
  } else if (f.t==='hearts'){
    var hn=num(v)||0;
    body='<div class="heartsel" data-k="'+f.k+'" data-v="'+hn+'">';
    for(var i=1;i<=(f.max||5);i++){
      var cls = (hn>=i)?'on':((hn>=i-0.5)?'half':'');
      body+='<span class="heart-btn" data-i="'+i+'">'+
        '<span class="hheart '+cls+'">♥<i>♥</i></span>'+
        '<button type="button" class="hit left" data-i="'+(i-0.5)+'" aria-label="'+(i-0.5)+' 颗心"></button>'+
        '<button type="button" class="hit right" data-i="'+i+'" aria-label="'+i+' 颗心"></button>'+
        '</span>';
    }
    body+='</div>';
  } else if (f.t==='dyn'){
    body='<div class="dynwrap" data-k="'+f.k+'" data-src="'+f.src+'">'+
      '<select data-dyn-sel="'+f.k+'"><option value="">（无）</option></select>'+
      '<input data-dyn-cus="'+f.k+'" type="text" placeholder="自定义…" style="display:none" autocomplete="off">'+
      '</div>';
  } else if (f.t==='geopick'){
    var isAmap = (f.mode==='amap');
    body='<div style="display:flex;gap:8px;margin:2px 0 8px">'+
      '<input type="text" class="search" data-amap-search placeholder="'+esc(isAmap?'如：金强牛肉面 上海':'如：黄山风景区，或直接点下方按钮')+'" style="flex:1" autocomplete="off">'+
      '<button class="btn primary sm" type="button" data-act="amapsearch">🔍 高德搜索</button>'+
      '</div>'+
      '<button type="button" class="btn ghost sm" data-act="'+(isAmap?'amappick':'geopick')+'">📍 '+(isAmap?'在地图上选点':'在地球上点选坐标')+'</button>'+
      '<button type="button" class="btn ghost sm" data-act="georeloc">🌍 按名称重新定位</button>'+
      '<span class="imgnote">'+esc(isAmap?'输入店名 / 城市搜高德自动填坐标，或点地图手动选':'输入地点名搜高德自动填坐标，或在地球上手动选')+'</span>';
  } else if (f.t==='check'){
    body='<label class="checkrow"><input data-f="'+f.k+'" type="checkbox"'+(v?' checked':'')+'>'+esc(f.k)+'</label>';
  } else if (f.t==='checks'){
    var arr=(v||[]);
    var rowCls = (f.statusRow ? ' checksrow statusrow' : ' checksrow');
    body='<div class="'+rowCls.trim()+'" data-k="'+f.k+'">'+(f.o||[]).map(function(o){
      return '<label class="checkrow"><input data-f="'+f.k+'" data-v="'+esc(o)+'" type="checkbox"'+(arr.indexOf(o)>=0?' checked':'')+'>'+esc(o)+'</label>';
    }).join('')+'</div>';
  }
  var lab = f.t==='geopick' ? '' : '<label>'+esc(f.lab||f.k)+(f.req?' *':'')+'</label>';
  return '<div class="'+cls+'">'+lab+body+
    (f.req?'<span class="err">这一项必填</span>':'')+'</div>';
}
/* v58：点背景关闭表单的守卫——必须「按下」和「松开」都在背景上才关闭。
   否则在输入框里选文字复制、拖到卡片外松手，click.target 落在背景上会误关表单。 */
function bindSheetBackdrop(host){
  host.addEventListener('mousedown', function(e){ host._downOnBackdrop=(e.target===host); });
  host.onclick=function(e){ if(e.target===host && host._downOnBackdrop){ host._downOnBackdrop=false; closeSheet(); } };
}
function closeSheet(){ $('sheetHost').hidden=true; $('sheetHost').innerHTML=''; editing=null; formAfter=null; }

/* ============ v49：手机扫码录入书籍（ISBN 条码 / 二维码）→ 查书自动填表 ============ */
function normIsbn(s){
  s=String(s||'').replace(/[\s-]/g,'').toUpperCase();
  if (/^\d{10}$/.test(s)){
    var sum=0; for(var i=0;i<9;i++) sum+=(i+1)*parseInt(s.charAt(i),10);
    var c=(11-(sum%11))%11, check=(c===10?'X':String(c));
    s='978'+s.slice(0,9)+check;
  }
  return /^\d{13}$/.test(s) ? s : '';
}
/* ---------- v65：ISBN 查书数据源 ----------
   实测（2026-09 从本机直连）：
     ① openlibrary.org/isbn/{isbn}.json   200 · ~2.4s · CORS:*
        中文书名、中文出版社名（作家出版社）、出版年、封面 ID —— 中文书质量最好
     ② openlibrary.org/api/books?bibkeys=ISBN:..&jscmd=data   200 · ~3.2s · CORS:*
        带作者名、出版社（常是英文音译 Chongqing Press）、封面 URL
     ③ openlibrary.org/search.json?q=isbn:..  200 · ~6.9s · CORS:*   兜底，命中率略高
     ④ googleapis.com/books/v1  实测 429 配额超限，且国内访问不了 —— 仅作最后兜底
   策略：①②并行打，合并字段（书名/出版社/年份/封面取①，作者取②）；
        都不中再退③，最后④。 */
/* ---------- v66：豆瓣（中文书最强的源，但需要代理）----------
   豆瓣自己**不发 Access-Control-Allow-Origin**，浏览器 JS 直接 fetch 读不到；
   而且 JS 也不允许改 Referer（frodo 移动 API 就靠它鉴权）。所以必须走一层代理。
   默认用 r.jina.ai（免费、支持 CORS、返回干净的 markdown，首次约 13–20s、
   之后有缓存约 1.5s）。嫌慢或被限流时，可以在「⚙ 同步设置」里换成自己的代理
   （Cloudflare Worker 之类），只要能把目标网页原样返回即可，两种格式都能解析。 */
var BOOK_PROXY_KEY='lifedesk_book_proxy';
function bookProxy(){
  try { return (localStorage.getItem(BOOK_PROXY_KEY) || 'https://r.jina.ai/').trim(); } catch(e){ return 'https://r.jina.ai/'; }
}
function setBookProxy(v){ try { localStorage.setItem(BOOK_PROXY_KEY, String(v||'').trim()); } catch(e){} }
/* 解析 r.jina.ai 的 markdown 结果 */
function parseDoubanMarkdown(txt){
  var get=function(label){
    var re=new RegExp('^'+label+'\\s*[:：]\\s*(.+)$','m');
    var m=re.exec(txt);
    if (!m) return '';
    /* 作者/出版社常被 markdown 链接包着：[商务印书馆](https://...) */
    return String(m[1]).replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').trim();
  };
  var out={};
  var t=/^Title:\s*(.+)$/m.exec(txt); if (t) out.名称=String(t[1]).trim();
  out.作者   = get('作者');
  out.出版社 = get('出版社');
  var y=get('出版年'); if (y){ var ym=/(\d{4})/.exec(y); if (ym) out.出版年=ym[1]; }
  var pg=get('页数');  if (pg){ var pm=/(\d+)/.exec(pg); if (pm) out.页数=pm[1]; }
  var pr=get('定价');  if (pr){ var rm=/[\d.]+/.exec(pr); if (rm) out.定价=rm[0]; }
  var rt=/\*\*([\d.]+)\*\*/.exec(txt); if (rt) out.豆瓣评分=rt[1];
  /* 封面：markdown 里是 [![alt](小图)](大图 "标题")，优先抓大图；
     抓不到大图就把小图的 /s/public/ 换成 /l/public/（豆瓣的固定规律）。 */
  var big=/https:\/\/[^)"'\s]+\/l\/public\/[^)"'\s]+\.(?:jpg|jpeg|png|webp)/i.exec(txt);
  if (big) out.封面=big[0];
  else {
    var any=/https:\/\/[^)"'\s]*doubanio\.com\/view\/subject\/[^)"'\s]+\.(?:jpg|jpeg|png|webp)/i.exec(txt);
    if (any) out.封面=String(any[0]).replace(/\/s\/public\//,'/l/public/');
  }
  if (!out.名称) return null;
  /* v80：豆瓣/代理返回错误页（被限流、书不存在、网络异常）时，标题常是「出现了一个问题」
     「页面不存在」之类，若当书名填进表单会污染书名。错误页几乎没有任何书目元数据，
     据此 + 标题哨兵词双重拒绝。 */
  if (/出现了一个问题|出现问题|页面不存在|访问被拒绝|请求过于频繁|无法访问|网络异常|Not Found|Error|Bad Gateway|Gateway Timeout|502|503|429/i.test(out.名称)) return null;
  if (!(out.作者 || out.出版社 || out.出版年 || out.ISBN || out.豆瓣评分)) return null;
  out._src='豆瓣';
  return out;
}
/* 解析代理返回的原始 HTML（自建代理场景） */
function parseDoubanHTML(html){
  var doc=new DOMParser().parseFromString(html,'text/html');
  var h1=doc.querySelector('#wrapper h1 span[property="v:itemreviewed"]') || doc.querySelector('#wrapper h1 span');
  var title=h1?String(h1.textContent||'').trim():'';
  if (!title) return null;
  var info=doc.querySelector('#info');
  var txt=info?String(info.textContent||''):'';
  var out={ 名称:title, _src:'豆瓣' };
  var m;
  if ((m=/作者[:\s]*([^\n\r]+)/.exec(txt)))    out.作者=String(m[1]).trim();
  if ((m=/出版社[:\s]*([^\n\r]+)/.exec(txt)))  out.出版社=String(m[1]).trim();
  if ((m=/出版年[:\s]*(\d{4})/.exec(txt)))     out.出版年=m[1];
  if ((m=/页数[:\s]*(\d+)/.exec(txt)))         out.页数=m[1];
  if ((m=/定价[:\s]*([\d.]+)/.exec(txt)))      out.定价=m[1];
  if ((m=/ISBN[:\s]*([\dXx]+)/.exec(txt)))     out.ISBN=m[1];
  var cov=doc.querySelector('#mainpic img');
  if (cov){
    var cu=cov.getAttribute('src')||'';
    if (cu) out.封面=String(cu).replace(/\/s\/public\//,'/l/public/');
  }
  var rat=doc.querySelector('[property="v:average"]');
  if (rat) out.豆瓣评分=String(rat.textContent||'').trim();
  /* v80：错误页（限流/不存在）标题会是「出现了一个问题」等，且无任何书目元数据，直接拒绝 */
  if (/出现了一个问题|出现问题|页面不存在|访问被拒绝|请求过于频繁|无法访问|网络异常|Not Found|Error|Bad Gateway|Gateway Timeout/i.test(out.名称)) return null;
  if (!(out.作者 || out.出版社 || out.出版年 || out.ISBN)) return null;
  return out;
}
function lookupDouban(isbn, cb){
  var px=bookProxy();
  if (!px){ cb(null); return; }
  var target='https://book.douban.com/isbn/'+encodeURIComponent(isbn)+'/';
  var url = (px.charAt(px.length-1)==='/') ? (px+target) : (px+encodeURIComponent(target));
  var timer=setTimeout(function(){ cb(null); }, 25000);   /* 代理可能很慢，别一直转圈 */
  fetch(url, { cache:'no-store' })
    .then(function(r){ return r && r.ok ? r.text() : null; })
    .then(function(t){
      clearTimeout(timer);
      if (!t){ cb(null); return; }
      var book=null;
      if (/^Title:/m.test(t) || /Markdown Content:/.test(t)) book=parseDoubanMarkdown(t);
      else book=parseDoubanHTML(t);
      cb(book);
    })
    .catch(function(){ clearTimeout(timer); cb(null); });
}
/* v80：带超时的 fetch —— 国内直连 Open Library 经常慢/卡住，加 9s 超时让兜底链尽快推进 */
function _fetchTimeout(url, ms){
  var ctrl=null, id=null;
  var opts={ cache:'no-store' };
  if (typeof AbortController==='function'){
    ctrl=new AbortController();
    opts.signal=ctrl.signal;
    id=setTimeout(function(){ try{ ctrl.abort(); }catch(e){} }, ms||9000);
  }
  return fetch(url, opts).then(function(r){ if(id) clearTimeout(id); return r; })
                          .catch(function(e){ if(id) clearTimeout(id); throw e; });
}
function _olJSON(url){
  return _fetchTimeout(url, 9000)
    .then(function(r){ return (r && r.ok) ? r.json() : null; })
    .catch(function(){ return null; });
}
/* v80：书籍查询结果本地缓存（localStorage），重复查同一本书/同一书名秒回，避免每次都走慢网络 */
var BOOK_CACHE_KEY='lifedesk_bookcache_v1';
function bookCacheGet(key){
  try{
    var raw=localStorage.getItem(BOOK_CACHE_KEY); if(!raw) return null;
    var m=JSON.parse(raw); var v=m[key];
    if(!v) return null;
    if (v._exp && v._exp < Date.now()) return null;
    return v;
  }catch(e){ return null; }
}
function bookCacheSet(key, val){
  try{
    var raw=localStorage.getItem(BOOK_CACHE_KEY);
    var m=raw?JSON.parse(raw):{};
    val._exp=Date.now()+1000*60*60*24*30;   /* 缓存 30 天 */
    m[key]=val;
    var ks=Object.keys(m);
    if (ks.length>400){ delete m[ks[0]]; }     /* 控制体积：最多 ~400 条 */
    localStorage.setItem(BOOK_CACHE_KEY, JSON.stringify(m));
  }catch(e){}
}
function lookupBookByISBN(isbn, cb){
  isbn=normIsbn(String(isbn||''));
  if (!isbn){ cb(null); return; }
  /* 缓存优先：同一本书第二次查直接秒回（扫码/书名搜索都受益） */
  var ckey='isbn:'+isbn;
  var cached=bookCacheGet(ckey);
  if (cached){ cb(cached); return; }

  var out={ ISBN:isbn, _src:'' };
  var edURL='https://openlibrary.org/isbn/'+encodeURIComponent(isbn)+'.json';
  var bkURL='https://openlibrary.org/api/books?bibkeys=ISBN:'+encodeURIComponent(isbn)+'&format=json&jscmd=data';
  var settled=false, olDone=false, dbDone=false;
  function done(book){
    if (settled) return; settled=true;
    if (book && book['名称']) bookCacheSet(ckey, book);   /* 命中即缓存，下次秒回 */
    cb(book);
  }
  function mergeOL(pair){
    var ed=pair[0], bk=pair[1] && pair[1]['ISBN:'+isbn];
    var title='', pub='', year='', cover='', authors=[];
    if (ed && ed.title){
      title=String(ed.title).trim();
      if (ed.publishers && ed.publishers.length) pub=String(ed.publishers[0]).trim();
      if (ed.publish_date){ var m=String(ed.publish_date).match(/\d{4}/); if(m) year=m[0]; }
      if (ed.covers && ed.covers.length) cover='https://covers.openlibrary.org/b/id/'+ed.covers[0]+'-L.jpg';
    }
    if (bk){
      if (!title && bk.title) title=String(bk.title).trim();
      if (!pub && bk.publishers && bk.publishers.length) pub=String(bk.publishers[0].name||'').trim();
      if (!year && bk.publish_date){ var m2=String(bk.publish_date).match(/\d{4}/); if(m2) year=m2[0]; }
      if (bk.authors) authors=bk.authors.map(function(a){ return String(a.name||'').trim(); }).filter(Boolean);
      if (!cover && bk.cover) cover=bk.cover.large || bk.cover.medium || '';
    }
    if (title){
      out._src='Open Library';
      out.名称=title; out.作者=authors.join(' / '); out.出版社=pub; out.出版年=year; out.封面=cover;
      return true;
    }
    return false;
  }
  /* ①② 与豆瓣都未命中，才走最后的 Open Library 搜索 → Google Books（避免 GB 先返回 null 把还在飞的豆瓣结果挤掉） */
  function maybeFallback(){
    if (settled || !olDone || !dbDone) return;
    _olJSON('https://openlibrary.org/search.json?q=isbn:'+encodeURIComponent(isbn)+'&fields=title,author_name,publish_date,publisher,cover_i')
      .catch(function(){ return null; })
      .then(function(d){
        if (settled) return;
        var doc=d && d.docs && d.docs[0];
        if (doc && (doc.title || (doc.author_name && doc.author_name.length))){
          var y3=''; if (doc.publish_date){ var m3=String(doc.publish_date[0]||'').match(/\d{4}/); if(m3) y3=m3[0]; }
          var c3=doc.cover_i ? ('https://covers.openlibrary.org/b/id/'+doc.cover_i+'-L.jpg') : '';
          out._src='Open Library 搜索';
          out.名称=String(doc.title||'').trim();
          out.作者=(doc.author_name||[]).join(' / ');
          out.出版社=(doc.publisher&&doc.publisher[0])||'';
          out.出版年=y3; out.封面=c3;
          done(out); return;
        }
        lookupGB(isbn, done);      /* 兜底：Google Books（国内基本不可达，且常 429） */
      });
  }

  /* v80：豆瓣与 Open Library ①② 并行启动 —— 中文书 Open Library 常查不到，
     原来要等 OL ①② 都回来才去问豆瓣（代理首访 13–20s），整体被拉长。
     现在豆瓣同时跑：OL 命中就秒回；OL 不中时豆瓣已在飞，不再额外排队。 */
  lookupDouban(isbn, function(db){
    dbDone=true;
    if (db && db['名称']) done(db);     /* 豆瓣命中直接返回（错误页已被解析器拒绝，不会到这里） */
    else maybeFallback();
  });
  /* v81：京东（中文书封面最全），与豆瓣并行；只有前面的源都没命中时才采用，避免慢通道盖掉快结果 */
  lookupJDByISBN(isbn, function(jd){
    if (jd && jd['名称'] && !settled) done(jd);
  });
  /* v82：芸台购（中文高校/教材书最全），与豆瓣并行；命中即采用 */
  lookupYunByISBN(isbn, function(yb){
    if (yb && yb['名称'] && !settled) done(yb);
  });
  /* v82：中国书网：站点屏蔽搜索，基本只兜底，安静失败 */
  lookupSinoByISBN(isbn, function(sb){
    if (sb && sb['名称'] && !settled) done(sb);
  });

  Promise.all([
    _olJSON(edURL).catch(function(){ return null; }),
    _olJSON(bkURL).catch(function(){ return null; })
  ]).then(function(pair){
    olDone=true;
    if (settled) return;
    if (mergeOL(pair)){ done(out); return; }   /* Open Library ①② 命中 */
    maybeFallback();
  });
}
function mapOL(doc, isbn){
  var yr=''; if(doc.publish_date&&doc.publish_date[0]){ var m=String(doc.publish_date[0]).match(/\d{4}/); if(m) yr=m[0]; }
  return {
    名称: doc.title||'',
    作者: (doc.author_name||[]).join(' / '),
    出版社: (doc.publisher&&doc.publisher[0])||'',
    出版年: yr,
    ISBN: isbn
  };
}
function lookupGB(isbn, cb){
  var url='https://www.googleapis.com/books/v1/volumes?q=isbn:'+encodeURIComponent(isbn);
  _fetchTimeout(url, 9000).then(function(r){ return r.ok?r.json():null; }).catch(function(){ return null; }).then(function(d){
    var v=d&&d.items&&d.items[0]&&d.items[0].volumeInfo;
    if(!v||!v.title){ cb(null); return; }
    var pd=v.publishedDate||'', yr=(pd.match(/\d{4}/)||[''])[0];
    cb({ 名称:v.title, 作者:(v.authors||[]).join(' / '), 出版社:v.publisher||'', 出版年:yr, ISBN:isbn });
  }).catch(function(){ cb(null); });
}
/* v81：京东源（中文书封面最全、元数据也较全）。
   京东 search/商品页是 JS 渲染 + 反爬验证墙，纯文本代理(r.jina.ai)拿不到商品页。
   只有把「同步设置」里的代理指向「能执行 JS 的渲染代理」(见 proxy-worker.js 的渲染模式) 才能拿到页面；
   代理不是 JS 渲染型时，下面函数会安静返回 null/[]，不拖慢主流程。 */
function _jdText(target){
  var px=bookProxy(); if(!px) return Promise.resolve(null);
  var url=(px.charAt(px.length-1)==='/')?(px+target):(px+encodeURIComponent(target));
  return _fetchTimeout(url, 12000).then(function(r){ return (r&&r.ok)?r.text():null; }).catch(function(){ return null; });
}
function _cleanJD(s){ return String(s||'').replace(/\s+/g,' ').replace(/【.*?】|（.*?）|\(.*?\)/g,'').replace(/^(京东|JD|自营|旗舰店)\s*/,'').trim(); }
function _jdParseProduct(html){
  if(!html) return null;
  try{
    var doc=new DOMParser().parseFromString(html,'text/html');
    var img=doc.querySelector('meta[property="og:image"]'); img=img?String(img.getAttribute('content')||'').trim():'';
    var ti=doc.querySelector('meta[property="og:title"]'); ti=ti?String(ti.getAttribute('content')||'').trim():'';
    if(!img && !ti) return null;
    var out={ 名称:_cleanJD(ti), 封面:img, _src:'京东' };
    var body=doc.body?doc.body.textContent:''; var m;
    if((m=/作者[:：]\s*([^\n;{]+)/.exec(body))) out.作者=_cleanJD(m[1]);
    if((m=/出版社[:：]\s*([^\n;{]+)/.exec(body))) out.出版社=_cleanJD(m[1]);
    if((m=/出版[年时间日期][:：]\s*(\d{4})/.exec(body))) out.出版年=m[1];
    return out;
  }catch(e){ return null; }
}
function _jdSkus(html, n){
  var set=[], re=/item\.jd\.com\/(\d+)\.html/g, mm;
  while((mm=re.exec(html||'')) && set.length<(n||4)){ if(set.indexOf(mm[1])<0) set.push(mm[1]); }
  return set;
}
function lookupJDByISBN(isbn, cb){
  _jdText('https://search.jd.com/Search?keyword='+encodeURIComponent(isbn)+'&enc=utf-8')
    .then(function(h){
      var skus=_jdSkus(h,1);
      if(!skus.length){ cb(null); return; }
      return _jdText('https://item.jd.com/'+skus[0]+'.html');
    })
    .then(function(ph){ cb(_jdParseProduct(ph)); })
    .catch(function(){ cb(null); });
}
function lookupJDByTitle(q, cb){
  _jdText('https://search.jd.com/Search?keyword='+encodeURIComponent(q)+'&enc=utf-8')
    .then(function(h){
      var skus=_jdSkus(h,4);
      if(!skus.length){ cb([]); return; }
      var list=[], got=0;
      skus.forEach(function(s){
        _jdText('https://item.jd.com/'+s+'.html')
          .then(function(ph){ var b=_jdParseProduct(ph); if(b) list.push(b); })
          .catch(function(){})
          .then(function(){ if(++got===skus.length){ cb(list.slice(0,6)); } });
      });
    })
    .catch(function(){ cb([]); });
}

/* ===================== v82：新增两个中文书源 ===================== */
/* 云图/芸台购（yuntaigo.com）：服务端渲染，经 r.jina.ai 转 markdown 后仍保留
   recordid 链接、OSS 封面、编者/责编/出版社/年/价 文本，可直接解析。 */
function _yunText(target){
  var px=bookProxy(); if(!px) return Promise.resolve(null);
  var url=(px.charAt(px.length-1)==='/')?(px+target):(px+encodeURIComponent(target));
  return _fetchTimeout(url, 12000).then(function(r){ return (r&&r.ok)?r.text():null; }).catch(function(){ return null; });
}
function _yunClean(s){
  return String(s||'').replace(/\s+/g,' ').replace(/\/{2,}/g,' / ').replace(/^(编者|责编)[:：]?/,'').trim();
}
function parseYunMarkdown(txt){
  if (!txt) return [];
  if (/没有找到|Error Page|索书号不存在|无相关/i.test(txt)) return [];
  var books=[], re=/\*\s*\[!\[[^\]]*\]\(([^)\s]*oss-cn[^)\s]*)\)\]\(https?:\/\/[^)\s]*?book\.action\?recordid=([A-Za-z0-9]+)[^\n]*\)\s*\r?\n\s*###\s*\[([^\]]+)\]\(https?:\/\/[^)\s]*?book\.action\?recordid=\2[^\n]*\)\s*\r?\n\s*编者:([^\n]*)/g, m;
  while((m=re.exec(txt))){
    var cover=String(m[1]||'').split('?')[0];   /* 去掉 ?x-oss-process 缩略图参数，取原图 */
    var book={ 名称:String(m[3]).trim(), 封面:cover, recordid:m[2], _src:'芸台购' };
    var parts=String(m[4]).split('|');
    var au=(parts[0]||'').replace(/^编者[:：]?/,''); if (au) book.作者=_yunClean(au);
    var segs=(parts[1]||'').replace(/^责编[:：]?/,'').replace(/\/\//g,'、').split('/');
    if (segs.length>1) book.出版社=String(segs[1]).trim();
    if (segs.length>2){ var ym=segs[2].match(/\d{4}/); if(ym) book.出版年=ym[0]; }
    if (segs.length>3){ var pm=segs[3].match(/[\d.]+/); if(pm) book.定价=pm[0]; }
    if (book.名称) books.push(book);
  }
  return books;
}
function lookupYunByISBN(isbn, cb){
  isbn=normIsbn(String(isbn||'')); if(!isbn){ cb(null); return; }
  _yunText('https://www.yuntaigo.com/bookSearch.action?text='+encodeURIComponent(isbn))
    .then(function(t){ var l=parseYunMarkdown(t); if(l&&l.length){ l[0].ISBN=isbn; cb(l[0]); } else cb(null); })
    .catch(function(){ cb(null); });
}
function lookupYunByTitle(q, cb){
  _yunText('https://www.yuntaigo.com/bookSearch.action?text='+encodeURIComponent(q))
    .then(function(t){ cb(parseYunMarkdown(t)||[]); })
    .catch(function(){ cb([]); });
}
/* 中国书网/中国高校教材图书网（sinobook.com.cn）：详情页经 r.jina.ai 中文正文正常、
   解析质量高；但站点屏蔽了程序化搜索（ISBN/书名搜索均返回「没有找到」），
   故仅作兜底/详情解析，命中率低时安静失败。 */
function parseSinoMarkdown(txt){
  if (!txt) return null;
  if (/没有找到满足条件的书目|Error Page/i.test(txt)) return null;
  /* jina 常把整页压成一行，字段用「Label：value Label：value」串排；
     用「下一个字段标签」作为取值结束边界，避免抓到文末。
     注意：作者/出版社在 jina 里常写成 markdown 链接 [名称](url)（无 Label：前缀），
     故取值后只取第一个链接文本，避免把后面的「相关图书」等导航链接混进来。 */
  var STOP='(?=\\s*(?:ISBN|责任编辑|作者|定价|版印次|开本|出版社|装订|出版日期|页数|分级|适用专业|类别|年度|季度|中图法分类|用途分类|读者分类|千字数|印刷日期|国家规划教材|省部级规划教材|入选重点出版项目|其他获奖项目|小团购|内容简介|作者简介|章节目录|书\\s*评|其\\s*它|相关评论|相关图书)\\s*[:：]|$)';
  var get=function(label){
    var m=new RegExp(label+'\\s*[:：]\\s*([\\s\\S]*?)'+STOP).exec(txt); if(!m) return '';
    return String(m[1]).trim();
  };
  /* 作者/出版社在 jina 里常写成 [名称](url)，只取第一个链接文本，丢弃后面的「相关图书」等导航链接 */
  var firstLink=function(s){ var m=/\[([^\]]+)\]\([^)]*\)/.exec(s||''); return m?String(m[1]).trim():(String(s||'').replace(/\s+/g,' ').trim()); };
  var out={ _src:'中国书网' };
  var nm=new RegExp('书名\\s*[:：]\\s*([\\s\\S]*?)'+STOP).exec(txt);
  out.名称=nm?String(nm[1]).split('[')[0].replace(/\s+/g,' ').trim():'';   /* 截掉书名后的 [丛书](url) */
  var im=/([0-9\-Xx]{10,17})/.exec(get('ISBN')); if(im) out.ISBN=im[1];
  out.作者=firstLink(get('作者')); out.出版社=firstLink(get('出版社'));
  var yr=get('出版日期')||get('出版时间'); var ym=yr&&yr.match(/\d{4}/); if(ym) out.出版年=ym[0];
  var pm=get('定价')&&get('定价').match(/[\d.]+/); if(pm) out.定价=pm[0];
  var cov=/https:\/\/[^)"'\s]*bkimg[^)"'\s]*\.(?:jpg|jpeg|png|webp)/i.exec(txt); if(cov) out.封面=cov[0];
  if (!out.名称) return null;
  if (/出现了一个问题|页面不存在|Error|Not Found|502|503/i.test(out.名称)) return null;
  if (!(out.作者||out.出版社||out.出版年||out.ISBN)) return null;
  return out;
}
function lookupSinoByISBN(isbn, cb){
  isbn=normIsbn(String(isbn||'')); if(!isbn){ cb(null); return; }
  _yunText('https://www.sinobook.com.cn/b2c/scrp/book.cfm?sFieldName=isbn&sKeyword='+encodeURIComponent(isbn))
    .then(function(t){ cb(parseSinoMarkdown(t)); })
    .catch(function(){ cb(null); });
}
function lookupSinoByTitle(q, cb){
  _yunText('https://www.sinobook.com.cn/b2c/scrp/book.cfm?sFieldName=sname&sKeyword='+encodeURIComponent(q))
    .then(function(t){ cb(parseSinoMarkdown(t)); })
    .catch(function(){ cb(null); });
}

/* v65：把查到的书直接填进「当前这张表」，不重开表单——
   用户可能已经填了一半（存放位置、价格、标签），重开会全丢。 */
function fillBookInPlace(book){
  var host=$('sheetHost');
  if (!host || !book){ return false; }
  var map=[['名称'],['作者'],['出版社'],['出版年']];
  var filled=0;
  map.forEach(function(pair){
    var k=pair[0], v=String(book[k]||'').trim();
    if (!v) return;
    var el=host.querySelector('[data-f="'+k+'"]');
    if (el){ el.value=v; el.dispatchEvent(new Event('input',{bubbles:true})); filled++; }
  });
  /* 封面：写进「照片」输入框，并触发已有的预览刷新 */
  if (book['封面']){
    var ci=host.querySelector('[data-f="照片"]');
    if (ci){
      ci.value=book['封面'];
      ci.dispatchEvent(new Event('input',{bubbles:true}));
      ci.dispatchEvent(new Event('change',{bubbles:true}));
      filled++;
    }
  }
  return filled;
}
function doIsbnLookup(){
  var host=$('sheetHost');
  var inp = host && host.querySelector('[data-f="ISBN"]');
  if (!inp){ toast('没找到 ISBN 输入框'); return; }
  var raw=String(inp.value||'').trim();
  if (!raw){ inp.focus(); toast('先填或扫码一个 ISBN'); return; }
  /* 支持粘贴带链接的（如某东某当的 URL 里含 isbn=978...） */
  var isbn=normIsbn(raw) || normIsbn(String(inp.value||'').replace(/[\s-]/g,''));
  if (!isbn){
    var m=raw.match(/isbn[=_]?(\d{13}|\d{10})/i) || raw.match(/(\d{13})/) || raw.match(/(\d{10})/);
    if (m) isbn=normIsbn(m[1]);
  }
  if (!isbn){ toast('ISBN 格式不对：要 13 位（或 10 位），当前是「'+raw.slice(0,20)+'」'); return; }
  if (inp.value!==isbn) inp.value=isbn;
  var btn=host.querySelector('[data-act="isbnlookup"]');
  if (btn){ btn.disabled=true; btn.textContent='搜…'; }
  toast('正在查书：'+isbn);
  lookupBookByISBN(isbn, function(book){
    if (btn){ btn.disabled=false; btn.textContent='搜书'; }
    if (!book || !book['名称']){ toast('没查到这本书（'+isbn+'），可以手动填'); return; }
    fillBookInPlace(book);
    /* 表单里没有页数/定价这两栏，就在提示里带一嘴，免得白查 */
    var extra=[];
    if (book['页数']) extra.push(book['页数']+' 页');
    if (book['定价']) extra.push('定价 '+book['定价']);
    if (book['豆瓣评分']) extra.push('豆瓣 '+book['豆瓣评分']);
    toast('已填入：'+book['名称']+(book['_src']?('（'+book['_src']+'）'):'')+(extra.length?(' · '+extra.join(' · ')):''));
  });
}
function fillBookFromISBN(isbn){
  isbn = normIsbn(String(isbn||''));
  if (!isbn){ toast('ISBN 格式不对'); return; }
  toast('正在查书…');
  lookupBookByISBN(isbn, function(book){
    if (!book){ toast('没查到这本书（ISBN '+isbn+'）'); return; }
    /* v65：表单已经开着（扫码就是从表单里点出来的）→ 原地回填，别重开，
       否则用户已经填好的存放位置 / 价格 / 标签会被冲掉。 */
    var host=$('sheetHost');
    if (host && !host.hidden && host.querySelector('[data-f="ISBN"]')){
      if (fillBookInPlace(book)){
        toast('已填入：'+(book['名称']||'')+(book['_src']?('（'+book['_src']+'）'):''));
        return;
      }
    }
    var merged = Object.assign({}, (editing && editing.vals) || {}, book);
    if (!merged['大类']) merged['大类'] = '书籍';
    openForm('collection', null, {prefill: merged});
    toast('已填入：'+(book['名称']||''));
  });
}
/* 通用：按需加载外部脚本（识别库在扫码时才拉，不影响首屏） */
function loadScript(src){
  return new Promise(function(res, rej){
    var s=document.createElement('script'); s.src=src; s.async=true;
    s.onload=function(){ res(); }; s.onerror=function(){ rej(new Error('load fail')); };
    document.head.appendChild(s);
  });
}
/* 把扫码/选图识别出来的原始串归一化成 ISBN 并触发查书 */
function onDetectBook(raw, cleanup){
  var isbn=normIsbn(raw);
  if(!isbn && /^https?:\/\//i.test(raw)){
    var m=raw.match(/isbn[=_]?(\d{13}|\d{10})/i) || raw.match(/(\d{13})/);
    if(m) isbn=normIsbn(m[1]);
  }
  if(!isbn){ toast('没认出 ISBN，可手动填：'+String(raw||'').slice(0,40)); return; }
  if(typeof cleanup==='function') cleanup();
  rCloseOverlay();
  fillBookFromISBN(isbn);
}
/* 拍照/选图识别：微信等禁了实时摄像头的环境，用 file+capture 拿照片，本地 ZXing 解码 */
function decodeBookPhoto(file){
  var msg=document.getElementById('scanMsg');
  if(msg) msg.textContent='正在识别照片中的条码…';
  loadScript('https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js').then(function(){
    if(!document.getElementById('scanHidden')){ if(msg) msg.textContent='已取消'; return; }
    try{
      var sc=new Html5Qrcode('scanHidden');
      sc.scanFile(file, false).then(function(text){ onDetectBook(text); })
        .catch(function(){ if(msg) msg.textContent='没在图片里认出条码，换张清晰照片，或点「手动输入」'; });
    }catch(e){ if(msg) msg.textContent='识别库初始化失败，请用「手动输入」'; }
  }).catch(function(){ if(msg) msg.textContent='识别库加载失败（需联网），请用「手动输入」'; });
}
function showManualIsbn(){
  var html='<div class="scanwrap" style="display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;padding:28px 22px;text-align:center">'+
    '<div style="font-size:48px;line-height:1">⌨️</div>'+
    '<h3 style="margin:0;font-family:var(--serif);font-size:18px;color:var(--ink)">手动输入 ISBN</h3>'+
    '<p class="imgnote" style="max-width:320px;margin:0 auto;line-height:1.6">输入书背的 ISBN（13 位或 10 位），系统自动查书并填表。</p>'+
    '<div style="width:100%;max-width:300px;display:flex;flex-direction:column;gap:10px;margin-top:6px">'+
      '<input type="text" id="manualIsbn" class="search" placeholder="如 9787544253994" inputmode="numeric" autocomplete="off" style="text-align:center;font-size:16px;letter-spacing:1px">'+
      '<button type="button" class="btn primary" id="manualLookup">查书并填入</button>'+
      '<button type="button" class="btn ghost sm" id="manualCancel">取消</button>'+
    '</div></div>';
  rShowOverlay(html);
  var inp=document.getElementById('manualIsbn'), btn=document.getElementById('manualLookup'), cancel=document.getElementById('manualCancel');
  if(inp) setTimeout(function(){ inp.focus(); }, 80);
  function doManual(){
    if(!inp) return;
    var v=normIsbn(inp.value);
    if(!v){ toast('请输入正确的 ISBN（10 或 13 位数字）'); inp.focus(); return; }
    rCloseOverlay(); fillBookFromISBN(v);
  }
  if(btn) btn.onclick=doManual;
  if(inp) inp.addEventListener('keydown', function(e){ if(e.key==='Enter') doManual(); });
  if(cancel) cancel.onclick=rCloseOverlay;
}
function openBookScanner(){
  var hasCam = ('BarcodeDetector' in window) && navigator.mediaDevices && navigator.mediaDevices.getUserMedia;
  var html='<div class="scanwrap" style="flex-direction:column;gap:14px;padding:24px 22px;align-items:center">'+
    '<h3 style="margin:0;font-family:var(--serif);font-size:18px;color:var(--ink)">录入书籍</h3>'+
    '<p class="imgnote" style="max-width:340px;text-align:center">三种方式任选：实时扫码、拍条形码照片、或手输 ISBN。</p>';
  if(hasCam){
    html+='<video id="scanVid" playsinline autoplay muted style="width:100%;max-width:320px;border-radius:12px;background:#000"></video>'+
      '<div id="scanMsg" class="imgnote" style="margin:0">对准书背 ISBN 条码…</div>';
  } else {
    html+='<div style="font-size:44px;line-height:1">📷</div>'+
      '<div id="scanMsg" class="imgnote" style="margin:0;text-align:center">本浏览器不支持实时摄像头，请用「拍照 / 选图识别」</div>';
  }
  html+='<div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-top:4px">'+
    '<label class="btn ghost" for="scanFile">📷 拍照 / 选图识别<input id="scanFile" type="file" accept="image/*" capture="environment" hidden></label>'+
    '<button type="button" class="btn ghost" id="scanManual">✏️ 手动输入</button>'+
    '<button type="button" class="btn ghost sm" id="scanCancel">取消</button>'+
    '</div><div id="scanHidden" style="position:fixed;left:-9999px;top:0;width:2px;height:2px;overflow:hidden"></div></div>';
  rShowOverlay(html);
  var finp=document.getElementById('scanFile');
  if(finp) finp.onchange=function(e){ var f=e.target.files&&e.target.files[0]; if(f) decodeBookPhoto(f); };
  var mb=document.getElementById('scanManual'); if(mb) mb.onclick=showManualIsbn;
  var cancel=document.getElementById('scanCancel');
  if(hasCam){
    var vid=document.getElementById('scanVid'), msg=document.getElementById('scanMsg');
    var stream=null, raf=0, det=null, done=false;
    function stopAll(){ done=true; if(raf) cancelAnimationFrame(raf); if(stream) stream.getTracks().forEach(function(t){t.stop();}); }
    BarcodeDetector.getSupportedFormats().then(function(fmts){
      det=new BarcodeDetector({formats: fmts.filter(function(f){ return ['ean_13','ean_8','upc_a','qr_code','code_128'].indexOf(f)>=0; })});
    }).catch(function(){ try{ det=new BarcodeDetector(); }catch(e){ if(msg) msg.textContent='此浏览器无法初始化扫码器'; } });
    navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}}).then(function(s){
      stream=s; vid.srcObject=s; vid.play(); scanLoop();
    }).catch(function(e){ if(msg) msg.textContent='无法打开摄像头：'+(e&&e.message||e)+'（需 HTTPS 与相机权限）'; });
    function scanLoop(){
      if(done) return;
      if(vid.readyState>=2 && det){
        det.detect(vid).then(function(res){ if(res&&res.length) onDetectBook(res[0].rawValue, stopAll); }).catch(function(){});
      }
      raf=requestAnimationFrame(scanLoop);
    }
    if(cancel) cancel.onclick=function(){ stopAll(); rCloseOverlay(); };
  } else {
    if(cancel) cancel.onclick=rCloseOverlay;
  }
}

/* ============ v77：ISBN 输入框下方的「扫码 / 照片识别 / 书名搜索」模块 ============
   与旧的 openBookScanner（全屏浮层）不同：本模块嵌在表单里 ISBN 输入框正下方，
   摄像头画面直接显示在表单内，用户能亲眼看到正在扫，识别到的号码自动填进 ISBN 框。 */
var _isbnLiveScanner=null, _isbnLiveTools=null, _isbnLiveStop=null;
var ISBN_QRCODE_SRC='https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js';
/* v79：iOS Safari 不提供原生 BarcodeDetector，html5-qrcode 只能跑 ZXing 纯 JS，非常慢。
   这个 polyfill 用 WebAssembly 版 ZXing 实现了同一套 BarcodeDetector API，iOS 上同样可用，
   解码速度比纯 JS 快数倍。加载失败会静默降级回 html5-qrcode，不影响功能。 */
var ISBN_BD_POLYFILL='https://cdn.jsdelivr.net/npm/@sec-ant/barcode-detector@1/+esm';
/* 取到可用的 BarcodeDetector：优先系统原生（Android Chrome），否则加载 wasm polyfill（iOS） */
async function ensureBarcodeDetector(){
  if (typeof window.BarcodeDetector === 'function') return window.BarcodeDetector;
  try{
    var mod = await import(ISBN_BD_POLYFILL);
    /* 兼容不同打包形态：命名导出 / 默认导出 / 个别版本自动挂到 window */
    var BD = (mod && (mod.BarcodeDetector || (mod.default && (mod.default.BarcodeDetector || mod.default)))) || null;
    if (BD && typeof BD === 'function'){ window.BarcodeDetector = BD; return BD; }
    if (typeof window.BarcodeDetector === 'function') return window.BarcodeDetector;
  }catch(e){}
  return null;
}
/* 取与某个扫码模块配套的 ISBN 输入框（模块与 .isbn-wrap 是同一个字段容器里的兄弟） */
function isbnInputOfTools(tools){
  if (!tools) return null;
  var box = tools.parentElement;
  return box ? box.querySelector('[data-f="ISBN"]') : null;
}
function stopInlineIsbnScan(msg){
  var t=_isbnLiveTools;
  var sc=_isbnLiveScanner;          /* 先抓局部引用：stop() 是异步的，全局量马上就会被清掉 */
  _isbnLiveScanner=null;
  /* v79：快速通道（原生 / wasm 解码）用的是自己起的定时器 + 媒体流，单独收尾 */
  if (_isbnLiveStop){ try{ _isbnLiveStop(); }catch(e){} }
  _isbnLiveStop=null;
  if (sc){
    var clearIt=function(){ try{ sc.clear(); }catch(e){} };
    try{ sc.stop().then(clearIt).catch(clearIt); }
    catch(e){ clearIt(); }
  }
  if (t){
    var live=t.querySelector('.isbn-live'); if(live) live.hidden=true;
    var rd=t.querySelector('.isbn-reader'); if(rd) rd.innerHTML='';   /* 兜底：清掉残留的 video */
    var btn=t.querySelector('[data-act="isbnlivecam"]');
    if(btn){ btn.classList.remove('on'); btn.textContent='📷 扫码'; }
  }
  _isbnLiveTools=null;
  if (msg) toast(msg);
}
/* v79：快速通道 —— 用 BarcodeDecoder（系统原生 或 wasm polyfill）自己抽帧解码。
   比 html5-qrcode 内置的 ZXing 纯 JS 快得多，iOS 上尤其明显。
   返回 true = 已接管；false = 用不了，交给 html5-qrcode 兜底。 */
async function startFastIsbnScan(tools){
  var reader=tools.querySelector('.isbn-reader');
  var msgEl=tools.querySelector('.isbn-live-msg');
  if (!reader) return false;
  var BD = await ensureBarcodeDetector();
  if (!BD) return false;
  if (_isbnLiveTools!==tools) return true;              /* 加载期间已被取消 */
  var vid=document.createElement('video');
  vid.setAttribute('playsinline',''); vid.setAttribute('muted','');
  vid.muted=true; vid.autoplay=true;
  vid.style.cssText='width:100%;height:auto;display:block;background:#000';
  reader.innerHTML=''; reader.appendChild(vid);
  var stream=null;
  try{
    stream=await navigator.mediaDevices.getUserMedia({
      video:{ facingMode:'environment', width:{ideal:1280}, height:{ideal:720} }
    });
  }catch(e){ return false; }
  if (_isbnLiveTools!==tools){                          /* 取流期间被取消 */
    try{ stream.getTracks().forEach(function(t){ t.stop(); }); }catch(e){}
    return true;
  }
  vid.srcObject=stream;
  try{ await vid.play(); }catch(e){}
  var det=null;
  try{ det=new BD({ formats:['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code'] }); }
  catch(e){ try{ det=new BD(); }catch(e2){ det=null; } }
  if (!det){
    try{ stream.getTracks().forEach(function(t){ t.stop(); }); }catch(e){}
    return false;
  }
  if (msgEl) msgEl.textContent='对准书背的 ISBN 条码，保持手机稳定…（快速识别）';
  var cv=document.createElement('canvas');
  var ctx=cv.getContext('2d', { willReadFrequently:true });
  var stopped=false;
  var timer=setInterval(function(){
    if (stopped || !vid.videoWidth || vid.readyState<2) return;
    /* 只取画面中间那条横带送解码：ISBN 条码是横向的，像素少一半，解码更快 */
    var vw=vid.videoWidth, vh=vid.videoHeight;
    var sh=Math.max(60, Math.floor(vh*0.5)), sy=Math.floor((vh-sh)/2);
    cv.width=vw; cv.height=sh;
    ctx.drawImage(vid, 0, sy, vw, sh, 0, 0, vw, sh);
    det.detect(cv).then(function(res){
      if (stopped) return;
      if (res && res.length){
        stopped=true; clearInterval(timer);
        onInlineIsbnDetected(tools, res[0].rawValue);
      }
    }).catch(function(){});
  }, 110);
  _isbnLiveStop=function(){
    stopped=true; clearInterval(timer);
    try{ stream.getTracks().forEach(function(t){ t.stop(); }); }catch(e){}
  };
  return true;
}
/* 兜底通道：html5-qrcode（ZXing 纯 JS，慢，但兼容性最好） */
function startHtml5IsbnScan(tools){
  var msgEl=tools.querySelector('.isbn-live-msg');
  var btn=tools.querySelector('[data-act="isbnlivecam"]');
  loadScript(ISBN_QRCODE_SRC).then(function(){
    if (_isbnLiveTools!==tools) return;                 /* 加载期间已被取消 */
    var reader=tools.querySelector('.isbn-reader');
    if (!reader) return;
    if (typeof Html5Qrcode==='undefined'){ if(msgEl) msgEl.textContent='扫码库加载失败（需联网），请改用「照片识别」或书名搜索'; return; }
    if (!reader.id) reader.id='isbnReader_'+Date.now();
    if (reader.innerHTML) reader.innerHTML='';        /* 兜底：清掉上一次残留的 video */
    if (msgEl) msgEl.textContent='对准书背的 ISBN 条码，保持手机稳定，1–2 秒即可识别…';
    try{ _isbnLiveScanner=new Html5Qrcode(reader.id); }
    catch(e){ if(msgEl) msgEl.textContent='无法初始化扫码器：'+((e&&e.message)||e); return; }
    _isbnLiveScanner.start(
      /* 限制分辨率：画面像素越少，单帧解码越快（EAN-13 条码在 720p 下完全够用） */
      { facingMode:'environment', width:{ideal:1280}, height:{ideal:720} },
      {
        fps: 15,
        aspectRatio: 1.4,
        /* 关键提速：设备带原生 BarcodeDetector（Android Chrome 有）时交给它解码，
           比内置的 ZXing 纯 JS 解码快一个数量级；不支持的机型自动回落到 ZXing。 */
        experimentalFeatures: { useBarCodeDetectorIfSupported: true },
        /* 取景框按实际画面自适应，避免在小画面设备上因固定尺寸报错；
           框小一点 → 需要分析的像素少 → 识别更快 */
        qrbox: function(vw, vh){
          return {
            width:  Math.max(150, Math.min(300, Math.floor(vw*0.8))),
            height: Math.max(80,  Math.min(170, Math.floor(vh*0.45)))
          };
        }
      },
      function(text){ onInlineIsbnDetected(tools, text); },
      function(){ /* 每帧没识别到，忽略 */ }
    ).catch(function(e){
      if (msgEl) msgEl.textContent='无法打开摄像头：'+((e&&e.message)||e)+'（需 HTTPS 与相机权限）';
      if (btn){ btn.classList.remove('on'); btn.textContent='📷 扫码'; }
    });
  }).catch(function(){
    if (msgEl) msgEl.textContent='扫码库加载失败（需联网），请改用「照片识别」或书名搜索';
  });
}
/* v79：入口分发 —— 先尝试「快速通道」（系统原生 BarcodeDetector，或 iOS 上的 wasm polyfill），
   成功接管就走这条（速度最快）；若设备不支持 / 加载失败，自动回落到 html5-qrcode（慢但兼容性最好）。 */
function startInlineIsbnScan(tools){
  if (_isbnLiveScanner || _isbnLiveStop) stopInlineIsbnScan();   /* 先清掉上一次残留，避免叠摄像头 */
  _isbnLiveTools=tools;
  var live=tools.querySelector('.isbn-live');
  if (live) live.hidden=false;
  var msgEl=tools.querySelector('.isbn-live-msg');
  if (msgEl) msgEl.textContent='正在启动摄像头…';
  startFastIsbnScan(tools).then(function(used){
    if (_isbnLiveTools!==tools) return;        /* 期间已被取消 */
    if (used) return;                          /* 快速通道已接管（含自身收尾逻辑） */
    startHtml5IsbnScan(tools);                 /* 落到 html5-qrcode 兜底 */
  }).catch(function(){
    if (_isbnLiveTools===tools) startHtml5IsbnScan(tools);
  });
}
/* 识别到内容：归一化成 ISBN → 填进 ISBN 框 → 停止扫码 → 自动查书填表 */
function onInlineIsbnDetected(tools, raw){
  var msgEl=tools.querySelector('.isbn-live-msg');
  var isbn=normIsbn(raw);
  if(!isbn && /^https?:\/\//i.test(raw)){
    var m=raw.match(/isbn[=_]?(\d{13}|\d{10})/i) || raw.match(/(\d{13})/);
    if(m) isbn=normIsbn(m[1]);
  }
  if(!isbn){
    if(msgEl) msgEl.textContent='识别到「'+String(raw||'').slice(0,24)+'」，不是 ISBN，继续对准条码…';
    return;
  }
  var inp=isbnInputOfTools(tools);
  if (inp){
    inp.value=isbn;
    inp.dispatchEvent(new Event('input',{bubbles:true}));
    inp.dispatchEvent(new Event('change',{bubbles:true}));
  }
  if (msgEl) msgEl.textContent='✔ 识别到 ISBN：'+isbn+'（已填入上方输入框）';
  try{ if (navigator.vibrate) navigator.vibrate(60); }catch(e){}   /* 识别成功震一下，手机上有明确反馈 */
  stopInlineIsbnScan('识别到 ISBN '+isbn+'，已填入并正在查书');
  setTimeout(function(){ fillBookFromISBN(isbn); }, 260);
}
/* 照片识别：禁了实时摄像头的环境（如微信内置浏览器）用拍照 decode */
function decodeBookPhotoInline(tools, file){
  var live=tools.querySelector('.isbn-live');
  var msgEl=tools.querySelector('.isbn-live-msg');
  if (live) live.hidden=false;
  if (msgEl) msgEl.textContent='正在识别照片中的条码…';
  loadScript(ISBN_QRCODE_SRC).then(function(){
    if (!tools.isConnected) return;
    if (typeof Html5Qrcode==='undefined'){ if(msgEl) msgEl.textContent='识别库加载失败（需联网）'; return; }
    var holder=document.createElement('div');
    holder.id='isbnPhotoReader_'+Date.now();
    holder.style.cssText='position:fixed;left:-9999px;top:0;width:2px;height:2px;overflow:hidden';
    document.body.appendChild(holder);
    var sc=null;
    try{ sc=new Html5Qrcode(holder.id); }
    catch(e){ if(msgEl) msgEl.textContent='识别库初始化失败，请直接用书名搜索'; holder.remove(); return; }
    sc.scanFile(file, false).then(function(text){
      try{ sc.clear(); }catch(e){}
      holder.remove();
      onInlineIsbnDetected(tools, text);
    }).catch(function(){
      try{ sc.clear(); }catch(e){}
      holder.remove();
      if (msgEl) msgEl.textContent='没在照片里认出条码，换张清晰照片，或直接输书名搜';
    });
  }).catch(function(){
    if (msgEl) msgEl.textContent='识别库加载失败（需联网），请直接用书名搜索';
  });
}
/* ---------- v77：按书名搜索（ISBN 扫不到时的兜底）---------- */
function lookupBookByTitle(q, cb){
  var key='title:'+String(q||'').trim().toLowerCase();
  var cached=bookCacheGet(key);
  if (cached){ cb(cached); return; }            /* 同书名秒回 */
  var url='https://openlibrary.org/search.json?q='+encodeURIComponent(q)+
          '&fields=title,author_name,first_publish_year,publisher,isbn,cover_i&limit=15';
  var olList=[], jdList=[], yunList=[], sinoList=[], done2=0, finished=false;
  function finish(){
    if (finished) return;
    if (++done2<4) return;          /* Open Library、京东、芸台购、中国书网 四路并行，全部回才合并 */
    finished=true;
    /* 合并：Open Library 在前，京东、芸台购补充（去重，按书名） */
    var seen={}, list=[];
    olList.concat(jdList, yunList, sinoList).forEach(function(b){
      var nk=String(b['名称']||'').trim().toLowerCase();
      if (!nk || seen[nk]) return; seen[nk]=1; list.push(b);
    });
    list=list.slice(0,14);
    if (list.length) bookCacheSet(key, list);   /* 只缓存有结果者，避免把瞬时网络失败记 30 天 */
    cb(list);
  }
  _olJSON(url).then(function(d){
    var docs=(d && d.docs) || [];
    docs.forEach(function(doc){
      var t=String(doc.title||'').trim();
      if (!t) return;
      var isbn='';
      if (doc.isbn && doc.isbn.length){
        for (var i=0;i<doc.isbn.length;i++){ var n=normIsbn(doc.isbn[i]); if (n){ isbn=n; break; } }
      }
      olList.push({
        名称: t,
        作者: (doc.author_name||[]).slice(0,3).join(' / '),
        出版社: (doc.publisher && doc.publisher[0]) || '',
        出版年: doc.first_publish_year ? String(doc.first_publish_year) : '',
        ISBN: isbn,
        封面: doc.cover_i ? ('https://covers.openlibrary.org/b/id/'+doc.cover_i+'-L.jpg') : ''
      });
    });
    olList=olList.slice(0,12);
    finish();
  }).catch(function(){ finish(); });
  /* v81：京东补充（中文书封面最全）；代理不是 JS 渲染型时安静返回 [] */
  lookupJDByTitle(q, function(jl){ jdList=jl||[]; finish(); });
  /* v82：芸台购（中文高校/教材书最全）并行补充；中国书网搜索被站方屏蔽，基本只兜底 */
  lookupYunByTitle(q, function(yl){ yunList=yl||[]; finish(); });
  lookupSinoByTitle(q, function(sl){ sinoList=sl||[]; finish(); });
}
function doTitleSearch(tools){
  var qEl=tools.querySelector('.isbn-title-q');
  var resEl=tools.querySelector('.isbn-results');
  var btn=tools.querySelector('[data-act="isbnsearchtitle"]');
  var q=String((qEl && qEl.value)||'').trim();
  if (!q){ if (qEl) qEl.focus(); toast('先输入书名（或作者名）'); return; }
  if (resEl) resEl.innerHTML='<div class="imgnote">正在搜索「'+esc(q)+'」…</div>';
  if (btn){ btn.disabled=true; btn.textContent='搜…'; }
  lookupBookByTitle(q, function(list){
    if (btn){ btn.disabled=false; btn.textContent='搜书名'; }
    if (!resEl) return;
    if (!list.length){
      resEl.innerHTML='<div class="imgnote">没搜到「'+esc(q)+'」，换个关键词或试试作者名</div>';
      return;
    }
    var h='<div class="imgnote">搜到 '+list.length+' 条，点一条填入表单：</div><div class="bkres">';
    list.forEach(function(b,i){
      var meta=[b['作者'],b['出版社'],b['出版年']].filter(Boolean).join(' · ');
      h+='<button type="button" class="bkres-item" data-bk="'+i+'">'+
        (b['封面']
          ? '<span class="bkres-cov" style="background-image:url(\''+String(b['封面']).replace(/["'()\\]/g,'')+'\')"></span>'
          : '<span class="bkres-cov ph"></span>')+
        '<span class="bkres-txt"><b>'+esc(b['名称'])+'</b>'+
        (meta?'<i>'+esc(meta)+'</i>':'')+
        '</span></button>';
    });
    h+='</div>';
    resEl.innerHTML=h;
    Array.prototype.forEach.call(resEl.querySelectorAll('.bkres-item'), function(el){
      el.onclick=function(){
        var b=list[parseInt(el.getAttribute('data-bk'),10)||0];
        if (!b) return;
        var inp=isbnInputOfTools(tools);
        if (inp && b['ISBN']){
          inp.value=b['ISBN'];
          inp.dispatchEvent(new Event('input',{bubbles:true}));
          inp.dispatchEvent(new Event('change',{bubbles:true}));
        }
        fillBookInPlace(b);
        toast('已填入：'+b['名称']);
      };
    });
  });
}
/* 「照片识别」的文件选择：委托到 document，表单每次重绘都不用重新绑定 */
document.addEventListener('change', function(e){
  var t=e.target;
  if (!t || !t.classList || !t.classList.contains('isbn-photo-input')) return;
  var tools = t.closest('[data-isbn-tools]');
  var f = t.files && t.files[0];
  if (tools && f) decodeBookPhotoInline(tools, f);
  t.value='';
});

/* ---------- 藏品详情：点开看购入信息和存放位置 ----------
   v62：购入时间 / 价格 / 存放位置 / 购入渠道 单击原地编辑；
       卡片右上角 ‹ › 切换上一条 / 下一条，键盘 ← → 同样可切。 */
var DETAIL_CTX=null;                 /* 当前详情卡的导航上下文（当前列表里的顺序） */
function detailSiblings(key, id){
  var ids=[];
  try{
    document.querySelectorAll('[data-act="item"][data-key="'+key+'"]').forEach(function(n){
      var v=n.getAttribute('data-id');
      if (v && ids.indexOf(String(v))<0) ids.push(String(v));
    });
  }catch(e){}
  /* DOM 里找不到（或只有一条）就退回整张表的自然顺序 */
  if (ids.indexOf(String(id))<0 || ids.length<2){
    ids=(store[key].rows||[]).map(function(r){ return String(r._id); });
  }
  return ids;
}
function detailStep(dir){
  if (!DETAIL_CTX) return;
  var ids=DETAIL_CTX.ids, i=ids.indexOf(String(DETAIL_CTX.id));
  if (i<0) return;
  var j=i+dir;
  if (j<0 || j>=ids.length) return;
  openItemDetail(DETAIL_CTX.key, ids[j]);
}
/* 只改指定的几个字段，别走 updateRow —— 那条路会把没传的字段清空 */
function patchRowFields(key, id, patch){
  var row=(store[key].rows||[]).filter(function(r){ return String(r._id)===String(id); })[0];
  if (!row) return false;
  Object.keys(patch).forEach(function(k){
    var v=patch[k];
    row[k] = (v===''||v==null) ? null : v;
  });
  if (MODE==='gh'){ queueGhSave(); localCacheSet(); }
  else if (MODE==='localfile'){ queueLocalSave(); }
  else if (MODE==='local'){ lsSet(key, store[key].rows); localCacheSet(); }
  return true;
}
function openItemDetail(key, id){
  var row=store[key].rows.filter(function(r){ return String(r._id)===String(id); })[0];
  if (!row) return;
  if (!DETAIL_CTX || DETAIL_CTX.key!==key || DETAIL_CTX.ids.indexOf(String(id))<0){
    DETAIL_CTX={ key:key, ids:detailSiblings(key, id), id:String(id) };
  } else { DETAIL_CTX.id=String(id); }
  var ids=DETAIL_CTX.ids, pos=ids.indexOf(String(id))+1;
  var title=row['名称']||'未命名';
  var cat=row['大类']||'', sub=row['小类']||'', ipName=row['IP']||'';
  var loc=row['存储地点']||'', ch=row['购入渠道']||'';
  var price=num(row['购入价格']), date=dstr(row['购入日期']);
  function ed(field, shown){
    return '<b class="ed" data-edin="'+field+'" title="单击编辑">'+shown+'<span class="edhint">✎</span></b>';
  }
  var host=$('sheetHost');
  var h='<div class="sheet"><div class="sheet-head"><div>'+
    '<p>'+esc(MODS[key].eyebrow)+'</p><h2>'+esc(title)+'</h2></div>'+
    '<div style="display:flex;align-items:center;gap:8px;flex:0 0 auto">'+
      '<div class="sheet-nav">'+
        '<button type="button" data-dnav="-1" title="上一条（←）"'+(pos<=1?' disabled':'')+'>‹</button>'+
        '<span class="dpos">'+pos+' / '+ids.length+'</span>'+
        '<button type="button" data-dnav="1" title="下一条（→）"'+(pos>=ids.length?' disabled':'')+'>›</button>'+
      '</div>'+
      '<button class="x" type="button" data-x="1">×</button>'+
    '</div></div>'+
    '<div class="dtop">'+
      '<div class="ph" style="'+coverStyle(row,title)+'">'+(hasCover(row)?'':'<b>'+esc(String(title).slice(0,1))+'</b>')+'</div>'+
      '<div><h3>'+esc(title)+'</h3><div class="meta">'+statusPill(row['状态'])+
        '<span class="pill s0">'+esc(cat)+(sub?' · '+esc(sub):'')+'</span>'+
        (num(row['星级'])?'<span class="stars">'+stars(row['星级'])+'</span>':'')+
        (ipName?'<span class="pill s2" data-gotoip="'+esc(ipName)+'" style="cursor:pointer">IP · '+esc(ipName)+'</span>':'')+
      '</div></div></div>'+
    '<div class="buybox"><h4>购入信息</h4><div class="buygrid">'+
      '<div><u>购入时间</u>'+ed('购入日期', date?esc(date):'<span style="color:#a89c8d;font-weight:500;font-size:13px">还没记</span>')+'</div>'+
      '<div><u>价格</u>'+ed('购入价格', price?esc('¥'+price.toFixed(2)):'<span style="color:#a89c8d;font-weight:500;font-size:13px">还没记</span>')+'</div>'+
      '<div><u>存放位置</u>'+ed('存储地点', loc?esc(loc):'<span style="color:#a89c8d;font-weight:500;font-size:13px">还没指定</span>')+'</div>'+
      '<div><u>购入渠道</u>'+ed('购入渠道', ch?esc(ch):'<span style="color:#a89c8d;font-weight:500;font-size:13px">还没记</span>')+'</div>'+
      '<div><u>持有</u>'+ed('持有', function(){ var h=effHold(row); return h!=null?esc(h):'<span style="color:#a89c8d;font-weight:500;font-size:13px">还没记</span>'; }())+'</div>'+
    '</div></div>'+
    (row['短评']?'<p class="dnote">'+esc(row['短评'])+'</p>':'')+
    '<div class="sheet-actions">'+
      '<button class="btn ghost" type="button" id="dDel" style="margin-right:auto;color:var(--red)">删除</button>'+
      '<button class="btn ghost" type="button" data-x="1">关闭</button>'+
      '<button class="btn primary" type="button" id="dEdit">编辑</button>'+
    '</div></div>';
  host.innerHTML=h; host.hidden=false;
  host.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=closeSheet; });
  host.querySelectorAll('[data-dnav]').forEach(function(n){
    n.onclick=function(){ if(!n.disabled) detailStep(parseInt(n.getAttribute('data-dnav'),10)); };
  });
  host.querySelectorAll('[data-edin]').forEach(function(n){
    n.onclick=function(e){ e.stopPropagation(); beginInlineEdit(key, id, n.getAttribute('data-edin'), n); };
  });
  bindSheetBackdrop(host);
  $('dEdit').onclick=function(){ closeSheet(); openForm(key, id); };
  $('dDel').onclick=function(){
    closeSheet();
    askConfirm('删除「'+title+'」？删掉就找不回来了。', function(){ deleteRow(key, id, title); });
  };
  var gip=host.querySelector('[data-gotoip]');
  if (gip) gip.onclick=function(){
    var nm=gip.getAttribute('data-gotoip');
    var target=store.ip.rows.filter(function(r){ return r['IP名称']===nm; })[0];
    if (!target) return;
    closeSheet();
    ui.view='collection'; ui.collection.mode='ip'; ui.collection.ipId=target._id;
    render();
  };
}
/* v62：购入信息四项的原地编辑 —— 点一下变成输入框，回车/失焦保存，Esc 取消 */
function beginInlineEdit(key, id, field, bEl){
  if (!bEl || bEl.querySelector('input,select')) return;
  var row=(store[key].rows||[]).filter(function(r){ return String(r._id)===String(id); })[0];
  if (!row) return;
  var orig=String(row[field]==null?'':row[field]);
  /* 持有：在库藏品没填过时，点击编辑默认带出 1 */
  if (field==='持有' && (row['持有']==null||row['持有']==='') && hasStatus(row,'在库')) orig='1';
  var ed;
  if (field==='存储地点'){
    ed=document.createElement('select'); ed.className='edsel';
    var locs=(store.loc && store.loc.rows || []);
    var has=locs.some(function(r){ return (r['地点名称']||'')===orig; });
    ed.innerHTML='<option value="">（暂不指定）</option>'+
      locs.map(function(r){ var n=r['地点名称']||'';
        return '<option value="'+esc(n)+'"'+(n===orig?' selected':'')+'>'+esc(n)+'</option>'; }).join('')+
      (orig && !has ? '<option value="'+esc(orig)+'" selected>'+esc(orig)+'</option>' : '');
  } else {
    ed=document.createElement('input'); ed.className='edin';
    ed.type = field==='购入价格' ? 'number' : 'text';
    if (field==='购入价格') ed.setAttribute('step','0.01');
    ed.value = field==='购入价格' ? String(num(row['购入价格'])||'') : orig;
    ed.placeholder = field==='购入日期' ? '2026 或 2026-03-05'
                   : field==='购入价格' ? '0.00'
                   : '淘宝 / 线下店 / 朋友送';
  }
  bEl.innerHTML=''; bEl.appendChild(ed);
  bEl.classList.remove('ed');
  setTimeout(function(){ try{ ed.focus(); if (ed.select) ed.select(); }catch(e){} }, 0);
  var done=false;
  function finish(save){
    if (done) return; done=true;
    var v=String(ed.value==null?'':ed.value).trim();
    if (!save){ openItemDetail(key,id); return; }
    if (field==='购入日期' && v && !/^\d{4}(-\d{1,2}(-\d{1,2})?)?$/.test(v)){
      toast('日期填 2026 或 2026-03-05 这种格式');
      openItemDetail(key,id); return;
    }
    var patch={}; patch[field] = field==='购入价格' ? (v===''?null:num(v)) : v;
    if (MODE==='db'){
      var vals={};
      activeFields(key, row).forEach(function(f){ vals[f.k]=fieldVal(row,f); });
      Object.keys(patch).forEach(function(k){ vals[k]=patch[k]; });
      updateRow(key, id, vals, function(){ openItemDetail(key,id); });
    } else {
      patchRowFields(key, id, patch);
      render();                      /* 背后的列表同步刷新 */
      openItemDetail(key, id);       /* 重画详情卡 */
      toast('已保存');
    }
  }
  ed.addEventListener('keydown', function(e){
    e.stopPropagation();             /* 输入时别触发 ← → 切换 */
    if (e.key==='Enter'){ e.preventDefault(); finish(true); }
    else if (e.key==='Escape'){ e.preventDefault(); finish(false); }
  });
  ed.addEventListener('blur', function(){ finish(true); });
  ed.addEventListener('click', function(e){ e.stopPropagation(); });
}
/* 详情卡开着时，← → 直接切上一条 / 下一条 */
document.addEventListener('keydown', function(e){
  var host=document.getElementById('sheetHost');
  if (!host || host.hidden || !DETAIL_CTX) return;
  var t=e.target;
  if (t && (t.tagName==='INPUT' || t.tagName==='TEXTAREA' || t.tagName==='SELECT' || t.isContentEditable)) return;
  if (e.key==='ArrowLeft'){ e.preventDefault(); detailStep(-1); }
  else if (e.key==='ArrowRight'){ e.preventDefault(); detailStep(1); }
});

/* ---------- v78：批量编辑（藏品馆） ----------
   选择模式：卡片浮出勾选徽章，点卡片切换选中；底部操作条支持「全选当前筛选结果 / 清空 / 批量编辑」。
   批量面板：逐字段勾选 + 填值，仅勾选字段写入选中项（一次把价格、持有等多个字段写一批）。 */
function selectedIds(){ return Object.keys(ui.collection.sel); }
function toggleSel(id){
  id=String(id);
  if (ui.collection.sel[id]) delete ui.collection.sel[id];
  else ui.collection.sel[id]=true;
  render();
}
/* 选择模式下：给每张藏品卡加勾选徽章，并渲染底部操作条 */
function renderBatchSel(){
  var stage=$('stage'); if (!stage) return;
  var cards=stage.querySelectorAll('[data-act="item"][data-key="collection"]');
  cards.forEach(function(n){
    var id=String(n.getAttribute('data-id'));
    var b=n.querySelector('.selbadge');
    if (!b){ b=document.createElement('span'); b.className='selbadge'; n.appendChild(b); }
    if (ui.collection.sel[id]){ n.classList.add('selon'); b.classList.add('on'); }
    else { n.classList.remove('selon'); b.classList.remove('on'); }
  });
  var bar=document.getElementById('batchBar');
  if (!bar){ bar=document.createElement('div'); bar.id='batchBar'; stage.appendChild(bar); }
  var ids=selectedIds(), total=cards.length;
  bar.innerHTML=
    '<span class="bbcnt">已选 <b>'+ids.length+'</b> 件</span>'+
    '<button class="btn ghost sm" type="button" data-act="batchselall">全选当前结果 ('+total+')</button>'+
    '<button class="btn ghost sm" type="button" data-act="batchclear"'+(ids.length?'':' disabled')+'>清空</button>'+
    '<button class="btn primary" type="button" data-act="batchedit"'+(ids.length?'':' disabled')+'>批量编辑 ('+ids.length+')</button>';
}
/* 单行字段（勾选 + 输入） */
function batchRow(k, type, ph){
  return '<div class="batchrow"><label class="bchk"><input type="checkbox" data-bf="'+k+'"> '+k+'</label>'+
    '<div class="bin"><input type="'+(type==='number'?'number':'text')+'" data-bv="'+k+'" placeholder="'+ph+'"></div></div>';
}
/* 打开批量编辑面板 */
function openBatchEdit(){
  var ids=selectedIds(), host=$('sheetHost');
  var stOpts=STATES_OWN.map(function(s){ return '<label class="stchk"><input type="checkbox" data-bf-status="'+esc(s)+'"> '+esc(s)+'</label>'; }).join('');
  host.innerHTML='<div class="sheet"><div class="sheet-head"><div><p>批量编辑</p><h2>写入 '+ids.length+' 件藏品</h2></div>'+
    '<button class="x" type="button" data-x="1" aria-label="关闭">×</button></div>'+
    '<div class="batchnote">只写入勾选的字段，未勾选的保持原样；价格与持有留空则不写。</div>'+
    '<div class="batchfields">'+
      batchRow('购入价格','number','如 129.00')+
      batchRow('持有','number','如 1')+
      '<div class="batchrow states"><label class="bchk"><input type="checkbox" data-bf="状态"> 状态</label><div class="stchecks">'+stOpts+'</div></div>'+
      batchRow('购入渠道','text','淘宝 / 线下店 / 朋友送')+
      batchRow('存储地点','text','房间 · 柜墙 · 层')+
      batchRow('购入日期','text','2026 或 2026-03-05')+
    '</div>'+
    '<div class="sheet-actions">'+
      '<button class="btn ghost" type="button" data-x="1">取消</button>'+
      '<button class="btn primary" type="button" id="batchApply">应用写入 '+ids.length+' 件</button>'+
    '</div></div>';
  host.hidden=false;
  host.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=closeSheet; });
  bindSheetBackdrop(host);
  $('batchApply').onclick=applyBatchEdit;
}
/* 应用：把勾选字段合并写入每一个选中项 */
function applyBatchEdit(){
  var ids=selectedIds(); if (!ids.length) return;
  var sheet=$('sheetHost');
  function checked(k){ var c=sheet.querySelector('input[data-bf="'+k+'"]'); return !!(c&&c.checked); }
  function raw(k){ var el=sheet.querySelector('[data-bv="'+k+'"]'); return el?el.value.trim():''; }
  var patch={};
  ['购入价格','持有','购入渠道','存储地点','购入日期'].forEach(function(k){
    if (checked(k)){
      var v=raw(k);
      if (v==='') return;
      if ((k==='购入价格'||k==='持有') && !/^-?\d+(\.\d+)?$/.test(v)){ toast(k+' 请填数字'); return; }
      patch[k]=(k==='购入价格'||k==='持有')?num(v):v;
    }
  });
  if (checked('状态')){
    var st=[]; sheet.querySelectorAll('input[data-bf-status]').forEach(function(c){ if(c.checked) st.push(c.getAttribute('data-bf-status')); });
    if (st.length) patch['状态']=st;
  }
  if (!Object.keys(patch).length){ toast('没有勾选任何字段，或勾选的字段都留空了'); return; }
  applyBatchPatch(ids, patch);
  ui.collection.selMode=false; ui.collection.sel={};
  closeSheet(); render();
  toast('已写入 '+ids.length+' 件');
}
/* 逐条写入（兼容 db / 本地 / 文件 / gh 模式） */
function applyBatchPatch(ids, patch){
  var key='collection';
  if (MODE==='db'){
    ids.forEach(function(id){
      var row=(store[key].rows||[]).filter(function(r){ return String(r._id)===String(id); })[0];
      if (!row) return;
      var vals={};
      activeFields(key, row).forEach(function(f){ vals[f.k]=fieldVal(row,f); });
      Object.keys(patch).forEach(function(k){ vals[k]=patch[k]; });
      updateRow(key, id, vals, function(){});
    });
    return;
  }
  /* 本地 / 文件 / gh：一次性改完所有行再统一落盘（避免每行全量重写） */
  var set={}; ids.forEach(function(id){ set[String(id)]=true; });
  (store[key].rows||[]).forEach(function(r){
    if (set[String(r._id)]){ Object.keys(patch).forEach(function(k){ r[k] = (patch[k]==null)?null:patch[k]; }); }
  });
  if (MODE==='gh'){ queueGhSave(); localCacheSet(); }
  else if (MODE==='localfile'){ queueLocalSave(); }
  else if (MODE==='local'){ lsSet(key, store[key].rows); localCacheSet(); }
}

/* ---------- 存储地点管理 ---------- */
function openLocManager(){
  var host=$('sheetHost');
  host.innerHTML='<div class="sheet"><div class="sheet-head"><div>'+
    '<p>存储地点</p><h2>东西都放在哪儿</h2></div>'+
    '<button class="x" type="button" data-x="1">×</button></div>'+
    '<div id="locList"></div>'+
    '<div class="sheet-actions"><button class="btn ghost" type="button" data-x="1">关闭</button>'+
    /* v75fix：三段字段（房间 / 柜体墙面 / 所在层）的选项管理入口 */
    '<button class="btn ghost" type="button" id="locFieldMgmt">字段管理</button>'+
    '<button class="btn primary" type="button" id="locAdd">新增地点</button></div></div>';
  host.hidden=false;
  host.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=closeSheet; });
  bindSheetBackdrop(host);
  function draw(){
    var list=$('locList'); if (!list) return;
    var rows=store.loc.rows;
    if (store.loc.status==='error'){
      list.innerHTML='<div class="empty"><b>地点没读到</b><span>关掉这个窗口，点页面上的「重试」。</span></div>'; return;
    }
    if (!rows.length){
      list.innerHTML='<div class="empty"><b>还没有地点</b><span>先加一个，比如「书房玻璃柜」。</span></div>'; return;
    }
    list.innerHTML=rows.map(function(r){
      var n=locDisplayName(r);          /* v75fix：三段合成显示名 */
      var cnt=store.collection.rows.filter(function(x){ return x['存储地点']===n; }).length;
      return '<div class="locrow"><div><b>'+esc(n)+'</b>'+
        (r['说明']?'<span> · '+esc(r['说明'])+'</span>':'')+
        '<span> · 存了 '+cnt+' 件</span></div>'+
        '<div class="ops">'+
          '<button class="btn link" type="button" data-loce="'+esc(r._id)+'">编辑</button>'+
          '<button class="btn link" type="button" data-locd="'+esc(r._id)+'" style="color:var(--red)">删除</button>'+
        '</div></div>';
    }).join('');
    list.querySelectorAll('[data-loce]').forEach(function(b){
      b.onclick=function(){ openForm('loc', b.getAttribute('data-loce'), {after: openLocManager}); };
    });
    list.querySelectorAll('[data-locd]').forEach(function(b){
      b.onclick=function(){
        var lid=b.getAttribute('data-locd');
        var n=locDisplayName(store.loc.rows.filter(function(x){ return String(x._id)===String(lid); })[0]||{});
        var used=store.collection.rows.filter(function(x){ return x['存储地点']===n; }).length;
        closeSheet();
        askConfirm('删除地点「'+n+'」？'+(used?'还有 '+used+' 件东西记在这儿，它们会变成「未指定」。':'')+' 删掉就找不回来了。', function(){
          deleteRow('loc', lid, n);
        });
      };
    });
  }
  draw();
  $('locAdd').onclick=function(){ openForm('loc', null, {after: openLocManager}); };
  var fm=$('locFieldMgmt'); if (fm) fm.onclick=openLocFieldMgmt;
}
/* v75fix：存储地点「字段管理」——维护 房间 / 柜体墙面 / 所在层 三个维度的可选值
   （只有「房间」必填，另外两个选填；这里增删的只是下拉候选，已录入的地点不受影响） */
function openLocFieldMgmt(){
  var host=$('sheetHost');
  function labelOf(d){ return d==='柜体墙面' ? '柜体/墙面' : d; }
  function draw(){
    var h='<div class="sheet"><div class="sheet-head"><div>'+
      '<p>存储地点</p><h2>字段管理</h2></div>'+
      '<button class="x" type="button" data-x="1">×</button></div>'+
      '<div class="pm-section" style="padding:0 0 6px">'+
      '<div class="hint" style="font-size:11.5px;color:var(--muted);margin-bottom:10px">'+
        '录入地点时按「房间 → 柜体/墙面 → 所在层」三段选（只有房间必填）。这里维护每段的候选值。'+
      '</div>';
    LOC_DIMS.forEach(function(d){
      var opts = LOC_OPTS[d] || [];
      h += '<div class="pm-cat-row" style="border-bottom:none;padding:2px 0">'+
             '<span class="pm-cat-name">'+esc(labelOf(d))+'</span>'+
             '<button class="btn ghost xs" type="button" data-locadd="'+esc(d)+'">＋ 新增</button>'+
           '</div>'+
           '<div class="pm-cat-subs" style="margin:2px 0 12px">'+
           (opts.length
             ? opts.map(function(o){
                 return '<span class="pm-sub-chip">'+esc(o)+
                   '<button type="button" class="pm-sub-rename" data-locdel="'+esc(d)+'" data-v="'+esc(o)+'" title="删除">✕</button></span>';
               }).join('')
             : '<span style="font-size:11.5px;color:var(--muted)">还没有选项</span>')+
           '</div>';
    });
    h += '</div><div class="sheet-actions">'+
         '<button class="btn ghost" type="button" id="locFmBack">返回</button></div></div>';
    host.innerHTML=h; host.hidden=false;
    host.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=openLocManager; });
    var back=$('locFmBack'); if (back) back.onclick=openLocManager;
    host.querySelectorAll('[data-locadd]').forEach(function(b){
      b.onclick=function(){
        var d=b.getAttribute('data-locadd');
        promptDialog('新增'+labelOf(d), labelOf(d)+'名称', '', '创建', function(name){
          if (!name) return '名称不能为空';
          if ((LOC_OPTS[d]||[]).indexOf(name)>=0) return '已存在该'+labelOf(d);
          addLocOpt(d, name);
          toast('已新增'+labelOf(d)+'「'+name+'」');
          draw(); return null;
        });
      };
    });
    host.querySelectorAll('[data-locdel]').forEach(function(b){
      b.onclick=function(){
        var d=b.getAttribute('data-locdel'), v=b.getAttribute('data-v');
        askConfirm('删除'+labelOf(d)+'「'+v+'」？已录入的地点不受影响。', function(){
          delLocOpt(d, v); toast('已删除'); draw();
        });
      };
    });
  }
  draw();
}

function askConfirm(msg, onYes, opts){
  opts = opts || {};
  var yesLabel = opts.yesLabel || '删除';
  var yesColor = opts.yesColor || 'var(--red)';
  var title = opts.title || '要继续吗';
  /* v58：改为独立覆盖层，不再复用 sheetHost。
     之前与表单共用容器：addRow 弹确认窗后，saveBtn 的 doSave 紧接着 closeSheet()，
     会把刚弹出的确认窗一并关掉——这正是「音乐/书籍录入点什么都没发生」的根因。 */
  var ov=document.createElement('div');
  ov.className='backdrop'; ov.style.zIndex=300;
  ov.innerHTML='<div class="sheet"><div class="sheet-head"><div><p>确认</p><h2>'+esc(title)+'</h2></div>'+
    '<button class="x" type="button" data-x="1">×</button></div>'+
    '<p style="font-size:13.5px;line-height:1.8;color:var(--muted);white-space:pre-line">'+esc(msg)+'</p>'+
    '<div class="sheet-actions"><button class="btn ghost" type="button" data-x="1">再想想</button>'+
    '<button class="btn primary" type="button" id="yesBtn" style="background:'+yesColor+'">'+esc(yesLabel)+'</button></div></div>';
  document.body.appendChild(ov);
  function done(){ if (ov && ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=done; });
  ov.onclick=function(e){ if(e.target===ov) done(); };
  var yb=ov.querySelector('#yesBtn');
  if (yb) yb.onclick=function(){ done(); onYes(); };
}

/* v67：带一个输入框的小对话框（新建小分类、重命名图片都用它）。
   onOk(v) 返回字符串 = 校验没通过，把原因显示在框里、不关闭；返回空 = 通过并关闭。 */
function promptDialog(title, label, defVal, okLabel, onOk){
  var ov=document.createElement('div');
  ov.className='backdrop'; ov.style.zIndex=300;
  ov.innerHTML='<div class="sheet"><div class="sheet-head"><div><p>输入</p><h2>'+esc(title)+'</h2></div>'+
    '<button class="x" type="button" data-x="1">×</button></div>'+
    '<label style="display:block;margin:6px 0 6px;font-size:12px;color:var(--muted)">'+esc(label)+'</label>'+
    '<input id="__pd_inp" type="text" value="'+esc(defVal||'')+'" autocomplete="off" '+
      'style="width:100%;box-sizing:border-box;min-height:38px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:#fff;font-size:14px">'+
    '<div id="__pd_err" style="color:var(--red);font-size:12px;min-height:18px;margin-top:6px"></div>'+
    '<div class="sheet-actions"><button class="btn ghost" type="button" data-x="1">取消</button>'+
    '<button class="btn primary" type="button" id="__pd_ok">'+esc(okLabel||'确定')+'</button></div></div>';
  document.body.appendChild(ov);
  function done(){ if (ov && ov.parentNode) ov.parentNode.removeChild(ov); }
  ov.querySelectorAll('[data-x]').forEach(function(n){ n.onclick=done; });
  ov.onclick=function(e){ if(e.target===ov) done(); };
  var inp=ov.querySelector('#__pd_inp'), err=ov.querySelector('#__pd_err');
  if (inp) setTimeout(function(){ try{ inp.focus(); inp.select(); }catch(e){} }, 30);
  function submit(){
    var v = String((inp && inp.value) || '').trim();
    var msg = onOk ? onOk(v) : null;
    if (msg){ if (err) err.textContent = msg; return; }
    done();
  }
  var okb=ov.querySelector('#__pd_ok');
  if (okb) okb.onclick=submit;
  if (inp) inp.addEventListener('keydown', function(e){ if (e.key==='Enter'){ e.preventDefault(); submit(); } });
}

