/* === 3D 地球仪 v5（电影级高清电影地形 + 国家边界 + 名称标签 + 旅行地标签） ===
   源码来源参考 zjz1160616058.github.io 的开源地球项目，结合 NASA HD 贴图与 three.js r149 自建。
   本段必须插入主 IIFE 内（共享 openForm / EARTH_DATAURL / store / ui 作用域）。
   不要被外层 IIFE 包裹，也不要单独 <script>，否则 scope 断裂。
*/
var GLOBE_ENGINE = 'three.js r149 + NASA HD + 自然地球 110m 国家边界';
function ensureEarth(){}
function clampZoom(z){ if (z<0.6) return 0.6; if (z>2.4) return 2.4; return z; } /* 上限使相机停在球体外侧(距离≈1.25>地形1.03)，避免放大时钻进球内看到蓝色背景 */
function pinchDistG(g){ var k=Object.keys(g.pointers); if(k.length<2) return 0; var a=g.pointers[k[0]], b=g.pointers[k[1]]; return Math.hypot(a.x-b.x, a.y-b.y); }

/* 经纬度 → 本地坐标（与 three.js SphereGeometry 默认 UV 对齐） */
function latLonVec3(lat, lon, r){
  var latR=lat*Math.PI/180, lonR=(lon+180)*Math.PI/180;
  var cl=Math.cos(latR), sl=Math.sin(latR);
  return new THREE.Vector3(-r*Math.cos(lonR)*cl, r*sl, r*Math.sin(lonR)*cl);
}

/* === 文字纹理工厂（缓存） === */
var _lblTexCache = {};
function _labelTex(text, opts){
  opts = opts || {};
  var key = text + '|' + (opts.color||'#fff') + '|' + (opts.size||128) + '|' + (opts.outline||'#000') + '|' + (opts.bg||'');
  if (_lblTexCache[key]) return _lblTexCache[key];
  var size = opts.size || 128;
  var pad = 16;
  var c = document.createElement('canvas');
  /* 自动测量文字宽度 */
  var measure = document.createElement('canvas').getContext('2d');
  var fs = Math.round(size * 0.55);
  measure.font = 'bold ' + fs + 'px "PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif';
  var w0 = measure.measureText(text).width;
  c.width = Math.max(64, Math.ceil(w0 + pad * 2));
  c.height = Math.round(size + pad * 2);
  var x = c.getContext('2d');
  x.font = 'bold ' + fs + 'px "PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif';
  x.textBaseline = 'middle';
  x.textAlign = 'center';
  /* 气泡背景（深色圆角） */
  if (opts.bg){
    var rx = c.width/2, ry = c.height/2;
    var rw = w0 + pad * 1.4, rh = size * 0.72;
    var rr = Math.min(rh/2, size*0.18);
    x.fillStyle = opts.bg;
    x.beginPath();
    if (x.roundRect) {
      x.roundRect(rx - rw/2, ry - rh/2, rw, rh, rr);
    } else {
      x.moveTo(rx - rw/2 + rr, ry - rh/2);
      x.lineTo(rx + rw/2 - rr, ry - rh/2);
      x.quadraticCurveTo(rx + rw/2, ry - rh/2, rx + rw/2, ry - rh/2 + rr);
      x.lineTo(rx + rw/2, ry + rh/2 - rr);
      x.quadraticCurveTo(rx + rw/2, ry + rh/2, rx + rw/2 - rr, ry + rh/2);
      x.lineTo(rx - rw/2 + rr, ry + rh/2);
      x.quadraticCurveTo(rx - rw/2, ry + rh/2, rx - rw/2, ry + rh/2 - rr);
      x.lineTo(rx - rw/2, ry - rh/2 + rr);
      x.quadraticCurveTo(rx - rw/2, ry - rh/2, rx - rw/2 + rr, ry - rh/2);
      x.closePath();
    }
    x.fill();
  }
  /* 描边 */
  if (opts.outline){
    x.lineWidth = Math.max(2, fs * 0.12);
    x.strokeStyle = opts.outline;
    x.lineJoin = 'round';
    x.strokeText(text, c.width/2, c.height/2);
  }
  x.fillStyle = opts.color || '#fff';
  x.fillText(text, c.width/2, c.height/2);
  var t = new THREE.CanvasTexture(c);
  t.minFilter = THREE.LinearFilter;
  t.magFilter = THREE.LinearFilter;
  t.needsUpdate = true;
  _lblTexCache[key] = t;
  return t;
}

/* === 国家多边形（球面弧线）渲染 === */
function buildCountryBorders(g, group){
  if (!g || !group || !__WORLD_COUNTRIES) return;
  var T = window.THREE;
  var mat = new T.LineBasicMaterial({color:0x99c5ff, transparent:true, opacity:0.32});
  var lineMat = new T.LineBasicMaterial({color:0xc6dcff, transparent:true, opacity:0.45});
  var countries = __WORLD_COUNTRIES;
  for (var i=0; i<countries.length; i++){
    var c = countries[i];
    var rings = c.r || [];
    for (var r=0; r<rings.length; r++){
      var flat = rings[r];
      var pts = [];
      for (var k=0; k<flat.length; k+=2){
        var lat = flat[k], lon = flat[k+1];
        if (lat===null || lon===null) { pts.push(new T.Vector3()); continue; }
        var v = latLonVec3(lat, lon, 1.035);
        pts.push(v);
      }
      /* 闭合 polygon */
      if (pts.length>1) pts.push(pts[0]);
      if (pts.length < 4) continue;  /* 跳过过小环 */
      var geo = new T.BufferGeometry().setFromPoints(pts);
      try {
        var line = new T.Line(geo, lineMat);
        line.userData = {country: c.n, ringIdx: r, kind:'border'};
        group.add(line);
      } catch(_){}
    }
  }
}

