    spr.center.set((size.tipX != null ? size.tipX : 0.5), 1.0);
    var bh = isVisited ? 0.010 : 0.012;     /* 草苗 0.012 = 红旗 0.010 × 1.2 */
    var ratio = (size.h > 0) ? (size.w / size.h) : 1;
