        if (g._lpTarget === hit && !g._dragging){
          g._dragging = true;
          g._dragTarget = hit;
          liftSprite(hit, 0.025);   /* 跳起来：ro0ff 上浮 0.025 */
          toast('已抓起 · 拖到新位置后松开');
        }
