/* v59：拾纪（本地记事本）——左标题列表，右电子纸 */
function renderNotes(){
  var notes = store.notes.rows || [];
  var activeId = ui.notes.id;
  var active = notes.filter(function(r){ return String(r._id)===String(activeId); })[0] || null;
  var listHtml = notes.length ? notes.map(function(r){
    var on = String(r._id)===String(activeId);
    return '<div class="note-item'+(on?' on':'')+'" data-act="noteselect" data-id="'+esc(r._id)+'">'+
           '<span class="note-title">'+esc(r['标题']||'未命名')+'</span>'+
           '<span class="note-date">'+esc(dstr(r['更新日期'])||'')+'</span>'+
           '</div>';
  }).join('') : '<div class="note-empty-list">还没有拾纪<br>点右上角「新建拾纪」开始</div>';
  
  var paperHtml = '';
  if (active){
    paperHtml = '<div class="note-paper note-font-'+esc(ui.notes.fontSize)+(ui.notes.edit?' edit':'')+'" '+
                'id="notePaper" data-act="notepaper" data-id="'+esc(active._id)+'">'+
                (active['内容'] || '<div><br></div>')+
                '</div>';
  } else {
    paperHtml = '<div class="note-paper note-empty">'+
                '<div class="note-empty-art">📝</div>'+
                '<p>在左侧选择一条拾纪，或新建一条开始记录</p>'+
                '</div>';
  }

  // 工具栏放在右侧区域的上方（v60：左侧显示当前拾纪名字，点一下可原地改名）
  var nameHtml = active
    ? '<span class="notes-title" id="noteTitleBox" data-act="noterename" title="点击改名">'+esc(active['标题']||'未命名')+'</span>'
    : '<span class="notes-title muted" id="noteTitleBox">未选择拾纪</span>';
  var toolbarHtml = '<div class="notes-toolbar">'+
    nameHtml+
    '<span class="notes-tb-gap"></span>'+
    '<button class="r-btn sm" data-act="notefont" title="字号 / 标题 / 粗斜下划线 / 颜色">字体</button>'+
    '<button class="r-btn sm" data-act="noteformat" title="列表与待办事项">格式</button>'+
    '<button class="r-btn sm" data-act="notesearch" title="在本篇拾纪里查找">搜索</button>'+
    '<button class="r-btn sm" data-act="noteimg">插入图片</button>'+
    (active ? '<button class="r-btn sm danger" data-act="notedel" data-id="'+esc(active._id)+'">删除</button>' : '')+
  '</div>';

  /* 拾纪页：额外带 .studyroom-notes（深色延伸背景 + 渐变蒙版只作用于此页） */
  return '<div class="studyroom studyroom-notes">' +
    '' +
    '<div class="st-head">' +
      '<h1>文 渊 斋 <span class="st-sep">·</span> <span class="st-sub">拾纪</span></h1>' +
      '<p>N O T E S · J O U R N A L · M E M O</p>' +
    '</div>' +
    '<div class="study-crumb">' +
      '<button class="r-btn" data-act="studyback">← 返回书 房主页</button>' +
      '<span class="crumb-now">拾纪</span>' +
    '</div>' +
    '<section class="sr-shelf notes-desk">' +
      '<header>' +
        '<h3>拾 纪 本</h3>' +
        '<span>' + notes.length + ' 条</span>' +
        '<button class="crumb-add r-btn" data-act="noteadd">＋ 新建拾纪</button>' +
      '</header>' +
      '<div class="notes-layout'+(ui.notes.collapsed?' collapsed':'')+'">' +
        '<button class="notes-toggle" type="button" data-act="notescollapse" aria-label="展开或收起拾纪列表"></button>' +
        '<div class="notes-list">' + listHtml + '</div>' +
        '<div class="notes-right">' +
          toolbarHtml +   // 工具栏在上方
          paperHtml +      // 电子纸在下方
        '</div>' +
      '</div>' +
    '</section>' +
  '</div>';
}
/* v60：从字段值里取出图片地址。
   本库的图片字段绝大多数是「附件数组」形态：[{imageUrl, viewport}]，
   少数（打卡点「封面图片」、馐馔坊「照片」）是纯字符串。
   旧代码直接 add(r[k])，把整个对象塞进了列表 —— 缩略图于是全变成
   [object Object]，既不显示、点了也插不进去。这里统一按三种形态解析。 */
function pickImgUrl(v){
  if (!v) return '';
  if (Array.isArray(v)){
    for (var i=0;i<v.length;i++){ var u=pickImgUrl(v[i]); if (u) return u; }
    return '';
  }
  if (typeof v === 'object') return v.imageUrl || v.url || v.src || '';
  return String(v).trim();
}
/* v60：拾纪电子纸的光标位置。
   插入图片时如果直接拿 window.getSelection()，光标多半还停在弹层里，
   图片会被插到弹层上、紧接着 rCloseOverlay() 把它一起删掉 —— 表现就是
   「点了图片没反应」。所以平时就把纸内的光标位置记下来，插入时恢复。 */
var NOTE_RANGE=null;
function noteSaveRange(){
  try{
    var sel=window.getSelection(); if(!sel || !sel.rangeCount) return;
    var r=sel.getRangeAt(0), paper=document.getElementById('notePaper');
    if (paper && paper.contains(r.commonAncestorContainer)) NOTE_RANGE=r.cloneRange();
  }catch(e){}
}
/* selectionchange 绑在 document 上，只需注册一次；
   放进 render 里每次重绘都会多挂一个，属于监听器泄漏。 */
document.addEventListener('selectionchange', noteSaveRange);
/* 拿到一个「一定在纸内」的 range：有记录就用记录，没有就落到正文末尾 */
function noteRangeIn(paper){
  var sel=window.getSelection();
  if (NOTE_RANGE && paper.contains(NOTE_RANGE.commonAncestorContainer)){
    try{ sel.removeAllRanges(); sel.addRange(NOTE_RANGE); return NOTE_RANGE; }catch(e){}
  }
  var r=document.createRange(); r.selectNodeContents(paper); r.collapse(false);
  try{ sel.removeAllRanges(); sel.addRange(r); }catch(e){}
  NOTE_RANGE=r.cloneRange();
  return r;
}
/* 拾纪图片插入：汇总数据库里已有的图片供挑选 */
function collectDbImages(){
  var imgs=[];
  function add(v){
    var u = resolveImgUrl(pickImgUrl(v));
    if (u && u!=='[object Object]' && imgs.indexOf(u)<0) imgs.push(u);
  }
  /* 一个字段里可能挂了多张附件，全部收进来，不要只取第一张 */
  function addAll(v){
    if (Array.isArray(v)){ v.forEach(function(x){ add(x); }); return; }
    add(v);
  }
  function fromRow(r, keys){ if(!r) return; keys.forEach(function(k){ addAll(r[k]); }); }
  function extractFromHtml(html){ var re=/<img[^>]+src=["']([^"']+)["']/gi, m; while((m=re.exec(html||''))!==null){ add(m[1]); } }
  (store.collection && store.collection.rows || []).forEach(function(r){ fromRow(r,['封面','照片']); });
  (store.ip && store.ip.rows || []).forEach(function(r){ fromRow(r,['IP图像']); });
  (store.series && store.series.rows || []).forEach(function(r){ fromRow(r,['系列封面']); });
  (store.travel && store.travel.rows || []).forEach(function(r){ fromRow(r,['封面','封面图片']); });
  (store.food && store.food.rows || []).forEach(function(r){ fromRow(r,['照片']); });
  (store.idea && store.idea.rows || []).forEach(function(r){ fromRow(r,['封面']); });
  (store.checkin && store.checkin.rows || []).forEach(function(r){ fromRow(r,['封面图片']); });
  (store.recipe && store.recipe.rows || []).forEach(function(r){ fromRow(r,['照片']); });
  (store.notes && store.notes.rows || []).forEach(function(r){ extractFromHtml(r['内容']); });
  return imgs;
}
function insertNoteImage(url){
  url = String(url||'').trim();
  if (!url || url==='[object Object]') return false;
  var paper=document.getElementById('notePaper'); if(!paper) return false;
  /* 没在编辑态就先进入，否则 contenteditable=false 时插入无效 */
  if (!ui.notes.edit){ ui.notes.edit = true; }
  paper.setAttribute('contenteditable','true');
  paper.classList.add('edit');
  try{ paper.focus({preventScroll:true}); }catch(e){ try{ paper.focus(); }catch(e2){} }
  var range = noteRangeIn(paper);
  var img=document.createElement('img');
  img.src=url;
  var fig=wrapNoteFigure(img);          /* v61：包一层图框，才能挂缩放/移动 */
  fig.style.width = '50%';
  range.deleteContents();
  range.insertNode(fig);
  /* 光标移到图框后面，方便接着打字 */
  var after=document.createRange(); after.setStartAfter(fig); after.collapse(true);
  try{ var sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(after); }catch(e){}
  NOTE_RANGE=after.cloneRange();
  paper.dispatchEvent(new Event('input'));
  scheduleNoteImageSave();              /* v61：新图落盘 */
  return true;
}

/* ============================================================
   v61：拾纪图片自由缩放 / 移动
   ------------------------------------------------------------
   每张图都包一层 <span class="np-fig">，尺寸与位置写在这个 span 的
   inline style 上，随 innerHTML 一起保存，刷新后原样恢复。
   选中框（#npFrame）挂在 body 上、不在电子纸里，所以不会被存进内容。
   ============================================================ */
function wrapNoteFigure(img){
  if (!img) return null;
  var p=img.parentNode;
  if (p && p.classList && p.classList.contains('np-fig')) return p;
  var fig=document.createElement('span');
  fig.className='np-fig';
  fig.setAttribute('contenteditable','false');
  fig.setAttribute('data-np-fig','1');
  if (p) p.insertBefore(fig, img);
  fig.appendChild(img);
  return fig;
}
/* 兼容旧内容：把历史遗留的裸 <img> 也包进图框 */
function normalizeNoteFigures(paper){
  if (!paper) return;
  var bare=paper.querySelectorAll('img');
  for (var i=0;i<bare.length;i++){
    var im=bare[i];
    if (im.closest && im.closest('.np-fig')) continue;
    wrapNoteFigure(im);
  }
}
var NP_CUR=null;                       /* 当前选中的 <img> */
function npPaperInnerWidth(paper){
  var cs=getComputedStyle(paper);
  var w=paper.clientWidth - (parseFloat(cs.paddingLeft)||0) - (parseFloat(cs.paddingRight)||0);
  return Math.max(80, w);
}
function npEnsureFrame(){
  var f=document.getElementById('npFrame');
  if (f) return f;
  f=document.createElement('div');
  f.id='npFrame';
  f.innerHTML=
    '<span class="np-handle" data-h="nw"></span>'+
    '<span class="np-handle" data-h="ne"></span>'+
    '<span class="np-handle" data-h="sw"></span>'+
    '<span class="np-handle" data-h="se"></span>'+
    '<span class="np-bar">'+
      '<button type="button" data-np="left" title="浮在左侧，文字环绕">◧</button>'+
      '<button type="button" data-np="center" title="居中独占一行">▣</button>'+
      '<button type="button" data-np="right" title="浮在右侧，文字环绕">◨</button>'+
      '<i class="np-gap"></i>'+
      '<button type="button" data-np="reset" title="恢复原始尺寸">⤾</button>'+
      '<button type="button" data-np="del" title="删除这张图">✕</button>'+
    '</span>';
  document.body.appendChild(f);

  function figOf(){ return (NP_CUR && NP_CUR.closest) ? NP_CUR.closest('.np-fig') : null; }
  function figPaper(){ var fg=figOf(); return (fg && fg.closest) ? fg.closest('.note-paper') : null; }
  function commit(){ var p=figPaper(); if (p) p.dispatchEvent(new Event('input')); }

  /* 工具栏按钮 */
  f.querySelector('.np-bar').addEventListener('mousedown', function(e){ e.preventDefault(); });
  f.querySelector('.np-bar').addEventListener('click', function(e){
    var b=e.target.closest ? e.target.closest('button[data-np]') : null;
    if (!b) return;
    e.stopPropagation();
    var fig=figOf(); if(!fig) return;
    var a=b.getAttribute('data-np');
    if (a==='left'){  fig.style.float='left';  fig.style.margin='6px 14px 8px 0'; }
    if (a==='right'){ fig.style.float='right'; fig.style.margin='6px 0 8px 14px'; }
    if (a==='center'){ fig.style.float='none'; fig.style.margin='8px auto'; }
    if (a==='reset'){ fig.style.width=''; fig.style.height=''; }
    if (a==='del'){
      fig.remove();
      commit();
      npDeselect();
      return;
    }
    commit();
    npSyncFrame();
  });

  /* 四角缩放 */
  f.querySelectorAll('.np-handle').forEach(function(h){
    h.addEventListener('mousedown', function(e){
      e.preventDefault(); e.stopPropagation();
      var img=NP_CUR; if(!img) return;
      var fig=img.closest('.np-fig'); if(!fig) return;
      var paper=fig.closest('.note-paper');
      var dir=h.getAttribute('data-h');
      var sx=e.clientX, sy=e.clientY;
      var r0=fig.getBoundingClientRect();
      var w0=r0.width, h0=r0.height;
      var inner=npPaperInnerWidth(paper);
      var ratio=h0/Math.max(1,w0);
      function move(ev){
        var dx=ev.clientX-sx;
        var w=(dir.indexOf('e')>=0) ? (w0+dx) : (w0-dx);
        w=Math.max(40, Math.min(inner, w));
        var pct=Math.round(w/inner*1000)/10;
        fig.style.width=pct+'%';
        fig.style.height='';
        npSyncFrame();
      }
      function up(){
        document.removeEventListener('mousemove', move);
        document.removeEventListener('mouseup', up);
        if (paper) paper.dispatchEvent(new Event('input'));
      }
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    });
  });
  return f;
}
function npSelectImg(img){
  if (!img) return;
  NP_CUR=img;
  var f=npEnsureFrame();
  f.classList.add('on');
  npSyncFrame();
}
function npDeselect(){
  NP_CUR=null;
  var f=document.getElementById('npFrame');
  if (f) f.classList.remove('on');
}
function npSyncFrame(){
  var f=document.getElementById('npFrame');
  if (!f || !NP_CUR) { if (f) f.classList.remove('on'); return; }
  if (!document.body.contains(NP_CUR)){ npDeselect(); return; }
  var r=NP_CUR.getBoundingClientRect();
  if (!r.width || !r.height){ f.classList.remove('on'); return; }
  f.style.left=r.left+'px'; f.style.top=r.top+'px';
  f.style.width=r.width+'px'; f.style.height=r.height+'px';
  /* 图片太靠上时工具栏会顶出屏幕，翻到框里面去 */
  if (r.top < 52) f.classList.add('np-bar-in'); else f.classList.remove('np-bar-in');
  f.classList.add('on');
}
/* 电子纸滚动 / 窗口变化时，选中框要跟着走 */
window.addEventListener('scroll', function(){ if (NP_CUR) npSyncFrame(); }, true);
window.addEventListener('resize', function(){ if (NP_CUR) npSyncFrame(); });
document.addEventListener('mousedown', function(e){
  if (!NP_CUR) return;
  var f=document.getElementById('npFrame');
  if (f && f.contains(e.target)) return;      /* 点在自己身上，交给各自的处理 */
  if (e.target.closest && e.target.closest('.np-fig')) return;
  npDeselect();
});
/* v60：工具栏里的拾纪名字 —— 点一下原地变成输入框，回车/失焦保存，Esc 取消 */
function beginNoteRename(){
  var box=document.getElementById('noteTitleBox');
  if(!box || !ui.notes.id) return;
  if (box.querySelector('input')) return;        /* 已经在编辑中，别重复建 */
  var note=(store.notes.rows||[]).filter(function(r){ return String(r._id)===String(ui.notes.id); })[0];
  if(!note) return;
  var old=String(note['标题']||'');
  var inp=document.createElement('input');
  inp.type='text'; inp.className='notes-title-input'; inp.value=old; inp.maxLength=60;
  inp.setAttribute('aria-label','拾纪名称');
  box.innerHTML=''; box.appendChild(inp); box.classList.add('editing');
  try{ inp.focus(); inp.select(); }catch(e){}
  var done=false;
  function finish(save){
    if (done) return; done=true;
    var v=String(inp.value||'').trim();
    if (save && v && v!==old){
      note['标题']=v; note['更新日期']=today(); saveNotes();
    }
    render();
  }
  inp.addEventListener('keydown', function(e){
    if (e.key==='Enter'){ e.preventDefault(); finish(true); }
    else if (e.key==='Escape'){ e.preventDefault(); finish(false); }
  });
  inp.addEventListener('blur', function(){ finish(true); });
  /* 输入框里的点击别再触发一次 noterename（虽然那边也有防重入，双保险） */
  inp.addEventListener('click', function(e){ e.stopPropagation(); });
}
/* ============================================================
   v61：拾纪图片落盘 —— 一条拾纪一个文件夹
   ------------------------------------------------------------
   目录：data/images/拾纪-{标题}-{id后4位}/
   写入后端按优先级依次尝试，覆盖「本地磁盘 / 线上 / 本地服务器」三种场景：
     1. FSA（用户挑过数据目录，Chrome 桌面端）→ 直接写文件
     2. GitHub 模式 → Contents API 直接 PUT（发布线上时图片跟 JSON 一起走）
     3. 本地 serve.js → POST /__img
   三种都不通（例如纯 localStorage 模式）就保留原图不落盘，并提示用户。
   ============================================================ */
function noteImageDir(note){
  var t = safeFileName(String((note && note['标题']) || '').trim());
  var id = String((note && note._id) || '').replace(/[^a-z0-9]/gi, '').slice(-4);
  return '拾纪-' + t + (id ? '-' + id : '');
}
function noteImageRel(note, name, dir){
  return DATA_PREFIX + '/' + IMG_DIR + '/' + (dir || noteImageDir(note)) + '/' + name;
}
async function writeImageBytes(rel, bytes, ext){
  try{
    /* 1) FSA：直接写本地磁盘 */
    if (_fsaHandle){
      var parts = String(rel).split('/').filter(Boolean);
      if (parts[0] === DATA_PREFIX) parts.shift();
      var nm = parts.pop();
      if (await _fsaWriteBinary(parts, nm, bytes)) return true;
    }
    /* 2) GitHub：Contents API */
    if (MODE === 'gh' && GH && GH.owner && GH.repo && GH.token){
      var blob = new Blob([bytes], { type: 'image/' + (ext === 'png' ? 'png' : (ext === 'webp' ? 'webp' : (ext === 'gif' ? 'gif' : 'jpeg'))) });
      if (await ghPutFile(rel, blob)) return true;
    }
    /* 3) 本地 serve.js */
    var r = await fetch('/__img?p=' + encodeURIComponent(rel), { method: 'POST', body: bytes });
    if (r && r.ok) return true;
  }catch(e){}
  return false;
}
function currentNote(){
  return (store.notes.rows || []).filter(function(r){ return String(r._id)===String(ui.notes.id); })[0] || null;
}
/* 把 DOM 里电子纸的 src 同步成已保存内容（不整体重绘，避免打断光标） */
function syncPaperImages(note){
  var paper=document.getElementById('notePaper'); if(!paper || !note) return;
  var tmp=document.createElement('div'); tmp.innerHTML=note['内容']||'';
  var a=tmp.querySelectorAll('img'), b=paper.querySelectorAll('img');
  for (var i=0;i<a.length && i<b.length;i++){
    var s=a[i].getAttribute('src')||'';
    if (s && s!==(b[i].getAttribute('src')||'')) b[i].setAttribute('src', s);
  }
}
var _noteImgBusy=false;
/* 把一条拾纪里还没落盘的图片（data: / 外链）写进它自己的文件夹 */
async function externalizeNoteImages(note){
  if (!note || _noteImgBusy) return 0;
  var holder=document.createElement('div');
  holder.innerHTML=note['内容']||'';
  var imgs=holder.querySelectorAll('img');
  if (!imgs.length) return 0;
  var todo=[];
  for (var i=0;i<imgs.length;i++){
    var src=String(imgs[i].getAttribute('src')||'').trim();
    if (/^data:image\//i.test(src)) todo.push({ el:imgs[i], src:src, kind:'data' });
    else if (/^https?:/i.test(src)) todo.push({ el:imgs[i], src:src, kind:'remote' });
  }
  if (!todo.length) return 0;
  _noteImgBusy=true;
  var dir=noteImageDir(note);
  /* FSA 模式下能扫目录拿最大编号；其它模式用时间戳，避免同名覆盖 */
  var seq = _fsaHandle ? await scanMaxImageSeqFor(dir) : 0;
  var done=0;
  try{
    for (var j=0;j<todo.length;j++){
      var it=todo[j], bytes=null, ext='jpg';
      if (it.kind==='data'){
        if (/image\/png/i.test(it.src)) ext='png';
        else if (/image\/webp/i.test(it.src)) ext='webp';
        else if (/image\/gif/i.test(it.src)) ext='gif';
        bytes=dataUrlToBytes(it.src);
      } else {
        var got=await fetchImageBytes(it.src);
        if (!got) continue;          /* 外链抓不到（防盗链等）：保留原链接，不阻断保存 */
        bytes=got.bytes; ext=got.ext;
      }
      if (!bytes || !bytes.length) continue;
      seq++;
      var name = _fsaHandle
        ? '拾纪-' + pad4(seq) + '.' + ext
        : '拾纪-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2,5) + '.' + ext;
      var rel = noteImageRel(note, name, dir);
      if (await writeImageBytes(rel, bytes, ext)){
        _imgUrlCache[rel]=it.src;     /* 立即可显示，避免闪空白 */
        it.el.setAttribute('src', rel);
        done++;
      } else { seq--; }
    }
  } finally { _noteImgBusy=false; }
  if (done){
    note['内容']=holder.innerHTML;
    note['更新日期']=today();
    saveNotes();
    syncPaperImages(note);
    toast('已保存 ' + done + ' 张新图片');
  }
  return done;
}
/* 输入时防抖落盘（避免每敲一个字就写一次文件），失焦时立即落盘 */
var _noteImgTimer=null;
function scheduleNoteImageSave(){
  if (_noteImgTimer) clearTimeout(_noteImgTimer);
  _noteImgTimer=setTimeout(function(){
    _noteImgTimer=null;
    var n=currentNote(); if (n) externalizeNoteImages(n);
  }, 1500);
}

/* ============================================================
   v61：图片库树形浏览 —— 按「页面 → 文件夹」两级组织，选中才加载
   ------------------------------------------------------------
   数据来源两条腿走路：
     A. 从数据库记录里的图片路径反推（任何模式都可用，零请求）；
     B. 能列目录时（本地 serve.js 的 /__imgtree，或 FSA 遍历）再补上
        磁盘上存在、但没被任何记录引用的图片。
   ============================================================ */
var NOTE_IMG_SCAN = [
  { key:'collection', name:'藏品馆', fields:['封面','照片'] },
  { key:'ip',         name:'IP 库',  fields:['IP图像'] },
  { key:'series',     name:'系列',   fields:['系列封面'] },
  { key:'av',         name:'影音厅', fields:['封面'] },
  { key:'travel',     name:'遐方坞', fields:['封面','封面图片'] },
  { key:'checkin',    name:'打卡点', fields:['封面图片'] },
  { key:'study',      name:'文渊斋', fields:['封面'] },
  { key:'food',       name:'馐馔坊', fields:['照片'] },
  { key:'recipe',     name:'私房菜谱', fields:['照片'] },
  { key:'idea',       name:'灵思阁', fields:['封面'] },
  { key:'notes',      name:'拾纪',   html:true }
];
function imgRelDir(rel){
  var m=/^data\/images\/([^/]+)\/[^/]+$/.exec(String(rel||''));
  return m ? m[1] : '';
}
/* A：从数据库反推目录树 —— { group: { folder: [rel...] } } */
function collectDbImageTree(){
  var tree={};
  function put(group, folder, rel){
    if (!group || !folder || !rel) return;
    if (!tree[group]) tree[group]={};
    if (!tree[group][folder]) tree[group][folder]=[];
    if (tree[group][folder].indexOf(rel)<0) tree[group][folder].push(rel);
  }
  NOTE_IMG_SCAN.forEach(function(cfg){
    var mod=store[cfg.key];
    var rows=(mod && mod.rows) || [];
    var gname=(MODS[cfg.key] && MODS[cfg.key].name) || cfg.name;
    rows.forEach(function(r){
      if (!r) return;
      if (cfg.html){
        var re=/<img[^>]+src=["']([^"']+)["']/gi, m;
        while ((m=re.exec(String(r['内容']||'')))!==null){
          var u=normalizeImgPath(m[1]);
          if (u && u.indexOf(DATA_PREFIX+'/'+IMG_DIR+'/')===0) put(gname, imgRelDir(u), u);
        }
        return;
      }
      cfg.fields.forEach(function(k){
        var v=r[k]; if (!v) return;
        var arr = Array.isArray(v) ? v : [v];
        arr.forEach(function(it){
          var u=normalizeImgPath(typeof it==='object' ? (it && it.imageUrl) : it);
          if (u && u.indexOf(DATA_PREFIX+'/'+IMG_DIR+'/')===0) put(gname, imgRelDir(u), u);
        });
      });
    });
  });
  return tree;
}
/* B：能列目录时补上磁盘上的图片（含无引用的孤儿图） */
async function fetchDiskFolders(){
  var out=[];
  try{
    if (_fsaHandle){
      var root=await _fsaGetDir([IMG_DIR], false);
      if (root){
        var list=await walkDirFiles(root, '', []);
        var byDir={};
        list.forEach(function(f){
          if (!/\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(f.rel)) return;
          var d=String(f.rel).split('/')[0];
          if (!d) return;
          (byDir[d]=byDir[d]||[]).push(DATA_PREFIX+'/'+IMG_DIR+'/'+f.rel);
        });
        Object.keys(byDir).forEach(function(d){ out.push({ name:d, files:byDir[d] }); });
        return out;
      }
    }
    var r=await fetch('/__imgtree', { cache:'no-store' });
    if (r && r.ok){
      var j=await r.json();
      (j && j.folders || []).forEach(function(f){
        out.push({ name:f.name, files:(f.files||[]).map(function(n){ return DATA_PREFIX+'/'+IMG_DIR+'/'+f.name+'/'+n; }) });
      });
    }
  }catch(e){}
  return out;
}
/* 合并 A + B，输出可直接渲染的下拉数据：
   [{ group:'藏品馆', folders:[{ name:'徽章-封面', urls:[...] }] }] */
function buildImageFolderTree(diskFolders){
  var tree=collectDbImageTree();
  (diskFolders||[]).forEach(function(f){
    if (!f.name || !f.files || !f.files.length) return;
    var g='磁盘上的图片';
    if (!tree[g]) tree[g]={};
    if (!tree[g][f.name]){
      /* 数据库里没有这个文件夹（可能全是孤儿图），整目录补进来 */
      tree[g][f.name]=f.files.slice();
    } else {
      /* 已有：把磁盘上多出来的补进去 */
      var have=tree[g][f.name];
      f.files.forEach(function(u){ if (have.indexOf(u)<0) have.push(u); });
    }
  });
  var out=[];
  /* v66：同一个文件夹可能同时出现在多个分组里——
     比如拾纪里引用了一张「徽章-封面」的图，它就会在「拾纪」分组下
     再造一个同名条目。如果后面按名字去覆盖，图片就会被「只有 1 张的那份」
     顶掉（表现为：往拾纪插一张图后，原文件夹的其它 16 张全不见了）。
     所以这里按文件夹名去重，url 求并集，一个文件夹只保留一个条目。 */
  var seen={};
  Object.keys(tree).forEach(function(g){
    Object.keys(tree[g]).forEach(function(n){
      if (seen[n]){
        tree[g][n].forEach(function(u){ if (seen[n].urls.indexOf(u)<0) seen[n].urls.push(u); });
        delete tree[g][n];                 /* 合并进首次出现的分组 */
      } else {
        seen[n]={ group:g, name:n, urls:tree[g][n] };
      }
    });
  });
  Object.keys(tree).forEach(function(g){
    var folders=Object.keys(tree[g]).map(function(n){
      return { name:n, urls:tree[g][n] };
    }).sort(function(a,b){ return a.name.localeCompare(b.name,'zh'); });
    folders.forEach(function(f){ f.urls.sort(); });
    if (folders.length) out.push({ group:g, folders:folders });
  });
  out.sort(function(a,b){ return a.group.localeCompare(b.group,'zh'); });
  return out;
}
/* 把树拍平成「文件夹名 -> url 列表」。同名只会出现一次（上面已去重），
   这里仍然写成合并而不是赋值，避免以后再撞同样的坑。 */
function flattenImageFolders(tree){
  var map={};
  (tree||[]).forEach(function(g){
    g.folders.forEach(function(f){
      if (!map[f.name]) map[f.name]=[];
      f.urls.forEach(function(u){ if (map[f.name].indexOf(u)<0) map[f.name].push(u); });
    });
  });
  return map;
}

/* v61：图片库改为树形文件夹浏览 —— 选中文件夹后才渲染缩略图 */
/* ============================================================
   v64：拾纪工具栏 · 字体 / 格式 / 搜索
   ------------------------------------------------------------
   电子纸是 contenteditable，这里统一用 execCommand 改样式，
   关键点是「先把光标还原回纸内再执行」——弹层按钮会抢焦点，
   不还原的话命令会作用在弹层上、或者干脆无效。
   ============================================================ */
function npPaper(){ return document.getElementById('notePaper'); }
function npExec(cmd, val){
  var paper=npPaper(); if(!paper) return false;
  if (!ui.notes.edit){ ui.notes.edit=true; }
  paper.setAttribute('contenteditable','true');
  try{ paper.focus({preventScroll:true}); }catch(e){ try{ paper.focus(); }catch(e2){} }
  noteRangeIn(paper);
  try{
    document.execCommand('styleWithCSS', false, true);
    if (val==null) document.execCommand(cmd, false, null);
    else document.execCommand(cmd, false, val);
  }catch(e){}
  noteSaveRange();
  paper.dispatchEvent(new Event('input'));
  return true;
}
/* 自定义颜色：默认两个色位，存在 localStorage，可随时从色盘改 */
var NP_COLOR_KEY='lifedesk_note_colors';
function npPresetColors(){ return ['#c92a2a','#e8590c','#f2b705','#2f9e44','#1c7ed6','#7048e8','#212529']; }  /* 红橙黄绿蓝紫黑 */
function npLoadCustom(){
  try{
    var a=JSON.parse(localStorage.getItem(NP_COLOR_KEY)||'null');
    if (Array.isArray(a) && a.length===2 && a[0] && a[1]) return a;
  }catch(e){}
  return ['#ad4e00','#0b7285'];
}
function npSaveCustom(a){ try{ localStorage.setItem(NP_COLOR_KEY, JSON.stringify(a)); }catch(e){} }
/* 共用一个隐藏的取色器（原生色盘），不随弹层销毁 */
var _npColorPicker=null;
function npPickColor(initial, onPick){
  if (!_npColorPicker){
    _npColorPicker=document.createElement('input');
    _npColorPicker.type='color';
    _npColorPicker.style.cssText='position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0';
    document.body.appendChild(_npColorPicker);
  }
  _npColorPicker.oninput=function(){ if(onPick) onPick(_npColorPicker.value); };
  _npColorPicker.value=initial||'#c92a2a';
  try{ _npColorPicker.click(); }catch(e){}
}
