/* ---------- 搜索：在本篇拾纪里查找 ---------- */
var NP_FIND={ ranges:[], idx:-1, q:'' };
function npCollectRanges(root, q){
  var out=[], low=q.toLowerCase(), guard=0;
  var walker=document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
  var n;
  while ((n=walker.nextNode()) && guard++<20000){
    var t=String(n.nodeValue||''); if(!t) continue;
    var lt=t.toLowerCase(), from=0, i;
    while ((i=lt.indexOf(low, from))>=0){
      var r=document.createRange();
      try{ r.setStart(n,i); r.setEnd(n,i+q.length); out.push(r); }catch(e){}
      from=i+Math.max(1,q.length);
    }
  }
  return out;
}
/* 用 CSS Custom Highlight API 高亮：不改 DOM，所以不会污染保存的内容 */
function npPaintHighlights(){
  try{
    if (!(window.CSS && CSS.highlights && typeof Highlight!=='undefined')) return;
    var hl=new Highlight();
    NP_FIND.ranges.forEach(function(r){ hl.add(r); });
    CSS.highlights.set('np-find', hl);
  }catch(e){}
}
function npClearHighlights(){
  try{ if (window.CSS && CSS.highlights) CSS.highlights.delete('np-find'); }catch(e){}
}
function npFindRefresh(){
  var paper=npPaper();
  var inp=document.getElementById('npFindInp');
  var cnt=document.getElementById('npFindCount');
  if (!paper || !inp) return;
  NP_FIND.q=String(inp.value||'').trim();
  NP_FIND.ranges = NP_FIND.q ? npCollectRanges(paper, NP_FIND.q) : [];
  NP_FIND.idx=-1;
  if (NP_FIND.ranges.length) npPaintHighlights(); else npClearHighlights();
  if (cnt) cnt.textContent = NP_FIND.q ? (NP_FIND.ranges.length ? (NP_FIND.ranges.length+' 处') : '无匹配') : '';
  if (NP_FIND.ranges.length) npFindStep(1);
}
function npFindStep(d){
  var n=NP_FIND.ranges.length; if(!n) return;
  NP_FIND.idx=(NP_FIND.idx+d+n)%n;
  var r=NP_FIND.ranges[NP_FIND.idx];
  try{ var sel=window.getSelection(); sel.removeAllRanges(); sel.addRange(r); }catch(e){}
  try{
    var paper=npPaper();
    if (paper){
      var pr=paper.getBoundingClientRect(), rr=r.getBoundingClientRect();
      if (rr.top<pr.top+4 || rr.bottom>pr.bottom-4){
        var host=r.startContainer.parentNode;
        if (host && host.scrollIntoView) host.scrollIntoView({block:'center'});
      }
    }
  }catch(e){}
  var cnt=document.getElementById('npFindCount');
  if (cnt) cnt.textContent=(NP_FIND.idx+1)+' / '+n;
}
function npClearFind(){
  NP_FIND={ ranges:[], idx:-1, q:'' };
  npClearHighlights();
}
function toggleNoteSearch(){
  var bar=document.getElementById('npSearchBar');
  if (bar){ npClearFind(); if(bar.parentNode) bar.parentNode.removeChild(bar); return; }
  var right=document.querySelector('.notes-right');
  if (!right) return;
  var d=document.createElement('div');
  d.className='np-searchbar'; d.id='npSearchBar';
  d.innerHTML='<span class="np-findwrap" id="npFindWrap">'+
      '<input id="npFindInp" type="text" placeholder="在本篇拾纪里查找…" autocomplete="off">'+
      '<button type="button" class="np-sclear" data-clear="1" title="清空">×</button>'+
    '</span>'+
    '<span class="np-scount" id="npFindCount"></span>'+
    '<button type="button" class="np-sbtn" data-d="-1" title="上一个（Shift+回车）">↑</button>'+
    '<button type="button" class="np-sbtn" data-d="1" title="下一个（回车）">↓</button>'+
    '<button type="button" class="np-sbtn" data-x="1" title="关闭搜索">×</button>';
  /* 插在工具栏下面、电子纸上面（放在最前面会盖住工具栏，位置很别扭） */
  var paperEl=right.querySelector('.note-paper');
  if (paperEl) right.insertBefore(d, paperEl);
  else right.appendChild(d);
  var inp=d.querySelector('#npFindInp');
  var wrapEl=d.querySelector('#npFindWrap');
  /* v66：清字按钮的显隐跟着输入内容走 */
  function syncClearBtn(){ if (wrapEl && inp) wrapEl.classList.toggle('has-text', !!inp.value); }
  d.querySelectorAll('.np-sbtn,.np-sclear').forEach(function(b){
    b.addEventListener('mousedown', function(e){ e.preventDefault(); });
    b.addEventListener('click', function(e){
      e.stopPropagation();
      if (b.hasAttribute('data-x')){ toggleNoteSearch(); return; }
      if (b.hasAttribute('data-clear')){
        inp.value=''; syncClearBtn(); npFindRefresh(); inp.focus(); return;  /* 只清字，不收起搜索条 */
      }
      npFindStep(parseInt(b.getAttribute('data-d'),10)||1);
    });
  });
  if (inp){
    inp.addEventListener('click', function(e){ e.stopPropagation(); });
    inp.addEventListener('input', function(){
      syncClearBtn();
      npFindRefresh();
    });
    inp.addEventListener('keydown', function(e){
      if (e.key==='Enter'){ e.preventDefault(); npFindStep(e.shiftKey?-1:1); }
      else if (e.key==='Escape'){ e.preventDefault(); toggleNoteSearch(); }
    });
    syncClearBtn();          /* v66：打开时就同步一次（编辑已有内容时也要显示） */
    npFindRefresh();
    inp.focus();
  }
}
function openNoteImagePicker(){
  npDeselect();                    /* 弹层 z-index 比选中框低，先收起来免得叠在上面 */
  var tree=buildImageFolderTree([]);
  var flat=[];
  tree.forEach(function(g){ g.folders.forEach(function(f){ flat.push(f); }); });
  var cur=flat.length ? flat[0].name : '';
  var selHtml='<select class="nip-dirsel" id="nipDirSel">'+
    tree.map(function(g){
      return '<optgroup label="'+esc(g.group)+'">'+
        g.folders.map(function(f){
          return '<option value="'+esc(f.name)+'"'+(f.name===cur?' selected':'')+'>'+
                 esc(f.name)+'（'+f.urls.length+'）</option>';
        }).join('')+
      '</optgroup>';
    }).join('')+
  '</select>';
  var html='<div class="nip">'+
    '<h2>插入图片 <span class="x" onclick="rCloseOverlay()">×</span></h2>'+
    '<div class="nip-tabs">'+
      '<button class="nip-tab on" data-tab="db">图片库</button>'+
      '<button class="nip-tab" data-tab="upload">上传/拍照</button>'+
      '<button class="nip-tab" data-tab="url">网络图片</button>'+
    '</div>'+
    '<div class="nip-body" data-panel="db">'+
      (flat.length
        ? '<div class="nip-dirrow">'+selHtml+'<span class="nip-hint" id="nipDirHint"></span></div>'+
          '<div class="nip-grid" id="nipGrid"></div>'
        : '<p class="nip-empty">数据库里暂时没有图片</p>')+
    '</div>'+
    '<div class="nip-body" data-panel="upload" style="display:none">'+
      '<p>从本机选择图片，会自动压缩后插入。</p>'+
      '<label class="btn primary">选择图片<input type="file" accept="image/*" id="nipUpload" hidden></label>'+
    '</div>'+
    '<div class="nip-body" data-panel="url" style="display:none">'+
      '<p>粘贴图片网址，或直接 Ctrl+V 粘贴到拾纪纸里。</p>'+
      '<div class="row"><input type="text" id="nipUrl" placeholder="https://..." style="flex:1"></div>'+
      '<div class="actions"><button class="btn primary" id="nipUrlBtn">插入</button></div>'+
    '</div>'+
  '</div>';
  var ov=rShowOverlay(html);

  /* 树形目录：选中某个文件夹后，才把它里面的图片渲染成缩略图。
     这样一次只加载一个文件夹，不会一打开就拉几百张图。 */
  var dirData=flattenImageFolders(tree);   /* v66：同名文件夹合并，不覆盖 */
  var grid=ov.querySelector('#nipGrid');
  var hint=ov.querySelector('#nipDirHint');
  var sel=ov.querySelector('#nipDirSel');
  function paintFolder(name){
    if (!grid) return;
    var urls=dirData[name]||[];
    grid.innerHTML = urls.length
      ? urls.map(function(u){
          return '<div class="nip-thumb" data-url="'+esc(u)+'" title="'+esc(String(u).split('/').pop())+'" '+
                 'style="background-image:url(\''+esc(u).replace(/["'()\\]/g,'')+'\')"></div>';
        }).join('')
      : '<p class="nip-empty">这个文件夹里没有图片</p>';
    if (hint) hint.textContent = urls.length ? urls.length+' 张，点一下插入' : '';
    /* 缩略图按需解码，文件夹大时也不卡 */
    grid.querySelectorAll('.nip-thumb').forEach(function(th){
      th.setAttribute('loading','lazy');
      th.onclick=function(e){
        e.stopPropagation();
        if (insertNoteImage(th.getAttribute('data-url'))) rCloseOverlay();
        else toast('这张图插不进去，换一张试试');
      };
    });
  }
  if (sel){
    sel.addEventListener('click', function(e){ e.stopPropagation(); });
    sel.addEventListener('change', function(){ paintFolder(sel.value); });
  }
  if (cur) paintFolder(cur);

  /* 打开后异步补上「磁盘上存在、数据库里没引用」的图片，补完刷新下拉但保留当前选择 */
  fetchDiskFolders().then(function(folders){
    if (!folders || !folders.length || !sel) return;
    var keep=sel.value;
    tree=buildImageFolderTree(folders);
    var flat2=[]; tree.forEach(function(g){ g.folders.forEach(function(f){ flat2.push(f); }); });
    if (!flat2.length) return;
    sel.innerHTML=tree.map(function(g){
      return '<optgroup label="'+esc(g.group)+'">'+
        g.folders.map(function(f){
          return '<option value="'+esc(f.name)+'">'+esc(f.name)+'（'+f.urls.length+'）</option>';
        }).join('')+
      '</optgroup>';
    }).join('');
    dirData=flattenImageFolders(tree);
    sel.value = (keep && dirData[keep]) ? keep : flat2[0].name;
    paintFolder(sel.value);
  });

  /* 标签切换 */
  ov.querySelectorAll('.nip-tab').forEach(function(btn){
    btn.onclick=function(){
      var tab=btn.getAttribute('data-tab');
      ov.querySelectorAll('.nip-tab').forEach(function(b){ b.classList.remove('on'); });
      ov.querySelectorAll('.nip-body').forEach(function(p){ p.style.display='none'; });
      btn.classList.add('on');
      var p=ov.querySelector('[data-panel="'+tab+'"]'); if(p) p.style.display='block';
    };
  });
  /* 上传 */
  var up=ov.querySelector('#nipUpload');
  if(up){
    up.onchange=function(){
      var ff=up.files && up.files[0]; if(!ff) return;
      compressImage(ff, 1200, function(dataUrl){
        if(!dataUrl){ toast('这张图读不出来，换个文件试试'); return; }
        if (insertNoteImage(dataUrl)) rCloseOverlay(); else toast('插入失败，再点一次「插入图片」试试');
      });
    };
  }
  /* 网络地址 */
  var urlInp=ov.querySelector('#nipUrl'), urlBtn=ov.querySelector('#nipUrlBtn');
  function doUrl(){
    var u=String(urlInp.value||'').trim(); if(!u){ toast('先填图片地址'); return; }
    if (insertNoteImage(u)) rCloseOverlay(); else toast('这个地址插不进去，换个链接试试');
  }
  if(urlBtn) urlBtn.onclick=doUrl;
  if(urlInp) urlInp.addEventListener('keydown', function(e){ if(e.key==='Enter') doUrl(); });
}

/* 工具：根据 id 字符串得到稳定 hash */
function hashStr(s){ var h=0; for(var i=0;i<s.length;i++){ h=(h*31+s.charCodeAt(i))|0; } return Math.abs(h); }
/* 调色板 + 暗化（用于 3D 书的封面渐变） */
var PALETTE = ['#a23a2a','#1f6b4f','#2a4d8f','#b5852a','#5a3a78','#7a4f2c','#2f7d86','#9c3f5a','#3a2618'];
function darken(hex, p){
  var m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if(!m) return hex;
  var n = parseInt(m[1],16);
  var r = Math.max(0, Math.round(((n>>16)&0xff)*(1-p)));
  var g = Math.max(0, Math.round(((n>>8)&0xff)*(1-p)));
  var b = Math.max(0, Math.round((n&0xff)*(1-p)));
  return '#'+((r<<16)|(g<<8)|b).toString(16).padStart(6,'0');
}

